	const causeId = ownData(value, "causeId");
	if (typeof edgeId !== "string" || edgeId.length === 0) return false;
	if (typeof causeId !== "string" || causeId.length === 0) return false;
	if (kind === "dirty") return hasOnlyKeys(value, ["causeId", "edgeId", "kind"]);
