	state: ReactiveIndexRestoreState<K, V> | readonly IndexRow<K, V>[],
	options: ReactiveIndexOptions = {},
): ReactiveIndex<K, V> {
	const rows = restoreIndexRows(state);
	return restoreReactiveIndexFromBackendState<K, V>(rows, options);
}

