	}

	private _subscribeDepAt(depNode: Node<unknown>, opts: { seedRestored?: boolean } = {}): void {
		nodeSubscribeDepAt(nodeRuntimeHost(this), depNode, opts);
	}

	private _seedRestoredDepAt(idx: number, depNode: Node<unknown>): void {
