		workItemId: subjectId ?? "unknown",
		state: "mapping-issue",
		sourceRefs,
		issues: [issue],
	};
	const audit: AgentRuntimeAuditRecord = {
		id: compoundTupleKey("work-item-action-proposal-issue-audit", [
			subjectId ?? "work-item",
