export type {
	KnowledgeGraphCursor,
	KnowledgeGraphEntity,
	KnowledgeGraphError,
	KnowledgeGraphErrorCode,
	KnowledgeGraphIndex,
	KnowledgeGraphPolicy,
	KnowledgeGraphReducerBundle,
	KnowledgeGraphReducerBundleOptions,
