	const name = opts.name ?? "agenticMemoryRecordApplicationEvidenceFacts";
	const projection = graph.node<AgenticMemoryRecordApplicationEvidenceFactsProjection>(
		[opts.applicationDecisions],
		(ctx) => {
			const state =
				ctx.state.get<{ evaluation: number }>() ??
				({ evaluation: 0 } satisfies { evaluation: number });
			state.evaluation += 1;
			ctx.state.set(state);
			ctx.down([
				[
					"DATA",
					projectAgenticMemoryRecordApplicationEvidenceFacts<T>(depLatest(ctx, 0), {
						evaluation: state.evaluation,
					}),
				],
			]);
		},
		{
			name: `${name}/projection`,
			factory: "agenticMemoryRecordApplicationEvidenceFacts",
			completeWhenDepsComplete: false,
			errorWhenDepsError: false,
		},
	);
	return {
		input: { applicationDecisions: opts.applicationDecisions },
		projection,
		evidenceFacts: solutionProjection(
			graph,
			projection,
			`${name}/evidenceFacts`,
			"agenticMemoryRecordApplicationEvidenceFacts",
			(fact) => fact.evidenceFacts,
		),
		priorEvidence: solutionProjection(
			graph,
			projection,
			`${name}/priorEvidence`,
			"agenticMemoryRecordApplicationEvidenceFactsPriorEvidence",
			(fact) => fact.priorEvidence,
		),
		status: solutionProjection(
			graph,
			projection,
			`${name}/status`,
			"agenticMemoryRecordApplicationEvidenceFactsStatus",
			(fact) => fact.status,
		),
		issues: solutionProjection(
			graph,
			projection,
			`${name}/issues`,
			"agenticMemoryRecordApplicationEvidenceFactsIssues",
			(fact) => fact.issues,
		),
		audit: solutionProjection(
			graph,
			projection,
			`${name}/audit`,
			"agenticMemoryRecordApplicationEvidenceFactsAudit",
			(fact) => fact.audit,
		),
		cursor: solutionProjection(
			graph,
			projection,
			`${name}/cursor`,
			"agenticMemoryRecordApplicationEvidenceFactsCursor",
			(fact) => fact.cursor,
		),
	};
}

function projectEvidenceFactsFromDecisions<T>(
	value: unknown,
	_evaluation: number | undefined,
): {
	readonly evidenceFacts: readonly AgenticMemoryRecordApplicationEvidence[];
	readonly issues: readonly DataIssue[];
	readonly audit: readonly AgenticMemoryRecordApplicationEvidenceProjectionAuditEntry[];
	readonly totalDecisions: number;
	readonly appliedDecisions: number;
	readonly skippedDecisions: number;
	readonly rejectedDecisions: number;
	readonly totalEvidenceFacts: number;
	readonly invalidEvidenceFacts: number;
} {
	const evidenceFacts: AgenticMemoryRecordApplicationEvidence[] = [];
	const issues: DataIssue[] = [];
	const audit: AgenticMemoryRecordApplicationEvidenceProjectionAuditEntry[] = [];
	if (!Array.isArray(value)) {
		issues.push(
			dataIssue(
				"agentic-memory.application-evidence-facts.invalid-decisions",
				"application decisions input must be an array",
				{ severity: "error" },
			),
		);
		return {
			evidenceFacts: Object.freeze(evidenceFacts),
			issues: Object.freeze(issues),
			audit: Object.freeze([
				auditEntry("issue-recorded", { reason: "application decisions input must be an array" }),
			]),
			totalDecisions: 0,
			appliedDecisions: 0,
			skippedDecisions: 0,
			rejectedDecisions: 0,
			totalEvidenceFacts: 0,
			invalidEvidenceFacts: 1,
		};
	}
	const length = safeArrayLength(value);
	if (length === undefined) {
		issues.push(
			dataIssue(
				"agentic-memory.application-evidence-facts.invalid-decisions",
				"application decisions input length could not be read",
				{ severity: "error" },
			),
		);
		return {
			evidenceFacts: Object.freeze(evidenceFacts),
			issues: Object.freeze(issues),
			audit: Object.freeze([
				auditEntry("issue-recorded", { reason: "application decisions length failed" }),
			]),
			totalDecisions: 0,
			appliedDecisions: 0,
			skippedDecisions: 0,
			rejectedDecisions: 0,
			totalEvidenceFacts: 0,
			invalidEvidenceFacts: 1,
		};
	}
	let appliedDecisions = 0;
	let skippedDecisions = 0;
	let rejectedDecisions = 0;
	let invalidEvidenceFacts = 0;
	for (let index = 0; index < length; index += 1) {
		try {
			if (!Object.hasOwn(value, index)) {
				throw new TypeError("application decisions must be dense");
			}
			const decision = value[index] as AgenticMemoryRecordApplicationDecision<T>;
			if (!isPlainRecord(decision)) {
				invalidEvidenceFacts += 1;
				issues.push(
					dataIssue(
						"agentic-memory.application-evidence-facts.invalid-decision",
						"application decision must be an object",
						{ severity: "error", path: [index] },
					),
				);
				continue;
			}
			const commonErrors = validateApplicationDecisionCommon(decision);
			if (commonErrors.length > 0) {
				invalidEvidenceFacts += 1;
				issues.push(
					dataIssue(
						"agentic-memory.application-evidence-facts.invalid-decision",
						"application decision is invalid",
						{ severity: "error", path: [index], refs: commonErrors },
					),
				);
				continue;
			}
			if (decision.state === "skipped") {
				skippedDecisions += 1;
				audit.push(
					auditEntry("decision-skipped", {
						admissionId: decision.admissionId,
						proposalId: decision.proposalId,
						applicationId: decision.applicationId,
						reason: decision.reasonCode,
					}),
				);
				continue;
			}
			if (decision.state === "rejected") {
				rejectedDecisions += 1;
				audit.push(
					auditEntry("decision-skipped", {
						admissionId: decision.admissionId,
						proposalId: decision.proposalId,
						applicationId: decision.applicationId,
						reason: decision.reasonCode,
					}),
				);
				continue;
			}
			if (decision.state !== "applied") {
				invalidEvidenceFacts += 1;
				issues.push(
					dataIssue(
						"agentic-memory.application-evidence-facts.invalid-decision",
						"application decision state is invalid",
						{ severity: "error", path: [index] },
					),
				);
				continue;
			}
			appliedDecisions += 1;
			const projected = evidenceFromDecision(decision, index);
			if (projected.evidence === undefined) {
				invalidEvidenceFacts += 1;
				issues.push(...projected.issues);
				continue;
			}
			evidenceFacts.push(projected.evidence);
			audit.push(
				auditEntry("evidence-fact-projected", {
					admissionId: projected.evidence.admissionId,
					proposalId: projected.evidence.proposalId,
					applicationId: projected.evidence.applicationId,
					sourceRefs: projected.evidence.sourceRefs,
					policyRefs: projected.evidence.policyRefs,
				}),
			);
		} catch (error) {
			invalidEvidenceFacts += 1;
			issues.push(
				dataIssue(
					"agentic-memory.application-evidence-facts.invalid-decision",
					`application decision access failed: ${errorMessage(error)}`,
					{ severity: "error", path: [index] },
				),
			);
		}
	}
	for (const issue of issues) {
		audit.push(auditEntry("issue-recorded", { reason: issue.code }));
	}
	return {
		evidenceFacts: Object.freeze(evidenceFacts),
		issues: Object.freeze(issues),
		audit: Object.freeze(audit),
		totalDecisions: length,
		appliedDecisions,
		skippedDecisions,
		rejectedDecisions,
		totalEvidenceFacts: evidenceFacts.length + invalidEvidenceFacts,
		invalidEvidenceFacts,
	};
}

function evidenceFromDecision<T>(
	decision: AgenticMemoryRecordApplicationDecision<T>,
	index: number,
): {
	readonly evidence?: AgenticMemoryRecordApplicationEvidence;
	readonly issues: readonly DataIssue[];
} {
	const validationErrors = [
		...dataRecordContainerErrors(decision, "decision"),
		...forbiddenAgenticMemoryDataFields(decision as unknown as Record<string, unknown>, "decision"),
	];
	if (decision.kind !== "agentic-memory-record-application-decision") {
		validationErrors.push("decision.kind must be agentic-memory-record-application-decision");
	}
	for (const field of ["applicationId", "admissionId", "proposalId"] as const) {
		if (!isNonEmptyString(decision[field])) {
			validationErrors.push(`decision.${field} must be non-empty`);
		}
	}
	if (!isApplicationOperation(decision.operation)) {
		validationErrors.push("decision.operation must be create, replace, or update");
	}
	if (decision.operationVersion !== AGENTIC_MEMORY_RECORD_APPLICATION_OPERATION_VERSION) {
		validationErrors.push("decision.operationVersion must be 1");
	}
	if (!isPlainRecord(decision.candidateMaterial)) {
		validationErrors.push("decision.candidateMaterial must be an object");
	}
	const record = decision.candidateMaterial?.record;
	if (!isPlainRecord(record) || !isNonEmptyString(record.id)) {
		validationErrors.push("decision.candidateMaterial.record.id must be non-empty");
	}
	const fragment = isPlainRecord(record) ? record.fragment : undefined;
	if (!isPlainRecord(fragment) || !isNonEmptyString(fragment.id)) {
		validationErrors.push("decision.candidateMaterial.record.fragment.id must be non-empty");
	}
	const recordId = isPlainRecord(record) && isNonEmptyString(record.id) ? record.id : undefined;
	const fragmentId =
		isPlainRecord(fragment) && isNonEmptyString(fragment.id) ? fragment.id : undefined;
	const targetRecordId = decision.targetRecordId ?? recordId;
	const appliedRecord = decision.record;
	if (!isPlainRecord(appliedRecord)) {
		validationErrors.push("decision.record must be present for applied decisions");
	} else {
		if (recordId !== undefined && appliedRecord.id !== recordId) {
			validationErrors.push("decision.record.id must match candidate record id");
		}
		const appliedFragment = appliedRecord.fragment;
		if (
			fragmentId !== undefined &&
			(!isPlainRecord(appliedFragment) || appliedFragment.id !== fragmentId)
		) {
			validationErrors.push("decision.record.fragment.id must match candidate fragment id");
		}
	}
	const materialIdentity = validateApplicationMaterialIdentity(
		decision.materialIdentity,
		"decision.materialIdentity",
		validationErrors,
		{
			operation: isApplicationOperation(decision.operation) ? decision.operation : undefined,
			operationVersion: decision.operationVersion === 1 ? 1 : undefined,
			recordId,
			fragmentId,
			targetRecordId,
		},
	);
	for (const [field, refs] of [
		["sourceRefs", decision.sourceRefs],
		["policyRefs", decision.policyRefs],
		["evidenceRefs", decision.evidenceRefs],
	] as const) {
		if (refs !== undefined) {
			validationErrors.push(
				...validateAgenticMemoryFactRefs(refs).map((error) => `decision.${field}: ${error}`),
			);
		}
	}
	if (
		recordId !== undefined &&
		isNonEmptyString(decision.targetRecordId) &&
		decision.targetRecordId !== recordId
	) {
		validationErrors.push("decision.targetRecordId must equal candidate record id when present");
	}
	if (
		isPlainRecord(appliedRecord) &&
		materialIdentity !== undefined &&
		targetRecordId !== undefined
	) {
		const appliedIdentity = applicationMaterialIdentityKey({
			operation: decision.operation,
			operationVersion: AGENTIC_MEMORY_RECORD_APPLICATION_OPERATION_VERSION,
			targetRecordId,
			record: appliedRecord as unknown as AgenticMemoryRecord<T>,
		});
		if (appliedIdentity.issue !== undefined) {
			validationErrors.push(
				`decision.record material identity is invalid: ${appliedIdentity.issue}`,
			);
		} else if (appliedIdentity.key !== materialIdentity.key) {
			validationErrors.push("decision.record must match decision.materialIdentity");
		}
	}
	if (
		validationErrors.length > 0 ||
		recordId === undefined ||
		fragmentId === undefined ||
		materialIdentity === undefined ||
		!isApplicationOperation(decision.operation)
	) {
		return {
			issues: [
				dataIssue(
					"agentic-memory.application-evidence-facts.invalid-decision",
					"application decision cannot become evidence",
					{ severity: "error", path: [index], refs: validationErrors },
				),
			],
		};
	}
	return {
		evidence: Object.freeze({
			kind: "agentic-memory-record-application-evidence",
			applicationId: decision.applicationId,
			admissionId: decision.admissionId,
			proposalId: decision.proposalId,
			operation: decision.operation,
			operationVersion: AGENTIC_MEMORY_RECORD_APPLICATION_OPERATION_VERSION,
			...(decision.idempotencyKey === undefined ? {} : { idempotencyKey: decision.idempotencyKey }),
			recordId,
			fragmentId,
			targetRecordId,
			materialIdentity,
			...(decision.sourceRefs === undefined
				? {}
				: { sourceRefs: snapshotAgenticMemoryFactRefs(decision.sourceRefs) }),
			...(decision.policyRefs === undefined
				? {}
				: { policyRefs: snapshotAgenticMemoryFactRefs(decision.policyRefs) }),
			...(decision.evidenceRefs === undefined
				? {}
				: { evidenceRefs: snapshotAgenticMemoryFactRefs(decision.evidenceRefs) }),
		}),
		issues: [],
	};
}

function applicationMaterialIdentityKey<T>(input: {
	readonly operation: AgenticMemoryRecordApplicationOperation;
	readonly operationVersion: 1;
	readonly targetRecordId: FactId;
	readonly record: AgenticMemoryRecord<T>;
}): { readonly key: string; readonly issue?: undefined } | { readonly issue: string } {
	try {
		const frame = Object.freeze({
			format: AGENTIC_MEMORY_RECORD_APPLICATION_MATERIAL_FRAME_FORMAT,
			version: 1,
			operation: input.operation,
			operationVersion: input.operationVersion,
			targetRecordId: input.targetRecordId,
			record: agenticMemoryRecordFrame(input.record as AgenticMemoryRecord<StrictJsonValue>),
		});
		return { key: textDecoder.decode(strictCanonicalJsonBytes(frame)) };
	} catch (error) {
		return { issue: errorMessage(error) };
	}
}

function validatePriorEvidenceInput(value: unknown): {
	readonly entries: readonly AgenticMemoryRecordApplicationEvidence[];
	readonly issues: readonly DataIssue[];
	readonly invalidEntries: number;
	readonly totalEntries: number;
	readonly sourceRefs?: readonly AgenticMemoryFactRef[];
	readonly policyRefs?: readonly AgenticMemoryFactRef[];
	readonly metadata?: Readonly<Record<string, StrictJsonValue>>;
} {
	try {
		return validatePriorEvidenceInputInner(value);
	} catch (error) {
		return {
			entries: Object.freeze([]),
			invalidEntries: 1,
			totalEntries: 1,
			issues: Object.freeze([
				dataIssue(
					"agentic-memory.application-prior-evidence.invalid",
					`application prior evidence access failed: ${errorMessage(error)}`,
					{ severity: "error" },
				),
			]),
		};
	}
}

function validatePriorEvidenceInputInner(value: unknown): {
	readonly entries: readonly AgenticMemoryRecordApplicationEvidence[];
	readonly issues: readonly DataIssue[];
	readonly invalidEntries: number;
	readonly totalEntries: number;
	readonly sourceRefs?: readonly AgenticMemoryFactRef[];
	readonly policyRefs?: readonly AgenticMemoryFactRef[];
	readonly metadata?: Readonly<Record<string, StrictJsonValue>>;
} {
	let rawEntries: unknown;
	let sourceRefs: readonly AgenticMemoryFactRef[] | undefined;
	let policyRefs: readonly AgenticMemoryFactRef[] | undefined;
	let metadata: Readonly<Record<string, StrictJsonValue>> | undefined;
	if (value === undefined) {
		rawEntries = [];
	} else if (Array.isArray(value)) {
		rawEntries = value;
	} else if (isPlainRecord(value)) {
		const validationErrors = [
			...dataRecordContainerErrors(value, "priorEvidence"),
			...forbiddenAgenticMemoryDataFields(value, "priorEvidence"),
		];
		if (value.kind !== "agentic-memory-record-application-prior-evidence") {
			validationErrors.push(
				"priorEvidence.kind must be agentic-memory-record-application-prior-evidence",
			);
		}
		sourceRefs =
			value.sourceRefs === undefined
				? undefined
				: snapshotFactRefs(value.sourceRefs, "priorEvidence.sourceRefs", validationErrors);
		policyRefs =
			value.policyRefs === undefined
				? undefined
				: snapshotFactRefs(value.policyRefs, "priorEvidence.policyRefs", validationErrors);
		metadata = snapshotMetadata(value.metadata, "priorEvidence.metadata", validationErrors);
		if (validationErrors.length > 0) {
			return {
				entries: Object.freeze([]),
				invalidEntries: 1,
				totalEntries: 1,
				issues: Object.freeze([
					dataIssue(
						"agentic-memory.application-prior-evidence.invalid",
						"application prior evidence is invalid",
						{ severity: "error", refs: validationErrors },
					),
				]),
			};
		}
		rawEntries = value.entries;
	} else {
		return {
			entries: Object.freeze([]),
			invalidEntries: 1,
			totalEntries: 1,
			issues: Object.freeze([
				dataIssue(
					"agentic-memory.application-prior-evidence.invalid",
					"application prior evidence must be an object or array",
					{ severity: "error" },
				),
			]),
		};
	}
	if (!Array.isArray(rawEntries)) {
		return {
			entries: Object.freeze([]),
			invalidEntries: 1,
			totalEntries: 1,
			issues: Object.freeze([
				dataIssue(
					"agentic-memory.application-prior-evidence.invalid",
					"application prior evidence entries must be an array",
					{ severity: "error" },
				),
			]),
		};
	}
	const length = safeArrayLength(rawEntries);
	if (length === undefined) {
		return {
			entries: Object.freeze([]),
			invalidEntries: 1,
			totalEntries: 1,
			issues: Object.freeze([
				dataIssue(
					"agentic-memory.application-prior-evidence.invalid",
					"application prior evidence entries length could not be read",
					{ severity: "error" },
				),
			]),
		};
	}
	const entries: AgenticMemoryRecordApplicationEvidence[] = [];
	const issues: DataIssue[] = [];
	let invalidEntries = 0;
	for (let index = 0; index < length; index += 1) {
		try {
			if (!Object.hasOwn(rawEntries, index)) {
				throw new TypeError("prior evidence entries must be dense");
			}
			const validation = validateApplicationEvidence(rawEntries[index], index);
			if (validation.evidence === undefined) {
				invalidEntries += 1;
				issues.push(...validation.issues);
				continue;
			}
			entries.push(validation.evidence);
		} catch (error) {
			invalidEntries += 1;
			issues.push(
				dataIssue(
					"agentic-memory.application-prior-evidence.invalid-entry",
					`application prior evidence entry access failed: ${errorMessage(error)}`,
					{ severity: "error", path: [index] },
				),
			);
		}
	}
	return {
		entries: Object.freeze(entries),
		invalidEntries,
		totalEntries: length,
		issues: Object.freeze(issues),
		...(sourceRefs === undefined ? {} : { sourceRefs }),
		...(policyRefs === undefined ? {} : { policyRefs }),
		...(metadata === undefined ? {} : { metadata }),
	};
}

function validateApplicationDecisionCommon(
	decision: AgenticMemoryRecordApplicationDecision<unknown>,
): readonly string[] {
	const validationErrors = [
		...dataRecordContainerErrors(decision, "decision"),
		...forbiddenAgenticMemoryDataFields(decision as unknown as Record<string, unknown>, "decision"),
	];
	if (decision.kind !== "agentic-memory-record-application-decision") {
		validationErrors.push("decision.kind must be agentic-memory-record-application-decision");
	}
	for (const field of ["applicationId", "admissionId", "proposalId"] as const) {
		if (!isNonEmptyString(decision[field])) {
			validationErrors.push(`decision.${field} must be non-empty`);
		}
	}
	if (!isApplicationOperation(decision.operation)) {
		validationErrors.push("decision.operation must be create, replace, or update");
	}
	if (decision.operationVersion !== AGENTIC_MEMORY_RECORD_APPLICATION_OPERATION_VERSION) {
		validationErrors.push("decision.operationVersion must be 1");
	}
	if (
		decision.state !== "applied" &&
		decision.state !== "skipped" &&
		decision.state !== "rejected"
	) {
		validationErrors.push("decision.state must be applied, skipped, or rejected");
	}
	if (!isNonEmptyString(decision.reasonCode)) {
		validationErrors.push("decision.reasonCode must be non-empty");
	}
	if (!isPlainRecord(decision.candidateMaterial)) {
		validationErrors.push("decision.candidateMaterial must be an object");
	}
	const record = decision.candidateMaterial?.record;
	if (!isPlainRecord(record) || !isNonEmptyString(record.id)) {
		validationErrors.push("decision.candidateMaterial.record.id must be non-empty");
	}
	const fragment = isPlainRecord(record) ? record.fragment : undefined;
	if (!isPlainRecord(fragment) || !isNonEmptyString(fragment.id)) {
		validationErrors.push("decision.candidateMaterial.record.fragment.id must be non-empty");
	}
	for (const [field, refs] of [
		["sourceRefs", decision.sourceRefs],
		["policyRefs", decision.policyRefs],
		["evidenceRefs", decision.evidenceRefs],
	] as const) {
		if (refs !== undefined) {
			validationErrors.push(
				...validateAgenticMemoryFactRefs(refs).map((error) => `decision.${field}: ${error}`),
			);
		}
	}
	return Object.freeze(validationErrors);
}

function validateApplicationEvidence(
	value: unknown,
	index: number,
): {
	readonly evidence?: AgenticMemoryRecordApplicationEvidence;
	readonly issues: readonly DataIssue[];
} {
	if (!isPlainRecord(value)) {
		return {
			issues: [
				dataIssue(
					"agentic-memory.application-prior-evidence.invalid-entry",
					"evidence must be an object",
					{ severity: "error", path: [index] },
				),
			],
		};
	}
	const validationErrors = [
		...dataRecordContainerErrors(value, "evidence"),
		...forbiddenAgenticMemoryDataFields(value, "evidence"),
	];
	if (value.kind !== "agentic-memory-record-application-evidence") {
		validationErrors.push("evidence.kind must be agentic-memory-record-application-evidence");
	}
	if (!isApplicationOperation(value.operation)) {
		validationErrors.push("evidence.operation must be create, replace, or update");
	}
	if (value.operationVersion !== AGENTIC_MEMORY_RECORD_APPLICATION_OPERATION_VERSION) {
		validationErrors.push("evidence.operationVersion must be 1");
	}
	for (const field of [
		"applicationId",
		"admissionId",
		"proposalId",
		"idempotencyKey",
		"recordId",
		"fragmentId",
		"targetRecordId",
	] as const) {
		if (value[field] !== undefined && !isNonEmptyString(value[field])) {
			validationErrors.push(`evidence.${field} must be non-empty when present`);
		}
	}
	if (!isNonEmptyString(value.admissionId)) {
		validationErrors.push("evidence.admissionId must be non-empty");
	}
	if (!isNonEmptyString(value.recordId)) {
		validationErrors.push("evidence.recordId must be non-empty");
	}
	if (!isNonEmptyString(value.fragmentId)) {
		validationErrors.push("evidence.fragmentId must be non-empty");
	}
	if (
		(value.operation === "replace" || value.operation === "update") &&
		value.targetRecordId === undefined
	) {
		validationErrors.push(`${value.operation} evidence.targetRecordId must be present`);
	}
	if (
		isNonEmptyString(value.recordId) &&
		isNonEmptyString(value.targetRecordId) &&
		value.targetRecordId !== value.recordId
	) {
		validationErrors.push("evidence.targetRecordId must equal recordId when present");
	}
	const materialIdentity = validateApplicationMaterialIdentity(
		value.materialIdentity,
		"evidence.materialIdentity",
		validationErrors,
		{
			operation: isApplicationOperation(value.operation) ? value.operation : undefined,
			operationVersion: value.operationVersion === 1 ? 1 : undefined,
			recordId: isNonEmptyString(value.recordId) ? value.recordId : undefined,
			fragmentId: isNonEmptyString(value.fragmentId) ? value.fragmentId : undefined,
			targetRecordId: isNonEmptyString(value.targetRecordId)
				? value.targetRecordId
				: isNonEmptyString(value.recordId)
					? value.recordId
					: undefined,
		},
	);
	for (const [field, refs] of [
		["sourceRefs", value.sourceRefs],
		["policyRefs", value.policyRefs],
		["evidenceRefs", value.evidenceRefs],
	] as const) {
		if (refs !== undefined) {
			validationErrors.push(
				...validateAgenticMemoryFactRefs(refs).map((error) => `evidence.${field}: ${error}`),
			);
		}
	}
	const metadata = snapshotMetadata(value.metadata, "evidence.metadata", validationErrors);
	if (validationErrors.length > 0 || materialIdentity === undefined) {
		return {
			issues: [
				dataIssue(
					"agentic-memory.application-prior-evidence.invalid-entry",
					"evidence is invalid",
					{ severity: "error", path: [index], refs: validationErrors },
				),
			],
		};
	}
	return {
		evidence: Object.freeze({
			kind: "agentic-memory-record-application-evidence",
			...(value.applicationId === undefined
				? {}
				: { applicationId: value.applicationId as FactId }),
			admissionId: value.admissionId as FactId,
			...(value.proposalId === undefined ? {} : { proposalId: value.proposalId as FactId }),
			operation: value.operation as AgenticMemoryRecordApplicationOperation,
			operationVersion: AGENTIC_MEMORY_RECORD_APPLICATION_OPERATION_VERSION,
			...(value.idempotencyKey === undefined
				? {}
				: { idempotencyKey: value.idempotencyKey as string }),
			recordId: value.recordId as FactId,
			fragmentId: value.fragmentId as FactId,
			...(value.targetRecordId === undefined
				? {}
				: { targetRecordId: value.targetRecordId as FactId }),
			materialIdentity,
			...(value.sourceRefs === undefined
				? {}
				: { sourceRefs: snapshotAgenticMemoryFactRefs(value.sourceRefs) }),
			...(value.policyRefs === undefined
				? {}
				: { policyRefs: snapshotAgenticMemoryFactRefs(value.policyRefs) }),
			...(value.evidenceRefs === undefined
				? {}
				: { evidenceRefs: snapshotAgenticMemoryFactRefs(value.evidenceRefs) }),
			...(metadata === undefined ? {} : { metadata }),
		}),
		issues: [],
	};
}

function aggregateEvidence(entries: readonly AgenticMemoryRecordApplicationEvidence[]): {
	readonly entries: readonly AgenticMemoryRecordApplicationEvidence[];
	readonly issues: readonly DataIssue[];
	readonly audit: readonly AgenticMemoryRecordApplicationEvidenceProjectionAuditEntry[];
	readonly duplicates: number;
} {
	const out: AgenticMemoryRecordApplicationEvidence[] = [];
	const seenExact = new Set<string>();
	const byAdmission = new Map<FactId, AgenticMemoryRecordApplicationEvidence[]>();
	const byIdempotency = new Map<string, AgenticMemoryRecordApplicationEvidence[]>();
	const issues: DataIssue[] = [];
	const audit: AgenticMemoryRecordApplicationEvidenceProjectionAuditEntry[] = [];
	let duplicates = 0;
	for (const entry of entries) {
		const exactKey = evidenceExactKey(entry);
		if (seenExact.has(exactKey)) {
			duplicates += 1;
			audit.push(
				auditEntry("duplicate-suppressed", {
					admissionId: entry.admissionId,
					proposalId: entry.proposalId,
					applicationId: entry.applicationId,
				}),
			);
			continue;
		}
		seenExact.add(exactKey);
		const admissionEntries = byAdmission.get(entry.admissionId) ?? [];
		const conflictingAdmission = admissionEntries.find((candidate) =>
			evidenceConflict(candidate, entry),
		);
		if (conflictingAdmission !== undefined) {
			issues.push(
				dataIssue(
					"agentic-memory.application-prior-evidence.conflicting-admission-evidence",
					"application prior evidence reuses admissionId with conflicting material",
					{ severity: "error", subjectId: entry.admissionId },
				),
			);
		}
		admissionEntries.push(entry);
		byAdmission.set(entry.admissionId, admissionEntries);
		if (entry.idempotencyKey !== undefined) {
			const idempotencyEntries = byIdempotency.get(entry.idempotencyKey) ?? [];
			const conflictingIdempotency = idempotencyEntries.find((candidate) =>
				evidenceConflict(candidate, entry),
			);
			if (conflictingIdempotency !== undefined) {
				issues.push(
					dataIssue(
						"agentic-memory.application-prior-evidence.conflicting-idempotency-evidence",
						"application prior evidence reuses idempotencyKey with conflicting material",
						{ severity: "error", subjectId: entry.idempotencyKey, refs: [entry.admissionId] },
					),
				);
			}
			idempotencyEntries.push(entry);
			byIdempotency.set(entry.idempotencyKey, idempotencyEntries);
		}
		out.push(entry);
		audit.push(
			auditEntry("prior-evidence-projected", {
				admissionId: entry.admissionId,
				proposalId: entry.proposalId,
				applicationId: entry.applicationId,
				sourceRefs: entry.sourceRefs,
				policyRefs: entry.policyRefs,
			}),
		);
	}
	return {
		entries: Object.freeze(out),
		issues: Object.freeze(issues),
		audit: Object.freeze(audit),
		duplicates,
	};
}

function validateApplicationMaterialIdentity(
	value: unknown,
	label: string,
	validationErrors: string[],
	context: {
		readonly operation?: AgenticMemoryRecordApplicationOperation;
		readonly operationVersion?: 1;
		readonly recordId?: FactId;
		readonly fragmentId?: FactId;
		readonly targetRecordId?: FactId;
	},
): AgenticMemoryRecordApplicationEvidence["materialIdentity"] | undefined {
	if (!isPlainRecord(value)) {
		validationErrors.push(`${label} must be an object`);
		return undefined;
	}
	validationErrors.push(
		...dataRecordContainerErrors(value, label),
		...forbiddenAgenticMemoryDataFields(value, label),
	);
	const extraFields = unexpectedFields(value, ["algorithm", "key"]);
	if (extraFields.length > 0) {
		validationErrors.push(`${label} has unexpected fields: ${extraFields.join(", ")}`);
	}
	if (value.algorithm !== AGENTIC_MEMORY_RECORD_APPLICATION_MATERIAL_IDENTITY_ALGORITHM) {
		validationErrors.push(
			`${label}.algorithm must be ${AGENTIC_MEMORY_RECORD_APPLICATION_MATERIAL_IDENTITY_ALGORITHM}`,
		);
	}
	if (!isNonEmptyString(value.key)) {
		validationErrors.push(`${label}.key must be a non-empty string`);
	}
	if (isNonEmptyString(value.key)) {
		validateApplicationMaterialIdentityKey(value.key, label, context, validationErrors);
	}
	if (
		value.algorithm !== AGENTIC_MEMORY_RECORD_APPLICATION_MATERIAL_IDENTITY_ALGORITHM ||
		!isNonEmptyString(value.key) ||
		extraFields.length > 0
	) {
		return undefined;
	}
	return Object.freeze({
		algorithm: AGENTIC_MEMORY_RECORD_APPLICATION_MATERIAL_IDENTITY_ALGORITHM,
		key: value.key,
	});
}

function validateApplicationMaterialIdentityKey(
	key: string,
	label: string,
	context: {
		readonly operation?: AgenticMemoryRecordApplicationOperation;
		readonly operationVersion?: 1;
		readonly recordId?: FactId;
		readonly fragmentId?: FactId;
		readonly targetRecordId?: FactId;
	},
	validationErrors: string[],
): void {
	let decoded: unknown;
	try {
		decoded = strictJsonCodec.decode(textEncoder.encode(key));
	} catch (error) {
		validationErrors.push(`${label}.key must be canonical strict JSON: ${errorMessage(error)}`);
		return;
	}
	if (!isPlainRecord(decoded)) {
		validationErrors.push(`${label}.key frame must be an object`);
		return;
	}
	const frame = decoded as Record<string, unknown>;
	const extraFields = unexpectedFields(frame, [
		"format",
		"operation",
		"operationVersion",
		"record",
		"targetRecordId",
		"version",
	]);
	if (extraFields.length > 0) {
		validationErrors.push(`${label}.key frame has unexpected fields: ${extraFields.join(", ")}`);
	}
	if (frame.format !== AGENTIC_MEMORY_RECORD_APPLICATION_MATERIAL_FRAME_FORMAT) {
		validationErrors.push(`${label}.key frame format is invalid`);
	}
	if (frame.version !== 1) {
		validationErrors.push(`${label}.key frame version must be 1`);
	}
	if (!isApplicationOperation(frame.operation)) {
		validationErrors.push(`${label}.key frame operation must be create, replace, or update`);
	} else if (context.operation !== undefined && frame.operation !== context.operation) {
		validationErrors.push(`${label}.key frame operation must match evidence.operation`);
	}
	if (frame.operationVersion !== 1) {
		validationErrors.push(`${label}.key frame operationVersion must be 1`);
	} else if (
		context.operationVersion !== undefined &&
		frame.operationVersion !== context.operationVersion
	) {
		validationErrors.push(
			`${label}.key frame operationVersion must match evidence.operationVersion`,
		);
	}
	if (!isNonEmptyString(frame.targetRecordId)) {
		validationErrors.push(`${label}.key frame targetRecordId must be non-empty`);
	} else if (
		context.targetRecordId !== undefined &&
		frame.targetRecordId !== context.targetRecordId
	) {
		validationErrors.push(`${label}.key frame targetRecordId must match evidence target`);
	}
	try {
		const recordFrame = assertAgenticMemoryRecordFrame(frame.record);
		if (context.recordId !== undefined && recordFrame.record.id !== context.recordId) {
			validationErrors.push(`${label}.key frame record.id must match evidence.recordId`);
		}
		if (context.fragmentId !== undefined && recordFrame.record.fragment.id !== context.fragmentId) {
			validationErrors.push(`${label}.key frame record.fragment.id must match evidence.fragmentId`);
		}
	} catch (error) {
		validationErrors.push(`${label}.key frame record is invalid: ${errorMessage(error)}`);
	}
}

function evidenceConflict(
	a: AgenticMemoryRecordApplicationEvidence,
	b: AgenticMemoryRecordApplicationEvidence,
): boolean {
	if (!evidenceScopesOverlap(a, b)) return false;
	return (
		evidenceCoordinateKey(a) !== evidenceCoordinateKey(b) ||
		a.materialIdentity.key !== b.materialIdentity.key
	);
}

function evidenceScopesOverlap(
	a: AgenticMemoryRecordApplicationEvidence,
	b: AgenticMemoryRecordApplicationEvidence,
): boolean {
	return (
		a.applicationId === undefined ||
		b.applicationId === undefined ||
		a.applicationId === b.applicationId
	);
}

function evidenceExactKey(evidence: AgenticMemoryRecordApplicationEvidence): string {
	return canonicalTupleKey([
		evidence.applicationId ?? "",
		evidence.admissionId,
		evidence.proposalId ?? "",
		evidence.idempotencyKey ?? "",
		evidenceCoordinateKey(evidence),
		evidence.materialIdentity.key,
	]);
}

function evidenceCoordinateKey(evidence: AgenticMemoryRecordApplicationEvidence): string {
	return canonicalTupleKey([
		evidence.operation,
		String(evidence.operationVersion),
		evidence.recordId,
		evidence.fragmentId,
		evidence.targetRecordId ?? evidence.recordId,
	]);
}

function evidenceCursor(
	input: AgenticMemoryRecordApplicationPriorEvidenceCursor,
): AgenticMemoryRecordApplicationPriorEvidenceCursor {
	return Object.freeze({
		evaluation: input.evaluation ?? 0,
		applicationDecisions: input.applicationDecisions,
		appliedDecisions: input.appliedDecisions,
		skippedDecisions: input.skippedDecisions,
		rejectedDecisions: input.rejectedDecisions,
		evidenceFacts: input.evidenceFacts,
		validEvidenceFacts: input.validEvidenceFacts,
		invalidEvidenceFacts: input.invalidEvidenceFacts,
		duplicateEvidenceFacts: input.duplicateEvidenceFacts,
		issues: input.issues,
	});
}

function evidenceStatus(
	cursor: AgenticMemoryRecordApplicationPriorEvidenceCursor,
): AgenticMemoryRecordApplicationEvidenceProjectionStatus {
	const state =
		cursor.issues > 0 && cursor.validEvidenceFacts === 0
			? "error"
			: cursor.issues > 0
				? "partial"
				: cursor.evidenceFacts === 0 && cursor.applicationDecisions === 0
					? "empty"
					: cursor.validEvidenceFacts === 0 &&
							(cursor.skippedDecisions > 0 || cursor.rejectedDecisions > 0)
						? "blocked"
						: "ready";
	return Object.freeze({ state, cursor });
}

function auditEntry(
	action: AgenticMemoryRecordApplicationEvidenceProjectionAuditEntry["action"],
	fields: Omit<AgenticMemoryRecordApplicationEvidenceProjectionAuditEntry, "kind" | "action"> = {},
): AgenticMemoryRecordApplicationEvidenceProjectionAuditEntry {
	return Object.freeze({
		kind: "agentic-memory-record-application-evidence-projection-audit",
		action,
		...fields,
	});
}

function isApplicationOperation(value: unknown): value is AgenticMemoryRecordApplicationOperation {
	return value === "create" || value === "replace" || value === "update";
}

function dataRecordContainerErrors(value: unknown, label: string): readonly string[] {
	if (!isPlainRecord(value)) return [`${label} must be an object when present`];
	const errors: string[] = [];
	const proto = Object.getPrototypeOf(value);
	if (proto !== Object.prototype && proto !== null) {
		errors.push(`${label} must be a plain data object`);
	}
	if (Object.getOwnPropertySymbols(value).length > 0) {
		errors.push(`${label} must not carry symbol keys`);
	}
	for (const key of Object.getOwnPropertyNames(value)) {
		const descriptor = Object.getOwnPropertyDescriptor(value, key);
		if (descriptor === undefined) continue;
		if ("get" in descriptor || "set" in descriptor) {
			errors.push(`${label}.${key} must be a data property`);
		}
	}
	return errors;
}

function unexpectedFields(
	value: Record<string, unknown>,
	expected: readonly string[],
): readonly string[] {
	const allowed = new Set(expected);
	return Object.keys(value)
		.filter((key) => !allowed.has(key))
		.sort();
}

function snapshotMetadata(
	value: unknown,
	label: string,
	errors: string[],
): Readonly<Record<string, StrictJsonValue>> | undefined {
	if (value === undefined) return undefined;
	if (!isPlainRecord(value)) {
		errors.push(`${label} must be a strict JSON object`);
		return undefined;
	}
	try {
		return cloneStrictJsonObject(value);
	} catch {
		errors.push(`${label} must be a strict JSON object`);
		return undefined;
	}
}

function snapshotFactRefs(
	value: unknown,
	label: string,
	errors: string[],
): readonly AgenticMemoryFactRef[] | undefined {
	const validationErrors = validateAgenticMemoryFactRefs(value);
	if (validationErrors.length > 0) {
		errors.push(...validationErrors.map((error) => `${label}: ${error}`));
		return undefined;
	}
	return snapshotAgenticMemoryFactRefs(value);
}

function dataIssue(
	code: string,
	message: string,
	fields: Omit<DataIssue, "kind" | "code" | "message" | "source"> = {},
): DataIssue {
	return Object.freeze({
		kind: "issue",
		source: "agentic-memory",
		code,
		message,
		...fields,
	});
}

/**
 * Browser-only AgenticMemory committed fact-log reference backends (D594).
 *
 * Import from `@graphrefly/ts/solutions/agentic-memory/browser`; the universal
 * AgenticMemory barrels stay browser-safe without exposing concrete backends.
 */

/// <reference lib="dom" />

import {
	assertCommittedFactStreamIntegrity,
	committedFactBatchDisposition,
	committedFactReadWindow,
} from "../../committed-facts/internal.js";
import type { DataIssue } from "../../data/index.js";
import {
	type IndexedDbAppendLogOptions,
	type IndexedDbBackendSpec,
	indexedDbAppendLog,
} from "../../storage/browser.js";
import {
	AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND,
	type AgenticMemoryCommittedFact,
	type AgenticMemoryCommittedFactBatch,
	type AgenticMemoryCommittedFactCursor,
	type AgenticMemoryFactLogAuditEntry,
	agenticMemoryCommittedFactBatchCodec,
	assertAgenticMemoryCommittedFactBatch,
} from "./committed-fact-log.js";
import {
	type AgenticMemoryCommittedFactLogBackend,
	type AgenticMemoryCommittedFactLogBackendAppendResult,
	type AgenticMemoryCommittedFactLogBackendReadResult,
	agenticMemoryCommittedFactLogBackendCursor,
	agenticMemoryCommittedFactLogBackendStatus,
} from "./committed-fact-log-backend.js";
import type { StrictJsonValue } from "./types.js";

const DEFAULT_PREFIX = "agentic-memory-committed-fact-log";
const BACKEND_ID = "indexeddb-agentic-memory-committed-fact-log";

export interface IndexedDbAgenticMemoryCommittedFactLogBackendOptions<
	TJson extends StrictJsonValue = StrictJsonValue,
> extends Omit<IndexedDbAppendLogOptions<AgenticMemoryCommittedFactBatch<TJson>>, "codec"> {
	/** Diagnostic backend name. It is DATA/audit only, never a fact-stream cursor. */
	readonly backendName?: string;
}

/** Create a browser IndexedDB-backed D594 single-writer committed fact-log backend.
 *
 * The backend implements the D592 adapter contract directly. It appends each
 * canonical D589 committed fact batch as one strict JSON IndexedDB append-log
 * entry so a readable committed stream never exposes a partial batch. Browser
 * transaction completion is treated as a physical adapter durability attempt,
 * not an application acknowledgement, live graph truth, graph commit barrier,
 * fsync promise, or rollback authority. IndexedDB keys and storage cursors are
 * reported only through backend diagnostic DATA; fact-log cursors are computed
 * from committed fact-stream positions and never from IndexedDB keys, row ids,
 * or IDB cursors. The backend serializes calls made through one backend handle,
 * and requires host-enforced single-writer discipline for the same database,
 * object store, and prefix; it does not claim multi-tab or multi-handle writer
 * correctness.
 *
 * This helper does not materialize records, replay facts into application state,
 * hydrate/restore graphs, refresh subscribers, acknowledge applications, mutate
 * live graph truth, or create a graph commit barrier.
 *
 * @param spec - IndexedDB database and object-store specification owned by the host.
 * @param opts - Optional append-log prefix and diagnostic backend name.
 * @returns A D592 committed fact-log backend.
 * @category solutions
 * @example
 * ```ts
 * import { indexedDbAgenticMemoryCommittedFactLogBackend } from "@graphrefly/ts/solutions/agentic-memory/browser";
 *
 * const backend = indexedDbAgenticMemoryCommittedFactLogBackend({
 *   dbName: "agentic-memory",
 *   storeName: "committed-facts",
 * });
 * ```
 */
export function indexedDbAgenticMemoryCommittedFactLogBackend<
	TJson extends StrictJsonValue = StrictJsonValue,
>(
	spec: IndexedDbBackendSpec,
	opts: IndexedDbAgenticMemoryCommittedFactLogBackendOptions<TJson> = {},
): AgenticMemoryCommittedFactLogBackend<TJson> {
	const backendName = normalizeBackendName(opts.backendName);
	const prefix = opts.prefix ?? DEFAULT_PREFIX;
	const log = indexedDbAppendLog<AgenticMemoryCommittedFactBatch<TJson>>(spec, {
		...opts,
		prefix,
		codec: agenticMemoryCommittedFactBatchCodec<TJson>(),
	});
	let tail: PromiseLike<unknown> | undefined;

	function enqueue<R>(task: () => R | PromiseLike<R>): R | PromiseLike<R> {
		const run = tail === undefined ? task() : tail.then(task, task);
		if (isPromiseLike(run)) {
			tail = run.then(
				() => undefined,
				() => undefined,
			);
		}
		return run;
	}

	const status = () =>
		agenticMemoryCommittedFactLogBackendStatus("available", {
			backend: backendName,
			capabilities: [
				capability("single-writer", true, {
					mode: "host-enforced-single-writer-for-database-store-prefix",
					dbName: spec.dbName,
					storeName: spec.storeName,
					prefix,
					note: "This handle serializes its own calls; hosts must not run competing writers for the same database/store/prefix",
				}),
				capability("whole-batch-visibility", true, {
					storageEntry: "one committed fact batch per IndexedDB append-log entry",
				}),
				capability("browser-transaction-attempt", true, {
					reason:
						"IndexedDB transaction completion is a physical adapter durability attempt, not a graph commit barrier or fsync guarantee",
				}),
				capability("multi-writer-correctness", false, {
					reason: "D594 IndexedDB reference backend is single-writer",
				}),
				capability("fsync-guarantee", false, {
					reason:
						"browser transaction completion is not claimed as a D589 fsync or permanent durability guarantee",
				}),
			],
		});

	return {
		kind: "agentic-memory-committed-fact-log-backend",
		status,
		append(batch) {
			return enqueue(() => appendCore(batch));
		},
		read(opts = {}) {
			return enqueue(() => readCore(opts));
		},
	};

	function appendCore(
		batch: AgenticMemoryCommittedFactBatch<TJson>,
	):
		| AgenticMemoryCommittedFactLogBackendAppendResult
		| PromiseLike<AgenticMemoryCommittedFactLogBackendAppendResult> {
		let canonical: AgenticMemoryCommittedFactBatch<TJson>;
		try {
			canonical = assertAgenticMemoryCommittedFactBatch<TJson>(batch);
		} catch (error) {
			return appendResult("rejected", factCursor(0), 0, {
				issues: [
					issue("agentic-memory.fact-log-backend.indexeddb.invalid-batch", errorMessage(error)),
				],
			});
		}

		return readAllFacts().then(
			(existing) => {
				const cursorBefore = factCursor(existing.length);
				const disposition = committedFactBatchDisposition(existing, canonical.facts);
				switch (disposition.kind) {
					case "internal-conflict":
						return appendResult("conflict", cursorBefore, 0, {
							issues: [
								issue(
									"agentic-memory.fact-log-backend.indexeddb.internal-identity-conflict",
									"committed fact batch reuses one identity with different material",
									"error",
									disposition.identity,
								),
							],
						});
					case "internal-duplicate":
						return appendResult("rejected", cursorBefore, 0, {
							issues: [
								issue(
									"agentic-memory.fact-log-backend.indexeddb.internal-duplicate-identity",
									"committed fact batch repeats one identity; submit each fact identity once per batch",
									"error",
									disposition.identity,
								),
							],
						});
					case "conflict":
						return appendResult("conflict", cursorBefore, 0, {
							issues: [
								issue(
									"agentic-memory.fact-log-backend.indexeddb.identity-conflict",
									"committed fact identity was reused with different material",
									"error",
									disposition.identity,
								),
							],
						});
					case "duplicate":
						return appendResult("duplicate", cursorBefore, 0);
					case "partial-overlap":
						return appendResult("rejected", cursorBefore, 0, {
							issues: [
								issue(
									"agentic-memory.fact-log-backend.indexeddb.batch-overlaps-committed-log",
									"committed fact batch partially overlaps existing facts; retry by reading the stream cursor",
								),
							],
						});
					case "append":
						break;
				}

				return log.append(canonical).then(
					(entry) => {
						const cursor = factCursor(existing.length + canonical.facts.length);
						return appendResult("committed", cursor, canonical.facts.length, {
							backendCursor: agenticMemoryCommittedFactLogBackendCursor(backendName, {
								indexedDbKey: entry.key,
								appendLogSeq: entry.seq,
							}),
							backendStatus: status(),
							audit: [
								factLogAudit("batch-committed", {
									cursor,
									reason: "IndexedDB append-log entry committed as a whole batch",
								}),
							],
						});
					},
					(error) =>
						appendResult("uncertain", cursorBefore, 0, {
							issues: [
								issue(
									"agentic-memory.fact-log-backend.indexeddb.append-uncertain",
									`physical IndexedDB append outcome cannot be proven: ${errorMessage(error)}`,
									"error",
									canonical.batchIdentity.key,
								),
							],
							backendStatus: agenticMemoryCommittedFactLogBackendStatus("degraded", {
								backend: backendName,
								issues: [
									issue(
										"agentic-memory.fact-log-backend.indexeddb.append-uncertain",
										errorMessage(error),
									),
								],
							}),
						}),
				);
			},
			(error) =>
				appendResult("uncertain", factCursor(0), 0, {
					issues: [
						issue(
							"agentic-memory.fact-log-backend.indexeddb.precondition-read-failed",
							`could not prove preconditions before append: ${errorMessage(error)}`,
						),
					],
					backendStatus: agenticMemoryCommittedFactLogBackendStatus("degraded", {
						backend: backendName,
						issues: [
							issue(
								"agentic-memory.fact-log-backend.indexeddb.precondition-read-failed",
								errorMessage(error),
							),
						],
					}),
				}),
		);
	}

	function readCore(
		opts: Parameters<AgenticMemoryCommittedFactLogBackend<TJson>["read"]>[0] = {},
	):
		| AgenticMemoryCommittedFactLogBackendReadResult<TJson>
		| PromiseLike<AgenticMemoryCommittedFactLogBackendReadResult<TJson>> {
		const rawAfter = Object.hasOwn(opts, "after")
			? (opts as { readonly after?: unknown }).after
			: factCursor(0);
		const afterIssue = validateFactCursor(rawAfter);
		if (afterIssue !== undefined) {
			return readResult([], factCursor(0), false, {
				issues: [afterIssue],
				backendStatus: status(),
			});
		}
		const after = rawAfter as AgenticMemoryCommittedFactCursor;
		const limit = opts.limit ?? Number.POSITIVE_INFINITY;
		if (limit !== Number.POSITIVE_INFINITY && (!Number.isSafeInteger(limit) || limit < 0)) {
			return readResult([], after, false, {
				issues: [
					issue(
						"agentic-memory.fact-log-backend.indexeddb.invalid-read-limit",
						"read limit must be a non-negative safe integer or Infinity",
					),
				],
				backendStatus: status(),
			});
		}
		return log.read().then(
			(entries) => {
				try {
					const facts = flattenBatches(entries.map((entry) => entry.value));
					if (after.position > facts.length) {
						return readResult([], after, false, {
							issues: [
								issue(
									"agentic-memory.fact-log-backend.indexeddb.invalid-fact-cursor",
									"fact cursor is beyond the current stream tail",
								),
							],
							backendStatus: status(),
						});
					}
					const window = committedFactReadWindow(facts, after.position, limit);
					const cursor = factCursor(window.position);
					const lastEntry = entries[entries.length - 1];
					return readResult(window.facts, cursor, window.done, {
						backendCursor:
							lastEntry === undefined
								? undefined
								: agenticMemoryCommittedFactLogBackendCursor(backendName, {
										indexedDbKey: lastEntry.key,
										appendLogSeq: lastEntry.seq,
									}),
						backendStatus: status(),
						audit: [
							factLogAudit("facts-read", {
								cursor,
								reason: "IndexedDB backend returned committed facts in fact-stream order",
							}),
						],
					});
				} catch (error) {
					const storedIssue = issue(
						"agentic-memory.fact-log-backend.indexeddb.invalid-stored-stream",
						errorMessage(error),
					);
					return readResult([], after, false, {
						issues: [storedIssue],
						backendStatus: agenticMemoryCommittedFactLogBackendStatus("degraded", {
							backend: backendName,
							issues: [storedIssue],
						}),
					});
				}
			},
			(error) =>
				readResult([], after, false, {
					issues: [
						issue("agentic-memory.fact-log-backend.indexeddb.read-failed", errorMessage(error)),
					],
					backendStatus: agenticMemoryCommittedFactLogBackendStatus("degraded", {
						backend: backendName,
						issues: [
							issue("agentic-memory.fact-log-backend.indexeddb.read-failed", errorMessage(error)),
						],
					}),
				}),
		);
	}

	function readAllFacts(): PromiseLike<readonly AgenticMemoryCommittedFact<TJson>[]> {
		return log.read().then((entries) => flattenBatches(entries.map((entry) => entry.value)));
	}
}

function flattenBatches<TJson extends StrictJsonValue>(
	batches: readonly AgenticMemoryCommittedFactBatch<TJson>[],
): readonly AgenticMemoryCommittedFact<TJson>[] {
	const facts: AgenticMemoryCommittedFact<TJson>[] = [];
	for (const batch of batches) {
		const canonical = assertAgenticMemoryCommittedFactBatch<TJson>(batch);
		facts.push(...canonical.facts);
	}
	assertCommittedFactStreamIntegrity(facts);
	return Object.freeze(facts);
}

function appendResult(
	status: AgenticMemoryCommittedFactLogBackendAppendResult["status"],
	cursor: AgenticMemoryCommittedFactCursor,
	facts: number,
	opts: {
		readonly issues?: readonly DataIssue[];
		readonly audit?: readonly AgenticMemoryFactLogAuditEntry[];
		readonly backendStatus?: AgenticMemoryCommittedFactLogBackendAppendResult["backendStatus"];
		readonly backendCursor?: AgenticMemoryCommittedFactLogBackendAppendResult["backendCursor"];
	} = {},
): AgenticMemoryCommittedFactLogBackendAppendResult {
	return Object.freeze({
		status,
		cursor,
		facts,
		...(opts.issues === undefined ? {} : { issues: Object.freeze([...opts.issues]) }),
		...(opts.audit === undefined ? {} : { audit: Object.freeze([...opts.audit]) }),
		...(opts.backendStatus === undefined ? {} : { backendStatus: opts.backendStatus }),
		...(opts.backendCursor === undefined ? {} : { backendCursor: opts.backendCursor }),
	});
}

function readResult<TJson extends StrictJsonValue>(
	facts: readonly AgenticMemoryCommittedFact<TJson>[],
	cursor: AgenticMemoryCommittedFactCursor,
	done: boolean,
	opts: {
		readonly issues?: readonly DataIssue[];
		readonly audit?: readonly AgenticMemoryFactLogAuditEntry[];
		readonly backendStatus?: AgenticMemoryCommittedFactLogBackendReadResult<TJson>["backendStatus"];
		readonly backendCursor?: AgenticMemoryCommittedFactLogBackendReadResult<TJson>["backendCursor"];
	} = {},
): AgenticMemoryCommittedFactLogBackendReadResult<TJson> {
	return Object.freeze({
		facts: Object.freeze([...facts]),
		cursor,
		done,
		...(opts.issues === undefined ? {} : { issues: Object.freeze([...opts.issues]) }),
		...(opts.audit === undefined ? {} : { audit: Object.freeze([...opts.audit]) }),
		...(opts.backendStatus === undefined ? {} : { backendStatus: opts.backendStatus }),
		...(opts.backendCursor === undefined ? {} : { backendCursor: opts.backendCursor }),
	});
}

function validateFactCursor(cursor: unknown): DataIssue | undefined {
	if (cursor === null || typeof cursor !== "object") {
		return issue(
			"agentic-memory.fact-log-backend.indexeddb.invalid-fact-cursor",
			"read after cursor must be an AgenticMemory fact-stream cursor",
		);
	}
	const candidate = cursor as Partial<AgenticMemoryCommittedFactCursor>;
	const position = candidate.position;
	if (
		candidate.kind !== AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND ||
		position === undefined ||
		!Number.isSafeInteger(position) ||
		position < 0
	) {
		return issue(
			"agentic-memory.fact-log-backend.indexeddb.invalid-fact-cursor",
			"read after cursor must be an AgenticMemory fact-stream cursor",
		);
	}
	return undefined;
}

function factCursor(position: number): AgenticMemoryCommittedFactCursor {
	return Object.freeze({ kind: AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND, position });
}

function normalizeBackendName(value: string | undefined): string {
	return value === undefined || value.length === 0 ? BACKEND_ID : value;
}

function capability(name: string, supported: boolean, details?: StrictJsonValue) {
	return Object.freeze({
		kind: "agentic-memory-committed-fact-log-backend-capability" as const,
		name,
		supported,
		...(details === undefined ? {} : { details }),
	});
}

function issue(
	code: string,
	message: string,
	severity: DataIssue["severity"] = "error",
	subjectId?: string,
): DataIssue {
	return Object.freeze({
		kind: "issue",
		code,
		message,
		severity,
		...(subjectId === undefined ? {} : { subjectId }),
	});
}

function factLogAudit(
	action: AgenticMemoryFactLogAuditEntry["action"],
	fields: Omit<AgenticMemoryFactLogAuditEntry, "kind" | "action"> = {},
): AgenticMemoryFactLogAuditEntry {
	return Object.freeze({ kind: "agentic-memory-fact-log-audit", action, ...fields });
}

function errorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

function isPromiseLike<T>(value: T | PromiseLike<T>): value is PromiseLike<T> {
	return (
		value !== null &&
		(typeof value === "object" || typeof value === "function") &&
		typeof (value as PromiseLike<T>).then === "function"
	);
}

import type { Graph } from "../../graph/graph.js";
import { memoryRetrievalBundle } from "../../patterns/semantic-memory-graph.js";
import {
	agenticMemoryContextProjection,
	agenticMemoryProjection,
	agenticMemoryRecordProjection,
} from "./projection.js";
import type { AgenticMemoryBundle, AgenticMemoryBundleOptions } from "./types.js";

/**
 * Creates a lower-level agentic memory projection/retrieval bundle.
 *
 * This bundle does not implement D643/D789 record-use authorization. A governed
 * consumer must compose `agenticMemoryRecordUseGateBundle` first, select the
 * exact authorized occurrence matching its query, and pass only that occurrence's
 * `allowedRecords.value` as this bundle's `records` input. Do not erase identity
 * across multiple uses, fill from an unrelated latest value, or add a raw-record edge.
 *
 * @param graph - Graph that owns the created nodes or projector.
 * @param opts - Options that configure the helper.
 * @returns A bundle of graph-visible nodes for the recipe.
 * @category solutions
 * @example
 * ```ts
 * import { agenticMemoryBundle } from "@graphrefly/ts/solutions/agentic-memory";
 * ```
 */
export function agenticMemoryBundle<T = unknown>(
	graph: Graph,
	opts: AgenticMemoryBundleOptions<T>,
): AgenticMemoryBundle<T> {
	const name = opts.name ?? "agenticMemory";
	const projection = agenticMemoryRecordProjection<T>(graph, opts.records, `${name}/projection`);
	const projectedRecords = agenticMemoryProjection(
		graph,
		projection,
		`${name}/records`,
		"agenticMemoryRecords",
		(fact) => fact.records,
	);
	const projectedFragments = agenticMemoryProjection(
		graph,
		projection,
		`${name}/fragments`,
		"agenticMemoryFragments",
		(fact) => fact.fragments,
	);
	const status = agenticMemoryProjection(
		graph,
		projection,
		`${name}/status`,
		"agenticMemoryStatus",
		(fact) => fact.status,
	);
	const errors = agenticMemoryProjection(
		graph,
		projection,
		`${name}/errors`,
		"agenticMemoryErrors",
		(fact) => fact.errors,
	);
	const retrieval = memoryRetrievalBundle<T>(graph, {
		name: `${name}/retrieval`,
		fragments: projectedFragments,
		query: opts.query,
	});
	const sources = agenticMemoryProjection(
		graph,
		projection,
		`${name}/sources`,
		"agenticMemorySources",
		(fact) =>
			Object.freeze(
				fact.fragments.map((fragment) =>
					Object.freeze({
						fragmentId: fragment.id,
						...(fact.metadataByFragmentId[fragment.id] === undefined
							? {}
							: { record: fact.metadataByFragmentId[fragment.id] }),
						sources: Object.freeze([...fragment.sources]),
						...(fragment.parentFragmentId === undefined
							? {}
							: { parentFragmentId: fragment.parentFragmentId }),
						...(fragment.provenance === undefined ? {} : { provenance: fragment.provenance }),
					}),
				),
			),
	);
	const context = agenticMemoryContextProjection(
		graph,
		projection,
		retrieval.snapshot,
		`${name}/context`,
	);

	return {
		input: { records: opts.records, query: opts.query },
		projection,
		retrieval,
		retrievalSnapshot: retrieval.snapshot,
		records: projectedRecords,
		fragments: projectedFragments,
		sources,
		indexed: retrieval.indexed,
		ranked: retrieval.ranked,
		context,
		status,
		errors,
		retrievalStatus: retrieval.status,
		retrievalErrors: retrieval.errors,
		cursor: retrieval.cursor,
	};
}

/**
 * D165 solution-level KG assertion projection.
 *
 * Records and explicit assertion drafts stay visible as declared deps. This
 * bundle validates references and shape, then emits DATA facts only; it does
 * not extract assertions, call LLMs, read/write storage, or mutate topology.
 */

import type { DataIssue } from "../../data/index.js";
import { cloneStrictJsonValue } from "../../json/codec.js";
import {
	AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND,
	type AgenticMemoryCommittedFact,
	type AgenticMemoryCommittedFactBatch,
	type AgenticMemoryCommittedFactCursor,
	type AgenticMemoryCommittedFactLog,
	type AgenticMemoryCommittedFactReadOptions,
	type AgenticMemoryCommittedFactReadResult,
	type AgenticMemoryFactCommitResult,
	type AgenticMemoryFactCommitStatus,
	type AgenticMemoryFactLogAuditEntry,
	assertAgenticMemoryCommittedFact,
	assertAgenticMemoryCommittedFactBatch,
} from "./committed-fact-log.js";
import type { StrictJsonValue } from "./types.js";

export const AGENTIC_MEMORY_COMMITTED_FACT_LOG_BACKEND_CURSOR_KIND =
	"agentic-memory-committed-fact-log-backend.cursor";

export type AgenticMemoryCommittedFactLogBackendStatusState =
	| "available"
	| "degraded"
	| "unavailable"
	| "unknown";

export interface AgenticMemoryCommittedFactLogBackendCursor {
	readonly kind: typeof AGENTIC_MEMORY_COMMITTED_FACT_LOG_BACKEND_CURSOR_KIND;
	readonly backend: string;
	readonly value: StrictJsonValue;
}

export interface AgenticMemoryCommittedFactLogBackendCapability {
	readonly kind: "agentic-memory-committed-fact-log-backend-capability";
	readonly name: string;
	readonly supported: boolean;
	readonly status?: AgenticMemoryCommittedFactLogBackendStatusState;
	readonly details?: StrictJsonValue;
}

export interface AgenticMemoryCommittedFactLogBackendAuditEntry {
	readonly kind: "agentic-memory-committed-fact-log-backend-audit";
	readonly action:
		| "backend-append-attempted"
		| "backend-read-attempted"
		| "backend-result-normalized"
		| "backend-status-reported"
		| "backend-capability-reported"
		| "backend-cursor-reported"
		| "issue-recorded";
	readonly reason?: string;
	readonly backend?: string;
	readonly factLogCursor?: AgenticMemoryCommittedFactCursor;
	readonly backendCursor?: AgenticMemoryCommittedFactLogBackendCursor;
}

export interface AgenticMemoryCommittedFactLogBackendStatus {
	readonly kind: "agentic-memory-committed-fact-log-backend-status";
	readonly state: AgenticMemoryCommittedFactLogBackendStatusState;
	readonly backend?: string;
	readonly capabilities: readonly AgenticMemoryCommittedFactLogBackendCapability[];
	readonly issues: readonly DataIssue[];
	readonly audit: readonly AgenticMemoryCommittedFactLogBackendAuditEntry[];
}

export interface AgenticMemoryCommittedFactLogBackendAppendResult {
	readonly status: AgenticMemoryFactCommitStatus;
	readonly cursor: AgenticMemoryCommittedFactCursor;
	readonly facts: number;
	readonly issues?: readonly DataIssue[];
	readonly audit?: readonly AgenticMemoryFactLogAuditEntry[];
	readonly backendStatus?: AgenticMemoryCommittedFactLogBackendStatus;
	readonly backendCursor?: AgenticMemoryCommittedFactLogBackendCursor;
}

export interface AgenticMemoryCommittedFactLogBackendReadResult<
	TJson extends StrictJsonValue = StrictJsonValue,
> {
	readonly facts: readonly AgenticMemoryCommittedFact<TJson>[];
	readonly cursor: AgenticMemoryCommittedFactCursor;
	readonly done: boolean;
	readonly issues?: readonly DataIssue[];
	readonly audit?: readonly AgenticMemoryFactLogAuditEntry[];
	readonly backendStatus?: AgenticMemoryCommittedFactLogBackendStatus;
	readonly backendCursor?: AgenticMemoryCommittedFactLogBackendCursor;
}

export interface AgenticMemoryCommittedFactLogBackend<
	TJson extends StrictJsonValue = StrictJsonValue,
> {
	readonly kind?: "agentic-memory-committed-fact-log-backend";
	readonly status?:
		| AgenticMemoryCommittedFactLogBackendStatus
		| (() =>
				| AgenticMemoryCommittedFactLogBackendStatus
				| PromiseLike<AgenticMemoryCommittedFactLogBackendStatus>);
	append(
		batch: AgenticMemoryCommittedFactBatch<TJson>,
	):
		| AgenticMemoryCommittedFactLogBackendAppendResult
		| PromiseLike<AgenticMemoryCommittedFactLogBackendAppendResult>;
	read(
		opts?: AgenticMemoryCommittedFactReadOptions,
	):
		| AgenticMemoryCommittedFactLogBackendReadResult<TJson>
		| PromiseLike<AgenticMemoryCommittedFactLogBackendReadResult<TJson>>;
}

/** Build D592 backend status DATA.
 *
 * Backend status is diagnostic DATA only. It does not define protocol
 * semantics, acknowledge application success, mutate records, hydrate/restore
 * graph state, refresh subscribers, or create a graph commit barrier.
 *
 * @param state - Backend availability/status classification.
 * @param opts - Optional backend name, capabilities, issues, and audit entries.
 * @returns A normalized D592 backend status DATA object.
 * @category solutions
 */
export function agenticMemoryCommittedFactLogBackendStatus(
	state: AgenticMemoryCommittedFactLogBackendStatusState,
	opts: {
		readonly backend?: string;
		readonly capabilities?: readonly AgenticMemoryCommittedFactLogBackendCapability[];
		readonly issues?: readonly DataIssue[];
		readonly audit?: readonly AgenticMemoryCommittedFactLogBackendAuditEntry[];
	} = {},
): AgenticMemoryCommittedFactLogBackendStatus {
	validateBackendStatusState(state);
	return Object.freeze({
		kind: "agentic-memory-committed-fact-log-backend-status",
		state,
		...(opts.backend === undefined ? {} : { backend: opts.backend }),
		capabilities: Object.freeze(
			(opts.capabilities ?? []).map((capability) => normalizeCapability(capability)),
		),
		issues: Object.freeze((opts.issues ?? []).map(freezeIssue)),
		audit: Object.freeze((opts.audit ?? []).map(normalizeBackendAudit)),
	});
}

/** Build a D592 backend cursor DATA object.
 *
 * The returned cursor is intentionally not an
 * `AgenticMemoryCommittedFactCursor`; it may be reported through diagnostics
 * or audit DATA, but it must never become a D589 fact-stream cursor.
 *
 * @param backend - Backend identifier.
 * @param value - Backend-owned cursor/offset value.
 * @returns A backend cursor diagnostic DATA object.
 * @category solutions
 */
export function agenticMemoryCommittedFactLogBackendCursor(
	backend: string,
	value: StrictJsonValue,
): AgenticMemoryCommittedFactLogBackendCursor {
	if (!isNonEmptyString(backend)) {
		throw new TypeError("agenticMemoryCommittedFactLogBackendCursor: backend must be non-empty");
	}
	return Object.freeze({
		kind: AGENTIC_MEMORY_COMMITTED_FACT_LOG_BACKEND_CURSOR_KIND,
		backend,
		value: cloneStrictJsonValue(value, "backendCursor.value") as StrictJsonValue,
	});
}

/** Normalize a D592 backend append output into D589 commit result DATA.
 *
 * The normalized result describes committed fact-log persistence only. Backend
 * diagnostics are preserved as issues/audit DATA and never become application
 * acknowledgement, live graph truth, record mutation authority, hot hydration,
 * restore, or a graph commit barrier.
 *
 * @param output - Backend-supplied append output.
 * @param opts - Optional fallback fact-stream cursor for malformed outputs.
 * @returns A D589 `AgenticMemoryFactCommitResult`.
 * @category solutions
 */
export function normalizeAgenticMemoryCommittedFactLogBackendAppendResult(
	output: unknown,
	opts: {
		readonly fallbackCursor?: AgenticMemoryCommittedFactCursor;
		readonly expectedFacts?: number;
	} = {},
): AgenticMemoryFactCommitResult {
	const fallbackCursor = freezeFactCursor(opts.fallbackCursor ?? factCursor(0));
	let cloned: unknown;
	try {
		cloned = cloneStrictJsonValue(output, "agenticMemoryCommittedFactLogBackendAppendResult");
	} catch (error) {
		return appendResult("uncertain", fallbackCursor, 0, [
			issue(
				"agentic-memory.fact-log-backend.invalid-append-result",
				error instanceof Error ? error.message : String(error),
			),
		]);
	}
	if (cloned === null || typeof cloned !== "object" || Array.isArray(cloned)) {
		return appendResult("rejected", fallbackCursor, 0, [
			issue(
				"agentic-memory.fact-log-backend.invalid-append-result",
				"backend append result must be an object",
			),
		]);
	}

	const raw = cloned as Partial<AgenticMemoryCommittedFactLogBackendAppendResult>;
	const issues: DataIssue[] = [];
	const status = isCommitStatus(raw.status) ? raw.status : undefined;
	if (status === undefined) {
		issues.push(
			issue(
				"agentic-memory.fact-log-backend.invalid-append-status",
				"backend append result status is not a D589 commit status",
			),
		);
	}
	const cursor = validateFactCursor(raw.cursor);
	if (cursor === undefined) {
		issues.push(
			issue(
				"agentic-memory.fact-log-backend.invalid-fact-cursor",
				"backend append result cursor must be an AgenticMemory fact-stream cursor",
			),
		);
	}
	const rawFacts = raw.facts;
	const facts =
		typeof rawFacts === "number" && Number.isSafeInteger(rawFacts) && rawFacts >= 0
			? rawFacts
			: undefined;
	if (facts === undefined) {
		issues.push(
			issue(
				"agentic-memory.fact-log-backend.invalid-facts-count",
				"backend append result facts must be a non-negative safe integer",
			),
		);
	}
	if (opts.expectedFacts !== undefined && !isNonNegativeSafeInteger(opts.expectedFacts)) {
		issues.push(
			issue(
				"agentic-memory.fact-log-backend.invalid-expected-facts-count",
				"expected append facts must be a non-negative safe integer",
			),
		);
	}
	const committedFactsMismatch =
		status === "committed" &&
		facts !== undefined &&
		opts.expectedFacts !== undefined &&
		isNonNegativeSafeInteger(opts.expectedFacts) &&
		facts !== opts.expectedFacts;
	if (committedFactsMismatch) {
		issues.push(
			issue(
				"agentic-memory.fact-log-backend.committed-facts-mismatch",
				"backend committed append result must cover the whole submitted fact batch",
				{ details: { expectedFacts: opts.expectedFacts, reportedFacts: facts } },
			),
		);
	}
	const backendStatus = normalizeOptionalBackendStatus(raw.backendStatus, issues);
	issues.push(...normalizeIssues(raw.issues));
	const audit = normalizeFactLogAudit(raw.audit, issues);
	let backendCursor: AgenticMemoryCommittedFactLogBackendCursor | undefined;
	if (raw.backendCursor !== undefined) {
		backendCursor = validateBackendCursor(raw.backendCursor);
		if (backendCursor === undefined) {
			issues.push(
				issue(
					"agentic-memory.fact-log-backend.invalid-backend-cursor",
					"backend cursor must be diagnostic DATA and cannot replace the fact-stream cursor",
				),
			);
		}
	}
	if (backendStatus?.state === "degraded" || backendStatus?.state === "unavailable") {
		issues.push(
			issue("agentic-memory.fact-log-backend.status", `backend status is ${backendStatus.state}`, {
				severity: backendStatus.state === "degraded" ? "warning" : "error",
			}),
		);
	}
	if (backendStatus !== undefined) issues.push(...backendStatus.issues);

	const publicStatus = committedFactsMismatch
		? "uncertain"
		: status === undefined
			? "rejected"
			: (cursor === undefined || facts === undefined) &&
					(status === "committed" || status === "duplicate" || status === "uncertain")
				? "uncertain"
				: status;
	return appendResult(
		publicStatus,
		committedFactsMismatch ? fallbackCursor : (cursor ?? fallbackCursor),
		committedFactsMismatch ? 0 : (facts ?? 0),
		issues,
		[
			...audit,
			...backendDiagnosticAudit("backend-append-normalized", backendStatus, backendCursor),
		],
	);
}

/** Normalize a D592 backend read output into D589 read result DATA.
 *
 * Reads remain stream-ordered committed facts with a D589 fact-stream cursor.
 * Backend cursors/diagnostics are audit or issue DATA only and are never used
 * as fact-log cursors or replay/materialization authority.
 *
 * @param output - Backend-supplied read output.
 * @param opts - Optional fallback fact-stream cursor for malformed outputs.
 * @returns A D589 `AgenticMemoryCommittedFactReadResult`.
 * @category solutions
 */
export function normalizeAgenticMemoryCommittedFactLogBackendReadResult<
	TJson extends StrictJsonValue = StrictJsonValue,
>(
	output: unknown,
	opts: { readonly fallbackCursor?: AgenticMemoryCommittedFactCursor } = {},
): AgenticMemoryCommittedFactReadResult<TJson> {
	const fallbackCursor = freezeFactCursor(opts.fallbackCursor ?? factCursor(0));
	let cloned: unknown;
	try {
		cloned = cloneStrictJsonValue(output, "agenticMemoryCommittedFactLogBackendReadResult");
	} catch (error) {
		return readResult(Object.freeze([]), fallbackCursor, false, [
			issue(
				"agentic-memory.fact-log-backend.invalid-read-result",
				error instanceof Error ? error.message : String(error),
			),
		]);
	}
	if (cloned === null || typeof cloned !== "object" || Array.isArray(cloned)) {
		return readResult(Object.freeze([]), fallbackCursor, false, [
			issue(
				"agentic-memory.fact-log-backend.invalid-read-result",
				"backend read result must be an object",
			),
		]);
	}

	const raw = cloned as Partial<AgenticMemoryCommittedFactLogBackendReadResult<TJson>>;
	const issues: DataIssue[] = [];
	const cursor = validateFactCursor(raw.cursor);
	if (cursor === undefined) {
		issues.push(
			issue(
				"agentic-memory.fact-log-backend.invalid-fact-cursor",
				"backend read result cursor must be an AgenticMemory fact-stream cursor",
			),
		);
	}
	const done = typeof raw.done === "boolean" ? raw.done : undefined;
	if (done === undefined) {
		issues.push(
			issue(
				"agentic-memory.fact-log-backend.invalid-read-done",
				"backend read result done must be boolean",
			),
		);
	}
	const facts: AgenticMemoryCommittedFact<TJson>[] = [];
	if (!Array.isArray(raw.facts)) {
		issues.push(
			issue(
				"agentic-memory.fact-log-backend.invalid-read-facts",
				"backend read result facts must be an array",
			),
		);
	} else {
		for (let index = 0; index < raw.facts.length; index += 1) {
			try {
				facts.push(assertAgenticMemoryCommittedFact<TJson>(raw.facts[index]));
			} catch (error) {
				issues.push(
					issue(
						"agentic-memory.fact-log-backend.invalid-read-fact",
						error instanceof Error ? error.message : String(error),
						{ path: [index] },
					),
				);
			}
		}
	}
	const backendStatus = normalizeOptionalBackendStatus(raw.backendStatus, issues);
	issues.push(...normalizeIssues(raw.issues));
	const audit = normalizeFactLogAudit(raw.audit, issues);
	let backendCursor: AgenticMemoryCommittedFactLogBackendCursor | undefined;
	if (raw.backendCursor !== undefined) {
		backendCursor = validateBackendCursor(raw.backendCursor);
	}
	if (raw.backendCursor !== undefined && backendCursor === undefined) {
		issues.push(
			issue(
				"agentic-memory.fact-log-backend.invalid-backend-cursor",
				"backend cursor must be diagnostic DATA and cannot replace the fact-stream cursor",
			),
		);
	}
	if (backendStatus?.state === "degraded" || backendStatus?.state === "unavailable") {
		issues.push(
			issue("agentic-memory.fact-log-backend.status", `backend status is ${backendStatus.state}`, {
				severity: backendStatus.state === "degraded" ? "warning" : "error",
			}),
		);
	}
	if (backendStatus !== undefined) issues.push(...backendStatus.issues);
	const validFacts = issues.some((item) =>
		item.code.startsWith("agentic-memory.fact-log-backend.invalid-read-fact"),
	)
		? Object.freeze([])
		: Object.freeze(facts);
	const cursorCoversFacts =
		cursor !== undefined && cursor.position >= fallbackCursor.position + validFacts.length;
	if (!cursorCoversFacts) {
		issues.push(
			issue(
				"agentic-memory.fact-log-backend.invalid-read-cursor-coverage",
				"backend read cursor must not regress and must cover returned committed facts",
				{
					details: {
						fallbackPosition: fallbackCursor.position,
						reportedPosition: cursor?.position ?? null,
						facts: validFacts.length,
					},
				},
			),
		);
	}
	return readResult<TJson>(
		cursorCoversFacts ? validFacts : Object.freeze([]),
		cursorCoversFacts ? cursor : fallbackCursor,
		cursorCoversFacts ? (done ?? false) : false,
		issues,
		[...audit, ...backendDiagnosticAudit("backend-read-normalized", backendStatus, backendCursor)],
	);
}

/** Wrap a D592 backend as the existing D589 committed fact-log interface.
 *
 * The wrapper only canonicalizes append input and normalizes backend append/read
 * outputs. It does not add storage semantics, materialize records, replay facts
 * into application state, hydrate/restore graphs, refresh subscribers, or turn a
 * backend result into application acknowledgement or a graph commit barrier.
 *
 * @param backend - Backend implementation for physical append/read attempts.
 * @returns A D589 `AgenticMemoryCommittedFactLog` view over the backend.
 * @category solutions
 */
export function agenticMemoryCommittedFactLogBackendAdapter<
	TJson extends StrictJsonValue = StrictJsonValue,
>(backend: AgenticMemoryCommittedFactLogBackend<TJson>): AgenticMemoryCommittedFactLog<TJson> {
	return {
		append(batch) {
			let canonical: AgenticMemoryCommittedFactBatch<TJson>;
			try {
				canonical = assertAgenticMemoryCommittedFactBatch<TJson>(batch);
			} catch (error) {
				return appendResult("rejected", factCursor(0), 0, [
					issue(
						"agentic-memory.fact-log-backend.invalid-append-batch",
						error instanceof Error ? error.message : String(error),
					),
				]);
			}
			try {
				const out = backend.append(canonical);
				return isPromiseLike(out)
					? out.then(
							(value) => {
								try {
									return normalizeAgenticMemoryCommittedFactLogBackendAppendResult(value, {
										expectedFacts: canonical.facts.length,
									});
								} catch (error) {
									return appendResult("uncertain", factCursor(0), 0, [
										issue(
											"agentic-memory.fact-log-backend.append-normalization-threw",
											error instanceof Error ? error.message : String(error),
										),
									]);
								}
							},
							(error) =>
								appendResult("uncertain", factCursor(0), 0, [
									issue(
										"agentic-memory.fact-log-backend.append-threw",
										error instanceof Error ? error.message : String(error),
									),
								]),
						)
					: normalizeAgenticMemoryCommittedFactLogBackendAppendResult(out, {
							expectedFacts: canonical.facts.length,
						});
			} catch (error) {
				return appendResult("uncertain", factCursor(0), 0, [
					issue(
						"agentic-memory.fact-log-backend.append-threw",
						error instanceof Error ? error.message : String(error),
					),
				]);
			}
		},
		read(opts) {
			const fallback = readFallbackCursor(opts);
			if (fallback.issue !== undefined) {
				return readResult<TJson>(Object.freeze([]), fallback.cursor, false, [fallback.issue]);
			}
			try {
				const out = backend.read(opts);
				return isPromiseLike(out)
					? out.then(
							(value) => {
								try {
									return normalizeAgenticMemoryCommittedFactLogBackendReadResult<TJson>(value, {
										fallbackCursor: fallback.cursor,
									});
								} catch (error) {
									return readResult<TJson>(Object.freeze([]), fallback.cursor, false, [
										issue(
											"agentic-memory.fact-log-backend.read-normalization-threw",
											error instanceof Error ? error.message : String(error),
										),
									]);
								}
							},
							(error) =>
								readResult<TJson>(Object.freeze([]), fallback.cursor, false, [
									issue(
										"agentic-memory.fact-log-backend.read-threw",
										error instanceof Error ? error.message : String(error),
									),
								]),
						)
					: normalizeAgenticMemoryCommittedFactLogBackendReadResult<TJson>(out, {
							fallbackCursor: fallback.cursor,
						});
			} catch (error) {
				return readResult<TJson>(Object.freeze([]), fallback.cursor, false, [
					issue(
						"agentic-memory.fact-log-backend.read-threw",
						error instanceof Error ? error.message : String(error),
					),
				]);
			}
		},
	};
}

function appendResult(
	status: AgenticMemoryFactCommitStatus,
	cursor: AgenticMemoryCommittedFactCursor,
	facts: number,
	issues: readonly DataIssue[],
	extraAudit: readonly AgenticMemoryFactLogAuditEntry[] = [],
): AgenticMemoryFactCommitResult {
	const action: AgenticMemoryFactLogAuditEntry["action"] =
		status === "committed"
			? "batch-committed"
			: status === "duplicate"
				? "batch-duplicate"
				: status === "conflict"
					? "batch-conflict"
					: status === "rejected"
						? "batch-rejected"
						: "batch-uncertain";
	return Object.freeze({
		status,
		cursor: freezeFactCursor(cursor),
		facts,
		issues: Object.freeze(issues.map(freezeIssue)),
		audit: Object.freeze([
			auditEntry(action, { cursor }),
			...extraAudit,
			...issues.map((item) => auditEntry("issue-recorded", { reason: item.code })),
		]),
	});
}

function readResult<TJson extends StrictJsonValue>(
	facts: readonly AgenticMemoryCommittedFact<TJson>[],
	cursor: AgenticMemoryCommittedFactCursor,
	done: boolean,
	issues: readonly DataIssue[],
	extraAudit: readonly AgenticMemoryFactLogAuditEntry[] = [],
): AgenticMemoryCommittedFactReadResult<TJson> {
	return Object.freeze({
		facts: Object.freeze([...facts]),
		cursor: freezeFactCursor(cursor),
		done,
		issues: Object.freeze(issues.map(freezeIssue)),
		audit: Object.freeze([
			auditEntry("facts-read", { cursor, reason: `${facts.length} facts` }),
			...extraAudit,
			...issues.map((item) => auditEntry("issue-recorded", { reason: item.code })),
		]),
	});
}

function backendDiagnosticAudit(
	action: "backend-append-normalized" | "backend-read-normalized",
	status: AgenticMemoryCommittedFactLogBackendStatus | undefined,
	cursor: AgenticMemoryCommittedFactLogBackendCursor | undefined,
): readonly AgenticMemoryFactLogAuditEntry[] {
	const audit: AgenticMemoryFactLogAuditEntry[] = [auditEntry(action)];
	if (status !== undefined) {
		audit.push(
			auditEntry("backend-status-linked", {
				reason: `backend status ${status.state}`,
			}),
		);
		for (const capability of status.capabilities) {
			audit.push(
				auditEntry("backend-capability-linked", {
					reason: `${capability.name}:${capability.supported ? "supported" : "unsupported"}`,
				}),
			);
		}
	}
	if (cursor !== undefined) {
		audit.push(
			auditEntry("backend-cursor-linked", {
				reason: "backend cursor reported as diagnostic DATA, not fact-stream cursor",
			}),
		);
	}
	return Object.freeze(audit);
}

function normalizeOptionalBackendStatus(
	value: AgenticMemoryCommittedFactLogBackendStatus | undefined,
	issues: DataIssue[],
): AgenticMemoryCommittedFactLogBackendStatus | undefined {
	if (value === undefined) return undefined;
	try {
		const cloned = cloneStrictJsonValue(value, "backendStatus");
		if (cloned === null || typeof cloned !== "object" || Array.isArray(cloned)) {
			throw new TypeError("backendStatus must be an object");
		}
		const status = cloned as unknown as AgenticMemoryCommittedFactLogBackendStatus;
		return agenticMemoryCommittedFactLogBackendStatus(status.state, {
			backend: status.backend,
			capabilities: status.capabilities,
			issues: status.issues,
			audit: status.audit,
		});
	} catch (error) {
		issues.push(
			issue(
				"agentic-memory.fact-log-backend.invalid-status",
				error instanceof Error ? error.message : String(error),
			),
		);
		return undefined;
	}
}

function normalizeCapability(
	capability: AgenticMemoryCommittedFactLogBackendCapability,
): AgenticMemoryCommittedFactLogBackendCapability {
	if (capability?.kind !== "agentic-memory-committed-fact-log-backend-capability") {
		throw new TypeError("agenticMemoryCommittedFactLogBackendStatus: invalid capability kind");
	}
	if (!isNonEmptyString(capability.name)) {
		throw new TypeError("agenticMemoryCommittedFactLogBackendStatus: capability name required");
	}
	if (typeof capability.supported !== "boolean") {
		throw new TypeError("agenticMemoryCommittedFactLogBackendStatus: supported must be boolean");
	}
	if (capability.status !== undefined) validateBackendStatusState(capability.status);
	return Object.freeze({
		kind: "agentic-memory-committed-fact-log-backend-capability",
		name: capability.name,
		supported: capability.supported,
		...(capability.status === undefined ? {} : { status: capability.status }),
		...(capability.details === undefined
			? {}
			: {
					details: cloneStrictJsonValue(
						capability.details,
						"capability.details",
					) as StrictJsonValue,
				}),
	});
}

function normalizeBackendAudit(
	entry: AgenticMemoryCommittedFactLogBackendAuditEntry,
): AgenticMemoryCommittedFactLogBackendAuditEntry {
	if (entry?.kind !== "agentic-memory-committed-fact-log-backend-audit") {
		throw new TypeError("agenticMemoryCommittedFactLogBackendStatus: invalid backend audit kind");
	}
	if (!isBackendAuditAction(entry.action)) {
		throw new TypeError("agenticMemoryCommittedFactLogBackendStatus: invalid backend audit action");
	}
	return Object.freeze({
		kind: "agentic-memory-committed-fact-log-backend-audit",
		action: entry.action,
		...(entry.reason === undefined ? {} : { reason: entry.reason }),
		...(entry.backend === undefined ? {} : { backend: entry.backend }),
		...(entry.factLogCursor === undefined
			? {}
			: { factLogCursor: freezeFactCursor(entry.factLogCursor) }),
		...(entry.backendCursor === undefined
			? {}
			: {
					backendCursor: agenticMemoryCommittedFactLogBackendCursor(
						entry.backendCursor.backend,
						entry.backendCursor.value,
					),
				}),
	});
}

function normalizeIssues(values: readonly DataIssue[] | undefined): readonly DataIssue[] {
	if (values === undefined) return Object.freeze([]);
	if (!Array.isArray(values)) {
		return Object.freeze([
			issue("agentic-memory.fact-log-backend.invalid-issues", "backend issues must be an array"),
		]);
	}
	const issues: DataIssue[] = [];
	for (let index = 0; index < values.length; index += 1) {
		try {
			issues.push(freezeIssue(values[index]!));
		} catch (error) {
			issues.push(
				issue(
					"agentic-memory.fact-log-backend.invalid-issues",
					error instanceof Error ? error.message : String(error),
					{ path: [index] },
				),
			);
		}
	}
	return Object.freeze(issues);
}

function normalizeFactLogAudit(
	values: readonly AgenticMemoryFactLogAuditEntry[] | undefined,
	issues: DataIssue[],
): readonly AgenticMemoryFactLogAuditEntry[] {
	if (values === undefined) return Object.freeze([]);
	if (!Array.isArray(values)) {
		issues.push(
			issue("agentic-memory.fact-log-backend.invalid-audit", "backend audit must be an array"),
		);
		return Object.freeze([]);
	}
	const audit: AgenticMemoryFactLogAuditEntry[] = [];
	for (let index = 0; index < values.length; index += 1) {
		try {
			audit.push(freezeFactLogAuditEntry(values[index]!));
		} catch (error) {
			issues.push(
				issue(
					"agentic-memory.fact-log-backend.invalid-audit",
					error instanceof Error ? error.message : String(error),
					{ path: [index] },
				),
			);
		}
	}
	return Object.freeze(audit);
}

function freezeIssue(value: DataIssue): DataIssue {
	if (value?.kind !== "issue") {
		throw new TypeError("AgenticMemory backend issue must have kind issue");
	}
	if (!isNonEmptyString(value.code) || !isNonEmptyString(value.message)) {
		throw new TypeError("AgenticMemory backend issue code/message must be non-empty");
	}
	if (
		value.severity !== undefined &&
		value.severity !== "info" &&
		value.severity !== "warning" &&
		value.severity !== "error"
	) {
		throw new TypeError("AgenticMemory backend issue severity is invalid");
	}
	return Object.freeze({
		kind: "issue",
		code: value.code,
		message: value.message,
		...(value.severity === undefined ? {} : { severity: value.severity }),
		...(value.source === undefined ? {} : { source: requireString(value.source, "issue.source") }),
		...(value.subjectId === undefined
			? {}
			: { subjectId: requireString(value.subjectId, "issue.subjectId") }),
		...(value.correlationId === undefined
			? {}
			: { correlationId: requireString(value.correlationId, "issue.correlationId") }),
		...(value.causationId === undefined
			? {}
			: { causationId: requireString(value.causationId, "issue.causationId") }),
		...(value.path === undefined ? {} : { path: normalizeIssuePath(value.path) }),
		...(value.refs === undefined ? {} : { refs: normalizeIssueRefs(value.refs) }),
		...(value.retryable === undefined
			? {}
			: { retryable: requireBoolean(value.retryable, "issue.retryable") }),
		...(value.details === undefined
			? {}
			: { details: cloneStrictJsonValue(value.details, "issue.details") }),
		...(value.metadata === undefined ? {} : { metadata: normalizeIssueMetadata(value.metadata) }),
	}) as DataIssue;
}

function freezeFactLogAuditEntry(
	entry: AgenticMemoryFactLogAuditEntry,
): AgenticMemoryFactLogAuditEntry {
	if (entry?.kind !== "agentic-memory-fact-log-audit") {
		throw new TypeError("AgenticMemory fact-log audit kind is invalid");
	}
	if (!isFactLogAuditAction(entry.action)) {
		throw new TypeError("AgenticMemory fact-log audit action is invalid");
	}
	return deepFreezeStrict({
		...entry,
		...(entry.cursor === undefined ? {} : { cursor: freezeFactCursor(entry.cursor) }),
	}) as AgenticMemoryFactLogAuditEntry;
}

function auditEntry(
	action: AgenticMemoryFactLogAuditEntry["action"],
	fields: Omit<AgenticMemoryFactLogAuditEntry, "kind" | "action"> = {},
): AgenticMemoryFactLogAuditEntry {
	return Object.freeze({
		kind: "agentic-memory-fact-log-audit",
		action,
		...fields,
	});
}

function validateBackendCursor(
	value: AgenticMemoryCommittedFactLogBackendCursor,
): AgenticMemoryCommittedFactLogBackendCursor | undefined {
	if (value?.kind !== AGENTIC_MEMORY_COMMITTED_FACT_LOG_BACKEND_CURSOR_KIND) return undefined;
	if (!isNonEmptyString(value.backend)) return undefined;
	try {
		return agenticMemoryCommittedFactLogBackendCursor(value.backend, value.value);
	} catch {
		return undefined;
	}
}

function validateFactCursor(
	value: AgenticMemoryCommittedFactCursor | undefined,
): AgenticMemoryCommittedFactCursor | undefined {
	if (value?.kind !== AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND) return undefined;
	if (!Number.isSafeInteger(value.position) || value.position < 0) return undefined;
	return freezeFactCursor(value);
}

function readFallbackCursor(opts: AgenticMemoryCommittedFactReadOptions | undefined): {
	readonly cursor: AgenticMemoryCommittedFactCursor;
	readonly issue?: DataIssue;
} {
	if (opts?.after === undefined) return { cursor: factCursor(0) };
	const cursor = validateFactCursor(opts.after);
	if (cursor !== undefined) return { cursor };
	return {
		cursor: factCursor(0),
		issue: issue(
			"agentic-memory.fact-log-backend.invalid-read-options",
			"read after cursor must be an AgenticMemory fact-stream cursor",
		),
	};
}

function freezeFactCursor(
	cursor: AgenticMemoryCommittedFactCursor,
): AgenticMemoryCommittedFactCursor {
	const valid = validateFactCursorNoFreeze(cursor);
	if (!valid) throw new TypeError("AgenticMemory fact cursor must be a fact-stream cursor");
	return Object.freeze({ kind: cursor.kind, position: cursor.position });
}

function validateFactCursorNoFreeze(cursor: AgenticMemoryCommittedFactCursor): boolean {
	return (
		cursor?.kind === AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND &&
		Number.isSafeInteger(cursor.position) &&
		cursor.position >= 0
	);
}

function factCursor(position: number): AgenticMemoryCommittedFactCursor {
	if (!Number.isSafeInteger(position) || position < 0) {
		throw new RangeError("AgenticMemory fact cursor position must be a non-negative safe integer");
	}
	return Object.freeze({ kind: AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND, position });
}

function isNonNegativeSafeInteger(value: unknown): value is number {
	return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function issue(
	code: string,
	message: string,
	fields: Omit<DataIssue, "kind" | "code" | "message" | "severity"> & {
		readonly severity?: DataIssue["severity"];
	} = {},
): DataIssue {
	const { severity = "error", ...rest } = fields;
	return Object.freeze({ kind: "issue", code, message, severity, ...rest });
}

function isCommitStatus(value: unknown): value is AgenticMemoryFactCommitStatus {
	return (
		value === "committed" ||
		value === "duplicate" ||
		value === "conflict" ||
		value === "rejected" ||
		value === "uncertain"
	);
}

function validateBackendStatusState(
	value: unknown,
): asserts value is AgenticMemoryCommittedFactLogBackendStatusState {
	if (
		value !== "available" &&
		value !== "degraded" &&
		value !== "unavailable" &&
		value !== "unknown"
	) {
		throw new TypeError("AgenticMemory backend status state is invalid");
	}
}

function isBackendAuditAction(
	value: unknown,
): value is AgenticMemoryCommittedFactLogBackendAuditEntry["action"] {
	return (
		value === "backend-append-attempted" ||
		value === "backend-read-attempted" ||
		value === "backend-result-normalized" ||
		value === "backend-status-reported" ||
		value === "backend-capability-reported" ||
		value === "backend-cursor-reported" ||
		value === "issue-recorded"
	);
}

function isFactLogAuditAction(value: unknown): value is AgenticMemoryFactLogAuditEntry["action"] {
	return (
		value === "batch-committed" ||
		value === "batch-duplicate" ||
		value === "batch-conflict" ||
		value === "batch-rejected" ||
		value === "batch-uncertain" ||
		value === "facts-read" ||
		value === "backend-append-normalized" ||
		value === "backend-read-normalized" ||
		value === "backend-status-linked" ||
		value === "backend-capability-linked" ||
		value === "backend-cursor-linked" ||
		value === "issue-recorded"
	);
}

function isNonEmptyString(value: unknown): value is string {
	return typeof value === "string" && value.length > 0;
}

function requireString(value: unknown, label: string): string {
	if (typeof value !== "string") throw new TypeError(`${label} must be a string`);
	return value;
}

function requireBoolean(value: unknown, label: string): boolean {
	if (typeof value !== "boolean") throw new TypeError(`${label} must be boolean`);
	return value;
}

function normalizeIssuePath(value: unknown): readonly (string | number)[] {
	if (!Array.isArray(value)) throw new TypeError("issue.path must be an array");
	return Object.freeze(
		value.map((item, index) => {
			if (typeof item !== "string" && typeof item !== "number") {
				throw new TypeError(`issue.path[${index}] must be a string or number`);
			}
			if (typeof item === "number" && !Number.isSafeInteger(item)) {
				throw new TypeError(`issue.path[${index}] must be a safe integer`);
			}
			return item;
		}),
	);
}

function normalizeIssueRefs(value: unknown): readonly string[] {
	if (!Array.isArray(value)) throw new TypeError("issue.refs must be an array");
	return Object.freeze(value.map((item, index) => requireString(item, `issue.refs[${index}]`)));
}

function normalizeIssueMetadata(value: unknown): Record<string, unknown> {
	const metadata = cloneStrictJsonValue(value, "issue.metadata");
	if (metadata === null || typeof metadata !== "object" || Array.isArray(metadata)) {
		throw new TypeError("issue.metadata must be a strict JSON object");
	}
	return metadata as Record<string, unknown>;
}

function isPromiseLike<T>(value: T | PromiseLike<T>): value is PromiseLike<T> {
	return value !== null && typeof value === "object" && "then" in value;
}

function deepFreezeStrict<T>(value: T): T {
	if (value === null || typeof value !== "object") return value;
	for (const item of Object.values(value)) deepFreezeStrict(item);
	return Object.freeze(value);
}

