/** Build a D589 canonical committed fact batch.
 * @param facts - Canonical committed facts to append as one visible-or-invisible unit.
 * @returns A canonical committed fact batch.
 * @category solutions
 */
export function agenticMemoryCommittedFactBatch<TJson extends StrictJsonValue = StrictJsonValue>(
	facts: readonly AgenticMemoryCommittedFact<TJson>[],
): AgenticMemoryCommittedFactBatch<TJson> {
	if (facts.length === 0) throw new TypeError("agenticMemoryCommittedFactBatch: facts is empty");
	const normalized: readonly AgenticMemoryCommittedFact<TJson>[] = Object.freeze(
		facts.map((fact) => assertAgenticMemoryCommittedFact<TJson>(fact)),
	);
	return Object.freeze({
		format: AGENTIC_MEMORY_COMMITTED_FACT_BATCH_FORMAT,
		version: AGENTIC_MEMORY_COMMITTED_FACT_VERSION,
		kind: "agentic-memory-committed-fact-batch",
		batchIdentity: Object.freeze({
			algorithm: AGENTIC_MEMORY_COMMITTED_FACT_MATERIAL_IDENTITY_ALGORITHM,
			key: strictJsonString({
				format: AGENTIC_MEMORY_COMMITTED_FACT_BATCH_FORMAT,
				version: AGENTIC_MEMORY_COMMITTED_FACT_VERSION,
				facts: normalized.map((fact) => ({
					identity: fact.identity,
					materialIdentity: fact.materialIdentity,
				})),
			}),
		}),
		facts: normalized,
	});
}

/** Assert and canonicalize a D589 committed fact DTO.
 * @param value - Unknown fact DTO.
 * @returns A canonical committed fact DTO.
 * @category solutions
 */
export function assertAgenticMemoryCommittedFact<TJson extends StrictJsonValue = StrictJsonValue>(
	value: unknown,
): AgenticMemoryCommittedFact<TJson> {
	const cloned = cloneStrictJsonValue(value, "agenticMemoryCommittedFact");
	if (cloned === null || typeof cloned !== "object" || Array.isArray(cloned)) {
		throw new TypeError("agenticMemoryCommittedFact: fact must be an object");
	}
	const fact = cloned as unknown as AgenticMemoryCommittedFact<TJson>;
	if (fact.format !== AGENTIC_MEMORY_COMMITTED_FACT_FORMAT) {
		throw new TypeError("agenticMemoryCommittedFact: invalid format");
	}
	if (fact.version !== AGENTIC_MEMORY_COMMITTED_FACT_VERSION) {
		throw new TypeError("agenticMemoryCommittedFact: invalid version");
	}
	if (fact.kind !== "agentic-memory-committed-fact") {
		throw new TypeError("agenticMemoryCommittedFact: invalid kind");
	}
	validateFamily(fact.family);
	const coordinates = normalizeCoordinates(fact.coordinates, "coordinates");
	const material = cloneMaterial<TJson>(fact.material, "material");
	const canonical = agenticMemoryCommittedFact(fact.family, coordinates, material);
	if (
		canonical.identity.algorithm !== fact.identity?.algorithm ||
		canonical.identity.key !== fact.identity.key
	) {
		throw new TypeError("agenticMemoryCommittedFact: identity does not match canonical fact");
	}
	if (
		canonical.materialIdentity.algorithm !== fact.materialIdentity?.algorithm ||
		canonical.materialIdentity.key !== fact.materialIdentity.key
	) {
		throw new TypeError("agenticMemoryCommittedFact: materialIdentity does not match material");
	}
	return canonical;
}

/** Strict canonical JSON codec for D589 committed fact batches.
 * @returns A strict frame codec.
 * @category solutions
 */
export function agenticMemoryCommittedFactBatchCodec<
	TJson extends StrictJsonValue = StrictJsonValue,
>(): Codec<AgenticMemoryCommittedFactBatch<TJson>> {
	return {
		encode(value) {
			return strictJsonCodec.encode(assertAgenticMemoryCommittedFactBatch<TJson>(value));
		},
		decode(bytes) {
			return assertAgenticMemoryCommittedFactBatch<TJson>(strictJsonCodec.decode(bytes));
		},
	};
}

/** Assert and canonicalize a D589 committed fact batch.
 * @param value - Unknown batch DTO.
 * @returns A canonical committed fact batch.
 * @category solutions
 */
export function assertAgenticMemoryCommittedFactBatch<
	TJson extends StrictJsonValue = StrictJsonValue,
>(value: unknown): AgenticMemoryCommittedFactBatch<TJson> {
	const cloned = cloneStrictJsonValue(value, "agenticMemoryCommittedFactBatch");
	if (cloned === null || typeof cloned !== "object" || Array.isArray(cloned)) {
		throw new TypeError("agenticMemoryCommittedFactBatch: batch must be an object");
	}
	const batch = cloned as unknown as AgenticMemoryCommittedFactBatch<TJson>;
	if (batch.format !== AGENTIC_MEMORY_COMMITTED_FACT_BATCH_FORMAT) {
		throw new TypeError("agenticMemoryCommittedFactBatch: invalid format");
	}
	if (batch.version !== AGENTIC_MEMORY_COMMITTED_FACT_VERSION) {
		throw new TypeError("agenticMemoryCommittedFactBatch: invalid version");
	}
	if (batch.kind !== "agentic-memory-committed-fact-batch") {
		throw new TypeError("agenticMemoryCommittedFactBatch: invalid kind");
	}
	if (!Array.isArray(batch.facts)) {
		throw new TypeError("agenticMemoryCommittedFactBatch: facts must be an array");
	}
	const canonical = agenticMemoryCommittedFactBatch<TJson>(batch.facts);
	if (
		canonical.batchIdentity.algorithm !== batch.batchIdentity?.algorithm ||
		canonical.batchIdentity.key !== batch.batchIdentity.key
	) {
		throw new TypeError("agenticMemoryCommittedFactBatch: batchIdentity mismatch");
	}
	return canonical;
}

/** Create an in-memory D589 reference fact-log adapter.
 *
 * This adapter is an executable reference for fact-log persistence semantics. It
 * implements append/read behavior for canonical committed fact batches only;
 * library materialization remains a separate explicit DATA boundary. It does
 * not provide production durability, application acknowledgement, live graph
 * truth, hot hydration, or record mutation authority.
 * @returns A D589 committed fact-log reference adapter.
 * @category solutions
 */
export function memoryAgenticMemoryCommittedFactLog<
	TJson extends StrictJsonValue = StrictJsonValue,
>(): AgenticMemoryCommittedFactLog<TJson> {
	const facts: AgenticMemoryCommittedFact<TJson>[] = [];
	const byIdentity = new Map<string, AgenticMemoryCommittedFactMaterialIdentity>();

	function cursor(): AgenticMemoryCommittedFactCursor {
		return factCursor(facts.length);
	}

	return {
		append(batch) {
			let canonical: AgenticMemoryCommittedFactBatch<TJson>;
			try {
				canonical = assertAgenticMemoryCommittedFactBatch<TJson>(batch);
			} catch (error) {
				return commitResult("rejected", cursor(), 0, [
					issue(
						"agentic-memory.fact-log.batch-rejected",
						error instanceof Error ? error.message : String(error),
					),
				]);
			}
			const internal = internalIdentityConflicts(canonical.facts);
			if (internal !== undefined) {
				return commitResult(internal.status, cursor(), 0, [internal.issue]);
			}
			let existing = 0;
			for (const fact of canonical.facts) {
				const material = byIdentity.get(fact.identity.key);
				if (material === undefined) continue;
				if (material.key !== fact.materialIdentity.key) {
					return commitResult("conflict", cursor(), 0, [
						issue(
							"agentic-memory.fact-log.identity-conflict",
							"committed fact identity was reused with different material",
							{ subjectId: fact.identity.key },
						),
					]);
				}
				existing += 1;
			}
			if (existing === canonical.facts.length) {
				return commitResult("duplicate", cursor(), 0, []);
			}
			if (existing > 0) {
				return commitResult("rejected", cursor(), 0, [
					issue(
						"agentic-memory.fact-log.batch-overlaps-committed-log",
						"committed fact batch partially overlaps existing facts; retry by reading the stream cursor",
					),
				]);
			}
			for (const fact of canonical.facts) {
				facts.push(fact);
				byIdentity.set(fact.identity.key, fact.materialIdentity);
			}
			return commitResult("committed", cursor(), canonical.facts.length, []);
		},
		read(opts = {}) {
			const { after, limit } = validateReadOptions(opts);
			const visible = facts.slice(after, limit === Infinity ? undefined : after + limit);
			const next = factCursor(after + visible.length);
			return Object.freeze({
				facts: Object.freeze([...visible]),
				cursor: next,
				done: after + visible.length >= facts.length,
				issues: Object.freeze([]),
				audit: Object.freeze([
					audit("facts-read", { cursor: next, reason: `${visible.length} facts` }),
				]),
			});
		},
	};
}

/** True only for commit statuses that prove fact-log durability.
 * @param status - Commit result status.
 * @returns Whether the fact batch is known durable or idempotently already durable.
 * @category solutions
 */
export function agenticMemoryFactCommitStatusIsDurable(
	status: AgenticMemoryFactCommitStatus,
): boolean {
	return status === "committed" || status === "duplicate";
}

/** True only for commit statuses that prove the batch did not commit.
 * @param status - Commit result status.
 * @returns Whether the batch is known not to have committed.
 * @category solutions
 */
export function agenticMemoryFactCommitStatusIsTerminalFailure(
	status: AgenticMemoryFactCommitStatus,
): boolean {
	return status === "conflict" || status === "rejected";
}

/** Deterministically materialize AgenticMemory re-entry DATA from committed facts.
 *
 * The input order is the committed fact stream order supplied by an explicit
 * read/materialization boundary. This helper does not read storage, apply or
 * admit records, mutate live graph truth, refresh subscribers, or create a
 * graph commit barrier.
 *
 * @param facts - Committed facts in stream order.
 * @param opts - Optional prefix materialization seed used by snapshot+tail equivalence.
 * @returns Records/priorEvidence derived by library-owned materialization rules.
 * @category solutions
 */
export function materializeAgenticMemoryCommittedFacts<
	TJson extends StrictJsonValue = StrictJsonValue,
>(
	facts: readonly AgenticMemoryCommittedFact<TJson>[],
	opts: {
		readonly records?: readonly AgenticMemoryRecord<TJson>[];
		readonly priorEvidence?: AgenticMemoryRecordApplicationPriorEvidence;
	} = {},
): AgenticMemoryCommittedFactMaterialization<TJson> {
	const recordCodec = agenticMemoryRecordCodec<TJson>();
	const recordsById = new Map<FactId, AgenticMemoryRecord<TJson>>();
	for (const record of opts.records ?? []) recordsById.set(record.id, record);
	const evidence: AgenticMemoryRecordApplicationEvidence[] = [
		...(opts.priorEvidence?.entries ?? []),
	];
	const issues: DataIssue[] = [];
	const auditEntries: AgenticMemoryCommittedFactMaterializationAuditEntry[] = [];
	let invalidFacts = 0;
	let recordMaterialFacts = 0;
	let applicationDecisionFacts = 0;
	let applicationEvidenceFacts = 0;
	let priorEvidenceFacts = 0;

	for (let index = 0; index < facts.length; index += 1) {
		let fact: AgenticMemoryCommittedFact<TJson>;
		try {
			fact = assertAgenticMemoryCommittedFact<TJson>(facts[index]);
		} catch (error) {
			invalidFacts += 1;
			issues.push(
				issue(
					"agentic-memory.committed-fact-materialization.invalid-fact",
					error instanceof Error ? error.message : String(error),
					{ path: [index] },
				),
			);
			continue;
		}
		try {
			if (fact.material.kind === "agentic-memory-committed-record-material") {
				recordMaterialFacts += 1;
				const record = recordCodec.decode(strictJsonCodec.encode(fact.material.record));
				recordsById.set(record.id, record);
				auditEntries.push(
					materializationAudit("record-materialized", {
						factId: fact.identity.key,
						recordId: record.id,
					}),
				);
				continue;
			}
			if (fact.material.kind === "agentic-memory-committed-application-decision-material") {
				applicationDecisionFacts += 1;
				const decisions = decodeSingleApplicationDecision(fact.material.decision);
				const projected = projectAgenticMemoryRecordApplicationEvidenceFacts(decisions);
				evidence.push(...projected.priorEvidence.entries);
				auditEntries.push(
					materializationAudit("application-decision-evidence-projected", {
						factId: fact.identity.key,
						admissionId: decisions[0]?.admissionId,
					}),
				);
				continue;
			}
			if (fact.material.kind === "agentic-memory-committed-application-evidence-material") {
				applicationEvidenceFacts += 1;
				evidence.push(fact.material.evidence);
				auditEntries.push(
					materializationAudit("application-evidence-materialized", {
						factId: fact.identity.key,
						admissionId: fact.material.evidence.admissionId,
					}),
				);
				continue;
			}
			priorEvidenceFacts += 1;
			evidence.push(...fact.material.priorEvidence.entries);
			auditEntries.push(
				materializationAudit("prior-evidence-materialized", { factId: fact.identity.key }),
			);
		} catch (error) {
			invalidFacts += 1;
			issues.push(
				issue(
					"agentic-memory.committed-fact-materialization.failed",
					error instanceof Error ? error.message : String(error),
					{ path: [index], subjectId: fact.identity.key },
				),
			);
		}
	}

	const priorProjection = projectAgenticMemoryRecordApplicationPriorEvidence(evidence);
	issues.push(...priorProjection.issues);
	const cursor = materializationCursor({
		facts: facts.length,
		recordMaterialFacts,
		applicationDecisionFacts,
		applicationEvidenceFacts,
		priorEvidenceFacts,
		invalidFacts,
		issues: issues.length,
	});
	const records = Object.freeze([...recordsById.values()]);
	return Object.freeze({
		kind: "agentic-memory-committed-fact-materialization",
		records,
		priorEvidence: priorProjection.priorEvidence,
		status: Object.freeze({
			state:
				issues.length === 0
					? records.length === 0 && evidence.length === 0
						? "empty"
						: "ready"
					: "partial",
			cursor,
		}),
		issues: Object.freeze(issues),
		audit: Object.freeze([
			...auditEntries,
			...issues.map((item) =>
				materializationAudit("issue-recorded", { reason: item.code, factId: item.subjectId }),
			),
		]),
		cursor,
	});
}

/** Create a D589 compaction snapshot over a committed fact prefix.
 * @param facts - Committed prefix facts in stream order.
 * @returns Snapshot compaction artifact for that prefix.
 * @category solutions
 */
export function agenticMemoryCommittedFactSnapshot<TJson extends StrictJsonValue = StrictJsonValue>(
	facts: readonly AgenticMemoryCommittedFact<TJson>[],
): AgenticMemoryCommittedFactSnapshot<TJson> {
	const materialized = materializeAgenticMemoryCommittedFacts<TJson>(facts);
	return Object.freeze({
		format: AGENTIC_MEMORY_COMMITTED_FACT_SNAPSHOT_FORMAT,
		version: AGENTIC_MEMORY_COMMITTED_FACT_VERSION,
		kind: "agentic-memory-committed-fact-snapshot",
		coveredCursor: factCursor(facts.length),
		records: Object.freeze(materialized.records.map((record) => agenticMemoryRecordFrame(record))),
		priorEvidence: materialized.priorEvidence,
	});
}

/** Materialize a D589 compaction snapshot plus committed tail facts.
 *
 * Snapshot+tail materialization is an equivalence check over committed facts,
 * not backend-owned restore, hot hydration, or live graph mutation.
 *
 * @param snapshot - Prefix compaction artifact.
 * @param tail - Committed facts after the snapshot cursor.
 * @returns Materialization equivalent to the covered prefix plus tail facts.
 * @category solutions
 */
export function materializeAgenticMemoryCommittedFactSnapshotTail<
	TJson extends StrictJsonValue = StrictJsonValue,
>(
	snapshot: AgenticMemoryCommittedFactSnapshot<TJson>,
	tail: readonly AgenticMemoryCommittedFact<TJson>[],
): AgenticMemoryCommittedFactMaterialization<TJson> {
	const recordCodec = agenticMemoryRecordCodec<TJson>();
	const records = snapshot.records.map((frame) =>
		recordCodec.decode(strictJsonCodec.encode(frame)),
	);
	return materializeAgenticMemoryCommittedFacts(tail, {
		records,
		priorEvidence: snapshot.priorEvidence,
	});
}

/** Check D589 snapshot+tail equivalence for a committed prefix and tail.
 * @param prefix - Committed prefix facts.
 * @param tail - Committed tail facts.
 * @returns Whether snapshot+tail materializes identically to prefix plus tail facts.
 * @category solutions
 */
export function agenticMemoryCommittedFactSnapshotTailEquivalent<
	TJson extends StrictJsonValue = StrictJsonValue,
>(
	prefix: readonly AgenticMemoryCommittedFact<TJson>[],
	tail: readonly AgenticMemoryCommittedFact<TJson>[],
): boolean {
	const direct = materializationComparable(
		materializeAgenticMemoryCommittedFacts([...prefix, ...tail]),
	);
	const compacted = materializationComparable(
		materializeAgenticMemoryCommittedFactSnapshotTail(
			agenticMemoryCommittedFactSnapshot(prefix),
			tail,
		),
	);
	return strictJsonString(direct) === strictJsonString(compacted);
}

function strictJsonString(value: unknown): string {
	return textDecoder.decode(strictCanonicalJsonBytes(value));
}

function factCursor(position: number): AgenticMemoryCommittedFactCursor {
	if (!Number.isSafeInteger(position) || position < 0) {
		throw new RangeError("AgenticMemory fact cursor position must be a non-negative safe integer");
	}
	return Object.freeze({ kind: AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND, position });
}

function validateReadOptions(opts: AgenticMemoryCommittedFactReadOptions): {
	readonly after: number;
	readonly limit: number;
} {
	let after = 0;
	if (opts.after !== undefined) {
		const cloned = cloneStrictJsonValue(opts.after, "after");
		if (cloned === null || typeof cloned !== "object" || Array.isArray(cloned)) {
			throw new TypeError("AgenticMemory committed fact read cursor must be an object");
		}
		const cursor = cloned as unknown as AgenticMemoryCommittedFactCursor;
		if (cursor.kind !== AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND) {
			throw new TypeError("AgenticMemory committed fact read cursor must be a fact-stream cursor");
		}
		after = cursor.position;
	}
	const limit = opts.limit ?? Number.POSITIVE_INFINITY;
	if (!Number.isSafeInteger(after) || after < 0) {
		throw new RangeError("AgenticMemory committed fact read cursor must be >= 0");
	}
	if (limit !== Number.POSITIVE_INFINITY && (!Number.isSafeInteger(limit) || limit < 0)) {
		throw new RangeError("AgenticMemory committed fact read limit must be >= 0 or Infinity");
	}
	return { after, limit };
}

function issue(
	code: string,
	message: string,
	fields: Omit<DataIssue, "kind" | "code" | "message" | "severity"> = {},
): DataIssue {
	return Object.freeze({ kind: "issue", code, message, severity: "error", ...fields });
}

function audit(
	action: AgenticMemoryFactLogAuditEntry["action"],
	fields: Omit<AgenticMemoryFactLogAuditEntry, "kind" | "action"> = {},
): AgenticMemoryFactLogAuditEntry {
	return Object.freeze({ kind: "agentic-memory-fact-log-audit", action, ...fields });
}

function commitResult(
	status: AgenticMemoryFactCommitStatus,
	cursor: AgenticMemoryCommittedFactCursor,
	facts: number,
	issues: readonly DataIssue[],
): AgenticMemoryFactCommitResult {
	const action: AgenticMemoryFactLogAuditEntry["action"] =
		status === "committed"
			? "batch-committed"
			: status === "duplicate"
				? "batch-duplicate"
				: status === "conflict"
					? "batch-conflict"
					: status === "rejected"
						? "batch-rejected"
						: "batch-uncertain";
	return Object.freeze({
		status,
		cursor,
		facts,
		issues: Object.freeze([...issues]),
		audit: Object.freeze([
			audit(action, { cursor }),
			...issues.map((item) => audit("issue-recorded", { reason: item.code })),
		]),
	});
}

function internalIdentityConflicts(
	facts: readonly AgenticMemoryCommittedFact[],
): { readonly status: "conflict" | "rejected"; readonly issue: DataIssue } | undefined {
	const seen = new Map<string, string>();
	for (const fact of facts) {
		const existing = seen.get(fact.identity.key);
		if (existing === undefined) {
			seen.set(fact.identity.key, fact.materialIdentity.key);
			continue;
		}
		if (existing !== fact.materialIdentity.key) {
			return {
				status: "conflict",
				issue: issue(
					"agentic-memory.fact-log.batch-internal-conflict",
					"committed fact batch reuses one identity with different material",
					{ subjectId: fact.identity.key },
				),
			};
		}
		return {
			status: "rejected",
			issue: issue(
				"agentic-memory.fact-log.batch-duplicate-identity",
				"committed fact batch must not repeat the same fact identity",
				{ subjectId: fact.identity.key },
			),
		};
	}
	return undefined;
}

function normalizeCoordinates(
	value: AgenticMemoryCommittedFactCoordinates,
	label: string,
): AgenticMemoryCommittedFactCoordinates {
	const cloned = cloneStrictJsonValue(value, label);
	if (cloned === null || typeof cloned !== "object" || Array.isArray(cloned)) {
		throw new TypeError(`${label}: coordinates must be an object`);
	}
	const coords = cloned as unknown as AgenticMemoryCommittedFactCoordinates;
	if (!isNonEmptyString(coords.subjectId)) {
		throw new TypeError(`${label}.subjectId must be a non-empty string`);
	}
	if (coords.operation !== undefined && !isNonEmptyString(coords.operation)) {
		throw new TypeError(`${label}.operation must be a non-empty string`);
	}
	if (
		coords.operationVersion !== undefined &&
		(!Number.isSafeInteger(coords.operationVersion) || coords.operationVersion < 0)
	) {
		throw new TypeError(`${label}.operationVersion must be a non-negative safe integer`);
	}
	if (
		coords.scope !== undefined &&
		(!Array.isArray(coords.scope) || !coords.scope.every(isNonEmptyString))
	) {
		throw new TypeError(`${label}.scope must contain only non-empty strings`);
	}
	if (coords.correlationId !== undefined && !isNonEmptyString(coords.correlationId)) {
		throw new TypeError(`${label}.correlationId must be a non-empty string`);
	}
	if (coords.causationId !== undefined && !isNonEmptyString(coords.causationId)) {
		throw new TypeError(`${label}.causationId must be a non-empty string`);
	}
	return Object.freeze({
		subjectId: coords.subjectId,
		...(coords.operation === undefined ? {} : { operation: coords.operation }),
		...(coords.operationVersion === undefined ? {} : { operationVersion: coords.operationVersion }),
		...(coords.scope === undefined ? {} : { scope: Object.freeze([...coords.scope]) }),
		...(coords.sourceRefs === undefined
			? {}
			: { sourceRefs: normalizeFactRefs(coords.sourceRefs, `${label}.sourceRefs`) }),
		...(coords.correlationId === undefined ? {} : { correlationId: coords.correlationId }),
		...(coords.causationId === undefined ? {} : { causationId: coords.causationId }),
	});
}

function normalizeFactRefs(
	refs: readonly AgenticMemoryFactRef[],
	label: string,
): readonly AgenticMemoryFactRef[] {
	if (!Array.isArray(refs)) throw new TypeError(`${label} must be an array`);
	return Object.freeze(
		refs.map((ref, index) => {
			const cloned = cloneStrictJsonValue(ref, `${label}[${index}]`);
			const item = cloned as unknown as AgenticMemoryFactRef;
			if (!isNonEmptyString(item.kind) || !isNonEmptyString(item.id)) {
				throw new TypeError(`${label}[${index}] must have non-empty kind and id`);
			}
			return Object.freeze(item);
		}),
	);
}

function cloneMaterial<TJson extends StrictJsonValue>(
	material: AgenticMemoryCommittedFactMaterial<TJson>,
	label: string,
): AgenticMemoryCommittedFactMaterial<TJson> {
	const cloned = cloneStrictJsonValue(material, label);
	const normalized = cloned as unknown as AgenticMemoryCommittedFactMaterial<TJson>;
	if (normalized.kind === "agentic-memory-committed-record-material") {
		assertAgenticMemoryRecordFrame(normalized.record);
		return Object.freeze(normalized);
	}
	if (normalized.kind === "agentic-memory-committed-application-decision-material") {
		decodeSingleApplicationDecision(normalized.decision);
		return Object.freeze(normalized);
	}
	if (normalized.kind === "agentic-memory-committed-application-evidence-material") {
		assertNoPriorEvidenceIssues(
			projectAgenticMemoryRecordApplicationPriorEvidence([normalized.evidence]),
			`${label}.evidence`,
		);
		return Object.freeze(normalized);
	}
	if (normalized.kind === "agentic-memory-committed-prior-evidence-material") {
		assertNoPriorEvidenceIssues(
			projectAgenticMemoryRecordApplicationPriorEvidence(normalized.priorEvidence),
			`${label}.priorEvidence`,
		);
		return Object.freeze(normalized);
	}
	throw new TypeError(
		`${label}.kind is not a supported AgenticMemory committed fact material kind`,
	);
}

function validateFamily(family: AgenticMemoryCommittedFactFamily): void {
	if (
		family !== "record-material" &&
		family !== "application-decision" &&
		family !== "application-evidence" &&
		family !== "derived-prior-evidence"
	) {
		throw new TypeError("agenticMemoryCommittedFact: invalid family");
	}
}

function validateMaterialFamily(
	family: AgenticMemoryCommittedFactFamily,
	materialKind: AgenticMemoryCommittedFactMaterial["kind"],
): void {
	const expected =
		family === "record-material"
			? "agentic-memory-committed-record-material"
			: family === "application-decision"
				? "agentic-memory-committed-application-decision-material"
				: family === "application-evidence"
					? "agentic-memory-committed-application-evidence-material"
					: "agentic-memory-committed-prior-evidence-material";
	if (materialKind !== expected) {
		throw new TypeError("agenticMemoryCommittedFact: material kind does not match family");
	}
}

function assertNoPriorEvidenceIssues(
	projection: ReturnType<typeof projectAgenticMemoryRecordApplicationPriorEvidence>,
	label: string,
): void {
	if (projection.issues.length === 0) return;
	throw new TypeError(
		`${label} is invalid: ${projection.issues.map((item) => item.code).join(", ")}`,
	);
}

function isNonEmptyString(value: unknown): value is string {
	return typeof value === "string" && value.length > 0;
}

function frameSingleApplicationDecision<TJson extends StrictJsonValue>(
	decision: AgenticMemoryRecordApplicationDecision<TJson>,
): AgenticMemoryApplicationDecisionStoreFrameDecision<TJson> {
	const frame: AgenticMemoryApplicationDecisionStoreFrame<TJson> = {
		format: AGENTIC_MEMORY_APPLICATION_DECISION_STORE_FRAME_FORMAT,
		version: AGENTIC_MEMORY_STORE_FRAME_VERSION,
		kind: "agentic-memory-application-decision-store-frame",
		applicationDecisions: [decisionToFrame(decision)],
	};
	const [decoded] = decodeAgenticMemoryApplicationDecisionStoreFrame<TJson>(frame);
	if (decoded === undefined) throw new TypeError("application decision did not decode");
	return frame.applicationDecisions[0]!;
}

function decisionToFrame<TJson extends StrictJsonValue>(
	decision: AgenticMemoryRecordApplicationDecision<TJson>,
): AgenticMemoryApplicationDecisionStoreFrameDecision<TJson> {
	return {
		kind: "agentic-memory-record-application-decision",
		applicationId: decision.applicationId,
		admissionId: decision.admissionId,
		proposalId: decision.proposalId,
		operation: decision.operation,
		operationVersion: decision.operationVersion,
		state: decision.state,
		reasonCode: decision.reasonCode,
		...(decision.reason === undefined ? {} : { reason: decision.reason }),
		candidateMaterial: {
			...decision.candidateMaterial,
			record: agenticMemoryRecordFrame(decision.candidateMaterial.record),
		},
		...(decision.record === undefined ? {} : { record: agenticMemoryRecordFrame(decision.record) }),
		...(decision.targetRecordId === undefined ? {} : { targetRecordId: decision.targetRecordId }),
		...(decision.idempotencyKey === undefined ? {} : { idempotencyKey: decision.idempotencyKey }),
		...(decision.materialIdentity === undefined
			? {}
			: { materialIdentity: decision.materialIdentity }),
		...(decision.sourceRefs === undefined ? {} : { sourceRefs: decision.sourceRefs }),
		...(decision.policyRefs === undefined ? {} : { policyRefs: decision.policyRefs }),
		...(decision.evidenceRefs === undefined ? {} : { evidenceRefs: decision.evidenceRefs }),
	};
}

function decodeSingleApplicationDecision<TJson extends StrictJsonValue>(
	decision: AgenticMemoryApplicationDecisionStoreFrameDecision<TJson>,
): readonly AgenticMemoryRecordApplicationDecision<TJson>[] {
	return decodeAgenticMemoryApplicationDecisionStoreFrame<TJson>({
		format: AGENTIC_MEMORY_APPLICATION_DECISION_STORE_FRAME_FORMAT,
		version: AGENTIC_MEMORY_STORE_FRAME_VERSION,
		kind: "agentic-memory-application-decision-store-frame",
		applicationDecisions: [decision],
	});
}

function materializationCursor(
	input: AgenticMemoryCommittedFactMaterializationCursor,
): AgenticMemoryCommittedFactMaterializationCursor {
	return Object.freeze(input);
}

function materializationAudit(
	action: AgenticMemoryCommittedFactMaterializationAuditEntry["action"],
	fields: Omit<AgenticMemoryCommittedFactMaterializationAuditEntry, "kind" | "action"> = {},
): AgenticMemoryCommittedFactMaterializationAuditEntry {
	return Object.freeze({
		kind: "agentic-memory-committed-fact-materialization-audit",
		action,
		...fields,
	});
}

function materializationComparable<TJson extends StrictJsonValue>(
	value: AgenticMemoryCommittedFactMaterialization<TJson>,
): {
	readonly records: readonly AgenticMemoryRecordFrame<TJson>[];
	readonly priorEvidence: AgenticMemoryRecordApplicationPriorEvidence;
} {
	return {
		records: value.records.map((record) => agenticMemoryRecordFrame(record)),
		priorEvidence: value.priorEvidence,
	};
}

import type { Graph } from "../../graph/graph.js";
import { solutionOccurrenceJoin, solutionOccurrenceProjection } from "../occurrence.js";
import { agenticMemoryConsolidationBundle } from "./consolidation.js";
import { agenticMemoryRecordAdmissionBundle } from "./proposal-admission.js";
import { agenticMemoryRecordApplicationBundle } from "./record-application.js";
import type {
	AgenticMemoryConsolidationApplicationBundle,
	AgenticMemoryConsolidationApplicationBundleOptions,
} from "./types.js";

/**
 * D171/D572/D576/D577 composition from consolidation outcomes to record truth.
 *
 * Consolidation remains proposal-only; admission and application are explicit
 * graph-visible boundaries before any AgenticMemoryRecord snapshot changes.
 * @remarks D151: each input DATA is one complete identity/revision/digest/source-refs
 * occurrence. Policy and prior records travel in its value, never independent latest-value
 * dependencies. Outputs preserve that identity; replay conflicts and retention overflow fail closed.
 * The fixed recipe topology is retained for its graph lifetime; input snapshots are bounded by
 * maxOccurrences, not a claim that one protocol wave is one business occurrence.
 * @param graph - Graph that owns the created nodes or projector.
 * @param opts - Options that configure the helper.
 * @returns A bundle of graph-visible nodes for the recipe.
 * @category solutions
 * @example
 * ```ts
 * import { agenticMemoryConsolidationApplicationBundle } from "@graphrefly/ts/solutions";
 * ```
 */
export function agenticMemoryConsolidationApplicationBundle<T = unknown>(
	graph: Graph,
	opts: AgenticMemoryConsolidationApplicationBundleOptions<T>,
): AgenticMemoryConsolidationApplicationBundle<T> {
	const name = opts.name ?? "agenticMemoryConsolidationApplication";
	const input = solutionOccurrenceProjection(graph, opts.occurrences, {
		name: `${name}/input`,
		factory: "agenticMemoryConsolidationApplicationInput",
		maxOccurrences: opts.maxOccurrences,
		project: (value) => value,
	});
	const consolidation = agenticMemoryConsolidationBundle<T>(graph, {
		name: `${name}/consolidation`,
		occurrences: input,
		maxOccurrences: opts.maxOccurrences,
	});
	const admission = agenticMemoryRecordAdmissionBundle<T>(graph, {
		name: `${name}/admission`,
		maxOccurrences: opts.maxOccurrences,
		occurrences: solutionOccurrenceJoin(graph, input, consolidation.recordProposals, {
			name: `${name}/admission-input`,
			factory: "agenticMemoryConsolidationAdmissionInput",
			maxOccurrences: opts.maxOccurrences,
			project: (frame, proposals) =>
				Object.freeze({ records: frame.records, proposals, policy: frame.admissionPolicy }),
		}),
	});
	const application = agenticMemoryRecordApplicationBundle<T>(graph, {
		name: `${name}/application`,
		maxOccurrences: opts.maxOccurrences,
		occurrences: solutionOccurrenceJoin(graph, input, admission.admissions, {
			name: `${name}/application-input`,
			factory: "agenticMemoryConsolidationRecordApplicationInput",
			maxOccurrences: opts.maxOccurrences,
			project: (frame, admissions) =>
				Object.freeze({
					records: frame.records,
					admissions,
					policy: frame.applicationPolicy,
					...(frame.applicationPriorEvidence === undefined
						? {}
						: { priorEvidence: frame.applicationPriorEvidence }),
				}),
		}),
	});
	return {
		input,
		consolidation,
		admission,
		application,
		records: application.records,
		appliedRecords: application.appliedRecords,
		applicationDecisions: application.applicationDecisions,
		applicationStatus: application.status,
		applicationOperationStatuses: application.operationStatuses,
		applicationIssues: application.issues,
	};
}

import type { Graph } from "../../graph/graph.js";
import { compoundTupleKey } from "../../identity.js";
import type { FactId } from "../../patterns/semantic-memory.js";
import { solutionOccurrenceProjection, solutionOccurrenceSelect } from "../occurrence.js";
import {
	agenticStatusState,
	errorMessage,
	freezeError,
	isDenseArrayOf,
	isNonEmptyString,
	isPlainRecord,
	safeArrayLength,
	validateAndProjectRecords,
	validateAndSnapshotRecord,
} from "./shared.js";
import type {
	AgenticMemoryConsolidationBundle,
	AgenticMemoryConsolidationBundleOptions,
	AgenticMemoryConsolidationCommand,
	AgenticMemoryConsolidationCursor,
	AgenticMemoryConsolidationError,
	AgenticMemoryConsolidationOutcome,
	AgenticMemoryConsolidationRecordDraft,
	AgenticMemoryConsolidationRequest,
	AgenticMemoryConsolidationResult,
	AgenticMemoryConsolidationSnapshot,
	AgenticMemoryConsolidationStatus,
	AgenticMemoryError,
	AgenticMemoryFactRef,
	AgenticMemoryRecord,
	AgenticMemoryRecordApplicationOperation,
	AgenticMemoryRecordCandidateMaterial,
	AgenticMemoryRecordProposal,
	AgenticMemoryRetentionError,
} from "./types.js";

const AGENTIC_MEMORY_RECORD_APPLICATION_OPERATION_VERSION = 1 as const;

/**
 * Creates an agentic memory consolidation bundle.
 *
 * @remarks D151: each input DATA is one complete identity/revision/digest/source-refs
 * occurrence. Policy and prior records travel in its value, never independent latest-value
 * dependencies. Outputs preserve that identity; replay conflicts and retention overflow fail closed.
 * The fixed recipe topology is retained for its graph lifetime; input snapshots are bounded by
 * maxOccurrences, not a claim that one protocol wave is one business occurrence.
 * @param graph - Graph that owns the created nodes or projector.
 * @param opts - Options that configure the helper.
 * @returns A bundle of graph-visible nodes for the recipe.
 * @category solutions
 * @example
 * ```ts
 * import { agenticMemoryConsolidationBundle } from "@graphrefly/ts/solutions/agentic-memory";
 * ```
 */
export function agenticMemoryConsolidationBundle<T = unknown>(
	graph: Graph,
	opts: AgenticMemoryConsolidationBundleOptions<T>,
): AgenticMemoryConsolidationBundle<T> {
	const name = opts.name ?? "agenticMemoryConsolidation";
	const projection = solutionOccurrenceProjection(graph, opts.occurrences, {
		name: `${name}/projection`,
		factory: "agenticMemoryConsolidation",
		maxOccurrences: opts.maxOccurrences,
		project: (value): AgenticMemoryConsolidationSnapshot<T> => {
			const recordProjection = validateAndProjectRecords<T>(value.records);
			const requests = validateConsolidationRequests(value.requests, recordProjection.records);
			const outcomes = projectConsolidationOutcomes<T>(
				value.outcomes,
				requests.requests,
				recordProjection.records,
				1,
			);
			const cursor: AgenticMemoryConsolidationCursor = Object.freeze({
				evaluation: 1,
				validRequests: requests.requests.length,
				validOutcomes: outcomes.validOutcomes,
				invalidOutcomes: outcomes.invalidOutcomes,
				results: outcomes.results.length,
				proposedRecordDrafts: outcomes.proposedRecordDrafts.length,
				recordProposals: outcomes.recordProposals.length,
			});
			const errors = Object.freeze(
				[
					...recordProjection.errors.map(consolidationErrorFromRecordError),
					...requests.errors.map(consolidationErrorFromRetentionError),
					...outcomes.errors,
				].map((error) => freezeError({ ...error, cursor })),
			);
			const status: AgenticMemoryConsolidationStatus = Object.freeze({
				state: agenticStatusState(errors.length, outcomes.results.length),
				cursor,
			});
			return Object.freeze({
				results: Object.freeze(outcomes.results),
				proposedRecordDrafts: Object.freeze(outcomes.proposedRecordDrafts),
				recordProposals: Object.freeze(outcomes.recordProposals),
				commands: Object.freeze(outcomes.commands),
				status,
				errors,
				cursor,
			});
		},
	});
	return {
		input: opts.occurrences,
		projection,
		results: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/results`,
			"agenticMemoryConsolidationResults",
			(fact) => fact.results,
		),
		proposedRecordDrafts: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/proposedRecordDrafts`,
			"agenticMemoryConsolidationRecordDrafts",
			(fact) => fact.proposedRecordDrafts,
		),
		recordProposals: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/recordProposals`,
			"agenticMemoryConsolidationRecordProposals",
			(fact) => fact.recordProposals,
		),
		commands: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/commands`,
			"agenticMemoryConsolidationCommands",
			(fact) => fact.commands,
		),
		status: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/status`,
			"agenticMemoryConsolidationStatus",
			(fact) => fact.status,
		),
		errors: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/errors`,
			"agenticMemoryConsolidationErrors",
			(fact) => fact.errors,
		),
		cursor: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/cursor`,
			"agenticMemoryConsolidationCursor",
			(fact) => fact.cursor,
		),
	};
}

/** D168 deterministic context-packing bundle over explicit context text facts. */

function validateConsolidationRequests<T>(
	value: unknown,
	records: readonly AgenticMemoryRecord<T>[],
): {
	readonly requests: readonly AgenticMemoryConsolidationRequest[];
	readonly errors: readonly Omit<AgenticMemoryRetentionError, "cursor">[];
} {
	const byId = new Map(records.map((record) => [record.id, record]));
	const requests: AgenticMemoryConsolidationRequest[] = [];
	const errors: Omit<AgenticMemoryRetentionError, "cursor">[] = [];
	if (!Array.isArray(value)) {
		return {
			requests,
			errors: [
				{
					code: "invalid-commands-input",
					message: "agenticMemoryConsolidationBundle: requests input must be an array",
					command: value,
				},
			],
		};
	}
	const length = safeArrayLength(value);
	if (length === undefined) {
		return {
			requests,
			errors: [
				{
					code: "invalid-commands-input",
					message: "agenticMemoryConsolidationBundle: requests input length could not be read",
					command: value,
				},
			],
		};
	}
	const seen = new Set<FactId>();
	for (let i = 0; i < length; i += 1) {
		let raw: unknown;
		try {
			if (!Object.hasOwn(value, i)) {
				throw new TypeError("request array must be dense");
			}
			raw = value[i];
		} catch (error) {
			errors.push({
				code: "invalid-command",
				message: `agenticMemoryConsolidationBundle: request access failed: ${errorMessage(error)}`,
				index: i,
				validationErrors: Object.freeze(["request access failed"]),
			});
			continue;
		}
		if (!isPlainRecord(raw)) {
			errors.push({
				code: "invalid-command",
				message: "agenticMemoryConsolidationBundle: request must be an object",
				index: i,
				command: raw,
			});
			continue;
		}
		const id = isNonEmptyString(raw.id) ? raw.id : undefined;
		const commandId = isNonEmptyString(raw.commandId) ? raw.commandId : undefined;
		const recordIds = isDenseArrayOf(raw.recordIds, isNonEmptyString)
			? Object.freeze([...raw.recordIds])
			: undefined;
		const validationErrors: string[] = [];
		if (id === undefined) validationErrors.push("request.id must be a non-empty string");
		if (commandId === undefined) {
			validationErrors.push("request.commandId must be a non-empty string");
		}
		if (recordIds === undefined || recordIds.length === 0) {
			validationErrors.push("request.recordIds must be a non-empty string array");
		}
		if (raw.reason !== undefined && typeof raw.reason !== "string") {
			validationErrors.push("request.reason must be a string when present");
		}
		if (id !== undefined && seen.has(id)) {
			validationErrors.push(`duplicate request id '${id}'`);
		}
		const missing = (recordIds ?? []).filter((recordId) => !byId.has(recordId));
		if (missing.length > 0) {
			errors.push({
				code: "missing-record-ref",
				message: "agenticMemoryConsolidationBundle: request references missing records",
				index: i,
				commandId,
				recordIds: Object.freeze(missing),
				command: raw,
				validationErrors: Object.freeze(
					missing.map((recordId) => `record '${recordId}' is not projected`),
				),
			});
			continue;
		}
		if (
			validationErrors.length > 0 ||
			id === undefined ||
			commandId === undefined ||
			recordIds === undefined
		) {
			errors.push({
				code: "invalid-command",
				message: "agenticMemoryConsolidationBundle: request is invalid",
				index: i,
				commandId,
				recordIds,
				command: raw,
				validationErrors: Object.freeze(validationErrors),
			});
			continue;
		}
		seen.add(id);
		requests.push(
			Object.freeze({
				id,
				commandId,
				recordIds,
				...(raw.reason === undefined ? {} : { reason: raw.reason as string }),
			}),
		);
	}
	return { requests: Object.freeze(requests), errors };
}

function projectConsolidationOutcomes<T>(
	value: unknown,
	requests: readonly AgenticMemoryConsolidationRequest[],
	records: readonly AgenticMemoryRecord<T>[],
	evaluation: number,
): {
	readonly results: readonly AgenticMemoryConsolidationResult[];
	readonly proposedRecordDrafts: readonly AgenticMemoryConsolidationRecordDraft<T>[];
	readonly recordProposals: readonly AgenticMemoryRecordProposal<T>[];
	readonly commands: readonly AgenticMemoryConsolidationCommand[];
	readonly errors: readonly Omit<AgenticMemoryConsolidationError, "cursor">[];
	readonly validOutcomes: number;
	readonly invalidOutcomes: number;
} {
	const byRequest = new Map(requests.map((request) => [request.id, request]));
	const recordsById = new Map(records.map((record) => [record.id, record]));
	const results: AgenticMemoryConsolidationResult[] = [];
	const proposedRecordDrafts: AgenticMemoryConsolidationRecordDraft<T>[] = [];
	const recordProposals: AgenticMemoryRecordProposal<T>[] = [];
	const commands: AgenticMemoryConsolidationCommand[] = [];
	const errors: Omit<AgenticMemoryConsolidationError, "cursor">[] = [];
	let validOutcomes = 0;
	let invalidOutcomes = 0;
	if (!Array.isArray(value)) {
		return {
			results,
			proposedRecordDrafts,
			recordProposals,
			commands,
			validOutcomes,
			invalidOutcomes: 1,
			errors: [
				{
					code: "invalid-outcomes-input",
					message: "agenticMemoryConsolidationBundle: outcomes input must be an array",
					outcome: value,
				},
			],
		};
	}
	const length = safeArrayLength(value);
	if (length === undefined) {
		return {
			results,
			proposedRecordDrafts,
			recordProposals,
			commands,
			validOutcomes,
			invalidOutcomes: 1,
			errors: [
				{
					code: "invalid-outcomes-input",
					message: "agenticMemoryConsolidationBundle: outcomes input length could not be read",
					outcome: value,
				},
			],
		};
	}
	const seenOutcomes = new Set<FactId>();
	for (let i = 0; i < length; i += 1) {
		let raw: unknown;
		let outcome: {
			readonly outcome?: AgenticMemoryConsolidationOutcome<T>;
			readonly error?: Omit<AgenticMemoryConsolidationError, "cursor">;
		};
		try {
			if (!Object.hasOwn(value, i)) {
				throw new TypeError("outcome array must be dense");
			}
			raw = value[i];
			outcome = validateConsolidationOutcome<T>(raw, i);
		} catch (error) {
			invalidOutcomes += 1;
			errors.push({
				code: "invalid-outcome",
				message: `agenticMemoryConsolidationBundle: outcome access failed: ${errorMessage(error)}`,
				index: i,
				outcome: raw,
				validationErrors: Object.freeze(["outcome access failed"]),
			});
			continue;
		}
		if (outcome.error !== undefined || outcome.outcome === undefined) {
			invalidOutcomes += 1;
			if (outcome.error !== undefined) errors.push(outcome.error);
			continue;
		}
		const validOutcome = outcome.outcome;
		if (seenOutcomes.has(validOutcome.id)) {
			invalidOutcomes += 1;
			errors.push({
				code: "duplicate-outcome-id",
				message: "agenticMemoryConsolidationBundle: duplicate outcome id",
				index: i,
				outcomeId: validOutcome.id,
				requestId: validOutcome.requestId,
				outcome: raw,
				validationErrors: Object.freeze([`duplicate outcome id '${validOutcome.id}'`]),
			});
			continue;
		}
		const request = byRequest.get(validOutcome.requestId);
		if (request === undefined) {
			invalidOutcomes += 1;
			errors.push({
				code: "missing-request-ref",
				message: "agenticMemoryConsolidationBundle: outcome references missing request",
				index: i,
				outcomeId: validOutcome.id,
				requestId: validOutcome.requestId,
				outcome: raw,
				validationErrors: Object.freeze([`request '${validOutcome.requestId}' is not projected`]),
			});
			continue;
		}
		seenOutcomes.add(validOutcome.id);
		if (validOutcome.kind === "failed") {
			validOutcomes += 1;
			const resultId = compoundTupleKey("agentic-memory-consolidation-result", [
				validOutcome.requestId,
				validOutcome.id,
			]);
			results.push(
				Object.freeze({
					id: resultId,
					requestId: validOutcome.requestId,
					outcomeId: validOutcome.id,
					state: "failed",
					sourceRecordIds: request.recordIds,
					proposedRecordIds: Object.freeze([]),
					message: validOutcome.message,
					...(validOutcome.provenance === undefined ? {} : { provenance: validOutcome.provenance }),
				}),
			);
			commands.push(
				Object.freeze({
					id: compoundTupleKey("agentic-memory-consolidation-command", [resultId, "markFailed"]),
					kind: "markFailed",
					requestId: validOutcome.requestId,
					outcomeId: validOutcome.id,
					message: validOutcome.message,
				}),
			);
			continue;
		}
		const operation = validOutcome.applicationOperation ?? "create";
		const operationVersion =
			validOutcome.operationVersion ?? AGENTIC_MEMORY_RECORD_APPLICATION_OPERATION_VERSION;
		const targetRecordIds = validOutcome.targetRecordIds;
		if (operation === "replace" || operation === "update") {
			const validationErrors: string[] = [];
			if (targetRecordIds === undefined || targetRecordIds.length !== validOutcome.records.length) {
				validationErrors.push(`${operation} outcome.targetRecordIds must align with records`);
			}
			for (let recordIndex = 0; recordIndex < validOutcome.records.length; recordIndex += 1) {
				const record = validOutcome.records[recordIndex] as AgenticMemoryRecord<T>;
				const targetRecordId = targetRecordIds?.[recordIndex];
				if (targetRecordId === undefined) continue;
				if (!request.recordIds.includes(targetRecordId)) {
					validationErrors.push(
						`targetRecordIds[${recordIndex}]: target record '${targetRecordId}' is not in the request`,
					);
				}
				if (!recordsById.has(targetRecordId)) {
					validationErrors.push(
						`targetRecordIds[${recordIndex}]: target record '${targetRecordId}' is not projected`,
					);
				}
				if (record.id !== targetRecordId) {
					validationErrors.push(
						`records[${recordIndex}]: ${operation} record id '${record.id}' must equal target record id '${targetRecordId}'`,
					);
				}
			}
			if (validationErrors.length > 0) {
				invalidOutcomes += 1;
				errors.push({
					code: "invalid-proposed-record",
					message: `agenticMemoryConsolidationBundle: ${operation} outcome is invalid`,
					index: i,
					outcomeId: validOutcome.id,
					requestId: validOutcome.requestId,
					outcome: raw,
					validationErrors: Object.freeze(validationErrors),
				});
				continue;
			}
		}
		validOutcomes += 1;
		const draftIds = validOutcome.records.map((record) =>
			compoundTupleKey("agentic-memory-record-draft", [
				validOutcome.requestId,
				validOutcome.id,
				record.id,
			]),
		);
		const proposalIds = validOutcome.records.map((record) =>
			compoundTupleKey("agentic-memory-record-proposal", [
				validOutcome.requestId,
				validOutcome.id,
				record.id,
			]),
		);
		for (let recordIndex = 0; recordIndex < validOutcome.records.length; recordIndex += 1) {
			const record = validOutcome.records[recordIndex] as AgenticMemoryRecord<T>;
			const draftId = draftIds[recordIndex] as FactId;
			const proposalId = proposalIds[recordIndex] as FactId;
			const targetRecordId = targetRecordIds?.[recordIndex];
			const targetRecord =
				targetRecordId === undefined ? undefined : recordsById.get(targetRecordId);
			const refs = consolidationProposalRefs(request, validOutcome.id, draftId, targetRecord);
			const candidateMaterial: AgenticMemoryRecordCandidateMaterial<T> = Object.freeze({
				kind: "agentic-memory-record-candidate-material",
				operation,
				operationVersion,
				record,
				...(targetRecordId === undefined ? {} : { targetRecordId }),
				sourceRefs: refs,
				evidenceRefs: refs,
			});
			proposedRecordDrafts.push(
				Object.freeze({
					id: draftId,
					requestId: validOutcome.requestId,
					outcomeId: validOutcome.id,
					record,
					applicationOperation: operation,
					operationVersion,
					...(targetRecordId === undefined ? {} : { targetRecordId }),
					proposalId,
					candidateMaterial,
				}),
			);
			recordProposals.push(
				Object.freeze({
					kind: "agentic-memory-record-proposal",
					proposalId,
					operation,
					operationVersion,
					candidateMaterial,
					...(targetRecordId === undefined ? {} : { targetRecordId }),
					reason: request.reason ?? validOutcome.provenance ?? "consolidation",
					proposalStatus: "consolidation-proposed",
					sourceRefs: refs,
					evidenceRefs: refs,
					idempotencyKey: proposalId,
					correlationId: request.id,
					causationId: validOutcome.id,
				}),
			);
		}
		const resultId = compoundTupleKey("agentic-memory-consolidation-result", [
			validOutcome.requestId,
			validOutcome.id,
		]);
		results.push(
			Object.freeze({
				id: resultId,
				requestId: validOutcome.requestId,
				outcomeId: validOutcome.id,
				state: "proposed",
				sourceRecordIds: request.recordIds,
				proposedRecordIds: Object.freeze(validOutcome.records.map((record) => record.id)),
				applicationOperation: operation,
				...(targetRecordIds === undefined ? {} : { targetRecordIds }),
				proposalIds: Object.freeze(proposalIds),
				...(validOutcome.provenance === undefined ? {} : { provenance: validOutcome.provenance }),
			}),
		);
		commands.push(
			Object.freeze({
				id: compoundTupleKey("agentic-memory-consolidation-command", [resultId, "proposeRecords"]),
				kind: "proposeRecords",
				requestId: validOutcome.requestId,
				outcomeId: validOutcome.id,
				draftIds: Object.freeze(draftIds),
				proposalIds: Object.freeze(proposalIds),
			}),
		);
	}
	void evaluation;
	return {
		results: Object.freeze(results),
		proposedRecordDrafts: Object.freeze(proposedRecordDrafts),
		recordProposals: Object.freeze(recordProposals),
		commands: Object.freeze(commands),
		errors,
		validOutcomes,
		invalidOutcomes,
	};
}

function consolidationProposalRefs(
	request: AgenticMemoryConsolidationRequest,
	outcomeId: FactId,
	draftId: FactId,
	targetRecord?: AgenticMemoryRecord<unknown>,
): readonly AgenticMemoryFactRef[] {
	return Object.freeze([
		Object.freeze({ kind: "agentic-memory-consolidation-request", id: request.id }),
		Object.freeze({ kind: "agentic-memory-consolidation-outcome", id: outcomeId }),
		Object.freeze({ kind: "agentic-memory-consolidation-record-draft", id: draftId }),
		...(targetRecord === undefined
			? []
			: [
					Object.freeze({ kind: "agentic-memory-record", id: targetRecord.id }),
					Object.freeze({ kind: "agentic-memory-fragment", id: targetRecord.fragment.id }),
				]),
	]);
}

function validateConsolidationOutcome<T>(
	value: unknown,
	index: number,
): {
	readonly outcome?: AgenticMemoryConsolidationOutcome<T>;
	readonly error?: Omit<AgenticMemoryConsolidationError, "cursor">;
} {
	if (!isPlainRecord(value)) {
		return {
			error: {
				code: "invalid-outcome",
				message: "agenticMemoryConsolidationBundle: outcome must be an object",
				index,
				outcome: value,
			},
		};
	}
	const errors: string[] = [];
	const id = isNonEmptyString(value.id) ? value.id : undefined;
	const requestId = isNonEmptyString(value.requestId) ? value.requestId : undefined;
	if (id === undefined) errors.push("outcome.id must be a non-empty string");
	if (requestId === undefined) errors.push("outcome.requestId must be a non-empty string");
	if (value.kind !== "proposedRecords" && value.kind !== "failed") {
		errors.push("outcome.kind must be proposedRecords or failed");
	}
	if (value.provenance !== undefined && typeof value.provenance !== "string") {
		errors.push("outcome.provenance must be a string when present");
	}
	if (
		value.applicationOperation !== undefined &&
		value.applicationOperation !== "create" &&
		value.applicationOperation !== "replace" &&
		value.applicationOperation !== "update"
	) {
		errors.push("outcome.applicationOperation must be create, replace, or update when present");
	}
	if (
		value.operationVersion !== undefined &&
		value.operationVersion !== AGENTIC_MEMORY_RECORD_APPLICATION_OPERATION_VERSION
	) {
		errors.push("outcome.operationVersion must be 1 when present");
	}
	if (value.kind === "failed" && !isNonEmptyString(value.message)) {
		errors.push("failed outcome.message must be a non-empty string");
	}
	const records: AgenticMemoryRecord<T>[] = [];
	let targetRecordIds: readonly FactId[] | undefined;
	if (value.kind === "proposedRecords") {
		if (value.targetRecordIds !== undefined) {
			if (!isDenseArrayOf(value.targetRecordIds, isNonEmptyString)) {
				errors.push("proposedRecords.targetRecordIds must be a dense non-empty string array");
			} else {
				targetRecordIds = Object.freeze([...value.targetRecordIds]);
			}
		}
		if (!Array.isArray(value.records)) {
			errors.push("proposedRecords.records must be a non-empty array");
		} else {
			const recordsLength = safeArrayLength(value.records);
			const seenRecordIds = new Set<FactId>();
			if (recordsLength === undefined || recordsLength === 0) {
				errors.push("proposedRecords.records must be a non-empty array");
			}
			for (let i = 0; i < (recordsLength ?? 0); i += 1) {
				let result: {
					readonly record?: AgenticMemoryRecord<T>;
					readonly errors: Omit<AgenticMemoryError, "cursor">[];
				};
				try {
					if (!Object.hasOwn(value.records, i)) {
						throw new TypeError("proposedRecords.records must be dense");
					}
					result = validateAndSnapshotRecord<T>(value.records[i], i);
				} catch (error) {
					errors.push(`records[${i}]: record access failed: ${errorMessage(error)}`);
					continue;
				}
				if (result.record === undefined || result.errors.length > 0) {
					errors.push(
						...result.errors
							.flatMap((error) => error.validationErrors ?? [error.message])
							.map((error) => `records[${i}]: ${error}`),
					);
				} else if (seenRecordIds.has(result.record.id)) {
					errors.push(`records[${i}]: duplicate proposed record id '${result.record.id}'`);
				} else {
					seenRecordIds.add(result.record.id);
					records.push(result.record);
				}
			}
		}
	}
	if (errors.length > 0 || id === undefined || requestId === undefined) {
		return {
			error: {
				code: value.kind === "proposedRecords" ? "invalid-proposed-record" : "invalid-outcome",
				message: "agenticMemoryConsolidationBundle: outcome is invalid",
				index,
				outcomeId: id,
				requestId,
				outcome: value,
				validationErrors: Object.freeze(errors),
			},
		};
	}
	if (value.kind === "failed") {
		return {
			outcome: Object.freeze({
				id,
				requestId,
				kind: "failed",
				message: value.message as string,
				...(value.provenance === undefined ? {} : { provenance: value.provenance as string }),
			}),
		};
	}
	return {
		outcome: Object.freeze({
			id,
			requestId,
			kind: "proposedRecords",
			...(value.applicationOperation === undefined
				? {}
				: {
						applicationOperation:
							value.applicationOperation as AgenticMemoryRecordApplicationOperation,
					}),
			...(value.operationVersion === undefined
				? {}
				: { operationVersion: value.operationVersion as 1 }),
			records: Object.freeze(records),
			...(targetRecordIds === undefined ? {} : { targetRecordIds }),
			...(value.provenance === undefined ? {} : { provenance: value.provenance as string }),
		}),
	};
}

function consolidationErrorFromRecordError(
	error: Omit<AgenticMemoryError, "cursor">,
): Omit<AgenticMemoryConsolidationError, "cursor"> {
	return {
		...error,
		code: error.code,
	};
}

function consolidationErrorFromRetentionError(
	error: Omit<AgenticMemoryRetentionError, "cursor">,
): Omit<AgenticMemoryConsolidationError, "cursor"> {
	return {
		...error,
		code: error.code,
	};
}

import { depLatest } from "../../ctx/types.js";
import type { Graph } from "../../graph/graph.js";
import type { FactId } from "../../patterns/semantic-memory.js";
import { solutionProjection } from "./projection.js";
import {
	agenticStatusState,
	assertStrictJsonValue,
	cloneStrictJsonObject,
	errorMessage,
	freezeError,
	isNonEmptyString,
	isPlainRecord,
	safeArrayLength,
	validateAgenticMemoryContextAttribution,
	validateRecordMetadata,
} from "./shared.js";
import type {
	AgenticMemoryContextEntry,
	AgenticMemoryContextPackingBundle,
	AgenticMemoryContextPackingBundleOptions,
	AgenticMemoryContextPackingCursor,
	AgenticMemoryContextPackingError,
	AgenticMemoryContextPackingPolicy,
	AgenticMemoryContextPackingSnapshot,
	AgenticMemoryContextPackingStatus,
	AgenticMemoryContextText,
	AgenticMemoryPackedContext,
	AgenticMemoryPackedContextEntry,
	ValidatedPackingContext,
} from "./types.js";

/**
 * Creates an agentic memory context packing bundle.
 *
 * @param graph - Graph that owns the created nodes or projector.
 * @param opts - Options that configure the helper.
 * @returns A bundle of graph-visible nodes for the recipe.
 * @category solutions
 * @example
 * ```ts
 * import { agenticMemoryContextPackingBundle } from "@graphrefly/ts/solutions/agentic-memory";
 * ```
 */
export function agenticMemoryContextPackingBundle<T = unknown>(
	graph: Graph,
	opts: AgenticMemoryContextPackingBundleOptions<T>,
): AgenticMemoryContextPackingBundle<T> {
	const name = opts.name ?? "agenticMemoryContextPacking";
	const projection = graph.node<AgenticMemoryContextPackingSnapshot>(
		[opts.context, opts.texts, opts.policy],
		(ctx) => {
			const state =
				ctx.state.get<{ evaluation: number }>() ??
				({ evaluation: 0 } satisfies { evaluation: number });
			state.evaluation += 1;
			const packed = packContext(
				depLatest(ctx, 0),
				depLatest(ctx, 1),
				depLatest(ctx, 2),
				state.evaluation,
			);
			ctx.state.set(state);
			ctx.down([["DATA", packed]]);
		},
		{
			name: `${name}/projection`,
			factory: "agenticMemoryContextPacking",
			completeWhenDepsComplete: false,
			errorWhenDepsError: false,
		},
	);
	return {
		input: { context: opts.context, texts: opts.texts, policy: opts.policy },
		projection,
		packedContext: solutionProjection(
			graph,
			projection,
			`${name}/packedContext`,
			"agenticMemoryPackedContext",
			(fact) => fact.packedContext,
		),
		status: solutionProjection(
			graph,
			projection,
			`${name}/status`,
			"agenticMemoryContextPackingStatus",
			(fact) => fact.status,
		),
		errors: solutionProjection(
			graph,
			projection,
			`${name}/errors`,
			"agenticMemoryContextPackingErrors",
			(fact) => fact.errors,
		),
		cursor: solutionProjection(
			graph,
			projection,
			`${name}/cursor`,
			"agenticMemoryContextPackingCursor",
			(fact) => fact.cursor,
		),
	};
}

function packContext(
	contextValue: unknown,
	textsValue: unknown,
	policyValue: unknown,
	evaluation: number,
): AgenticMemoryContextPackingSnapshot {
	const errors: Omit<AgenticMemoryContextPackingError, "cursor">[] = [];
	const context = validatePackingContext(contextValue, errors);
	const texts = validateContextTexts(textsValue, errors);
	const policy = validatePackingPolicy(policyValue, errors);
	const packedEntries: AgenticMemoryPackedContextEntry[] = [];
	let omittedEntries = 0;
	let totalChars = 0;
	let totalCost = 0;
	if (context !== undefined && policy !== undefined) {
		for (const entry of context.entries) {
			const textFact = texts.get(entry.fragmentId);
			if (textFact === undefined) {
				omittedEntries += 1;
				errors.push({
					code: "missing-text",
					message: "agenticMemoryContextPackingBundle: missing text projection for context entry",
					fragmentId: entry.fragmentId,
					validationErrors: [`missing text for fragment '${entry.fragmentId}'`],
				});
				continue;
			}
			const cost = textFact.cost ?? textFact.text.length;
			const nextEntries = packedEntries.length + 1;
			const separatorChars = packedEntries.length === 0 ? 0 : 2;
			const nextChars = totalChars + separatorChars + textFact.text.length;
			const nextCost = totalCost + cost;
			const exceeds =
				(policy.maxEntries !== undefined && nextEntries > policy.maxEntries) ||
				(policy.maxChars !== undefined && nextChars > policy.maxChars) ||
				(policy.maxCost !== undefined && nextCost > policy.maxCost);
			if (exceeds) {
				omittedEntries += 1;
				continue;
			}
			const packedEntry: AgenticMemoryPackedContextEntry = Object.freeze({
				fragmentId: entry.fragmentId,
				text: textFact.text,
				cost,
				chars: textFact.text.length,
				...(entry.record === undefined ? {} : { record: entry.record }),
				...(entry.attribution === undefined ? {} : { attribution: entry.attribution }),
				...(policy.includeMetadata && textFact.metadata !== undefined
					? { metadata: textFact.metadata }
					: {}),
			});
			packedEntries.push(packedEntry);
			totalChars = nextChars;
			totalCost = nextCost;
		}
	}
	const cursor: AgenticMemoryContextPackingCursor = Object.freeze({
		evaluation,
		inputEntries: context?.entries.length ?? 0,
		packedEntries: packedEntries.length,
		omittedEntries,
		totalChars,
		totalCost,
	});
	const errorFacts = Object.freeze(
		errors.map((error) =>
			freezeError({
				...error,
				cursor,
			}),
		),
	);
	const packedContext: AgenticMemoryPackedContext = Object.freeze({
		entries: Object.freeze(packedEntries),
		text: packedEntries.map((entry) => entry.text).join("\n\n"),
		totalChars,
		totalCost,
		truncated: omittedEntries > 0,
	});
	const status: AgenticMemoryContextPackingStatus = Object.freeze({
		state: agenticStatusState(errorFacts.length, packedEntries.length),
		cursor,
	});
	return Object.freeze({
		packedContext,
		status,
		errors: errorFacts,
		cursor,
	});
}

function validatePackingContext(
	value: unknown,
	errors: Omit<AgenticMemoryContextPackingError, "cursor">[],
): ValidatedPackingContext | undefined {
	if (!isPlainRecord(value)) {
		errors.push({
			code: "invalid-context",
			message: "agenticMemoryContextPackingBundle: context must be an AgenticMemoryContext fact",
			value,
		});
		return undefined;
	}
	let entriesValue: unknown;
	try {
		entriesValue = value.entries;
	} catch (error) {
		errors.push({
			code: "invalid-context",
			message: `agenticMemoryContextPackingBundle: context entries access failed: ${errorMessage(error)}`,
			value,
			validationErrors: ["context entries access failed"],
		});
		return undefined;
	}
	if (!Array.isArray(entriesValue)) {
		errors.push({
			code: "invalid-context",
			message: "agenticMemoryContextPackingBundle: context must be an AgenticMemoryContext fact",
			value,
			validationErrors: ["context.entries must be an array"],
		});
		return undefined;
	}
	const length = safeArrayLength(entriesValue);
	if (length === undefined) {
		errors.push({
			code: "invalid-context",
			message: "agenticMemoryContextPackingBundle: context entries length could not be read",
			value,
			validationErrors: ["context.entries length could not be read"],
		});
		return undefined;
	}
	const entries: AgenticMemoryContextEntry[] = [];
	for (let i = 0; i < length; i += 1) {
		let raw: unknown;
		try {
			raw = entriesValue[i];
			if (!isPlainRecord(raw) || !isNonEmptyString(raw.fragmentId)) {
				errors.push({
					code: "invalid-context",
					message: "agenticMemoryContextPackingBundle: context entry is invalid",
					index: i,
					value: raw,
					validationErrors: ["context entry fragmentId must be a non-empty string"],
				});
				continue;
			}
			const record = validateRecordMetadata(raw.record);
			if (!record.ok) {
				errors.push({
					code: "invalid-context",
					message: "agenticMemoryContextPackingBundle: context entry record metadata is invalid",
					index: i,
					fragmentId: raw.fragmentId,
					value: raw,
					validationErrors: Object.freeze(record.errors),
				});
				continue;
			}
			const attribution = validateAgenticMemoryContextAttribution(raw.attribution, {
				fragmentId: raw.fragmentId,
				recordId: record.metadata?.recordId,
			});
			if (!attribution.ok) {
				errors.push({
					code: "invalid-context",
					message: "agenticMemoryContextPackingBundle: context entry attribution is invalid",
					index: i,
					fragmentId: raw.fragmentId,
					validationErrors: Object.freeze(attribution.errors),
				});
				continue;
			}
			entries.push(
				Object.freeze({
					fragmentId: raw.fragmentId,
					...(record.metadata === undefined ? {} : { record: record.metadata }),
					...(attribution.attribution === undefined
						? {}
						: { attribution: attribution.attribution }),
				}) as AgenticMemoryContextEntry,
			);
		} catch (error) {
			errors.push({
				code: "invalid-context",
				message: `agenticMemoryContextPackingBundle: context entry access failed: ${errorMessage(error)}`,
				index: i,
				value: raw,
				validationErrors: ["context entry access failed"],
			});
		}
	}
	return Object.freeze({
		entries: Object.freeze(entries),
	});
}

function validateContextTexts(
	value: unknown,
	errors: Omit<AgenticMemoryContextPackingError, "cursor">[],
): Map<FactId, AgenticMemoryContextText> {
	const out = new Map<FactId, AgenticMemoryContextText>();
	if (!Array.isArray(value)) {
		errors.push({
			code: "invalid-texts-input",
			message: "agenticMemoryContextPackingBundle: texts input must be an array",
			value,
		});
		return out;
	}
	const length = safeArrayLength(value);
	if (length === undefined) {
		errors.push({
			code: "invalid-texts-input",
			message: "agenticMemoryContextPackingBundle: texts input length could not be read",
			value,
		});
		return out;
	}
	for (let i = 0; i < length; i += 1) {
		try {
			const raw = value[i];
			const result = validateContextText(raw, i);
			if (result.error !== undefined) {
				errors.push(result.error);
				continue;
			}
			if (result.text === undefined) {
				errors.push({
					code: "invalid-text",
					message: "agenticMemoryContextPackingBundle: text fact is invalid",
					index: i,
					value: raw,
					validationErrors: ["text validation returned no fact"],
				});
				continue;
			}
			if (out.has(result.text.fragmentId)) {
				errors.push({
					code: "duplicate-text-fragment-id",
					message: "agenticMemoryContextPackingBundle: duplicate text fragment id",
					index: i,
					fragmentId: result.text.fragmentId,
					value: raw,
					validationErrors: [`duplicate text fragment id '${result.text.fragmentId}'`],
				});
				continue;
			}
			out.set(result.text.fragmentId, result.text);
		} catch (error) {
			errors.push({
				code: "invalid-text",
				message: `agenticMemoryContextPackingBundle: text access failed: ${errorMessage(error)}`,
				index: i,
				validationErrors: ["text access failed"],
			});
		}
	}
	return out;
}

function validateContextText(
	value: unknown,
	index: number,
): {
	readonly text?: AgenticMemoryContextText;
	readonly error?: Omit<AgenticMemoryContextPackingError, "cursor">;
} {
	if (!isPlainRecord(value)) {
		return {
			error: {
				code: "invalid-text",
				message: "agenticMemoryContextPackingBundle: text fact must be an object",
				index,
				value,
			},
		};
	}
	const errors: string[] = [];
	if (!isNonEmptyString(value.fragmentId)) errors.push("fragmentId must be a non-empty string");
	if (typeof value.text !== "string") errors.push("text must be a string");
	if (
		value.cost !== undefined &&
		(typeof value.cost !== "number" || !Number.isFinite(value.cost) || value.cost < 0)
	) {
		errors.push("cost must be a finite number >= 0");
	}
	if (value.metadata !== undefined) {
		try {
			if (!isPlainRecord(value.metadata)) {
				throw new TypeError("metadata must be a plain object when present");
			}
			assertStrictJsonValue(value.metadata, "metadata");
		} catch (error) {
			errors.push(errorMessage(error));
		}
	}
	if (errors.length > 0) {
		return {
			error: {
				code: "invalid-text",
				message: "agenticMemoryContextPackingBundle: text fact is invalid",
				index,
				fragmentId: typeof value.fragmentId === "string" ? value.fragmentId : undefined,
				value,
				validationErrors: Object.freeze(errors),
			},
		};
	}
	return {
		text: Object.freeze({
			fragmentId: value.fragmentId as string,
			text: value.text as string,
			...(value.cost === undefined ? {} : { cost: value.cost as number }),
			...(value.metadata === undefined ? {} : { metadata: cloneStrictJsonObject(value.metadata) }),
		}),
	};
}

function validatePackingPolicy(
	value: unknown,
	errors: Omit<AgenticMemoryContextPackingError, "cursor">[],
): AgenticMemoryContextPackingPolicy | undefined {
	if (!isPlainRecord(value)) {
		errors.push({
			code: "invalid-policy",
			message: "agenticMemoryContextPackingBundle: policy must be an object",
			value,
		});
		return undefined;
	}
	const validation: string[] = [];
	let maxEntries: unknown;
	let maxChars: unknown;
	let maxCost: unknown;
	let includeMetadata: unknown;
	try {
		maxEntries = value.maxEntries;
		maxChars = value.maxChars;
		maxCost = value.maxCost;
		includeMetadata = value.includeMetadata;
	} catch (error) {
		errors.push({
			code: "invalid-policy",
			message: `agenticMemoryContextPackingBundle: policy access failed: ${errorMessage(error)}`,
			value,
			validationErrors: ["policy access failed"],
		});
		return undefined;
	}
	if (
		maxEntries !== undefined &&
		(typeof maxEntries !== "number" || !Number.isSafeInteger(maxEntries) || maxEntries < 0)
	) {
		validation.push("maxEntries must be a safe integer >= 0");
	}
	if (
		maxChars !== undefined &&
		(typeof maxChars !== "number" || !Number.isSafeInteger(maxChars) || maxChars < 0)
	) {
		validation.push("maxChars must be a safe integer >= 0");
	}
	if (
		maxCost !== undefined &&
		(typeof maxCost !== "number" || !Number.isFinite(maxCost) || maxCost < 0)
	) {
		validation.push("maxCost must be a finite number >= 0");
	}
	if (includeMetadata !== undefined && typeof includeMetadata !== "boolean") {
		validation.push("includeMetadata must be a boolean when present");
	}
	if (validation.length > 0) {
		errors.push({
			code: "invalid-policy",
			message: "agenticMemoryContextPackingBundle: policy is invalid",
			value,
			validationErrors: Object.freeze(validation),
		});
		return undefined;
	}
	return Object.freeze({
		...(maxEntries === undefined ? {} : { maxEntries: maxEntries as number }),
		...(maxChars === undefined ? {} : { maxChars: maxChars as number }),
		...(maxCost === undefined ? {} : { maxCost: maxCost as number }),
		...(includeMetadata === undefined ? {} : { includeMetadata: includeMetadata as boolean }),
	});
}

import { depBatch } from "../../ctx/types.js";
import type { DataIssue } from "../../data/index.js";
import type { Graph } from "../../graph/graph.js";
import { cloneStrictJsonValue } from "../../json/codec.js";
import type { Node } from "../../node/node.js";
import {
	AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND,
	type AgenticMemoryCommittedFactBatch,
	type AgenticMemoryCommittedFactCursor,
	type AgenticMemoryCommittedFactIdentity,
	type AgenticMemoryCommittedFactMaterialIdentity,
	type AgenticMemoryFactCommitResult,
	type AgenticMemoryFactCommitStatus,
	type AgenticMemoryFactLogAuditEntry,
	agenticMemoryFactCommitStatusIsDurable,
	agenticMemoryFactCommitStatusIsTerminalFailure,
	assertAgenticMemoryCommittedFactBatch,
} from "./committed-fact-log.js";
import { solutionProjection } from "./projection.js";
import type { StrictJsonValue } from "./types.js";

export const AGENTIC_MEMORY_DURABILITY_ADVANCE_ON_COMMITTED_OR_DUPLICATE_POLICY =
	"agentic-memory-durability-advance-on-committed-or-duplicate";

export type AgenticMemoryDurabilityGateStatusState = "durable" | "terminal-failure" | "uncertain";

export interface AgenticMemoryDurabilityDownstreamAdvancePolicy {
	readonly kind: "agentic-memory-durability-downstream-advance-policy";
	readonly policyId: string;
	readonly allowCommitted?: true;
	readonly allowDuplicate?: true;
}

export interface AgenticMemoryDurabilityDownstreamAdvance {
	readonly kind: "agentic-memory-durability-downstream-advance";
	readonly allowed: boolean;
	readonly policyId?: string;
	readonly commitStatus: AgenticMemoryFactCommitStatus;
	readonly reason:
		| "fact-log-committed"
		| "fact-log-duplicate"
		| "terminal-durability-attempt-failure"
		| "uncertain-requires-read-resolution"
		| "no-explicit-policy";
}

export interface AgenticMemoryDurabilityGateCursor {
	readonly evaluation: number;
	readonly batchFacts: number;
	readonly resultFacts: number;
	readonly committed: number;
	readonly duplicate: number;
	readonly terminalFailures: number;
	readonly uncertain: number;
	readonly issues: number;
}

export interface AgenticMemoryDurabilityGateStatus {
	readonly state: AgenticMemoryDurabilityGateStatusState;
	readonly commitStatus: AgenticMemoryFactCommitStatus;
	readonly downstreamAdvance: AgenticMemoryDurabilityDownstreamAdvance;
	readonly factLogCursor: AgenticMemoryCommittedFactCursor;
	readonly cursor: AgenticMemoryDurabilityGateCursor;
}

export interface AgenticMemoryDurabilityGateAuditEntry {
	readonly kind: "agentic-memory-durability-gate-audit";
	readonly action:
		| "durability-result-projected"
		| "downstream-advance-allowed"
		| "downstream-advance-blocked"
		| "terminal-failure-recorded"
		| "uncertain-resolution-required"
		| "fact-log-audit-linked"
		| "issue-recorded";
	readonly reason?: string;
	readonly commitStatus?: AgenticMemoryFactCommitStatus;
	readonly batchIdentity?: AgenticMemoryCommittedFactMaterialIdentity;
	readonly factLogCursor?: AgenticMemoryCommittedFactCursor;
	readonly factLogAction?: AgenticMemoryFactLogAuditEntry["action"];
}

export interface AgenticMemoryDurabilityResult {
	readonly kind: "agentic-memory-durability-result";
	readonly batchIdentity: AgenticMemoryCommittedFactMaterialIdentity;
	readonly factIdentities: readonly AgenticMemoryCommittedFactIdentity[];
	readonly batchFacts: number;
	readonly commitStatus: AgenticMemoryFactCommitStatus;
	readonly factLogCursor: AgenticMemoryCommittedFactCursor;
	readonly state: AgenticMemoryDurabilityGateStatusState;
	readonly downstreamAdvance: AgenticMemoryDurabilityDownstreamAdvance;
}

export interface AgenticMemoryDurabilityGateProjection {
	readonly kind: "agentic-memory-durability-gate-projection";
	readonly result: AgenticMemoryDurabilityResult;
	readonly status: AgenticMemoryDurabilityGateStatus;
	readonly issues: readonly DataIssue[];
	readonly audit: readonly AgenticMemoryDurabilityGateAuditEntry[];
	readonly cursor: AgenticMemoryDurabilityGateCursor;
}

export interface AgenticMemoryDurabilityUncertainResolutionStatus {
	readonly kind: "agentic-memory-durability-uncertain-resolution-status";
	readonly state: "not-required" | "requires-fact-log-read";
	readonly batchIdentity: AgenticMemoryCommittedFactMaterialIdentity;
	readonly factIdentities: readonly AgenticMemoryCommittedFactIdentity[];
	readonly factLogCursor: AgenticMemoryCommittedFactCursor;
	readonly reason: "status-is-not-uncertain" | "uncertain-requires-read-idempotency-resolution";
}

export interface AgenticMemoryDurabilityGateInput<TJson extends StrictJsonValue = StrictJsonValue> {
	readonly kind: "agentic-memory-durability-gate-input";
	readonly batch: AgenticMemoryCommittedFactBatch<TJson>;
	readonly commitResult: AgenticMemoryFactCommitResult;
}

export interface AgenticMemoryDurabilityGateBundle<
	TJson extends StrictJsonValue = StrictJsonValue,
> {
	readonly input: {
		readonly attemptResult: Node<AgenticMemoryDurabilityGateInput<TJson>>;
	};
	readonly projection: Node<AgenticMemoryDurabilityGateProjection>;
	readonly result: Node<AgenticMemoryDurabilityResult>;
	readonly status: Node<AgenticMemoryDurabilityGateStatus>;
	readonly downstreamAdvance: Node<AgenticMemoryDurabilityDownstreamAdvance>;
	readonly issues: Node<readonly DataIssue[]>;
	readonly audit: Node<readonly AgenticMemoryDurabilityGateAuditEntry[]>;
	readonly cursor: Node<AgenticMemoryDurabilityGateCursor>;
}

export interface AgenticMemoryDurabilityGateBundleOptions<
	TJson extends StrictJsonValue = StrictJsonValue,
> {
	readonly name?: string;
	readonly attemptResult: Node<AgenticMemoryDurabilityGateInput<TJson>>;
	readonly downstreamAdvancePolicy?: AgenticMemoryDurabilityDownstreamAdvancePolicy;
}

/** D590 explicit policy for workflows that may advance after fact-log durability.
 *
 * The returned policy only allows `committed` and `duplicate` fact-log commit
 * statuses. It does not turn a durability result into an application
 * acknowledgement, live graph truth, record mutation authority, hot hydration,
 * or a graph wave/batch commit barrier.
 *
 * @param policyId - Optional caller-visible policy identifier.
 * @returns A D590 downstream-advance policy.
 * @category solutions
 */
export function agenticMemoryDurabilityAdvanceOnCommittedOrDuplicatePolicy(
	policyId = AGENTIC_MEMORY_DURABILITY_ADVANCE_ON_COMMITTED_OR_DUPLICATE_POLICY,
): AgenticMemoryDurabilityDownstreamAdvancePolicy {
	return Object.freeze({
		kind: "agentic-memory-durability-downstream-advance-policy",
		policyId,
		allowCommitted: true,
		allowDuplicate: true,
	});
}

/** Evaluate the D590 explicit downstream-advance policy.
 *
 * Only `committed` and `duplicate` can return true, and only when the supplied
 * policy explicitly allows that status.
 *
 * @param status - D589 fact-log commit status.
 * @param policy - Explicit downstream-advance policy.
 * @returns Whether a downstream workflow may advance by the supplied policy.
 * @category solutions
 */
export function agenticMemoryDurabilityResultMayAdvance(
	status: AgenticMemoryFactCommitStatus,
	policy: AgenticMemoryDurabilityDownstreamAdvancePolicy,
): boolean {
	if (status === "committed") return policy.allowCommitted === true;
	if (status === "duplicate") return policy.allowDuplicate === true;
	return false;
}

/** Pair a canonical D589 fact batch with its explicit fact-log commit result.
 *
 * The graph bundle consumes this paired DATA shape so it never correlates a
 * stale result from one batch with another batch. The pair is still only
 * fact-log persistence progress, not an application acknowledgement or graph
 * commit barrier.
 *
 * @param batch - Canonical D589 committed fact batch.
 * @param commitResult - D589 fact-log commit result for this batch attempt.
 * @returns A D590 durability-gate input DATA object.
 * @category solutions
 */
export function agenticMemoryDurabilityGateInput<TJson extends StrictJsonValue = StrictJsonValue>(
	batch: AgenticMemoryCommittedFactBatch<TJson>,
	commitResult: AgenticMemoryFactCommitResult,
): AgenticMemoryDurabilityGateInput<TJson> {
	return Object.freeze({
		kind: "agentic-memory-durability-gate-input",
		batch: assertAgenticMemoryCommittedFactBatch<TJson>(batch),
		commitResult: assertAgenticMemoryFactCommitResult(commitResult),
	});
}

/** Project a D590 graph-visible durability result from a canonical batch and commit result.
 *
 * This helper classifies fact-log persistence progress only. It does not call a
 * backend, append facts, acknowledge application success, mutate records,
 * hydrate/restore graph state, or create a graph commit barrier.
 *
 * @param batch - Canonical D589 committed fact batch.
 * @param commitResult - Host/backend supplied D589 fact-log commit result DATA.
 * @param opts - Optional evaluation counter and explicit downstream-advance policy.
 * @returns Durability result/read-model DATA facts.
 * @category solutions
 */
export function projectAgenticMemoryDurabilityGate<TJson extends StrictJsonValue = StrictJsonValue>(
	batch: AgenticMemoryCommittedFactBatch<TJson>,
	commitResult: AgenticMemoryFactCommitResult,
	opts: {
		readonly evaluation?: number;
		readonly downstreamAdvancePolicy?: AgenticMemoryDurabilityDownstreamAdvancePolicy;
	} = {},
): AgenticMemoryDurabilityGateProjection {
	const canonicalBatch = assertAgenticMemoryCommittedFactBatch<TJson>(batch);
	const result = assertAgenticMemoryFactCommitResult(commitResult);
	const issues = Object.freeze([...result.issues]);
	const state = durabilityState(result.status);
	const downstreamAdvance = downstreamAdvanceFor(result.status, opts.downstreamAdvancePolicy);
	const cursor = Object.freeze({
		evaluation: opts.evaluation ?? 0,
		batchFacts: canonicalBatch.facts.length,
		resultFacts: result.facts,
		committed: result.status === "committed" ? 1 : 0,
		duplicate: result.status === "duplicate" ? 1 : 0,
		terminalFailures: agenticMemoryFactCommitStatusIsTerminalFailure(result.status) ? 1 : 0,
		uncertain: result.status === "uncertain" ? 1 : 0,
		issues: issues.length,
	} satisfies AgenticMemoryDurabilityGateCursor);
	const durabilityResult: AgenticMemoryDurabilityResult = Object.freeze({
		kind: "agentic-memory-durability-result",
		batchIdentity: canonicalBatch.batchIdentity,
		factIdentities: Object.freeze(canonicalBatch.facts.map((fact) => fact.identity)),
		batchFacts: canonicalBatch.facts.length,
		commitStatus: result.status,
		factLogCursor: result.cursor,
		state,
		downstreamAdvance,
	});
	const status: AgenticMemoryDurabilityGateStatus = Object.freeze({
		state,
		commitStatus: result.status,
		downstreamAdvance,
		factLogCursor: result.cursor,
		cursor,
	});
	const audit = Object.freeze([
		auditEntry("durability-result-projected", {
			batchIdentity: canonicalBatch.batchIdentity,
			commitStatus: result.status,
			factLogCursor: result.cursor,
		}),
		auditEntry(
			downstreamAdvance.allowed ? "downstream-advance-allowed" : "downstream-advance-blocked",
			{
				batchIdentity: canonicalBatch.batchIdentity,
				commitStatus: result.status,
				factLogCursor: result.cursor,
				reason: downstreamAdvance.reason,
			},
		),
		...(agenticMemoryFactCommitStatusIsTerminalFailure(result.status)
			? [
					auditEntry("terminal-failure-recorded", {
						batchIdentity: canonicalBatch.batchIdentity,
						commitStatus: result.status,
						factLogCursor: result.cursor,
					}),
				]
			: []),
		...(result.status === "uncertain"
			? [
					auditEntry("uncertain-resolution-required", {
						batchIdentity: canonicalBatch.batchIdentity,
						commitStatus: result.status,
						factLogCursor: result.cursor,
						reason: "read/idempotency resolution required",
					}),
				]
			: []),
		...result.audit.map((entry) =>
			auditEntry("fact-log-audit-linked", {
				batchIdentity: canonicalBatch.batchIdentity,
				commitStatus: result.status,
				factLogCursor: entry.cursor ?? result.cursor,
				factLogAction: entry.action,
				reason: entry.reason,
			}),
		),
		...issues.map((issue) =>
			auditEntry("issue-recorded", {
				batchIdentity: canonicalBatch.batchIdentity,
				commitStatus: result.status,
				factLogCursor: result.cursor,
				reason: issue.code,
			}),
		),
	]);
	return Object.freeze({
		kind: "agentic-memory-durability-gate-projection",
		result: durabilityResult,
		status,
		issues,
		audit,
		cursor,
	});
}

/** Describe the D590 resolution requirement for an uncertain durability result.
 *
 * This helper does not perform the read. It only names the required next
 * boundary: explicit fact-log read plus idempotency/material-identity
 * resolution, followed by library-owned materialization if facts re-enter.
 *
 * @param result - D590 durability result DATA.
 * @returns Whether explicit fact-log read resolution is required.
 * @category solutions
 */
export function agenticMemoryDurabilityUncertainResolutionStatus(
	result: AgenticMemoryDurabilityResult,
): AgenticMemoryDurabilityUncertainResolutionStatus {
	return Object.freeze({
		kind: "agentic-memory-durability-uncertain-resolution-status",
		state: result.commitStatus === "uncertain" ? "requires-fact-log-read" : "not-required",
		batchIdentity: result.batchIdentity,
		factIdentities: result.factIdentities,
		factLogCursor: result.factLogCursor,
		reason:
			result.commitStatus === "uncertain"
				? "uncertain-requires-read-idempotency-resolution"
				: "status-is-not-uncertain",
	});
}

/** Create a graph-visible D590 durability-result gate bundle.
 *
 * The bundle consumes explicit paired batch/result DATA supplied by a host or
 * adapter boundary. It performs no storage I/O, never appends facts, and never
 * correlates independent latest values.
 *
 * @param graph - Graph that owns the created nodes.
 * @param opts - Paired attempt-result input plus optional explicit downstream policy.
 * @returns Projection and read-model nodes for durability result/status/issues/audit/cursor.
 * @category solutions
 */
export function agenticMemoryDurabilityGateBundle<TJson extends StrictJsonValue = StrictJsonValue>(
	graph: Graph,
	opts: AgenticMemoryDurabilityGateBundleOptions<TJson>,
): AgenticMemoryDurabilityGateBundle<TJson> {
	const name = opts.name ?? "agenticMemoryDurabilityGate";
	const projection = graph.node<AgenticMemoryDurabilityGateProjection>(
		[opts.attemptResult],
		(ctx) => {
			const attempts = depBatch(ctx, 0) ?? [];
			if (attempts.length === 0) return;
			const state =
				ctx.state.get<{ evaluation: number }>() ??
				({ evaluation: 0 } satisfies { evaluation: number });
			const outputs: AgenticMemoryDurabilityGateProjection[] = [];
			for (const raw of attempts) {
				const attempt = assertAgenticMemoryDurabilityGateInput<TJson>(raw);
				state.evaluation += 1;
				outputs.push(
					projectAgenticMemoryDurabilityGate(attempt.batch, attempt.commitResult, {
						evaluation: state.evaluation,
						downstreamAdvancePolicy: opts.downstreamAdvancePolicy,
					}),
				);
			}
			ctx.state.set(state);
			ctx.down(outputs.map((output) => ["DATA", output] as const));
		},
		{
			name: `${name}/projection`,
			factory: "agenticMemoryDurabilityGate",
			completeWhenDepsComplete: false,
			errorWhenDepsError: false,
		},
	);
	return {
		input: { attemptResult: opts.attemptResult },
		projection,
		result: solutionProjection(
			graph,
			projection,
			`${name}/result`,
			"agenticMemoryDurabilityGateResult",
			(fact) => fact.result,
		),
		status: solutionProjection(
			graph,
			projection,
			`${name}/status`,
			"agenticMemoryDurabilityGateStatus",
			(fact) => fact.status,
		),
		downstreamAdvance: solutionProjection(
			graph,
			projection,
			`${name}/downstreamAdvance`,
			"agenticMemoryDurabilityGateDownstreamAdvance",
			(fact) => fact.status.downstreamAdvance,
		),
		issues: solutionProjection(
			graph,
			projection,
			`${name}/issues`,
			"agenticMemoryDurabilityGateIssues",
			(fact) => fact.issues,
		),
		audit: solutionProjection(
			graph,
			projection,
			`${name}/audit`,
			"agenticMemoryDurabilityGateAudit",
			(fact) => fact.audit,
		),
		cursor: solutionProjection(
			graph,
			projection,
			`${name}/cursor`,
			"agenticMemoryDurabilityGateCursor",
			(fact) => fact.cursor,
		),
	};
}

function assertAgenticMemoryDurabilityGateInput<TJson extends StrictJsonValue = StrictJsonValue>(
	value: unknown,
): AgenticMemoryDurabilityGateInput<TJson> {
	const cloned = cloneStrictJsonValue(value, "agenticMemoryDurabilityGateInput");
	if (cloned === null || typeof cloned !== "object" || Array.isArray(cloned)) {
		throw new TypeError("agenticMemoryDurabilityGateInput: input must be an object");
	}
	const input = cloned as unknown as AgenticMemoryDurabilityGateInput<TJson>;
	if (input.kind !== "agentic-memory-durability-gate-input") {
		throw new TypeError("agenticMemoryDurabilityGateInput: invalid kind");
	}
	return agenticMemoryDurabilityGateInput(input.batch, input.commitResult);
}

function assertAgenticMemoryFactCommitResult(
	value: AgenticMemoryFactCommitResult,
): AgenticMemoryFactCommitResult {
	const cloned = cloneStrictJsonValue(value, "agenticMemoryFactCommitResult");
	if (cloned === null || typeof cloned !== "object" || Array.isArray(cloned)) {
		throw new TypeError("agenticMemoryFactCommitResult: result must be an object");
	}
	const result = cloned as unknown as AgenticMemoryFactCommitResult;
	if (!isCommitStatus(result.status)) {
		throw new TypeError("agenticMemoryFactCommitResult: invalid status");
	}
	validateCursor(result.cursor);
	if (!Number.isSafeInteger(result.facts) || result.facts < 0) {
		throw new TypeError("agenticMemoryFactCommitResult: facts must be a non-negative safe integer");
	}
	if (!Array.isArray(result.issues)) {
		throw new TypeError("agenticMemoryFactCommitResult: issues must be an array");
	}
	if (!Array.isArray(result.audit)) {
		throw new TypeError("agenticMemoryFactCommitResult: audit must be an array");
	}
	const cursor = freezeCursor(result.cursor);
	return Object.freeze({
		status: result.status,
		cursor,
		facts: result.facts,
		issues: Object.freeze(result.issues.map(freezeIssue)),
		audit: Object.freeze(result.audit.map(freezeFactLogAuditEntry)),
	});
}

function downstreamAdvanceFor(
	status: AgenticMemoryFactCommitStatus,
	policy: AgenticMemoryDurabilityDownstreamAdvancePolicy | undefined,
): AgenticMemoryDurabilityDownstreamAdvance {
	const nonDurableReason = agenticMemoryFactCommitStatusIsTerminalFailure(status)
		? "terminal-durability-attempt-failure"
		: status === "uncertain"
			? "uncertain-requires-read-resolution"
			: undefined;
	if (nonDurableReason !== undefined) {
		return Object.freeze({
			kind: "agentic-memory-durability-downstream-advance",
			allowed: false,
			...(policy === undefined ? {} : { policyId: policy.policyId }),
			commitStatus: status,
			reason: nonDurableReason,
		});
	}
	if (policy === undefined) {
		return Object.freeze({
			kind: "agentic-memory-durability-downstream-advance",
			allowed: false,
			commitStatus: status,
			reason: "no-explicit-policy",
		});
	}
	const allowed = agenticMemoryDurabilityResultMayAdvance(status, policy);
	return Object.freeze({
		kind: "agentic-memory-durability-downstream-advance",
		allowed,
		policyId: policy.policyId,
		commitStatus: status,
		reason: status === "committed" ? "fact-log-committed" : "fact-log-duplicate",
	});
}

function durabilityState(
	status: AgenticMemoryFactCommitStatus,
): AgenticMemoryDurabilityGateStatusState {
	if (agenticMemoryFactCommitStatusIsDurable(status)) return "durable";
	if (agenticMemoryFactCommitStatusIsTerminalFailure(status)) return "terminal-failure";
	return "uncertain";
}

function isCommitStatus(value: unknown): value is AgenticMemoryFactCommitStatus {
	return (
		value === "committed" ||
		value === "duplicate" ||
		value === "conflict" ||
		value === "rejected" ||
		value === "uncertain"
	);
}

function validateCursor(cursor: AgenticMemoryCommittedFactCursor): void {
	if (cursor?.kind !== AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND) {
		throw new TypeError("agenticMemoryFactCommitResult: cursor must be a fact-stream cursor");
	}
	if (!Number.isSafeInteger(cursor.position) || cursor.position < 0) {
		throw new TypeError("agenticMemoryFactCommitResult: cursor position must be >= 0");
	}
}

function freezeCursor(cursor: AgenticMemoryCommittedFactCursor): AgenticMemoryCommittedFactCursor {
	validateCursor(cursor);
	return Object.freeze({ kind: cursor.kind, position: cursor.position });
}

function freezeIssue(issue: DataIssue): DataIssue {
	return deepFreezeStrict({ ...issue }) as DataIssue;
}

function freezeFactLogAuditEntry(
	entry: AgenticMemoryFactLogAuditEntry,
): AgenticMemoryFactLogAuditEntry {
	return deepFreezeStrict({
		...entry,
		...(entry.cursor === undefined ? {} : { cursor: freezeCursor(entry.cursor) }),
	}) as AgenticMemoryFactLogAuditEntry;
}

function deepFreezeStrict<T>(value: T): T {
	if (value === null || typeof value !== "object") return value;
	for (const item of Object.values(value)) deepFreezeStrict(item);
	return Object.freeze(value);
}

function auditEntry(
	action: AgenticMemoryDurabilityGateAuditEntry["action"],
	fields: Omit<AgenticMemoryDurabilityGateAuditEntry, "kind" | "action"> = {},
): AgenticMemoryDurabilityGateAuditEntry {
	return Object.freeze({ kind: "agentic-memory-durability-gate-audit", action, ...fields });
}

