/** Read committed facts at runtime start and project D591/D593 DATA.
 *
 * This helper is an explicit runtime/source-boundary composition over D589,
 * D591, and D593. It calls the supplied fact log's `read` method, materializes
 * the returned committed facts with library-owned rules, and exposes
 * caller-wirable records, priorEvidence, evidence, status, issues, audit, and
 * cursor DTOs. It does not read a concrete backend directly, hydrate/restore a
 * graph, mutate live records, refresh subscribers, or create a graph commit
 * barrier.
 *
 * @param log - D589/D592-compatible committed fact log.
 * @param opts - Optional read cursor/limit and evaluation counter.
 * @returns Startup read composition DATA, or a PromiseLike when the log is async.
 * @category solutions
 */
export function agenticMemoryCommittedFactLogStartupRead<
	TJson extends StrictJsonValue = StrictJsonValue,
>(
	log: AgenticMemoryCommittedFactLog<TJson>,
	opts: AgenticMemoryCommittedFactLogStartupReadOptions = {},
):
	| AgenticMemoryCommittedFactLogStartupReadResult<TJson>
	| PromiseLike<AgenticMemoryCommittedFactLogStartupReadResult<TJson>> {
	const evaluation = opts.evaluation ?? 0;
	const fallbackCursor = freezeFactCursor(opts.read?.after ?? factCursor(0));
	try {
		const read = log.read(opts.read);
		return isPromiseLike(read)
			? read.then(
					(result) =>
						safeStartupReadResult<TJson>(
							normalizeAgenticMemoryCommittedFactLogBackendReadResult<TJson>(result, {
								fallbackCursor,
							}),
							evaluation,
							fallbackCursor,
						),
					(error) => startupReadResult<TJson>(readFailureResult(error, fallbackCursor), evaluation),
				)
			: startupReadResult<TJson>(
					normalizeAgenticMemoryCommittedFactLogBackendReadResult<TJson>(read, {
						fallbackCursor,
					}),
					evaluation,
				);
	} catch (error) {
		return startupReadResult<TJson>(readFailureResult(error, fallbackCursor), evaluation);
	}
}

/** Append a canonical committed fact batch and project D590 durability DATA.
 *
 * This helper is an explicit runtime/source-boundary composition over D589 and
 * D590. It appends only caller-supplied canonical committed fact batches through
 * the supplied fact log and returns durability DATA for explicit downstream
 * policy. A result is fact-log persistence progress only: not application
 * acknowledgement, live graph truth, record mutation authority, hot hydration,
 * restore, or a graph wave/batch commit barrier.
 *
 * @param log - D589/D592-compatible committed fact log.
 * @param batch - Canonical committed fact batch to append.
 * @param opts - Optional evaluation counter and explicit downstream policy.
 * @returns Append attempt composition DATA, or a PromiseLike when the log is async.
 * @category solutions
 */
export function agenticMemoryCommittedFactLogAppendAttempt<
	TJson extends StrictJsonValue = StrictJsonValue,
>(
	log: AgenticMemoryCommittedFactLog<TJson>,
	batch: AgenticMemoryCommittedFactBatch<TJson>,
	opts: AgenticMemoryCommittedFactLogAppendAttemptOptions = {},
):
	| AgenticMemoryCommittedFactLogAppendAttemptResult<TJson>
	| PromiseLike<AgenticMemoryCommittedFactLogAppendAttemptResult<TJson>> {
	const canonicalBatch = assertAgenticMemoryCommittedFactBatch<TJson>(batch);
	const evaluation = opts.evaluation ?? 0;
	try {
		const appended = log.append(canonicalBatch);
		return isPromiseLike(appended)
			? appended.then(
					(result) =>
						safeAppendAttemptResult(
							canonicalBatch,
							normalizeAgenticMemoryCommittedFactLogBackendAppendResult(result, {
								expectedFacts: canonicalBatch.facts.length,
							}),
							opts,
							evaluation,
						),
					(error) =>
						appendAttemptResult(
							canonicalBatch,
							appendFailureResult(error, factCursor(0)),
							opts,
							evaluation,
						),
				)
			: appendAttemptResult(
					canonicalBatch,
					normalizeAgenticMemoryCommittedFactLogBackendAppendResult(appended, {
						expectedFacts: canonicalBatch.facts.length,
					}),
					opts,
					evaluation,
				);
	} catch (error) {
		return appendAttemptResult(
			canonicalBatch,
			appendFailureResult(error, factCursor(0)),
			opts,
			evaluation,
		);
	}
}

function safeStartupReadResult<TJson extends StrictJsonValue>(
	readResult: AgenticMemoryCommittedFactReadResult<TJson>,
	evaluation: number,
	fallbackCursor: AgenticMemoryCommittedFactCursor,
): AgenticMemoryCommittedFactLogStartupReadResult<TJson> {
	try {
		return startupReadResult<TJson>(readResult, evaluation);
	} catch (error) {
		return startupReadResult<TJson>(readFailureResult(error, fallbackCursor), evaluation);
	}
}

function safeAppendAttemptResult<TJson extends StrictJsonValue>(
	batch: AgenticMemoryCommittedFactBatch<TJson>,
	commitResult: AgenticMemoryFactCommitResult,
	opts: AgenticMemoryCommittedFactLogAppendAttemptOptions,
	evaluation: number,
): AgenticMemoryCommittedFactLogAppendAttemptResult<TJson> {
	try {
		return appendAttemptResult(batch, commitResult, opts, evaluation);
	} catch (error) {
		return appendAttemptResult(batch, appendFailureResult(error, factCursor(0)), opts, evaluation);
	}
}

function startupReadResult<TJson extends StrictJsonValue>(
	readResult: AgenticMemoryCommittedFactReadResult<TJson>,
	evaluation: number,
): AgenticMemoryCommittedFactLogStartupReadResult<TJson> {
	const materialization = projectAgenticMemoryCommittedFactReadMaterialization<TJson>(readResult, {
		evaluation,
	});
	const bootstrap = projectAgenticMemoryMaterializedFactLogBootstrap<TJson>(materialization, {
		evaluation,
	});
	const cursor: AgenticMemoryCommittedFactLogStartupReadCursor = Object.freeze({
		evaluation,
		factLogCursor: freezeFactCursor(bootstrap.status.factLogCursor),
		readMaterialization: materialization.cursor,
		bootstrap: bootstrap.cursor,
	});
	const issues = Object.freeze([...bootstrap.issues]);
	return Object.freeze({
		kind: "agentic-memory-committed-fact-log-startup-read-result",
		readResult,
		materialization,
		bootstrap,
		bootstrapInput: bootstrap.input,
		records: bootstrap.records,
		priorEvidence: bootstrap.priorEvidence,
		evidence: bootstrap.evidence,
		bootstrapStatus: bootstrap.status,
		issues,
		audit: Object.freeze([
			auditEntry("startup-read-attempted", {
				factLogCursor: readResult.cursor,
				reason: "explicit runtime boundary read",
			}),
			auditEntry("read-result-linked", {
				factLogCursor: readResult.cursor,
				reason: `${readResult.facts.length} committed facts supplied as DATA`,
			}),
			auditEntry("materialization-linked", {
				factLogCursor: materialization.status.factLogCursor,
				reason: materialization.status.state,
			}),
			auditEntry("bootstrap-linked", {
				factLogCursor: bootstrap.status.factLogCursor,
				reason: bootstrap.status.readyForCallerWiring
					? "caller-wirable DATA ready"
					: "caller-wirable DATA not ready",
			}),
			auditEntry("startup-read-projected", {
				factLogCursor: bootstrap.status.factLogCursor,
				reason: "D591 materialization and D593 bootstrap projection completed",
			}),
			...issues.map((item) => auditEntry("issue-recorded", { reason: item.code })),
		]),
		cursor,
	});
}

function appendAttemptResult<TJson extends StrictJsonValue>(
	batch: AgenticMemoryCommittedFactBatch<TJson>,
	commitResult: AgenticMemoryFactCommitResult,
	opts: AgenticMemoryCommittedFactLogAppendAttemptOptions,
	evaluation: number,
): AgenticMemoryCommittedFactLogAppendAttemptResult<TJson> {
	const attemptResult = agenticMemoryDurabilityGateInput(batch, commitResult);
	const durability = projectAgenticMemoryDurabilityGate(batch, commitResult, {
		evaluation,
		downstreamAdvancePolicy: opts.downstreamAdvancePolicy,
	});
	const cursor: AgenticMemoryCommittedFactLogAppendAttemptCursor = Object.freeze({
		evaluation,
		factLogCursor: freezeFactCursor(durability.status.factLogCursor),
		durability: durability.cursor,
	});
	const issues = Object.freeze([...durability.issues]);
	return Object.freeze({
		kind: "agentic-memory-committed-fact-log-append-attempt-result",
		batch,
		commitResult,
		attemptResult,
		durability,
		durabilityStatus: durability.status,
		issues,
		audit: Object.freeze([
			auditEntry("append-attempted", {
				factLogCursor: commitResult.cursor,
				reason: "explicit runtime boundary append",
			}),
			auditEntry("commit-result-linked", {
				factLogCursor: commitResult.cursor,
				reason: commitResult.status,
			}),
			auditEntry("durability-linked", {
				factLogCursor: durability.status.factLogCursor,
				reason: durability.status.state,
			}),
			auditEntry("append-durability-projected", {
				factLogCursor: durability.status.factLogCursor,
				reason: "D590 durability result DATA projected",
			}),
			...issues.map((item) => auditEntry("issue-recorded", { reason: item.code })),
		]),
		cursor,
	});
}

function readFailureResult<TJson extends StrictJsonValue>(
	error: unknown,
	cursor: AgenticMemoryCommittedFactCursor,
): AgenticMemoryCommittedFactReadResult<TJson> {
	const readIssue = issue(
		"agentic-memory.fact-log-runtime.startup-read-threw",
		error instanceof Error ? error.message : String(error),
	);
	return Object.freeze({
		facts: Object.freeze([]),
		cursor: freezeFactCursor(cursor),
		done: false,
		issues: Object.freeze([readIssue]),
		audit: Object.freeze([
			factLogAudit("facts-read", {
				cursor,
				reason: "runtime boundary read failed before committed facts were proven",
			}),
			factLogAudit("issue-recorded", { reason: readIssue.code }),
		]),
	});
}

function appendFailureResult(
	error: unknown,
	cursor: AgenticMemoryCommittedFactCursor,
): AgenticMemoryFactCommitResult {
	const appendIssue = issue(
		"agentic-memory.fact-log-runtime.append-threw",
		error instanceof Error ? error.message : String(error),
	);
	return Object.freeze({
		status: "uncertain",
		cursor: freezeFactCursor(cursor),
		facts: 0,
		issues: Object.freeze([appendIssue]),
		audit: Object.freeze([
			factLogAudit("batch-uncertain", {
				cursor,
				reason: "runtime boundary append failed before commit status was proven",
			}),
			factLogAudit("issue-recorded", { reason: appendIssue.code }),
		]),
	});
}

function factCursor(position: number): AgenticMemoryCommittedFactCursor {
	return Object.freeze({ kind: AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND, position });
}

function freezeFactCursor(
	cursor: AgenticMemoryCommittedFactCursor,
): AgenticMemoryCommittedFactCursor {
	if (cursor.kind !== AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND) {
		throw new TypeError("AgenticMemory fact-log runtime cursor must be a fact-stream cursor");
	}
	if (!Number.isSafeInteger(cursor.position) || cursor.position < 0) {
		throw new TypeError("AgenticMemory fact-log runtime cursor position must be >= 0");
	}
	return Object.freeze({ kind: cursor.kind, position: cursor.position });
}

function issue(code: string, message: string): DataIssue {
	return Object.freeze({ kind: "issue", code, message, severity: "error" });
}

function factLogAudit(
	action: AgenticMemoryFactLogAuditEntry["action"],
	fields: Omit<AgenticMemoryFactLogAuditEntry, "kind" | "action"> = {},
): AgenticMemoryFactLogAuditEntry {
	return Object.freeze({ kind: "agentic-memory-fact-log-audit", action, ...fields });
}

function auditEntry(
	action: AgenticMemoryCommittedFactLogRuntimePersistenceAuditEntry["action"],
	fields: Omit<AgenticMemoryCommittedFactLogRuntimePersistenceAuditEntry, "kind" | "action"> = {},
): AgenticMemoryCommittedFactLogRuntimePersistenceAuditEntry {
	return Object.freeze({
		kind: "agentic-memory-committed-fact-log-runtime-persistence-audit",
		action,
		...fields,
	});
}

function isPromiseLike<T>(value: T | PromiseLike<T>): value is PromiseLike<T> {
	return (
		value !== null &&
		(typeof value === "object" || typeof value === "function") &&
		typeof (value as PromiseLike<T>).then === "function"
	);
}

import { type Codec, strictJsonCodec } from "../../json/codec.js";
import type { MemoryFragment } from "../../patterns/semantic-memory.js";
import {
	assertAgenticMemoryRecordCodecShape,
	assertArtifactKindValue,
	assertConfidence,
	assertExactKeys,
	assertFiniteNumberArray,
	assertKindValue,
	assertNonEmptyString,
	assertPersistenceLevelValue,
	assertScopeFrame,
	assertStrictJsonValue,
	assertString,
	assertStringArray,
	decimalBigIntString,
	isPlainRecord,
	parseDecimalBigInt,
	validateAndSnapshotRecord,
} from "./shared.js";
import type {
	AgenticMemoryFragmentFrame,
	AgenticMemoryRecord,
	AgenticMemoryRecordFrame,
	StrictJsonValue,
} from "./types.js";

export const AGENTIC_MEMORY_RECORD_FRAME_FORMAT = "graphrefly.agenticMemoryRecord";
export const AGENTIC_MEMORY_RECORD_FRAME_VERSION = 1;

/**
 * Creates an agentic memory record frame.
 *
 * @param record - Record to encode, validate, or project.
 * @returns The agentic memory record frame result.
 * @category solutions
 * @example
 * ```ts
 * import { agenticMemoryRecordFrame } from "@graphrefly/ts/solutions/agentic-memory";
 * ```
 */
export function agenticMemoryRecordFrame<TJson extends StrictJsonValue>(
	record: AgenticMemoryRecord<TJson>,
): AgenticMemoryRecordFrame<TJson> {
	const result = validateAndSnapshotRecord<TJson>(record, 0);
	if (result.errors.length > 0 || result.record === undefined) {
		throw new TypeError(
			`agenticMemoryRecordFrame: invalid record: ${result.errors
				.flatMap((error) => error.validationErrors ?? [error.message])
				.join("; ")}`,
		);
	}
	assertAgenticMemoryRecordCodecShape(record);
	assertStrictJsonValue(result.record.fragment.payload, "record.fragment.payload");
	return Object.freeze({
		format: AGENTIC_MEMORY_RECORD_FRAME_FORMAT,
		version: AGENTIC_MEMORY_RECORD_FRAME_VERSION,
		record: Object.freeze({
			id: result.record.id,
			kind: result.record.kind,
			persistenceLevel: result.record.persistenceLevel,
			artifactKind: result.record.artifactKind,
			...(result.record.scope === undefined ? {} : { scope: result.record.scope }),
			fragment: fragmentFrame(result.record.fragment as MemoryFragment<TJson>),
		}),
	});
}

/** Assert and snapshot a decoded D166 record frame. Unknown fields fail honestly.
 * @param value - Unknown value to check or decode.
 * @returns The narrowed, validated value.
 * @category solutions
 * @example
 * ```ts
 * import { assertAgenticMemoryRecordFrame } from "@graphrefly/ts/solutions";
 * ```
 */
export function assertAgenticMemoryRecordFrame<TJson extends StrictJsonValue = StrictJsonValue>(
	value: unknown,
): AgenticMemoryRecordFrame<TJson> {
	if (!isPlainRecord(value))
		throw new TypeError("agenticMemoryRecordFrame: frame must be an object");
	assertStrictJsonValue(value, "agenticMemoryRecordFrame");
	assertExactKeys(value, ["format", "record", "version"], "agenticMemoryRecordFrame");
	if (value.format !== AGENTIC_MEMORY_RECORD_FRAME_FORMAT) {
		throw new TypeError("agenticMemoryRecordFrame: invalid format");
	}
	if (value.version !== AGENTIC_MEMORY_RECORD_FRAME_VERSION) {
		throw new TypeError("agenticMemoryRecordFrame: invalid version");
	}
	const rawRecord = value.record;
	if (!isPlainRecord(rawRecord)) {
		throw new TypeError("agenticMemoryRecordFrame: record must be an object");
	}
	assertExactKeys(
		rawRecord,
		rawRecord.scope === undefined
			? ["artifactKind", "fragment", "id", "kind", "persistenceLevel"]
			: ["artifactKind", "fragment", "id", "kind", "persistenceLevel", "scope"],
		"agenticMemoryRecordFrame.record",
	);
	const rawFragment = rawRecord.fragment;
	if (!isPlainRecord(rawFragment)) {
		throw new TypeError("agenticMemoryRecordFrame: fragment must be an object");
	}
	assertExactKeys(
		rawFragment,
		[
			"id",
			"payload",
			"tNs",
			...(rawFragment.validFrom === undefined ? [] : ["validFrom"]),
			...(rawFragment.validTo === undefined ? [] : ["validTo"]),
			"confidence",
			"tags",
			"sources",
			...(rawFragment.embedding === undefined ? [] : ["embedding"]),
			...(rawFragment.parentFragmentId === undefined ? [] : ["parentFragmentId"]),
			...(rawFragment.provenance === undefined ? [] : ["provenance"]),
		],
		"agenticMemoryRecordFrame.record.fragment",
	);
	if (rawRecord.scope !== undefined) assertScopeFrame(rawRecord.scope);
	const frame = value as unknown as AgenticMemoryRecordFrame<TJson>;
	const decoded = recordFromFrame(frame);
	const roundtrip = agenticMemoryRecordFrame(decoded);
	return roundtrip as AgenticMemoryRecordFrame<TJson>;
}

/** Strict canonical JSON codec for D166 AgenticMemoryRecordFrame values.
 * @returns A `Codec<AgenticMemoryRecordFrame<TJson>>` value.
 * @category solutions
 * @example
 * ```ts
 * import { agenticMemoryRecordFrameCodec } from "@graphrefly/ts/solutions";
 * ```
 */
export function agenticMemoryRecordFrameCodec<
	TJson extends StrictJsonValue = StrictJsonValue,
>(): Codec<AgenticMemoryRecordFrame<TJson>> {
	return {
		encode(value: AgenticMemoryRecordFrame<TJson>): Uint8Array {
			return strictJsonCodec.encode(assertAgenticMemoryRecordFrame<TJson>(value));
		},
		decode(bytes: Uint8Array): AgenticMemoryRecordFrame<TJson> {
			return assertAgenticMemoryRecordFrame<TJson>(strictJsonCodec.decode(bytes));
		},
	};
}

/** Strict canonical JSON codec that persists records and decodes bigint fields back to bigint.
 * @returns A `Codec<` value.
 * @category solutions
 * @example
 * ```ts
 * import { agenticMemoryRecordCodec } from "@graphrefly/ts/solutions";
 * ```
 */
export function agenticMemoryRecordCodec<TJson extends StrictJsonValue = StrictJsonValue>(): Codec<
	AgenticMemoryRecord<TJson>
> {
	const frameCodec = agenticMemoryRecordFrameCodec<TJson>();
	return {
		encode(value: AgenticMemoryRecord<TJson>): Uint8Array {
			return frameCodec.encode(agenticMemoryRecordFrame(value));
		},
		decode(bytes: Uint8Array): AgenticMemoryRecord<TJson> {
			return recordFromFrame(frameCodec.decode(bytes));
		},
	};
}

/**
 * D167 solution-level retention command projection.
 *
 * Archive/restore/setPersistenceLevel are derived views over current records;
 * requestConsolidation emits request facts only.
 */

function fragmentFrame<TJson extends StrictJsonValue>(
	fragment: MemoryFragment<TJson>,
): AgenticMemoryFragmentFrame<TJson> {
	return Object.freeze({
		id: fragment.id,
		payload: fragment.payload,
		tNs: decimalBigIntString(fragment.tNs, "fragment.tNs"),
		...(fragment.validFrom === undefined
			? {}
			: { validFrom: decimalBigIntString(fragment.validFrom, "fragment.validFrom") }),
		...(fragment.validTo === undefined
			? {}
			: { validTo: decimalBigIntString(fragment.validTo, "fragment.validTo") }),
		confidence: fragment.confidence,
		tags: Object.freeze([...fragment.tags]),
		sources: Object.freeze([...fragment.sources]),
		...(fragment.embedding === undefined
			? {}
			: { embedding: Object.freeze([...fragment.embedding]) }),
		...(fragment.parentFragmentId === undefined
			? {}
			: { parentFragmentId: fragment.parentFragmentId }),
		...(fragment.provenance === undefined ? {} : { provenance: fragment.provenance }),
	});
}

function recordFromFrame<TJson extends StrictJsonValue>(
	frame: AgenticMemoryRecordFrame<TJson>,
): AgenticMemoryRecord<TJson> {
	const fragment = frame.record.fragment;
	const record: AgenticMemoryRecord<TJson> = {
		id: assertNonEmptyString(frame.record.id, "record.id"),
		kind: assertKindValue(frame.record.kind),
		persistenceLevel: assertPersistenceLevelValue(frame.record.persistenceLevel),
		artifactKind: assertArtifactKindValue(frame.record.artifactKind),
		...(frame.record.scope === undefined ? {} : { scope: assertScopeFrame(frame.record.scope) }),
		fragment: {
			id: assertNonEmptyString(fragment.id, "fragment.id"),
			payload: assertStrictJsonValue(fragment.payload, "fragment.payload") as TJson,
			tNs: parseDecimalBigInt(fragment.tNs, "fragment.tNs"),
			...(fragment.validFrom === undefined
				? {}
				: { validFrom: parseDecimalBigInt(fragment.validFrom, "fragment.validFrom") }),
			...(fragment.validTo === undefined
				? {}
				: { validTo: parseDecimalBigInt(fragment.validTo, "fragment.validTo") }),
			confidence: assertConfidence(fragment.confidence, "fragment.confidence"),
			tags: assertStringArray(fragment.tags, "fragment.tags"),
			sources: assertStringArray(fragment.sources, "fragment.sources"),
			...(fragment.embedding === undefined
				? {}
				: { embedding: assertFiniteNumberArray(fragment.embedding, "fragment.embedding") }),
			...(fragment.parentFragmentId === undefined
				? {}
				: {
						parentFragmentId: assertNonEmptyString(fragment.parentFragmentId, "parentFragmentId"),
					}),
			...(fragment.provenance === undefined
				? {}
				: { provenance: assertString(fragment.provenance, "provenance") }),
		},
	};
	const result = validateAndSnapshotRecord<TJson>(record, 0);
	if (result.errors.length > 0 || result.record === undefined) {
		throw new TypeError(
			`agenticMemoryRecordFrame: decoded record is invalid: ${result.errors
				.flatMap((error) => error.validationErrors ?? [error.message])
				.join("; ")}`,
		);
	}
	return result.record;
}

