/**
 * Creates an agentic memory kg projection bundle.
 *
 * @param graph - Graph that owns the created nodes or projector.
 * @param opts - Options that configure the helper.
 * @returns A bundle of graph-visible nodes for the recipe.
 * @category solutions
 * @example
 * ```ts
 * import { agenticMemoryKgProjectionBundle } from "@graphrefly/ts/solutions/agentic-memory";
 * ```
 */
export function agenticMemoryKgProjectionBundle(
	graph: Graph,
	opts: AgenticMemoryKgProjectionBundleOptions,
): AgenticMemoryKgProjectionBundle {
	const name = opts.name ?? "agenticMemoryKgProjection";
	const projection = graph.node<AgenticMemoryKgProjectionSnapshot>(
		[opts.records, opts.drafts],
		(ctx) => {
			const state =
				ctx.state.get<{ evaluation: number }>() ??
				({ evaluation: 0 } satisfies { evaluation: number });
			state.evaluation += 1;
			const recordProjection = validateAndProjectRecords(depLatest(ctx, 0));
			const draftProjection = validateAndProjectKgDrafts(
				depLatest(ctx, 1),
				recordProjection.records,
			);
			const cursor: AgenticMemoryKgProjectionCursor = Object.freeze({
				evaluation: state.evaluation,
				validRecords: recordProjection.records.length,
				validDrafts: draftProjection.assertions.length,
				invalidDrafts: draftProjection.invalidDrafts,
				projectedAssertions: draftProjection.assertions.length,
			});
			const errors = Object.freeze(
				[...recordProjection.errors.map(kgErrorFromRecordError), ...draftProjection.errors].map(
					(error) => freezeError({ ...error, cursor }),
				),
			);
			const status: AgenticMemoryKgProjectionStatus = Object.freeze({
				state: agenticStatusState(errors.length, draftProjection.assertions.length),
				cursor,
			});
			ctx.state.set(state);
			ctx.down([
				[
					"DATA",
					Object.freeze({
						assertions: Object.freeze(draftProjection.assertions),
						status,
						errors,
						cursor,
					}),
				],
			]);
		},
		{
			name: `${name}/projection`,
			factory: "agenticMemoryKgProjection",
			completeWhenDepsComplete: false,
			errorWhenDepsError: false,
		},
	);
	return {
		input: { records: opts.records, drafts: opts.drafts },
		projection,
		assertions: solutionProjection(
			graph,
			projection,
			`${name}/assertions`,
			"agenticMemoryKgAssertions",
			(fact) => fact.assertions,
		),
		status: solutionProjection(
			graph,
			projection,
			`${name}/status`,
			"agenticMemoryKgStatus",
			(fact) => fact.status,
		),
		errors: solutionProjection(
			graph,
			projection,
			`${name}/errors`,
			"agenticMemoryKgErrors",
			(fact) => fact.errors,
		),
		cursor: solutionProjection(
			graph,
			projection,
			`${name}/cursor`,
			"agenticMemoryKgCursor",
			(fact) => fact.cursor,
		),
	};
}

/** Build a D166 strict-JSON frame from an in-memory AgenticMemoryRecord. */

function validateAndProjectKgDrafts(
	value: unknown,
	records: readonly AgenticMemoryRecord[],
): {
	readonly assertions: KnowledgeAssertion[];
	readonly errors: Omit<AgenticMemoryKgProjectionError, "cursor">[];
	readonly invalidDrafts: number;
} {
	const assertions: KnowledgeAssertion[] = [];
	const errors: Omit<AgenticMemoryKgProjectionError, "cursor">[] = [];
	let invalidDrafts = 0;
	if (!Array.isArray(value)) {
		return {
			assertions,
			invalidDrafts: 1,
			errors: [
				{
					code: "invalid-drafts-input",
					message: "agenticMemoryKgProjectionBundle: drafts input must be an array",
					draft: value,
				},
			],
		};
	}
	const length = safeArrayLength(value);
	if (length === undefined) {
		return {
			assertions,
			invalidDrafts: 1,
			errors: [
				{
					code: "invalid-drafts-input",
					message: "agenticMemoryKgProjectionBundle: drafts input length could not be read",
					draft: value,
				},
			],
		};
	}
	const recordById = new Map(records.map((record) => [record.id, record]));
	const fragmentToRecord = new Map(records.map((record) => [record.fragment.id, record.id]));
	const seenAssertions = new Set<FactId>();
	for (let i = 0; i < length; i += 1) {
		let raw: unknown;
		try {
			raw = value[i];
			const result = validateKgDraft(raw, i);
			if (result.errors.length > 0 || result.draft === undefined) {
				invalidDrafts += 1;
				errors.push(...result.errors);
				continue;
			}
			const draft = result.draft;
			if (seenAssertions.has(draft.id)) {
				invalidDrafts += 1;
				errors.push({
					code: "duplicate-assertion-id",
					message: "agenticMemoryKgProjectionBundle: duplicate assertion id",
					index: i,
					assertionId: draft.id,
					recordId: draft.recordId,
					fragmentId: draft.fragmentId,
					draft: raw,
					validationErrors: [`duplicate assertion id '${draft.id}'`],
				});
				continue;
			}
			const record = recordById.get(draft.recordId);
			if (record === undefined) {
				invalidDrafts += 1;
				errors.push({
					code: "missing-record-ref",
					message: "agenticMemoryKgProjectionBundle: draft references a missing record",
					index: i,
					assertionId: draft.id,
					recordId: draft.recordId,
					fragmentId: draft.fragmentId,
					draft: raw,
					validationErrors: [`record '${draft.recordId}' is not projected`],
				});
				continue;
			}
			const owner = fragmentToRecord.get(draft.fragmentId);
			if (owner === undefined) {
				invalidDrafts += 1;
				errors.push({
					code: "missing-fragment-ref",
					message: "agenticMemoryKgProjectionBundle: draft references a missing fragment",
					index: i,
					assertionId: draft.id,
					recordId: draft.recordId,
					fragmentId: draft.fragmentId,
					draft: raw,
					validationErrors: [`fragment '${draft.fragmentId}' is not projected`],
				});
				continue;
			}
			if (owner !== draft.recordId || record.fragment.id !== draft.fragmentId) {
				invalidDrafts += 1;
				errors.push({
					code: "fragment-record-mismatch",
					message: "agenticMemoryKgProjectionBundle: draft record and fragment refs disagree",
					index: i,
					assertionId: draft.id,
					recordId: draft.recordId,
					fragmentId: draft.fragmentId,
					draft: raw,
					validationErrors: [
						`fragment '${draft.fragmentId}' belongs to record '${owner}', not '${draft.recordId}'`,
					],
				});
				continue;
			}
			seenAssertions.add(draft.id);
			assertions.push(
				Object.freeze({
					id: draft.id,
					recordId: draft.recordId,
					fragmentId: draft.fragmentId,
					subject: draft.subject,
					predicate: draft.predicate,
					object: draft.object,
					...(draft.confidence === undefined ? {} : { confidence: draft.confidence }),
					sources: Object.freeze(draft.sources ?? [draft.fragmentId]),
					...(draft.provenance === undefined ? {} : { provenance: draft.provenance }),
				}),
			);
		} catch (error) {
			invalidDrafts += 1;
			errors.push({
				code: "invalid-draft",
				message: `agenticMemoryKgProjectionBundle: draft access failed: ${errorMessage(error)}`,
				index: i,
				draft: raw,
				validationErrors: ["draft access failed"],
			});
		}
	}
	return { assertions, errors, invalidDrafts };
}

function validateKgDraft(
	value: unknown,
	index: number,
): {
	readonly draft?: AgenticMemoryKgAssertionDraft;
	readonly errors: Omit<AgenticMemoryKgProjectionError, "cursor">[];
} {
	const errors: Omit<AgenticMemoryKgProjectionError, "cursor">[] = [];
	if (!isPlainRecord(value)) {
		return {
			errors: [
				{
					code: "invalid-draft",
					message: "agenticMemoryKgProjectionBundle: draft must be an object",
					index,
					draft: value,
				},
			],
		};
	}
	const raw = value as Partial<AgenticMemoryKgAssertionDraft>;
	const id = typeof raw.id === "string" && raw.id.length > 0 ? raw.id : undefined;
	const recordId =
		typeof raw.recordId === "string" && raw.recordId.length > 0 ? raw.recordId : undefined;
	const fragmentId =
		typeof raw.fragmentId === "string" && raw.fragmentId.length > 0 ? raw.fragmentId : undefined;
	const subject = validateAssertionSubject(raw.subject);
	const object = validateAssertionObject(raw.object);
	const shapeErrors: string[] = [];
	if (id === undefined) shapeErrors.push("draft.id must be a non-empty string");
	if (recordId === undefined) {
		shapeErrors.push("draft.recordId must be a non-empty string");
	}
	if (fragmentId === undefined) {
		shapeErrors.push("draft.fragmentId must be a non-empty string");
	}
	shapeErrors.push(...subject.errors);
	if (typeof raw.predicate !== "string" || raw.predicate.length === 0) {
		shapeErrors.push("draft.predicate must be a non-empty string");
	}
	shapeErrors.push(...object.errors);
	if (
		raw.confidence !== undefined &&
		(!Number.isFinite(raw.confidence) || raw.confidence < 0 || raw.confidence > 1)
	) {
		shapeErrors.push("draft.confidence must be a finite number in [0, 1]");
	}
	if (raw.sources !== undefined && !isDenseArrayOf(raw.sources, isNonEmptyString)) {
		shapeErrors.push("draft.sources must be a readonly string array");
	}
	if (raw.provenance !== undefined && typeof raw.provenance !== "string") {
		shapeErrors.push("draft.provenance must be a string when present");
	}
	if (shapeErrors.length > 0) errors.push(kgShapeError(index, value, ...shapeErrors));
	if (errors.length > 0 || id === undefined || recordId === undefined || fragmentId === undefined) {
		return { errors };
	}
	return {
		draft: Object.freeze({
			id,
			recordId,
			fragmentId,
			subject: subject.subject as KnowledgeAssertionSubject,
			predicate: raw.predicate as string,
			object: object.object as KnowledgeAssertionObject,
			...(raw.confidence === undefined ? {} : { confidence: raw.confidence }),
			...(raw.sources === undefined ? {} : { sources: Object.freeze([...raw.sources]) }),
			...(raw.provenance === undefined ? {} : { provenance: raw.provenance }),
		}),
		errors,
	};
}

function validateAssertionSubject(value: unknown): {
	readonly subject?: KnowledgeAssertionSubject;
	readonly errors: readonly string[];
} {
	if (!isPlainRecord(value)) return { errors: ["subject must be an object"] };
	const id = value.id;
	const type = value.type;
	const errors: string[] = [];
	if (typeof id !== "string" || id.length === 0) errors.push("subject.id must be non-empty");
	if (type !== undefined && (typeof type !== "string" || type.length === 0)) {
		errors.push("subject.type must be a non-empty string when present");
	}
	if (errors.length > 0) return { errors };
	return {
		subject: Object.freeze({
			id: id as string,
			...(type === undefined ? {} : { type: type as string }),
		}),
		errors,
	};
}

function validateAssertionObject(value: unknown): {
	readonly object?: KnowledgeAssertionObject;
	readonly errors: readonly string[];
} {
	if (!isPlainRecord(value)) return { errors: ["object must be an object"] };
	const kind = value.kind;
	const errors: string[] = [];
	if (kind === "entity") {
		if (typeof value.id !== "string" || value.id.length === 0) {
			errors.push("object.id must be non-empty for entity objects");
		}
		if (value.type !== undefined && (typeof value.type !== "string" || value.type.length === 0)) {
			errors.push("object.type must be a non-empty string when present");
		}
		if (Object.hasOwn(value, "value")) errors.push("entity object must not include value");
		if (errors.length > 0) return { errors };
		return {
			object: Object.freeze({
				kind: "entity",
				id: value.id as string,
				...(value.type === undefined ? {} : { type: value.type as string }),
			}),
			errors,
		};
	}
	if (kind === "value") {
		if (!Object.hasOwn(value, "value")) errors.push("value object must include value");
		else {
			try {
				assertStrictJsonValue(value.value, "object.value");
			} catch (error) {
				errors.push(errorMessage(error));
			}
		}
		if (
			value.valueType !== undefined &&
			(typeof value.valueType !== "string" || value.valueType.length === 0)
		) {
			errors.push("object.valueType must be a non-empty string when present");
		}
		if (Object.hasOwn(value, "id")) errors.push("value object must not include id");
		if (errors.length > 0) return { errors };
		return {
			object: Object.freeze({
				kind: "value",
				value: value.value as StrictJsonValue,
				...(value.valueType === undefined ? {} : { valueType: value.valueType as string }),
			}),
			errors,
		};
	}
	return { errors: ["object.kind must be entity or value"] };
}

function kgShapeError(
	index: number,
	draft: unknown,
	...validationErrors: readonly string[]
): Omit<AgenticMemoryKgProjectionError, "cursor"> {
	return {
		code: "invalid-assertion-shape",
		message: "agenticMemoryKgProjectionBundle: draft assertion shape is invalid",
		index,
		draft,
		validationErrors: Object.freeze([...validationErrors]),
	};
}

function kgErrorFromRecordError(
	error: Omit<AgenticMemoryError, "cursor">,
): Omit<AgenticMemoryKgProjectionError, "cursor"> {
	return {
		...error,
		code: error.code,
	};
}

import { depLatest } from "../../ctx/types.js";
import type { DataIssue } from "../../data/index.js";
import type { Graph } from "../../graph/graph.js";
import { canonicalTupleKey, compoundTupleKey } from "../../identity.js";
import type { FactId } from "../../patterns/semantic-memory.js";
import { solutionProjection } from "./projection.js";
import {
	cloneStrictJsonObject,
	dataRecordContainerErrors,
	errorMessage,
	forbiddenAgenticMemoryDataFields,
	isNonEmptyString,
	isPlainRecord,
	isStrictJsonObject,
	safeArrayLength,
	snapshotAgenticMemoryFactRefs,
	validateAgenticMemoryFactRefs,
	validateAndProjectRecords,
	validateAndSnapshotRecord,
} from "./shared.js";
import type {
	AgenticMemoryFactRef,
	AgenticMemoryRecord,
	AgenticMemoryRecordApplicationOperation,
	AgenticMemoryRecordCandidateMaterial,
	AgenticMemoryRecordMaterializationAuditEntry,
	AgenticMemoryRecordMaterializationCursor,
	AgenticMemoryRecordMaterializationIntent,
	AgenticMemoryRecordMaterializationProjection,
	AgenticMemoryRecordMaterializationStatusState,
	AgenticMemoryRecordMaterializerBundle,
	AgenticMemoryRecordMaterializerBundleOptions,
	AgenticMemoryRecordProposal,
	StrictJsonValue,
} from "./types.js";

const AGENTIC_MEMORY_RECORD_MATERIALIZER_ID =
	"agentic-memory-record-complete-next-record-materializer";
const AGENTIC_MEMORY_RECORD_MATERIALIZATION_OPERATION_VERSION = 1 as const;
const AGENTIC_MEMORY_RECORD_MATERIALIZATION_OPERATIONS = ["create", "replace", "update"] as const;

interface MaterializerOptions<T> {
	readonly records?: readonly AgenticMemoryRecord<T>[];
	readonly materializerId?: FactId;
	readonly evaluation?: number;
	readonly sourceRefs?: readonly AgenticMemoryFactRef[];
	readonly policyRefs?: readonly AgenticMemoryFactRef[];
}

interface ValidatedIntent<T> {
	readonly intent: AgenticMemoryRecordMaterializationIntent<T>;
	readonly candidateMaterial: AgenticMemoryRecordCandidateMaterial<T>;
	readonly proposal: AgenticMemoryRecordProposal<T>;
	readonly material: MaterialComparable<T>;
	readonly applicationMaterial: ApplicationMaterialComparable<T>;
	readonly coordinateKey: string;
	readonly effectiveTargetRecordId: FactId;
}

interface MaterialComparable<T> {
	readonly operation: AgenticMemoryRecordApplicationOperation;
	readonly operationVersion: 1;
	readonly targetRecordId?: FactId;
	readonly record: AgenticMemoryRecord<T>;
	readonly reason?: string;
	readonly idempotencyKey?: string;
	readonly correlationId?: string;
	readonly causationId?: string;
	readonly sourceRefs?: readonly AgenticMemoryFactRef[];
	readonly policyRefs?: readonly AgenticMemoryFactRef[];
	readonly evidenceRefs?: readonly AgenticMemoryFactRef[];
	readonly metadata?: Readonly<Record<string, StrictJsonValue>>;
}

interface ApplicationMaterialComparable<T> {
	readonly operation: AgenticMemoryRecordApplicationOperation;
	readonly operationVersion: 1;
	readonly targetRecordId: FactId;
	readonly record: AgenticMemoryRecord<T>;
}

/**
 * Materializes D586 complete-next-record change intents into proposal-compatible DATA.
 *
 * The helper validates domain-specific intent facts against current records and
 * emits full `AgenticMemoryRecordProposal` material only. It does not admit,
 * apply, persist, hydrate, commit, mutate live records, or interpret patch/merge
 * semantics.
 *
 * @param intents - Complete-next-record materialization intent DATA.
 * @param opts - Current records, optional evaluation, materializer id, and refs.
 * @returns Candidate material/proposals plus materializer-local status, issues, audit, and cursor.
 * @category solutions
 * @example
 * ```ts
 * import { materializeAgenticMemoryRecordChanges } from "@graphrefly/ts/solutions/agentic-memory";
 * ```
 */
export function materializeAgenticMemoryRecordChanges<T = unknown>(
	intents: unknown,
	opts: MaterializerOptions<T> = {},
): AgenticMemoryRecordMaterializationProjection<T> {
	const validatedOptions = validateMaterializerOptions(opts);
	const materializerId = validatedOptions.materializerId;
	const materializerOpts: MaterializerOptions<T> = {
		...opts,
		materializerId,
		sourceRefs: validatedOptions.sourceRefs,
		policyRefs: validatedOptions.policyRefs,
	};
	const recordProjection = validateAndProjectRecords<T>(opts.records ?? []);
	const recordsById = new Map(recordProjection.records.map((record) => [record.id, record]));
	const issues: DataIssue[] = [
		...recordProjection.errors.map(recordProjectionIssue),
		...validatedOptions.issues,
	];
	const audit: AgenticMemoryRecordMaterializationAuditEntry[] = [];
	let intentsCount = 0;
	let invalidIntents = 0;
	let duplicateIntents = 0;
	let divergentIntents = 0;
	let coordinateConflicts = 0;
	const validated: ValidatedIntent<T>[] = [];

	if (!Array.isArray(intents)) {
		invalidIntents += 1;
		issues.push(
			dataIssue(
				"agentic-memory.materializer.invalid-input",
				"materialization intents input must be an array",
				{ severity: "error" },
			),
		);
	} else {
		const length = safeArrayLength(intents);
		if (length === undefined) {
			invalidIntents += 1;
			issues.push(
				dataIssue(
					"agentic-memory.materializer.invalid-input",
					"materialization intents input length could not be read",
					{ severity: "error" },
				),
			);
		} else {
			intentsCount = length;
			for (let index = 0; index < length; index += 1) {
				try {
					if (!Object.hasOwn(intents, index)) {
						throw new TypeError("materialization intents must be dense");
					}
					const result = validateMaterializationIntent<T>(
						intents[index],
						index,
						recordsById,
						materializerId,
						materializerOpts,
					);
					if (result.intent === undefined) {
						invalidIntents += 1;
						issues.push(...result.issues);
						continue;
					}
					validated.push(result.intent);
				} catch (error) {
					invalidIntents += 1;
					issues.push(
						dataIssue(
							"agentic-memory.materializer.invalid-intent",
							`materialization intent access failed: ${errorMessage(error)}`,
							{ severity: "error", path: [index] },
						),
					);
				}
			}
		}
	}

	const groups = new Map<FactId, ValidatedIntent<T>[]>();
	for (const item of validated) {
		const group = groups.get(item.intent.intentId);
		if (group === undefined) groups.set(item.intent.intentId, [item]);
		else group.push(item);
	}

	const representatives: ValidatedIntent<T>[] = [];
	for (const [intentId, group] of groups) {
		const first = group[0];
		if (first === undefined) continue;
		const divergent = group.some((item) => !deepEqualValue(item.material, first.material));
		if (divergent) {
			divergentIntents += 1;
			issues.push(
				dataIssue(
					"agentic-memory.materializer.duplicate-intent-divergent",
					"duplicate materialization intent id produced divergent material",
					{
						severity: "error",
						subjectId: intentId,
						refs: group.map((item) => item.proposal.proposalId),
					},
				),
			);
			audit.push(
				materializationAudit("divergent-intent", {
					intentId,
					reason: "duplicate intentId with divergent material",
				}),
			);
			continue;
		}
		if (group.length > 1) {
			duplicateIntents += group.length - 1;
			audit.push(
				materializationAudit("duplicate-suppressed", {
					intentId,
					proposalId: first.proposal.proposalId,
					operation: first.intent.operation,
					operationVersion: first.intent.operationVersion,
					targetRecordId: first.intent.targetRecordId ?? first.intent.record.id,
					recordId: first.intent.record.id,
					reason: "duplicate intentId with identical material",
				}),
			);
		}
		representatives.push(first);
	}

	const candidateMaterials: AgenticMemoryRecordCandidateMaterial<T>[] = [];
	const proposals: AgenticMemoryRecordProposal<T>[] = [];
	const coordinateGroups = new Map<string, ValidatedIntent<T>[]>();
	for (const item of representatives) {
		const group = coordinateGroups.get(item.coordinateKey);
		if (group === undefined) coordinateGroups.set(item.coordinateKey, [item]);
		else group.push(item);
	}
	for (const [coordinateKey, group] of coordinateGroups) {
		const first = group[0];
		if (first === undefined) continue;
		const coordinateDivergent = group.some(
			(item) => !deepEqualValue(item.applicationMaterial, first.applicationMaterial),
		);
		if (coordinateDivergent) {
			coordinateConflicts += 1;
			issues.push(
				dataIssue(
					"agentic-memory.materializer.coordinate-conflict",
					"materialization intents produced divergent material for the same application coordinate",
					{
						severity: "error",
						subjectId: first.effectiveTargetRecordId,
						refs: group.map((item) => item.proposal.proposalId),
					},
				),
			);
			audit.push(
				materializationAudit("coordinate-conflict", {
					intentId: first.intent.intentId,
					operation: first.intent.operation,
					operationVersion: first.intent.operationVersion,
					targetRecordId: first.effectiveTargetRecordId,
					recordId: first.intent.record.id,
					reason: `same application coordinate with divergent material: ${coordinateKey}`,
				}),
			);
			continue;
		}
		for (const item of group) {
			candidateMaterials.push(item.candidateMaterial);
			proposals.push(item.proposal);
			audit.push(
				materializationAudit("proposal-materialized", {
					intentId: item.intent.intentId,
					proposalId: item.proposal.proposalId,
					operation: item.intent.operation,
					operationVersion: item.intent.operationVersion,
					targetRecordId: item.effectiveTargetRecordId,
					recordId: item.intent.record.id,
					sourceRefs: item.proposal.sourceRefs,
					policyRefs: item.proposal.policyRefs,
					evidenceRefs: item.proposal.evidenceRefs,
				}),
			);
		}
	}
	for (const issue of issues) {
		audit.push(materializationAudit("issue-recorded", { reason: issue.code }));
	}

	const cursor: AgenticMemoryRecordMaterializationCursor = Object.freeze({
		evaluation: opts.evaluation ?? 0,
		records: safeInputLength(opts.records),
		validRecords: recordProjection.records.length,
		invalidRecords: recordProjection.invalidRecordIndexes.size,
		intents: intentsCount,
		validIntents: validated.length,
		invalidIntents,
		duplicateIntents,
		divergentIntents,
		coordinateConflicts,
		candidateMaterials: candidateMaterials.length,
		proposals: proposals.length,
		issues: issues.length,
	});
	return Object.freeze({
		kind: "agentic-memory-record-materialization-projection",
		candidateMaterials: Object.freeze(candidateMaterials),
		proposals: Object.freeze(proposals),
		status: Object.freeze({ state: materializationStatus(cursor), cursor }),
		issues: Object.freeze(issues),
		audit: Object.freeze(audit),
		cursor,
	});
}

/**
 * Creates a graph-visible D586 complete-next-record materializer bundle.
 *
 * The bundle turns current records plus materialization intents into ordinary
 * proposal DATA. It does not wire those proposals into admission/application,
 * storage, hydration, durable commit, or same-evaluation evidence feedback.
 *
 * @param graph - Graph that owns the created nodes.
 * @param opts - Records and intents input nodes plus optional materializer id/name.
 * @returns Projection node plus proposal/candidate/status/issues/audit/cursor nodes.
 * @category solutions
 */
export function agenticMemoryRecordMaterializerBundle<T = unknown>(
	graph: Graph,
	opts: AgenticMemoryRecordMaterializerBundleOptions<T>,
): AgenticMemoryRecordMaterializerBundle<T> {
	const name = opts.name ?? "agenticMemoryRecordMaterializer";
	const projection = graph.node<AgenticMemoryRecordMaterializationProjection<T>>(
		[opts.records, opts.intents],
		(ctx) => {
			const state =
				ctx.state.get<{ evaluation: number }>() ??
				({ evaluation: 0 } satisfies { evaluation: number });
			state.evaluation += 1;
			ctx.state.set(state);
			ctx.down([
				[
					"DATA",
					materializeAgenticMemoryRecordChanges<T>(depLatest(ctx, 1), {
						records: depLatest(ctx, 0) as readonly AgenticMemoryRecord<T>[] | undefined,
						materializerId: opts.materializerId,
						evaluation: state.evaluation,
					}),
				],
			]);
		},
		{
			name: `${name}/projection`,
			factory: "agenticMemoryRecordMaterializer",
			completeWhenDepsComplete: false,
			errorWhenDepsError: false,
		},
	);
	return {
		input: { records: opts.records, intents: opts.intents },
		projection,
		proposals: solutionProjection(
			graph,
			projection,
			`${name}/proposals`,
			"agenticMemoryRecordMaterializerProposals",
			(fact) => fact.proposals,
		),
		candidateMaterials: solutionProjection(
			graph,
			projection,
			`${name}/candidateMaterials`,
			"agenticMemoryRecordMaterializerCandidateMaterials",
			(fact) => fact.candidateMaterials,
		),
		status: solutionProjection(
			graph,
			projection,
			`${name}/status`,
			"agenticMemoryRecordMaterializerStatus",
			(fact) => fact.status,
		),
		issues: solutionProjection(
			graph,
			projection,
			`${name}/issues`,
			"agenticMemoryRecordMaterializerIssues",
			(fact) => fact.issues,
		),
		audit: solutionProjection(
			graph,
			projection,
			`${name}/audit`,
			"agenticMemoryRecordMaterializerAudit",
			(fact) => fact.audit,
		),
		cursor: solutionProjection(
			graph,
			projection,
			`${name}/cursor`,
			"agenticMemoryRecordMaterializerCursor",
			(fact) => fact.cursor,
		),
	};
}

function validateMaterializationIntent<T>(
	value: unknown,
	index: number,
	recordsById: ReadonlyMap<FactId, AgenticMemoryRecord<T>>,
	materializerId: FactId,
	opts: MaterializerOptions<T>,
): {
	readonly intent?: ValidatedIntent<T>;
	readonly issues: readonly DataIssue[];
} {
	if (!isPlainRecord(value)) {
		return {
			issues: [
				dataIssue(
					"agentic-memory.materializer.invalid-intent",
					"materialization intent must be an object",
					{ severity: "error", path: [index] },
				),
			],
		};
	}
	const validationErrors = [
		...dataRecordContainerErrors(value, "intent"),
		...forbiddenAgenticMemoryDataFields(value, "intent"),
		...unexpectedFields(value, [
			"kind",
			"intentId",
			"operation",
			"operationVersion",
			"record",
			"targetRecordId",
			"reason",
			"idempotencyKey",
			"correlationId",
			"causationId",
			"sourceRefs",
			"policyRefs",
			"evidenceRefs",
			"metadata",
		]).map((field) => `intent.${field} is not part of materialization intent`),
	];
	if (value.kind !== "agentic-memory-record-materialization-intent") {
		validationErrors.push("intent.kind must be agentic-memory-record-materialization-intent");
	}
	const intentId = isNonEmptyString(value.intentId) ? value.intentId : undefined;
	if (intentId === undefined) validationErrors.push("intent.intentId must be non-empty");
	const operation = isMaterializationOperation(value.operation) ? value.operation : undefined;
	if (operation === undefined) {
		validationErrors.push("intent.operation must be create, replace, or update");
	}
	if (value.operationVersion !== AGENTIC_MEMORY_RECORD_MATERIALIZATION_OPERATION_VERSION) {
		validationErrors.push("intent.operationVersion must be 1");
	}
	if (value.targetRecordId !== undefined && !isNonEmptyString(value.targetRecordId)) {
		validationErrors.push("intent.targetRecordId must be non-empty when present");
	}
	for (const field of ["reason", "idempotencyKey", "correlationId", "causationId"] as const) {
		if (value[field] !== undefined && typeof value[field] !== "string") {
			validationErrors.push(`intent.${field} must be a string when present`);
		}
	}
	const sourceRefs = snapshotRefs(value.sourceRefs, "intent.sourceRefs", validationErrors);
	const policyRefs = snapshotRefs(value.policyRefs, "intent.policyRefs", validationErrors);
	const evidenceRefs = snapshotRefs(value.evidenceRefs, "intent.evidenceRefs", validationErrors);
	const metadata = snapshotMetadata(value.metadata, "intent.metadata", validationErrors);
	const materialSourceRefs = mergeRefs([...(opts.sourceRefs ?? []), ...sourceRefs]);
	const materialPolicyRefs = mergeRefs([...(opts.policyRefs ?? []), ...policyRefs]);
	const recordResult = validateAndSnapshotRecord<T>(value.record, index);
	if (recordResult.record === undefined || recordResult.errors.length > 0) {
		validationErrors.push(
			...recordResult.errors.flatMap((error) =>
				(error.validationErrors ?? [error.message]).map((message) => `intent.record: ${message}`),
			),
		);
	}
	const record = recordResult.record;
	const targetRecordId = isNonEmptyString(value.targetRecordId) ? value.targetRecordId : undefined;
	const currentRecord = targetRecordId === undefined ? undefined : recordsById.get(targetRecordId);
	if (operation === "create" && targetRecordId !== undefined && record?.id !== targetRecordId) {
		validationErrors.push("create targetRecordId must be absent or equal to record.id");
	}
	if ((operation === "replace" || operation === "update") && targetRecordId === undefined) {
		validationErrors.push(`${operation} targetRecordId is required`);
	}
	if ((operation === "replace" || operation === "update") && targetRecordId !== undefined) {
		if (currentRecord === undefined) {
			validationErrors.push(`${operation} targetRecordId must reference a current record`);
		}
		if (record !== undefined && record.id !== targetRecordId) {
			validationErrors.push(`${operation} record.id must equal targetRecordId`);
		}
		if (
			currentRecord !== undefined &&
			record !== undefined &&
			!hasExistingTargetLineage(record, currentRecord, [
				...(materialSourceRefs ?? []),
				...evidenceRefs,
			])
		) {
			validationErrors.push(
				`${operation} requires explicit lineage to the prior record or fragment`,
			);
		}
	}
	if (
		validationErrors.length > 0 ||
		intentId === undefined ||
		operation === undefined ||
		record === undefined
	) {
		return {
			issues: [
				dataIssue(
					"agentic-memory.materializer.invalid-intent",
					"materialization intent is invalid",
					{
						severity: "error",
						subjectId: intentId,
						path: [index],
						refs: validationErrors,
					},
				),
			],
		};
	}
	const effectiveTargetRecordId = targetRecordId ?? record.id;
	const coordinateKey = materializationCoordinateKey(
		operation,
		AGENTIC_MEMORY_RECORD_MATERIALIZATION_OPERATION_VERSION,
		effectiveTargetRecordId,
	);
	const candidateMaterial: AgenticMemoryRecordCandidateMaterial<T> = Object.freeze({
		kind: "agentic-memory-record-candidate-material",
		operation,
		operationVersion: AGENTIC_MEMORY_RECORD_MATERIALIZATION_OPERATION_VERSION,
		record,
		...(targetRecordId === undefined ? {} : { targetRecordId }),
		...(materialSourceRefs === undefined ? {} : { sourceRefs: materialSourceRefs }),
		...(materialPolicyRefs === undefined ? {} : { policyRefs: materialPolicyRefs }),
		...(evidenceRefs.length === 0 ? {} : { evidenceRefs }),
		...(metadata === undefined ? {} : { metadata }),
	});
	const proposalId = compoundTupleKey("agentic-memory-record-proposal", [
		materializerId,
		intentId,
		operation,
		effectiveTargetRecordId,
		record.id,
	]);
	const proposal: AgenticMemoryRecordProposal<T> = Object.freeze({
		kind: "agentic-memory-record-proposal",
		proposalId,
		operation,
		operationVersion: AGENTIC_MEMORY_RECORD_MATERIALIZATION_OPERATION_VERSION,
		candidateMaterial,
		...(targetRecordId === undefined ? {} : { targetRecordId }),
		...(value.reason === undefined ? {} : { reason: value.reason as string }),
		proposalStatus: "materialized",
		...(materialSourceRefs === undefined ? {} : { sourceRefs: materialSourceRefs }),
		...(materialPolicyRefs === undefined ? {} : { policyRefs: materialPolicyRefs }),
		...(evidenceRefs.length === 0 ? {} : { evidenceRefs }),
		...(value.idempotencyKey === undefined
			? {}
			: { idempotencyKey: value.idempotencyKey as string }),
		...(value.correlationId === undefined ? {} : { correlationId: value.correlationId as string }),
		causationId: value.causationId === undefined ? intentId : (value.causationId as string),
		...(metadata === undefined ? {} : { metadata }),
	});
	const intent: AgenticMemoryRecordMaterializationIntent<T> = Object.freeze({
		kind: "agentic-memory-record-materialization-intent",
		intentId,
		operation,
		operationVersion: AGENTIC_MEMORY_RECORD_MATERIALIZATION_OPERATION_VERSION,
		record,
		...(targetRecordId === undefined ? {} : { targetRecordId }),
		...(value.reason === undefined ? {} : { reason: value.reason as string }),
		...(value.idempotencyKey === undefined
			? {}
			: { idempotencyKey: value.idempotencyKey as string }),
		...(value.correlationId === undefined ? {} : { correlationId: value.correlationId as string }),
		...(value.causationId === undefined ? {} : { causationId: value.causationId as string }),
		...(sourceRefs.length === 0 ? {} : { sourceRefs }),
		...(policyRefs.length === 0 ? {} : { policyRefs }),
		...(evidenceRefs.length === 0 ? {} : { evidenceRefs }),
		...(metadata === undefined ? {} : { metadata }),
	});
	return {
		intent: {
			intent,
			candidateMaterial,
			proposal,
			applicationMaterial: Object.freeze({
				operation,
				operationVersion: AGENTIC_MEMORY_RECORD_MATERIALIZATION_OPERATION_VERSION,
				targetRecordId: effectiveTargetRecordId,
				record,
			}),
			coordinateKey,
			effectiveTargetRecordId,
			material: Object.freeze({
				operation,
				operationVersion: AGENTIC_MEMORY_RECORD_MATERIALIZATION_OPERATION_VERSION,
				...(targetRecordId === undefined ? {} : { targetRecordId }),
				record,
				...(value.reason === undefined ? {} : { reason: value.reason as string }),
				...(value.idempotencyKey === undefined
					? {}
					: { idempotencyKey: value.idempotencyKey as string }),
				...(value.correlationId === undefined
					? {}
					: { correlationId: value.correlationId as string }),
				causationId: value.causationId === undefined ? intentId : (value.causationId as string),
				...(materialSourceRefs === undefined ? {} : { sourceRefs: materialSourceRefs }),
				...(materialPolicyRefs === undefined ? {} : { policyRefs: materialPolicyRefs }),
				...(evidenceRefs.length === 0 ? {} : { evidenceRefs }),
				...(metadata === undefined ? {} : { metadata }),
			}),
		},
		issues: [],
	};
}

function validateMaterializerOptions<T>(opts: MaterializerOptions<T>): {
	readonly materializerId: FactId;
	readonly sourceRefs?: readonly AgenticMemoryFactRef[];
	readonly policyRefs?: readonly AgenticMemoryFactRef[];
	readonly issues: readonly DataIssue[];
} {
	const refs: string[] = [];
	const sourceRefs = snapshotRefs(opts.sourceRefs, "options.sourceRefs", refs);
	const policyRefs = snapshotRefs(opts.policyRefs, "options.policyRefs", refs);
	if (opts.materializerId !== undefined && !isNonEmptyString(opts.materializerId)) {
		refs.push("options.materializerId must be non-empty when present");
	}
	const materializerId = isNonEmptyString(opts.materializerId)
		? opts.materializerId
		: AGENTIC_MEMORY_RECORD_MATERIALIZER_ID;
	return {
		materializerId,
		...(sourceRefs.length === 0 ? {} : { sourceRefs }),
		...(policyRefs.length === 0 ? {} : { policyRefs }),
		issues:
			refs.length === 0
				? Object.freeze([])
				: Object.freeze([
						dataIssue(
							"agentic-memory.materializer.invalid-options",
							"materializer options are invalid",
							{ severity: "error", refs },
						),
					]),
	};
}

function recordProjectionIssue(
	error: ReturnType<typeof validateAndProjectRecords>["errors"][number],
): DataIssue {
	return dataIssue("agentic-memory.materializer.invalid-record", error.message, {
		severity: "error",
		subjectId: error.recordId,
		refs: error.validationErrors,
	});
}

function snapshotRefs(
	value: unknown,
	label: string,
	errors: string[],
): readonly AgenticMemoryFactRef[] {
	if (value === undefined) return Object.freeze([]);
	const refErrors = validateAgenticMemoryFactRefs(value);
	if (refErrors.length > 0) {
		errors.push(...refErrors.map((error) => `${label}: ${error}`));
		return Object.freeze([]);
	}
	return snapshotAgenticMemoryFactRefs(value);
}

function snapshotMetadata(
	value: unknown,
	label: string,
	errors: string[],
): Readonly<Record<string, StrictJsonValue>> | undefined {
	if (value === undefined) return undefined;
	if (!isPlainRecord(value) || !isStrictJsonObject(value)) {
		errors.push(`${label} must be a strict JSON object`);
		return undefined;
	}
	for (const forbidden of forbiddenAgenticMemoryDataFields(value, label)) {
		errors.push(forbidden);
	}
	return cloneStrictJsonObject(value);
}

function unexpectedFields(
	value: Record<string, unknown>,
	expected: readonly string[],
): readonly string[] {
	const allowed = new Set(expected);
	return Object.keys(value)
		.filter((key) => !allowed.has(key))
		.sort();
}

function isMaterializationOperation(
	value: unknown,
): value is AgenticMemoryRecordApplicationOperation {
	return AGENTIC_MEMORY_RECORD_MATERIALIZATION_OPERATIONS.some((operation) => operation === value);
}

function hasExistingTargetLineage<T>(
	record: AgenticMemoryRecord<T>,
	prior: AgenticMemoryRecord<T>,
	refs: readonly AgenticMemoryFactRef[],
): boolean {
	if (record.fragment.parentFragmentId === prior.fragment.id) return true;
	if (
		record.fragment.sources.some((source) => source === prior.id || source === prior.fragment.id)
	) {
		return true;
	}
	return refs.some((ref) => {
		const kind = ref.kind.toLowerCase();
		return (
			(ref.id === prior.id && kind.includes("record")) ||
			(ref.id === prior.fragment.id && kind.includes("fragment"))
		);
	});
}

function mergeRefs(
	refs: readonly AgenticMemoryFactRef[],
): readonly AgenticMemoryFactRef[] | undefined {
	if (refs.length === 0) return undefined;
	const seen = new Set<string>();
	const out: AgenticMemoryFactRef[] = [];
	for (const ref of refs) {
		const key = canonicalTupleKey([ref.kind, ref.id]);
		if (seen.has(key)) continue;
		seen.add(key);
		out.push(ref);
	}
	return Object.freeze(out);
}

function materializationCoordinateKey(
	operation: AgenticMemoryRecordApplicationOperation,
	operationVersion: 1,
	targetRecordId: FactId,
): string {
	return canonicalTupleKey([
		"agentic-memory-record-materialization-coordinate",
		operation,
		String(operationVersion),
		targetRecordId,
	]);
}

function materializationAudit(
	action: AgenticMemoryRecordMaterializationAuditEntry["action"],
	patch: Omit<AgenticMemoryRecordMaterializationAuditEntry, "kind" | "action"> = {},
): AgenticMemoryRecordMaterializationAuditEntry {
	return Object.freeze({
		kind: "agentic-memory-record-materialization-audit",
		action,
		...patch,
	});
}

function materializationStatus(
	cursor: AgenticMemoryRecordMaterializationCursor,
): AgenticMemoryRecordMaterializationStatusState {
	if (cursor.issues > 0 && cursor.proposals === 0) return "error";
	if (cursor.issues > 0) return "partial";
	if (cursor.proposals > 0) return "ready";
	return cursor.intents > 0 ? "blocked" : "empty";
}

function safeInputLength(value: unknown): number {
	if (!Array.isArray(value)) return 0;
	return safeArrayLength(value) ?? 0;
}

function deepEqualValue(a: unknown, b: unknown): boolean {
	return deepEqualValueInner(a, b, new WeakMap<object, WeakSet<object>>());
}

function deepEqualValueInner(
	a: unknown,
	b: unknown,
	seen: WeakMap<object, WeakSet<object>>,
): boolean {
	if (Object.is(a, b)) return true;
	if (typeof a !== "object" || a === null || typeof b !== "object" || b === null) {
		return false;
	}
	let seenForA = seen.get(a);
	if (seenForA?.has(b)) return true;
	if (seenForA === undefined) {
		seenForA = new WeakSet<object>();
		seen.set(a, seenForA);
	}
	seenForA.add(b);
	if (Array.isArray(a) || Array.isArray(b)) {
		if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
		for (let index = 0; index < a.length; index += 1) {
			if (!deepEqualValueInner(a[index], b[index], seen)) return false;
		}
		return true;
	}
	const aRecord = a as Record<string, unknown>;
	const bRecord = b as Record<string, unknown>;
	const aKeys = Object.keys(aRecord).sort();
	const bKeys = Object.keys(bRecord).sort();
	if (aKeys.length !== bKeys.length) return false;
	for (let index = 0; index < aKeys.length; index += 1) {
		const key = aKeys[index] as string;
		if (key !== bKeys[index]) return false;
		if (!deepEqualValueInner(aRecord[key], bRecord[key], seen)) return false;
	}
	return true;
}

function dataIssue(
	code: string,
	message: string,
	opts: {
		readonly severity?: DataIssue["severity"];
		readonly subjectId?: string;
		readonly path?: readonly (string | number)[];
		readonly refs?: readonly string[];
	} = {},
): DataIssue {
	return Object.freeze({
		kind: "issue",
		code,
		message,
		source: "agentic-memory",
		...opts,
	});
}

/**
 * Node-only AgenticMemory committed fact-log reference backends (D594).
 *
 * Import from `@graphrefly/ts/solutions/agentic-memory/node`; the universal
 * AgenticMemory barrels stay browser-safe.
 */

import {
	assertCommittedFactStreamIntegrity,
	committedFactBatchDisposition,
	committedFactReadWindow,
} from "../../committed-facts/internal.js";
import type { DataIssue } from "../../data/index.js";
import { type FileAppendLogOptions, fileAppendLog } from "../../storage/node.js";
import {
	AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND,
	type AgenticMemoryCommittedFact,
	type AgenticMemoryCommittedFactBatch,
	type AgenticMemoryCommittedFactCursor,
	type AgenticMemoryFactLogAuditEntry,
	agenticMemoryCommittedFactBatchCodec,
	assertAgenticMemoryCommittedFactBatch,
} from "./committed-fact-log.js";
import {
	type AgenticMemoryCommittedFactLogBackend,
	type AgenticMemoryCommittedFactLogBackendAppendResult,
	type AgenticMemoryCommittedFactLogBackendReadResult,
	agenticMemoryCommittedFactLogBackendCursor,
	agenticMemoryCommittedFactLogBackendStatus,
} from "./committed-fact-log-backend.js";
import type { StrictJsonValue } from "./types.js";

const DEFAULT_PREFIX = "agentic-memory-committed-fact-log";
const BACKEND_ID = "node-file-agentic-memory-committed-fact-log";

export interface NodeFileAgenticMemoryCommittedFactLogBackendOptions<
	TJson extends StrictJsonValue = StrictJsonValue,
> extends Omit<FileAppendLogOptions<AgenticMemoryCommittedFactBatch<TJson>>, "codec"> {
	/** Diagnostic backend name. It is DATA/audit only, never a fact-stream cursor. */
	readonly backendName?: string;
}

/** Create a Node file-backed D594 single-writer committed fact-log backend.
 *
 * The backend implements the D592 adapter contract directly. It appends each
 * canonical D589 committed fact batch as one strict JSON append-log entry so a
 * readable committed stream never exposes a partial batch. Physical file paths,
 * append-log sequence keys, writer mode, and durability limits are reported only
 * through backend diagnostic DATA; fact-log cursors are computed from committed
 * fact-stream positions and never from file names, storage keys, or row ids.
 * Write completion means the storage promise settled; this backend does not
 * claim host fsync or permanent durability guarantees.
 *
 * This helper does not materialize records, replay facts into application state,
 * hydrate/restore graphs, refresh subscribers, acknowledge applications, mutate
 * live graph truth, or create a graph commit barrier.
 *
 * @param dir - Directory owned by the host for the file-backed append log.
 * @param opts - Optional namespace/prefix/extension and diagnostic backend name.
 * @returns A D592 committed fact-log backend.
 * @category solutions
 */
export function nodeFileAgenticMemoryCommittedFactLogBackend<
	TJson extends StrictJsonValue = StrictJsonValue,
>(
	dir: string,
	opts: NodeFileAgenticMemoryCommittedFactLogBackendOptions<TJson> = {},
): AgenticMemoryCommittedFactLogBackend<TJson> {
	const backendName = opts.backendName ?? BACKEND_ID;
	const prefix = opts.prefix ?? DEFAULT_PREFIX;
	const log = fileAppendLog<AgenticMemoryCommittedFactBatch<TJson>>(dir, {
		...opts,
		prefix,
		codec: agenticMemoryCommittedFactBatchCodec<TJson>(),
	});
	let tail: PromiseLike<unknown> | undefined;

	function enqueue<R>(task: () => R | PromiseLike<R>): R | PromiseLike<R> {
		const run = tail === undefined ? task() : tail.then(task, task);
		if (isPromiseLike(run)) {
			tail = run.then(
				() => undefined,
				() => undefined,
			);
		}
		return run;
	}

	const status = () =>
		agenticMemoryCommittedFactLogBackendStatus("available", {
			backend: backendName,
			capabilities: [
				capability("single-writer", true, {
					mode: "single-writer-per-backend-handle",
					prefix,
					note: "Node file fact-log backend assumes one writer for this storage prefix",
				}),
				capability("whole-batch-visibility", true, {
					storageEntry: "one committed fact batch per append-log entry",
				}),
				capability("multi-writer-correctness", false, {
					reason: "D594 first reference backend is single-writer",
				}),
				capability("fsync-guarantee", false, {
					reason:
						"write completion means the storage promise settled; host fsync/transaction guarantees are not claimed as D589 semantics",
				}),
			],
		});

	return {
		kind: "agentic-memory-committed-fact-log-backend",
		status,
		append(batch) {
			return enqueue(() => appendCore(batch));
		},
		read(opts = {}) {
			return enqueue(() => readCore(opts));
		},
	};

	function appendCore(
		batch: AgenticMemoryCommittedFactBatch<TJson>,
	):
		| AgenticMemoryCommittedFactLogBackendAppendResult
		| PromiseLike<AgenticMemoryCommittedFactLogBackendAppendResult> {
		let canonical: AgenticMemoryCommittedFactBatch<TJson>;
		try {
			canonical = assertAgenticMemoryCommittedFactBatch<TJson>(batch);
		} catch (error) {
			return appendResult("rejected", factCursor(0), 0, {
				issues: [
					issue("agentic-memory.fact-log-backend.node-file.invalid-batch", errorMessage(error)),
				],
			});
		}

		return readAllFacts().then(
			(existing) => {
				const cursorBefore = factCursor(existing.length);
				const disposition = committedFactBatchDisposition(existing, canonical.facts);
				switch (disposition.kind) {
					case "internal-conflict":
						return appendResult("conflict", cursorBefore, 0, {
							issues: [
								issue(
									"agentic-memory.fact-log-backend.node-file.internal-identity-conflict",
									"committed fact batch reuses one identity with different material",
									"error",
									disposition.identity,
								),
							],
						});
					case "internal-duplicate":
						return appendResult("rejected", cursorBefore, 0, {
							issues: [
								issue(
									"agentic-memory.fact-log-backend.node-file.internal-duplicate-identity",
									"committed fact batch repeats one identity; submit each fact identity once per batch",
									"error",
									disposition.identity,
								),
							],
						});
					case "conflict":
						return appendResult("conflict", cursorBefore, 0, {
							issues: [
								issue(
									"agentic-memory.fact-log-backend.node-file.identity-conflict",
									"committed fact identity was reused with different material",
									"error",
									disposition.identity,
								),
							],
						});
					case "duplicate":
						return appendResult("duplicate", cursorBefore, 0);
					case "partial-overlap":
						return appendResult("rejected", cursorBefore, 0, {
							issues: [
								issue(
									"agentic-memory.fact-log-backend.node-file.batch-overlaps-committed-log",
									"committed fact batch partially overlaps existing facts; retry by reading the stream cursor",
								),
							],
						});
					case "append":
						break;
				}

				return log.append(canonical).then(
					(entry) => {
						const cursor = factCursor(existing.length + canonical.facts.length);
						return appendResult("committed", cursor, canonical.facts.length, {
							backendCursor: agenticMemoryCommittedFactLogBackendCursor(backendName, {
								appendLogSeq: entry.seq,
								storageKey: entry.key,
							}),
							backendStatus: status(),
							audit: [
								factLogAudit("batch-committed", {
									cursor,
									reason: "node file append-log entry committed as a whole batch",
								}),
							],
						});
					},
					(error) =>
						appendResult("uncertain", cursorBefore, 0, {
							issues: [
								issue(
									"agentic-memory.fact-log-backend.node-file.append-uncertain",
									`physical append outcome cannot be proven: ${errorMessage(error)}`,
									"error",
									canonical.batchIdentity.key,
								),
							],
							backendStatus: agenticMemoryCommittedFactLogBackendStatus("degraded", {
								backend: backendName,
								issues: [
									issue(
										"agentic-memory.fact-log-backend.node-file.append-uncertain",
										errorMessage(error),
									),
								],
							}),
						}),
				);
			},
			(error) =>
				appendResult("uncertain", factCursor(0), 0, {
					issues: [
						issue(
							"agentic-memory.fact-log-backend.node-file.precondition-read-failed",
							`could not prove preconditions before append: ${errorMessage(error)}`,
						),
					],
					backendStatus: agenticMemoryCommittedFactLogBackendStatus("degraded", {
						backend: backendName,
						issues: [
							issue(
								"agentic-memory.fact-log-backend.node-file.precondition-read-failed",
								errorMessage(error),
							),
						],
					}),
				}),
		);
	}

	function readCore(
		opts: Parameters<AgenticMemoryCommittedFactLogBackend<TJson>["read"]>[0] = {},
	):
		| AgenticMemoryCommittedFactLogBackendReadResult<TJson>
		| PromiseLike<AgenticMemoryCommittedFactLogBackendReadResult<TJson>> {
		const after = opts.after ?? factCursor(0);
		const afterIssue = validateFactCursor(after);
		if (afterIssue !== undefined) {
			return readResult([], factCursor(0), false, {
				issues: [afterIssue],
				backendStatus: status(),
			});
		}
		const limit = opts.limit ?? Number.POSITIVE_INFINITY;
		if (limit !== Number.POSITIVE_INFINITY && (!Number.isSafeInteger(limit) || limit < 0)) {
			return readResult([], after, false, {
				issues: [
					issue(
						"agentic-memory.fact-log-backend.node-file.invalid-read-limit",
						"read limit must be a non-negative safe integer or Infinity",
					),
				],
				backendStatus: status(),
			});
		}
		return log.read().then(
			(entries) => {
				try {
					const facts = flattenBatches(entries.map((entry) => entry.value));
					if (after.position > facts.length) {
						return readResult([], after, false, {
							issues: [
								issue(
									"agentic-memory.fact-log-backend.node-file.invalid-fact-cursor",
									"fact cursor is beyond the current stream tail",
								),
							],
							backendStatus: status(),
						});
					}
					const window = committedFactReadWindow(facts, after.position, limit);
					const cursor = factCursor(window.position);
					const lastEntry = entries[entries.length - 1];
					return readResult(window.facts, cursor, window.done, {
						backendCursor:
							lastEntry === undefined
								? undefined
								: agenticMemoryCommittedFactLogBackendCursor(backendName, {
										appendLogSeq: lastEntry.seq,
										storageKey: lastEntry.key,
									}),
						backendStatus: status(),
						audit: [
							factLogAudit("facts-read", {
								cursor,
								reason: "node file backend returned committed facts in fact-stream order",
							}),
						],
					});
				} catch (error) {
					const storedIssue = issue(
						"agentic-memory.fact-log-backend.node-file.invalid-stored-stream",
						errorMessage(error),
					);
					return readResult([], after, false, {
						issues: [storedIssue],
						backendStatus: agenticMemoryCommittedFactLogBackendStatus("degraded", {
							backend: backendName,
							issues: [storedIssue],
						}),
					});
				}
			},
			(error) =>
				readResult([], after, false, {
					issues: [
						issue("agentic-memory.fact-log-backend.node-file.read-failed", errorMessage(error)),
					],
					backendStatus: agenticMemoryCommittedFactLogBackendStatus("degraded", {
						backend: backendName,
						issues: [
							issue("agentic-memory.fact-log-backend.node-file.read-failed", errorMessage(error)),
						],
					}),
				}),
		);
	}

	function readAllFacts(): PromiseLike<readonly AgenticMemoryCommittedFact<TJson>[]> {
		return log.read().then((entries) => flattenBatches(entries.map((entry) => entry.value)));
	}
}

function flattenBatches<TJson extends StrictJsonValue>(
	batches: readonly AgenticMemoryCommittedFactBatch<TJson>[],
): readonly AgenticMemoryCommittedFact<TJson>[] {
	const facts: AgenticMemoryCommittedFact<TJson>[] = [];
	for (const batch of batches) {
		const canonical = assertAgenticMemoryCommittedFactBatch<TJson>(batch);
		facts.push(...canonical.facts);
	}
	assertCommittedFactStreamIntegrity(facts);
	return Object.freeze(facts);
}

function appendResult(
	status: AgenticMemoryCommittedFactLogBackendAppendResult["status"],
	cursor: AgenticMemoryCommittedFactCursor,
	facts: number,
	opts: {
		readonly issues?: readonly DataIssue[];
		readonly audit?: readonly AgenticMemoryFactLogAuditEntry[];
		readonly backendStatus?: AgenticMemoryCommittedFactLogBackendAppendResult["backendStatus"];
		readonly backendCursor?: AgenticMemoryCommittedFactLogBackendAppendResult["backendCursor"];
	} = {},
): AgenticMemoryCommittedFactLogBackendAppendResult {
	return Object.freeze({
		status,
		cursor,
		facts,
		...(opts.issues === undefined ? {} : { issues: Object.freeze([...opts.issues]) }),
		...(opts.audit === undefined ? {} : { audit: Object.freeze([...opts.audit]) }),
		...(opts.backendStatus === undefined ? {} : { backendStatus: opts.backendStatus }),
		...(opts.backendCursor === undefined ? {} : { backendCursor: opts.backendCursor }),
	});
}

function readResult<TJson extends StrictJsonValue>(
	facts: readonly AgenticMemoryCommittedFact<TJson>[],
	cursor: AgenticMemoryCommittedFactCursor,
	done: boolean,
	opts: {
		readonly issues?: readonly DataIssue[];
		readonly audit?: readonly AgenticMemoryFactLogAuditEntry[];
		readonly backendStatus?: AgenticMemoryCommittedFactLogBackendReadResult<TJson>["backendStatus"];
		readonly backendCursor?: AgenticMemoryCommittedFactLogBackendReadResult<TJson>["backendCursor"];
	} = {},
): AgenticMemoryCommittedFactLogBackendReadResult<TJson> {
	return Object.freeze({
		facts: Object.freeze([...facts]),
		cursor,
		done,
		...(opts.issues === undefined ? {} : { issues: Object.freeze([...opts.issues]) }),
		...(opts.audit === undefined ? {} : { audit: Object.freeze([...opts.audit]) }),
		...(opts.backendStatus === undefined ? {} : { backendStatus: opts.backendStatus }),
		...(opts.backendCursor === undefined ? {} : { backendCursor: opts.backendCursor }),
	});
}

function validateFactCursor(cursor: AgenticMemoryCommittedFactCursor): DataIssue | undefined {
	if (
		cursor.kind !== AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND ||
		!Number.isSafeInteger(cursor.position) ||
		cursor.position < 0
	) {
		return issue(
			"agentic-memory.fact-log-backend.node-file.invalid-fact-cursor",
			"read after cursor must be an AgenticMemory fact-stream cursor",
		);
	}
	return undefined;
}

function factCursor(position: number): AgenticMemoryCommittedFactCursor {
	return Object.freeze({ kind: AGENTIC_MEMORY_FACT_STREAM_CURSOR_KIND, position });
}

function capability(name: string, supported: boolean, details?: StrictJsonValue) {
	return Object.freeze({
		kind: "agentic-memory-committed-fact-log-backend-capability" as const,
		name,
		supported,
		...(details === undefined ? {} : { details }),
	});
}

function issue(
	code: string,
	message: string,
	severity: DataIssue["severity"] = "error",
	subjectId?: string,
): DataIssue {
	return Object.freeze({
		kind: "issue",
		code,
		message,
		severity,
		...(subjectId === undefined ? {} : { subjectId }),
	});
}

function factLogAudit(
	action: AgenticMemoryFactLogAuditEntry["action"],
	fields: Omit<AgenticMemoryFactLogAuditEntry, "kind" | "action"> = {},
): AgenticMemoryFactLogAuditEntry {
	return Object.freeze({ kind: "agentic-memory-fact-log-audit", action, ...fields });
}

function errorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

function isPromiseLike<T>(value: T | PromiseLike<T>): value is PromiseLike<T> {
	return (
		value !== null &&
		(typeof value === "object" || typeof value === "function") &&
		typeof (value as PromiseLike<T>).then === "function"
	);
}

import { depBatch, depLatest } from "../../ctx/types.js";
import type { Graph } from "../../graph/graph.js";
import type { Node } from "../../node/node.js";
import type { MemoryRetrievalSnapshot } from "../../patterns/semantic-memory-graph.js";
import { agenticStatusState, contextState, validateAndProjectRecords } from "./shared.js";
import type {
	AgenticMemoryContext,
	AgenticMemoryProjectionCursor,
	AgenticMemoryProjectionSnapshot,
	AgenticMemoryRecord,
	AgenticMemoryStatus,
} from "./types.js";

export function solutionProjection<TFact, TSnapshot>(
	graph: Graph,
	snapshot: Node<TSnapshot>,
	name: string,
	factory: string,
	select: (fact: TSnapshot) => TFact,
): Node<TFact> {
	return graph.node<TFact>(
		[snapshot],
		(ctx) => {
			for (const raw of depBatch(ctx, 0) ?? []) {
				ctx.down([["DATA", select(raw as TSnapshot)]]);
			}
		},
		{
			name,
			factory,
			completeWhenDepsComplete: false,
			errorWhenDepsError: false,
		},
	);
}

export function agenticMemoryProjection<TFact, T>(
	graph: Graph,
	snapshot: Node<AgenticMemoryProjectionSnapshot<T>>,
	name: string,
	factory: string,
	select: (fact: AgenticMemoryProjectionSnapshot<T>) => TFact,
): Node<TFact> {
	return graph.node<TFact>(
		[snapshot],
		(ctx) => {
			for (const raw of depBatch(ctx, 0) ?? []) {
				ctx.down([["DATA", select(raw as AgenticMemoryProjectionSnapshot<T>)]]);
			}
		},
		{
			name,
			factory,
			completeWhenDepsComplete: false,
			errorWhenDepsError: false,
		},
	);
}

export function agenticMemoryContextProjection<T>(
	graph: Graph,
	projection: Node<AgenticMemoryProjectionSnapshot<T>>,
	retrieval: Node<MemoryRetrievalSnapshot<T>>,
	name: string,
): Node<AgenticMemoryContext<T>> {
	return graph.node<AgenticMemoryContext<T>>(
		[projection, retrieval],
		(ctx) => {
			const projectionFact = depLatest(ctx, 0) as AgenticMemoryProjectionSnapshot<T> | undefined;
			const retrievalFacts = depBatch(ctx, 1) ?? [];
			if (projectionFact === undefined || retrievalFacts.length === 0) return;
			for (const raw of retrievalFacts) {
				ctx.down([
					["DATA", contextFromSnapshot(projectionFact, raw as MemoryRetrievalSnapshot<T>)],
				]);
			}
		},
		{
			name,
			factory: "agenticMemoryContext",
			completeWhenDepsComplete: false,
			errorWhenDepsError: false,
		},
	);
}

export function contextFromSnapshot<T>(
	projection: AgenticMemoryProjectionSnapshot<T>,
	retrieval: MemoryRetrievalSnapshot<T>,
): AgenticMemoryContext<T> {
	const entries = retrieval.ranked.results.map((fragment, index) => {
		const record = projection.metadataByFragmentId[fragment.id];
		return Object.freeze({
			fragmentId: fragment.id,
			payload: fragment.payload,
			confidence: fragment.confidence,
			tags: fragment.tags,
			sources: fragment.sources,
			...(record === undefined ? {} : { record }),
			attribution: Object.freeze({
				fragmentId: fragment.id,
				...(record === undefined ? {} : { recordId: record.recordId }),
				rank: index + 1,
			}),
			fragment,
		});
	});
	const hasContext = entries.length > 0;
	const state = contextState(projection.status.state, retrieval.status.state);
	return Object.freeze({
		state,
		query: retrieval.ranked.query,
		entries: Object.freeze(entries),
		cursor: retrieval.cursor,
		errors: projection.errors,
		retrievalErrors: retrieval.errors,
		contextReady: hasContext && (state === "ready" || state === "partial"),
	});
}

export function agenticMemoryRecordProjection<T>(
	graph: Graph,
	records: Node<readonly AgenticMemoryRecord<T>[]>,
	name: string,
): Node<AgenticMemoryProjectionSnapshot<T>> {
	return graph.node<AgenticMemoryProjectionSnapshot<T>>(
		[records],
		(ctx) => {
			const state =
				ctx.state.get<{ evaluation: number }>() ??
				({ evaluation: 0 } satisfies { evaluation: number });
			state.evaluation += 1;
			const rawRecords = (depBatch(ctx, 0) ?? []).at(-1);
			const projected = validateAndProjectRecords<T>(rawRecords);
			const cursor: AgenticMemoryProjectionCursor = Object.freeze({
				evaluation: state.evaluation,
				validRecords: projected.records.length,
				invalidRecords: projected.invalidRecordIndexes.size,
				projectedFragments: projected.fragments.length,
			});
			const status: AgenticMemoryStatus = Object.freeze({
				state: agenticStatusState(projected.errors.length, projected.records.length),
				cursor,
			});
			const errors = Object.freeze(
				projected.errors.map((error) =>
					Object.freeze({
						...error,
						...(error.validationErrors === undefined
							? {}
							: { validationErrors: Object.freeze([...error.validationErrors]) }),
						cursor,
					}),
				),
			);
			ctx.state.set(state);
			ctx.down([
				[
					"DATA",
					Object.freeze({
						records: Object.freeze(projected.records),
						fragments: Object.freeze(projected.fragments),
						metadataByFragmentId: Object.freeze(projected.metadataByFragmentId),
						status,
						errors,
						cursor,
					}),
				],
			]);
		},
		{
			name,
			factory: "agenticMemoryProjection",
			completeWhenDepsComplete: false,
			errorWhenDepsError: false,
		},
	);
}

import type { DataIssue } from "../../data/index.js";
import type { Graph } from "../../graph/graph.js";
import { canonicalTupleKey, compoundTupleKey } from "../../identity.js";
import type { FactId } from "../../patterns/semantic-memory.js";
import { solutionOccurrenceProjection, solutionOccurrenceSelect } from "../occurrence.js";
import {
	cloneStrictJsonObject,
	errorMessage,
	forbiddenAgenticMemoryDataFields,
	isNonEmptyString,
	isPlainRecord,
	isStrictJsonObject,
	safeArrayLength,
	snapshotAgenticMemoryFactRefs,
	validateAgenticMemoryContextAttribution,
	validateAgenticMemoryFactRefs,
	validateAndProjectRecords,
	validateAndSnapshotRecord,
} from "./shared.js";
import type {
	AgenticMemoryFactRef,
	AgenticMemoryProposalAdmissionAudit,
	AgenticMemoryProposalAdmissionCursor,
	AgenticMemoryProposalAdmissionDecision,
	AgenticMemoryProposalAdmissionDecisionState,
	AgenticMemoryProposalAdmissionOptions,
	AgenticMemoryProposalAdmissionPolicy,
	AgenticMemoryProposalAdmissionSnapshot,
	AgenticMemoryProposalAdmissionStatus,
	AgenticMemoryRecordAdmissionBundle,
	AgenticMemoryRecordAdmissionBundleOptions,
	AgenticMemoryRecordCandidateMaterial,
	AgenticMemoryRecordProposal,
} from "./types.js";

/**
 * Creates an agentic memory record admission bundle.
 *
 * @remarks D151: each input DATA is one complete identity/revision/digest/source-refs
 * occurrence. Policy and prior records travel in its value, never independent latest-value
 * dependencies. Outputs preserve that identity; replay conflicts and retention overflow fail closed.
 * The fixed recipe topology is retained for its graph lifetime; input snapshots are bounded by
 * maxOccurrences, not a claim that one protocol wave is one business occurrence.
 * @param graph - Graph that owns the created nodes or projector.
 * @param opts - Options that configure the helper.
 * @returns A bundle of graph-visible nodes for the recipe.
 * @category solutions
 * @example
 * ```ts
 * import { agenticMemoryRecordAdmissionBundle } from "@graphrefly/ts/solutions/agentic-memory";
 * ```
 */
export function agenticMemoryRecordAdmissionBundle<T = unknown>(
	graph: Graph,
	opts: AgenticMemoryRecordAdmissionBundleOptions<T>,
): AgenticMemoryRecordAdmissionBundle<T> {
	const name = opts.name ?? "agenticMemoryRecordAdmission";
	const projection = solutionOccurrenceProjection(graph, opts.occurrences, {
		name: `${name}/projection`,
		factory: "agenticMemoryRecordAdmission",
		maxOccurrences: opts.maxOccurrences,
		project: (value) =>
			admitAgenticMemoryRecordProposals<T>(value.proposals, value.policy, {
				records: value.records,
				evaluation: 1,
			}),
	});
	return {
		input: opts.occurrences,
		projection,
		admissions: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/admissions`,
			"agenticMemoryRecordAdmissionAdmissions",
			(fact) => fact.admissions,
		),
		admitted: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/admitted`,
			"agenticMemoryRecordAdmissionAdmissionsAdmitted",
			(fact) => fact.admitted,
		),
		rejected: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/rejected`,
			"agenticMemoryRecordAdmissionAdmissionsRejected",
			(fact) => fact.rejected,
		),
		needsReview: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/needsReview`,
			"agenticMemoryRecordAdmissionAdmissionsNeedsReview",
			(fact) => fact.needsReview,
		),
		status: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/status`,
			"agenticMemoryRecordAdmissionStatus",
			(fact) => fact.status,
		),
		issues: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/issues`,
			"agenticMemoryRecordAdmissionIssues",
			(fact) => fact.issues,
		),
		audit: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/audit`,
			"agenticMemoryRecordAdmissionAudit",
			(fact) => fact.audit,
		),
		cursor: solutionOccurrenceSelect(
			graph,
			projection,
			`${name}/cursor`,
			"agenticMemoryRecordAdmissionCursor",
			(fact) => fact.cursor,
		),
	};
}

/**
 * Admits agentic memory record proposals.
 *
 * @param proposals - proposals value used by the helper.
 * @param policy - Policy object used to admit, retry, or route work.
 * @param opts - Options that configure the helper.
 * @returns The admit agentic memory record proposals result.
 * @category solutions
 * @example
 * ```ts
 * import { admitAgenticMemoryRecordProposals } from "@graphrefly/ts/solutions/agentic-memory";
 * ```
 */
export function admitAgenticMemoryRecordProposals<T = unknown>(
	proposals: unknown,
	policy: unknown,
	opts: AgenticMemoryProposalAdmissionOptions<T> = {},
): AgenticMemoryProposalAdmissionSnapshot<T> {
	const validatedPolicy = safeValidateAdmissionPolicy(policy);
	const recordProjection = validateAndProjectRecords<T>(opts.records ?? []);
	const projected = projectProposalAdmissions<T>(proposals, validatedPolicy.policy, {
		...opts,
		records: recordProjection.records,
	});
	const cursor = Object.freeze({
		...projected.cursor,
		invalidPolicies: validatedPolicy.invalidPolicies,
		issues:
			recordProjection.errors.length + validatedPolicy.issues.length + projected.issues.length,
	});
	return Object.freeze({
		admissions: projected.admissions,
		admitted: projected.admitted,
		rejected: projected.rejected,
		needsReview: projected.needsReview,
		status: Object.freeze({
			state: admissionStatus(cursor),
			cursor,
		}),
		issues: Object.freeze([
			...recordProjectionIssues(recordProjection.errors),
			...validatedPolicy.issues,
			...projected.issues,
		]),
		audit: projected.audit,
		cursor,
	});
}

function projectProposalAdmissions<T>(
	value: unknown,
	policy: AgenticMemoryProposalAdmissionPolicy,
	opts: AgenticMemoryProposalAdmissionOptions<T> = {},
): {
	readonly proposals: number;
	readonly validProposals: number;
	readonly invalidProposals: number;
	readonly admissions: readonly AgenticMemoryProposalAdmissionDecision<T>[];
	readonly admitted: readonly AgenticMemoryProposalAdmissionDecision<T>[];
	readonly rejected: readonly AgenticMemoryProposalAdmissionDecision<T>[];
	readonly needsReview: readonly AgenticMemoryProposalAdmissionDecision<T>[];
	readonly issues: readonly DataIssue[];
	readonly audit: readonly AgenticMemoryProposalAdmissionAudit[];
	readonly cursor: Omit<AgenticMemoryProposalAdmissionSnapshot<T>["cursor"], "invalidPolicies">;
} {
	const admissions: AgenticMemoryProposalAdmissionDecision<T>[] = [];
	const issues: DataIssue[] = [];
	const audit: AgenticMemoryProposalAdmissionAudit[] = [];
	let proposals = 0;
	let invalidProposals = 0;
	const records = opts.records ?? [];
	if (!Array.isArray(value)) {
		return {
			proposals,
			validProposals: 0,
			invalidProposals: 1,
			admissions: Object.freeze(admissions),
			admitted: Object.freeze([]),
			rejected: Object.freeze([]),
			needsReview: Object.freeze([]),
			issues: Object.freeze([
				dataIssue("agentic-memory.proposal.invalid-input", "proposals input must be an array", {
					severity: "error",
				}),
			]),
			audit: Object.freeze(audit),
			cursor: proposalAdmissionCursor(opts.evaluation, 0, 0, 1, 0, 0, 0, 1),
		};
	}
	const length = safeArrayLength(value);
	if (length === undefined) {
		return {
			proposals,
			validProposals: 0,
			invalidProposals: 1,
			admissions: Object.freeze(admissions),
			admitted: Object.freeze([]),
			rejected: Object.freeze([]),
			needsReview: Object.freeze([]),
			issues: Object.freeze([
				dataIssue(
					"agentic-memory.proposal.invalid-input",
					"proposals input length could not be read",
					{ severity: "error" },
				),
			]),
			audit: Object.freeze(audit),
			cursor: proposalAdmissionCursor(opts.evaluation, 0, 0, 1, 0, 0, 0, 1),
		};
	}
	proposals = length;
	const seenProposals = new Set<FactId>();
	const seenCandidateRecordIds = new Set<FactId>();
	const seenTargetRecordIds = new Set<FactId>();
	const currentRecordIds = new Set(records.map((record) => record.id));
	for (let index = 0; index < length; index += 1) {
		let raw: unknown;
		let proposal: AgenticMemoryRecordProposal<T> | undefined;
		try {
			if (!Object.hasOwn(value, index)) throw new TypeError("proposal array must be dense");
			raw = value[index];
			const result = validateProposal<T>(raw, index);
			if (result.proposal === undefined) {
				invalidProposals += 1;
				issues.push(...result.issues);
				continue;
			}
			proposal = result.proposal;
		} catch (error) {
			invalidProposals += 1;
			issues.push(
				dataIssue(
					"agentic-memory.proposal.invalid",
					`proposal access failed: ${errorMessage(error)}`,
					{ severity: "error", path: [index] },
				),
			);
			continue;
		}
		if (seenProposals.has(proposal.proposalId)) {
			invalidProposals += 1;
			issues.push(
				dataIssue("agentic-memory.proposal.duplicate-id", "duplicate proposal id", {
					severity: "error",
					subjectId: proposal.proposalId,
					path: [index],
				}),
			);
			continue;
		}
		seenProposals.add(proposal.proposalId);
		if (seenCandidateRecordIds.has(proposal.candidateMaterial.record.id)) {
			invalidProposals += 1;
			issues.push(
				dataIssue(
					"agentic-memory.proposal.duplicate-candidate-record-id",
					"duplicate candidate record id in proposal batch",
					{
						severity: "error",
						subjectId: proposal.proposalId,
						path: [index, "candidateMaterial", "record", "id"],
						refs: [proposal.candidateMaterial.record.id],
					},
				),
			);
			continue;
		}
		seenCandidateRecordIds.add(proposal.candidateMaterial.record.id);
		const effectiveTargetRecordId =
			proposal.targetRecordId ??
			proposal.candidateMaterial.targetRecordId ??
			proposal.candidateMaterial.record.id;
		if (seenTargetRecordIds.has(effectiveTargetRecordId)) {
			invalidProposals += 1;
			issues.push(
				dataIssue(
					"agentic-memory.proposal.duplicate-target-record-id",
					"duplicate target record id in proposal batch",
					{
						severity: "error",
						subjectId: proposal.proposalId,
						path: [index, "targetRecordId"],
						refs: [effectiveTargetRecordId],
					},
				),
			);
			continue;
		}
		seenTargetRecordIds.add(effectiveTargetRecordId);
		const admission = admitProposal(proposal, currentRecordIds, policy);
		admissions.push(admission);
		audit.push(admissionAudit(admission, policy));
	}
	const admitted = Object.freeze(admissions.filter((admission) => admission.state === "admitted"));
	const rejected = Object.freeze(admissions.filter((admission) => admission.state === "rejected"));
	const needsReview = Object.freeze(
		admissions.filter((admission) => admission.state === "needs-review"),
	);
	return {
		proposals,
		validProposals: admissions.length,
		invalidProposals,
		admissions: Object.freeze(admissions),
		admitted,
		rejected,
		needsReview,
		issues: Object.freeze(issues),
		audit: Object.freeze(audit),
		cursor: proposalAdmissionCursor(
			opts.evaluation,
			proposals,
			admissions.length,
			invalidProposals,
			admitted.length,
			rejected.length,
			needsReview.length,
			issues.length,
		),
	};
}

function validateProposal<T>(
	value: unknown,
	index: number,
): {
	readonly proposal?: AgenticMemoryRecordProposal<T>;
	readonly issues: readonly DataIssue[];
} {
	if (!isPlainRecord(value)) {
		return {
			issues: [
				dataIssue("agentic-memory.proposal.invalid", "proposal must be an object", {
					severity: "error",
					path: [index],
				}),
			],
		};
	}
	const validationErrors: string[] = [];
	validationErrors.push(...forbiddenAgenticMemoryDataFields(value, "proposal"));
	if (value.kind !== "agentic-memory-record-proposal") {
		validationErrors.push("proposal.kind must be agentic-memory-record-proposal");
	}
	const proposalId = isNonEmptyString(value.proposalId) ? value.proposalId : undefined;
	if (proposalId === undefined) validationErrors.push("proposal.proposalId must be non-empty");
	if (value.targetRecordId !== undefined && !isNonEmptyString(value.targetRecordId)) {
		validationErrors.push("proposal.targetRecordId must be non-empty when present");
	}
	if (value.operation !== undefined && typeof value.operation !== "string") {
		validationErrors.push("proposal.operation must be a string when present");
	}
	if (
		value.operationVersion !== undefined &&
		(typeof value.operationVersion !== "number" || !Number.isInteger(value.operationVersion))
	) {
		validationErrors.push("proposal.operationVersion must be an integer when present");
	}
	for (const [field, refs] of [
		["sourceRefs", value.sourceRefs],
		["policyRefs", value.policyRefs],
		["evidenceRefs", value.evidenceRefs],
	] as const) {
		if (refs !== undefined) {
			const refErrors = validateAgenticMemoryFactRefs(refs);
			if (refErrors.length > 0) {
				validationErrors.push(...refErrors.map((error) => `proposal.${field}: ${error}`));
			}
		}
	}
	const candidateMaterial = validateCandidateMaterial<T>(value.candidateMaterial, index);
	if (candidateMaterial.issues.length > 0 || candidateMaterial.material === undefined) {
		validationErrors.push(
			...candidateMaterial.issues.flatMap((issue) =>
				(issue.refs ?? [issue.message]).map((message) => `candidateMaterial: ${message}`),
			),
		);
	}
	if (
		isNonEmptyString(value.targetRecordId) &&
		candidateMaterial.material?.targetRecordId !== undefined &&
		value.targetRecordId !== candidateMaterial.material.targetRecordId
	) {
		validationErrors.push(
			"proposal.targetRecordId conflicts with candidateMaterial.targetRecordId",
		);
	}
	if (
		typeof value.operation === "string" &&
		candidateMaterial.material?.operation !== undefined &&
		value.operation !== candidateMaterial.material.operation
	) {
		validationErrors.push("proposal.operation conflicts with candidateMaterial.operation");
	}
	if (
		typeof value.operationVersion === "number" &&
		candidateMaterial.material?.operationVersion !== undefined &&
		value.operationVersion !== candidateMaterial.material.operationVersion
	) {
		validationErrors.push(
			"proposal.operationVersion conflicts with candidateMaterial.operationVersion",
		);
	}
	if (value.metadata !== undefined && !isStrictJsonObject(value.metadata)) {
		validationErrors.push("proposal.metadata must be a strict JSON object");
	}
	for (const field of [
		"reason",
		"proposalStatus",
		"idempotencyKey",
		"correlationId",
		"causationId",
	]) {
		const current = value[field];
		if (current !== undefined && typeof current !== "string") {
			validationErrors.push(`proposal.${field} must be a string when present`);
		}
	}
	if (
		validationErrors.length > 0 ||
		proposalId === undefined ||
		candidateMaterial.material === undefined
	) {
		return {
			issues: [
				dataIssue("agentic-memory.proposal.invalid", "proposal is invalid", {
					severity: "error",
					subjectId: proposalId,
					path: [index],
					refs: validationErrors,
				}),
			],
		};
	}
	return {
		proposal: Object.freeze({
			kind: "agentic-memory-record-proposal",
			proposalId,
			...(value.operation === undefined
				? {}
				: { operation: value.operation as AgenticMemoryRecordProposal<T>["operation"] }),
			...(value.operationVersion === undefined
				? {}
				: {
						operationVersion:
							value.operationVersion as AgenticMemoryRecordProposal<T>["operationVersion"],
					}),
			candidateMaterial: candidateMaterial.material,
			...(value.targetRecordId === undefined
				? {}
				: { targetRecordId: value.targetRecordId as FactId }),
			...(value.reason === undefined ? {} : { reason: value.reason as string }),
			...(value.proposalStatus === undefined
				? {}
				: { proposalStatus: value.proposalStatus as string }),
			...(value.sourceRefs === undefined
				? {}
				: { sourceRefs: snapshotAgenticMemoryFactRefs(value.sourceRefs) }),
			...(value.policyRefs === undefined
				? {}
				: { policyRefs: snapshotAgenticMemoryFactRefs(value.policyRefs) }),
			...(value.evidenceRefs === undefined
				? {}
				: { evidenceRefs: snapshotAgenticMemoryFactRefs(value.evidenceRefs) }),
			...(value.idempotencyKey === undefined
				? {}
				: { idempotencyKey: value.idempotencyKey as string }),
			...(value.correlationId === undefined
				? {}
				: { correlationId: value.correlationId as string }),
			...(value.causationId === undefined ? {} : { causationId: value.causationId as string }),
			...(value.metadata === undefined ? {} : { metadata: cloneStrictJsonObject(value.metadata) }),
		}),
		issues: [],
	};
}

function recordProjectionIssues(
	errors: readonly ReturnType<typeof validateAndProjectRecords>["errors"][number][],
): readonly DataIssue[] {
	return errors.map((error) =>
		dataIssue("agentic-memory.record.invalid", error.message, {
			severity: "error",
			subjectId: error.recordId,
			refs: error.validationErrors,
		}),
	);
}

function admitProposal<T>(
	proposal: AgenticMemoryRecordProposal<T>,
	currentRecordIds: ReadonlySet<FactId>,
	policy: AgenticMemoryProposalAdmissionPolicy,
): AgenticMemoryProposalAdmissionDecision<T> {
	const targetRecordId = proposal.targetRecordId ?? proposal.candidateMaterial.targetRecordId;
	const duplicate =
		(policy.rejectDuplicateRecordIds ?? true) &&
		currentRecordIds.has(proposal.candidateMaterial.record.id) &&
		targetRecordId !== proposal.candidateMaterial.record.id;
	const missingSourceRefs =
		(policy.requireSourceRefs ?? false) &&
		(proposal.sourceRefs?.length ?? 0) + (proposal.candidateMaterial.sourceRefs?.length ?? 0) === 0;
	const state: AgenticMemoryProposalAdmissionDecisionState = duplicate
		? "rejected"
		: missingSourceRefs
			? "needs-review"
			: (policy.defaultState ?? "needs-review");
	const reason = duplicate
		? "candidate record id already exists"
		: missingSourceRefs
			? "policy requires sourceRefs"
			: (proposal.reason ?? `policy:${policy.policyId}`);
	const evidenceRefs = mergeRefs([
		...(proposal.candidateMaterial.evidenceRefs ?? []),
		...(proposal.evidenceRefs ?? []),
	]);
	return Object.freeze({
		kind: "agentic-memory-record-admission",
		admissionId: compoundTupleKey("admission", [policy.policyId, proposal.proposalId]),
		proposalId: proposal.proposalId,
		state,
		...(proposal.operation === undefined ? {} : { operation: proposal.operation }),
		...(proposal.operationVersion === undefined
			? {}
			: { operationVersion: proposal.operationVersion }),
		candidateMaterial: proposal.candidateMaterial,
		...(targetRecordId === undefined ? {} : { targetRecordId }),
		reason,
		sourceRefs: mergeRefs([
			...(proposal.candidateMaterial.sourceRefs ?? []),
			...(proposal.sourceRefs ?? []),
			...(policy.sourceRefs ?? []),
		]),
		policyRefs: mergeRefs([
			...(proposal.candidateMaterial.policyRefs ?? []),
			...(proposal.policyRefs ?? []),
			{ kind: "agentic-memory-record-admission-policy", id: policy.policyId },
			...(policy.policyRefs ?? []),
		]),
		...(evidenceRefs === undefined ? {} : { evidenceRefs }),
		...(proposal.idempotencyKey === undefined ? {} : { idempotencyKey: proposal.idempotencyKey }),
		...(proposal.correlationId === undefined ? {} : { correlationId: proposal.correlationId }),
		...(proposal.causationId === undefined ? {} : { causationId: proposal.causationId }),
	});
}

function validateCandidateMaterial<T>(
	value: unknown,
	index: number,
): {
	readonly material?: AgenticMemoryRecordCandidateMaterial<T>;
	readonly issues: readonly DataIssue[];
} {
	if (!isPlainRecord(value)) {
		return {
			issues: [
				dataIssue("agentic-memory.proposal.invalid", "candidateMaterial must be an object", {
					severity: "error",
					path: [index, "candidateMaterial"],
				}),
			],
		};
	}
	const validationErrors: string[] = [];
	validationErrors.push(...forbiddenAgenticMemoryDataFields(value, "candidateMaterial"));
	if (value.kind !== "agentic-memory-record-candidate-material") {
		validationErrors.push(
			"candidateMaterial.kind must be agentic-memory-record-candidate-material",
		);
	}
	if (value.targetRecordId !== undefined && !isNonEmptyString(value.targetRecordId)) {
		validationErrors.push("candidateMaterial.targetRecordId must be non-empty when present");
	}
	if (value.operation !== undefined && typeof value.operation !== "string") {
		validationErrors.push("candidateMaterial.operation must be a string when present");
	}
	if (
		value.operationVersion !== undefined &&
		(typeof value.operationVersion !== "number" || !Number.isInteger(value.operationVersion))
	) {
		validationErrors.push("candidateMaterial.operationVersion must be an integer when present");
	}
	for (const [field, refs] of [
		["sourceRefs", value.sourceRefs],
		["policyRefs", value.policyRefs],
		["evidenceRefs", value.evidenceRefs],
	] as const) {
		if (refs !== undefined) {
			const refErrors = validateAgenticMemoryFactRefs(refs);
			if (refErrors.length > 0) {
				validationErrors.push(...refErrors.map((error) => `candidateMaterial.${field}: ${error}`));
			}
		}
	}
	if (value.metadata !== undefined && !isStrictJsonObject(value.metadata)) {
		validationErrors.push("candidateMaterial.metadata must be a strict JSON object");
	}
	const candidate = validateAndSnapshotRecord<T>(value.record, index);
	if (candidate.errors.length > 0 || candidate.record === undefined) {
		validationErrors.push(
			...candidate.errors.flatMap((error) =>
				(error.validationErrors ?? [error.message]).map(
					(message) => `candidateMaterial.record: ${message}`,
				),
			),
		);
	}
	const attribution = validateAgenticMemoryContextAttribution(value.attribution, {
		fragmentId: candidate.record?.fragment.id,
		recordId: candidate.record?.id,
	});
	if (!attribution.ok) {
		validationErrors.push(...attribution.errors.map((error) => `candidateMaterial.${error}`));
	}
	if (validationErrors.length > 0 || candidate.record === undefined) {
		return {
			issues: [
				dataIssue("agentic-memory.proposal.invalid", "candidateMaterial is invalid", {
					severity: "error",
					path: [index, "candidateMaterial"],
					refs: validationErrors,
				}),
			],
		};
	}
	return {
		material: Object.freeze({
			kind: "agentic-memory-record-candidate-material",
			...(value.operation === undefined
				? {}
				: { operation: value.operation as AgenticMemoryRecordCandidateMaterial<T>["operation"] }),
			...(value.operationVersion === undefined
				? {}
				: {
						operationVersion:
							value.operationVersion as AgenticMemoryRecordCandidateMaterial<T>["operationVersion"],
					}),
			record: candidate.record,
			...(value.targetRecordId === undefined
				? {}
				: { targetRecordId: value.targetRecordId as FactId }),
			...(attribution.attribution === undefined ? {} : { attribution: attribution.attribution }),
			...(value.sourceRefs === undefined
				? {}
				: { sourceRefs: snapshotAgenticMemoryFactRefs(value.sourceRefs) }),
			...(value.policyRefs === undefined
				? {}
				: { policyRefs: snapshotAgenticMemoryFactRefs(value.policyRefs) }),
			...(value.evidenceRefs === undefined
				? {}
				: { evidenceRefs: snapshotAgenticMemoryFactRefs(value.evidenceRefs) }),
			...(value.metadata === undefined ? {} : { metadata: cloneStrictJsonObject(value.metadata) }),
		}),
		issues: [],
	};
}

function admissionAudit<T>(
	admission: AgenticMemoryProposalAdmissionDecision<T>,
	policy: AgenticMemoryProposalAdmissionPolicy,
): AgenticMemoryProposalAdmissionAudit {
	return Object.freeze({
		kind: "agentic-memory-record-admission-audit",
		admissionId: admission.admissionId,
		proposalId: admission.proposalId,
		state: admission.state,
		reason: admission.reason,
		sourceRefs: admission.sourceRefs,
		policyRefs: mergeRefs([
			...(admission.policyRefs ?? []),
			{ kind: "agentic-memory-record-admission-policy", id: policy.policyId },
		]),
	});
}

function safeValidateAdmissionPolicy(value: unknown): {
	readonly policy: AgenticMemoryProposalAdmissionPolicy;
	readonly issues: readonly DataIssue[];
	readonly invalidPolicies: number;
} {
	try {
		return validateAdmissionPolicy(value);
	} catch (error) {
		return {
			policy: defaultAdmissionPolicy(),
			invalidPolicies: 1,
			issues: [
				dataIssue(
					"agentic-memory.admission-policy.invalid",
					`admission policy access failed: ${errorMessage(error)}`,
					{ severity: "error" },
				),
			],
		};
	}
}

function validateAdmissionPolicy(value: unknown): {
	readonly policy: AgenticMemoryProposalAdmissionPolicy;
	readonly issues: readonly DataIssue[];
	readonly invalidPolicies: number;
} {
	if (!isPlainRecord(value)) {
		return {
			policy: defaultAdmissionPolicy(),
			invalidPolicies: 1,
			issues: [
				dataIssue("agentic-memory.admission-policy.invalid", "admission policy must be an object", {
					severity: "error",
				}),
			],
		};
	}
	const validationErrors: string[] = [];
	validationErrors.push(...forbiddenAgenticMemoryDataFields(value, "policy"));
	if (value.kind !== "agentic-memory-record-admission-policy") {
		validationErrors.push("policy.kind must be agentic-memory-record-admission-policy");
	}
	const policyId = isNonEmptyString(value.policyId) ? value.policyId : undefined;
	if (policyId === undefined) validationErrors.push("policy.policyId must be non-empty");
	if (
		value.defaultState !== undefined &&
		value.defaultState !== "admitted" &&
		value.defaultState !== "rejected" &&
		value.defaultState !== "needs-review"
	) {
		validationErrors.push("policy.defaultState must be admitted, rejected, or needs-review");
	}
	for (const field of ["requireSourceRefs", "rejectDuplicateRecordIds"]) {
		if (value[field] !== undefined && typeof value[field] !== "boolean") {
			validationErrors.push(`policy.${field} must be boolean when present`);
		}
	}
	for (const [field, refs] of [
		["sourceRefs", value.sourceRefs],
		["policyRefs", value.policyRefs],
	] as const) {
		if (refs !== undefined) {
			validationErrors.push(
				...validateAgenticMemoryFactRefs(refs).map((error) => `policy.${field}: ${error}`),
			);
		}
	}
	if (value.metadata !== undefined && !isStrictJsonObject(value.metadata)) {
		validationErrors.push("policy.metadata must be a strict JSON object");
	}
	if (validationErrors.length > 0 || policyId === undefined) {
		return {
			policy: defaultAdmissionPolicy(),
			invalidPolicies: 1,
			issues: [
				dataIssue("agentic-memory.admission-policy.invalid", "admission policy is invalid", {
					severity: "error",
					subjectId: policyId,
					refs: validationErrors,
				}),
			],
		};
	}
	return {
		policy: Object.freeze({
			kind: "agentic-memory-record-admission-policy",
			policyId,
			...(value.defaultState === undefined
				? {}
				: { defaultState: value.defaultState as AgenticMemoryProposalAdmissionDecisionState }),
			...(value.requireSourceRefs === undefined
				? {}
				: { requireSourceRefs: value.requireSourceRefs as boolean }),
			...(value.rejectDuplicateRecordIds === undefined
				? {}
				: { rejectDuplicateRecordIds: value.rejectDuplicateRecordIds as boolean }),
			...(value.sourceRefs === undefined
				? {}
				: { sourceRefs: snapshotAgenticMemoryFactRefs(value.sourceRefs) }),
			...(value.policyRefs === undefined
				? {}
				: { policyRefs: snapshotAgenticMemoryFactRefs(value.policyRefs) }),
			...(value.metadata === undefined ? {} : { metadata: cloneStrictJsonObject(value.metadata) }),
		}),
		issues: [],
		invalidPolicies: 0,
	};
}

function defaultAdmissionPolicy(): AgenticMemoryProposalAdmissionPolicy {
	return Object.freeze({
		kind: "agentic-memory-record-admission-policy",
		policyId: "invalid-policy",
		defaultState: "rejected",
	});
}

function proposalAdmissionCursor(
	evaluation: number | undefined,
	proposals: number,
	validProposals: number,
	invalidProposals: number,
	admitted: number,
	rejected: number,
	needsReview: number,
	issues: number,
): Omit<AgenticMemoryProposalAdmissionCursor, "invalidPolicies"> {
	return Object.freeze({
		evaluation: evaluation ?? 0,
		proposals,
		validProposals,
		invalidProposals,
		admitted,
		rejected,
		needsReview,
		issues,
	});
}

function admissionStatus(
	cursor: AgenticMemoryProposalAdmissionCursor,
): AgenticMemoryProposalAdmissionStatus["state"] {
	if ((cursor.invalidProposals > 0 || cursor.invalidPolicies > 0) && cursor.validProposals === 0) {
		return "error";
	}
	if (cursor.invalidProposals > 0 || cursor.invalidPolicies > 0 || cursor.issues > 0) {
		return "partial";
	}
	if (cursor.proposals === 0) return "empty";
	if (cursor.needsReview > 0) return "blocked";
	return "ready";
}

function mergeRefs(
	refs: readonly AgenticMemoryFactRef[],
): readonly AgenticMemoryFactRef[] | undefined {
	if (refs.length === 0) return undefined;
	const seen = new Set<string>();
	const out: AgenticMemoryFactRef[] = [];
	for (const ref of refs) {
		const key = canonicalTupleKey([ref.kind, ref.id]);
		if (seen.has(key)) continue;
		seen.add(key);
		out.push(ref);
	}
	return Object.freeze(out);
}

function dataIssue(
	code: string,
	message: string,
	opts: {
		readonly severity?: DataIssue["severity"];
		readonly subjectId?: string;
		readonly path?: readonly (string | number)[];
		readonly refs?: readonly string[];
	} = {},
): DataIssue {
	return Object.freeze({
		kind: "issue",
		code,
		message,
		source: "agentic-memory",
		...opts,
	});
}

