	readonly inputIndex: number;
}

interface ValidDecision {
	readonly decision: AgenticMemoryRecordUseDecision;
	readonly inputIndex: number;
}

interface DecisionClaim {
	readonly requestKey: string;
	readonly recordId: string;
	readonly recordKey: string;
}

interface EvaluationDiagnostics {
	readonly exclusions: AgenticMemoryRecordUseExclusion[];
	readonly issues: AgenticMemoryRecordUseIssue[];
	readonly audit: AgenticMemoryRecordUseAuditEntry[];
	readonly reasonCounts: Record<AgenticMemoryRecordUseReasonCode, number>;
}

/**
 * Caller-selected metadata for creating one exact external D643 decision.
 * @category solutions
 */
export interface AgenticMemoryRecordUseDecisionOptions {
	readonly decisionId: string;
	readonly state: AgenticMemoryRecordUseDecisionState;
}

/**
 * Assert, normalize, sort, and deeply freeze one strict D643 request.
 *
 * Unknown fields and non-strict JSON values fail instead of being ignored.
 *
 * @param value - Unknown request-shaped DATA to validate.
 * @returns A normalized immutable v1 request.
 * @category solutions
 */
export function assertAgenticMemoryRecordUseRequest(value: unknown): AgenticMemoryRecordUseRequest {
	assertDataObject(value, "record-use request");
	assertExactFields(
		value,
		[
			"authorityCoordinates",
			"format",
			"policyCoordinates",
			"purpose",
			"requestId",
			"scope",
			"sourceRevisions",
			"subject",
			"version",
		],
		"record-use request",
	);
	if (value.format !== AGENTIC_MEMORY_RECORD_USE_REQUEST_FORMAT) {
		throw new TypeError("record-use request has an invalid format");
	}
	if (value.version !== AGENTIC_MEMORY_RECORD_USE_VERSION) {
		throw new TypeError("record-use request has an invalid version");
	}
	if (!isNonEmptyString(value.requestId)) {
		throw new TypeError("record-use requestId must be a non-empty string");
	}
	const request = Object.freeze({
		format: AGENTIC_MEMORY_RECORD_USE_REQUEST_FORMAT,
		version: AGENTIC_MEMORY_RECORD_USE_VERSION,
		requestId: value.requestId,
		subject: canonicalCoordinate(value.subject, "record-use request subject"),
		purpose: canonicalCoordinate(value.purpose, "record-use request purpose"),
		scope: canonicalCoordinate(value.scope, "record-use request scope"),
		sourceRevisions: canonicalRevisionCoordinates(
			value.sourceRevisions,
			"record-use request sourceRevisions",
		),
		policyCoordinates: canonicalRevisionCoordinates(
			value.policyCoordinates,
			"record-use request policyCoordinates",
		),
		authorityCoordinates: canonicalRevisionCoordinates(
			value.authorityCoordinates,
			"record-use request authorityCoordinates",
		),
	});
	strictCanonicalJsonBytes(request);
	return request;
}

/**
 * Return the synchronous strict-canonical identity of the complete D643 request frame.
 *
 * @param request - Strict request DATA to normalize and identify.
 * @returns A versioned request identity suitable for external decision creation.
 * @category solutions
 */
export function agenticMemoryRecordUseRequestIdentity(
	request: unknown,
): AgenticMemoryRecordUseRequestIdentity {
	const canonical = assertAgenticMemoryRecordUseRequest(request);
	return Object.freeze({
		version: AGENTIC_MEMORY_RECORD_USE_VERSION,
		algorithm: AGENTIC_MEMORY_RECORD_USE_REQUEST_IDENTITY_ALGORITHM,
		key: strictJsonText({
			format: REQUEST_IDENTITY_FRAME_FORMAT,
			version: AGENTIC_MEMORY_RECORD_USE_VERSION,
			request: canonical,
		}),
	});
}

/**
 * Return the synchronous strict-canonical identity of the complete canonical record frame.
 *
 * @param record - Current AgenticMemory record to identify.
 * @returns A versioned identity over the complete canonical record frame.
 * @category solutions
 */
export function agenticMemoryRecordUseRecordIdentity<
	TJson extends StrictJsonValue = StrictJsonValue,
>(record: AgenticMemoryRecord<TJson>): AgenticMemoryRecordUseRecordIdentity {
	return canonicalRecord(record, 0).identity;
}

/**
 * Create the D574 tuple coordinate used internally for exact-one decision cardinality.
 *
 * Callers pass ordinary request/record data and never hand-encode canonical identity material.
 *
 * @param request - Exact use request.
 * @param record - Exact current record.
 * @returns The D574 tuple key for request identity, record id, and record identity.
 * @category solutions
 */
export function agenticMemoryRecordUseDecisionCoordinate<
	TJson extends StrictJsonValue = StrictJsonValue,
>(request: AgenticMemoryRecordUseRequest, record: AgenticMemoryRecord<TJson>): string {
	const requestIdentity = agenticMemoryRecordUseRequestIdentity(request);
	const canonical = canonicalRecord(record, 0);
	return decisionCoordinate(requestIdentity.key, canonical.record.id, canonical.identity.key);
}

/**
 * Create one strict external decision pinned to an exact current request and record.
 *
 * @param request - Exact use request authorized or denied by the external authority.
 * @param record - Exact current record covered by the decision.
 * @param options - External decision id and allowed/denied state.
 * @returns An immutable strict v1 decision.
 * @category solutions
 */
export function createAgenticMemoryRecordUseDecision<
	TJson extends StrictJsonValue = StrictJsonValue,
>(
	request: AgenticMemoryRecordUseRequest,
	record: AgenticMemoryRecord<TJson>,
	options: AgenticMemoryRecordUseDecisionOptions,
): AgenticMemoryRecordUseDecision {
	if (!isNonEmptyString(options.decisionId)) {
		throw new TypeError("record-use decisionId must be a non-empty string");
	}
	if (options.state !== "allowed" && options.state !== "denied") {
		throw new TypeError("record-use decision state must be allowed or denied");
	}
	const canonical = canonicalRecord(record, 0);
	return Object.freeze({
		format: AGENTIC_MEMORY_RECORD_USE_DECISION_FORMAT,
		version: AGENTIC_MEMORY_RECORD_USE_VERSION,
		decisionId: options.decisionId,
		requestIdentity: agenticMemoryRecordUseRequestIdentity(request),
		recordId: canonical.record.id,
		recordIdentity: canonical.identity,
		state: options.state,
	});
}

/**
 * Assert and snapshot one strict v1 external decision.
 *
 * @param value - Unknown decision-shaped DATA to validate.
 * @returns A normalized immutable decision.
 * @category solutions
 */
export function assertAgenticMemoryRecordUseDecision(
	value: unknown,
): AgenticMemoryRecordUseDecision {
	assertDataObject(value, "record-use decision");
	assertExactFields(
		value,
		["decisionId", "format", "recordId", "recordIdentity", "requestIdentity", "state", "version"],
		"record-use decision",
	);
	if (value.format !== AGENTIC_MEMORY_RECORD_USE_DECISION_FORMAT) {
		throw new TypeError("record-use decision has an invalid format");
	}
	if (value.version !== AGENTIC_MEMORY_RECORD_USE_VERSION) {
		throw new TypeError("record-use decision has an invalid version");
	}
	if (!isNonEmptyString(value.decisionId)) {
		throw new TypeError("record-use decisionId must be a non-empty string");
	}
	if (!isNonEmptyString(value.recordId)) {
		throw new TypeError("record-use decision recordId must be a non-empty string");
	}
	if (value.state !== "allowed" && value.state !== "denied") {
		throw new TypeError("record-use decision state must be allowed or denied");
	}
	const requestIdentity = assertRequestIdentity(value.requestIdentity);
	const parsedRecordIdentity = assertRecordIdentity(value.recordIdentity);
	if (parsedRecordIdentity.recordId !== value.recordId) {
		throw new TypeError("record-use decision recordId does not match its record identity");
	}
	const decision = Object.freeze({
		format: AGENTIC_MEMORY_RECORD_USE_DECISION_FORMAT,
		version: AGENTIC_MEMORY_RECORD_USE_VERSION,
		decisionId: value.decisionId,
		requestIdentity,
		recordId: value.recordId,
		recordIdentity: parsedRecordIdentity.identity,
		state: value.state,
	});
	strictCanonicalJsonBytes(decision);
	return decision;
}

/**
 * Evaluate one exact D643 use synchronously.
 *
 * Structural faults are attributed to the affected coordinate and make the
 * exact-use evaluation globally fail-closed. A valid denial remains ready.
 *
 * @param recordsValue - Current AgenticMemory record array.
 * @param requestValue - One strict exact-use request.
 * @param decisionsValue - External decisions for the request and current records.
 * @param evaluation - Evaluation-local positive sequence value.
 * @returns One immutable fail-closed snapshot shared by declared projections.
 * @category solutions
 */
export function projectAgenticMemoryRecordUseGate<TJson extends StrictJsonValue = StrictJsonValue>(
	recordsValue: unknown,
	requestValue: unknown,
	decisionsValue: unknown,
	evaluation = 1,
): AgenticMemoryRecordUseSnapshot<TJson> {
	if (!Number.isSafeInteger(evaluation) || evaluation < 1) {
		throw new TypeError("record-use evaluation must be a safe integer >= 1");
	}
	const fallbackRecords = safeInputLength(recordsValue);
	const fallbackDecisions = safeInputLength(decisionsValue);
	try {
		return projectAgenticMemoryRecordUseGateInner<TJson>(
			recordsValue,
			requestValue,
			decisionsValue,
			evaluation,
		);
	} catch {
		return globalFailure<TJson>("invalid-input", evaluation, fallbackRecords, fallbackDecisions);
	}
}

function projectAgenticMemoryRecordUseGateInner<TJson extends StrictJsonValue = StrictJsonValue>(
	recordsValue: unknown,
	requestValue: unknown,
	decisionsValue: unknown,
	evaluation: number,
): AgenticMemoryRecordUseSnapshot<TJson> {
	const inputRecords = arrayLength(recordsValue);
	const inputDecisions = arrayLength(decisionsValue);
	if (inputRecords === undefined || inputDecisions === undefined) {
		return globalFailure<TJson>(
			"invalid-input",
			evaluation,
			inputRecords ?? 0,
			inputDecisions ?? 0,
		);
	}
	if (!Array.isArray(recordsValue)) {
		return globalFailure<TJson>("invalid-record", evaluation, inputRecords, inputDecisions);
	}
	if (!Array.isArray(decisionsValue)) {
		return globalFailure<TJson>("invalid-decision", evaluation, inputRecords, inputDecisions);
	}
	if (
		inputRecords > AGENTIC_MEMORY_RECORD_USE_V1_LIMITS.records ||
		inputDecisions > AGENTIC_MEMORY_RECORD_USE_V1_LIMITS.decisions
	) {
		return globalFailure<TJson>("input-overflow", evaluation, inputRecords, inputDecisions);
	}
	let request: AgenticMemoryRecordUseRequest;
	try {
		request = assertAgenticMemoryRecordUseRequest(requestValue);
	} catch {
		return globalFailure<TJson>("invalid-request", evaluation, inputRecords, inputDecisions);
	}
	const recordsContainerValid =
		dataArrayContainerErrors(recordsValue, "record-use records", inputRecords).length === 0;
	const decisionsContainerValid =
		dataArrayContainerErrors(decisionsValue, "record-use decisions", inputDecisions).length === 0;
	if (!recordsContainerValid || !decisionsContainerValid) {
		return globalFailure<TJson>(
			!recordsContainerValid ? "invalid-record" : "invalid-decision",
			evaluation,
			inputRecords,
			inputDecisions,
		);
	}

	const diagnostics = emptyDiagnostics();
	const canonicalRecords: CanonicalRecord<TJson>[] = [];
	let invalidRecords = 0;
	for (let index = 0; index < inputRecords; index += 1) {
		if (!Object.hasOwn(recordsValue, index)) {
			invalidRecords += 1;
			addRecordFault(diagnostics, "invalid-record");
			continue;
		}
		const raw = recordsValue[index];
		try {
			canonicalRecords.push(canonicalRecord(raw as AgenticMemoryRecord<TJson>, index));
		} catch {
			invalidRecords += 1;
			addRecordFault(diagnostics, "invalid-record");
		}
	}
	canonicalRecords.sort(compareCanonicalRecords);

	const duplicateRecordIds = new Set<string>();
	const recordsById = new Map<string, CanonicalRecord<TJson>[]>();
	for (const current of canonicalRecords) {
		const group = recordsById.get(current.record.id);
		if (group === undefined) recordsById.set(current.record.id, [current]);
		else {
			group.push(current);
			duplicateRecordIds.add(current.record.id);
		}
	}
	for (const recordId of [...duplicateRecordIds].sort()) {
		const group = recordsById.get(recordId) ?? [];
		for (const _current of group) {
			addExclusion(diagnostics, "duplicate-record");
			addAudit(diagnostics, {
				action: "excluded",
				reason: "duplicate-record",
			});
		}
		addIssue(diagnostics, "duplicate-record");
	}

	const requestIdentity = agenticMemoryRecordUseRequestIdentity(request);
	const validDecisions: ValidDecision[] = [];
	const invalidClaims = new Map<string, DecisionClaim[]>();
	let invalidDecisions = 0;
	for (let index = 0; index < inputDecisions; index += 1) {
		if (!Object.hasOwn(decisionsValue, index)) {
			invalidDecisions += 1;
			addDecisionFault(diagnostics, "invalid-decision");
			continue;
		}
		const raw = decisionsValue[index];
		const claim = decisionClaim(raw);
		try {
			validDecisions.push({
				decision: assertAgenticMemoryRecordUseDecision(raw),
				inputIndex: index,
			});
		} catch {
			invalidDecisions += 1;
			addDecisionFault(diagnostics, "invalid-decision");
			if (claim !== undefined) {
				const coordinate = decisionCoordinate(claim.requestKey, claim.recordId, claim.recordKey);
				const claims = invalidClaims.get(coordinate);
				if (claims === undefined) invalidClaims.set(coordinate, [claim]);
				else claims.push(claim);
			}
		}
	}
	validDecisions.sort(compareValidDecisions);

	const exact = new Map<string, ValidDecision[]>();
	const anomalyByRecordId = new Map<string, Set<AgenticMemoryRecordUseReasonCode>>();
	for (const current of validDecisions) {
		const decision = current.decision;
		const recordGroup = recordsById.get(decision.recordId);
		if (recordGroup === undefined) {
			addExclusion(diagnostics, "orphan-decision");
			addIssue(diagnostics, "orphan-decision");
			addAudit(diagnostics, {
				action: "excluded",
				reason: "orphan-decision",
			});
			continue;
		}
		if (decision.requestIdentity.key !== requestIdentity.key) {
			addRecordAnomaly(anomalyByRecordId, decision.recordId, "request-mismatch");
			continue;
		}
		const matchingMaterial = recordGroup.some(
			(record) => record.identity.key === decision.recordIdentity.key,
		);
		if (!matchingMaterial) {
			addRecordAnomaly(anomalyByRecordId, decision.recordId, "stale-record");
			continue;
		}
		const coordinate = decisionCoordinate(
			decision.requestIdentity.key,
			decision.recordId,
			decision.recordIdentity.key,
		);
		const matches = exact.get(coordinate);
		if (matches === undefined) exact.set(coordinate, [current]);
		else matches.push(current);
	}

	const allowedRecords: AgenticMemoryRecord<TJson>[] = [];
	let deniedRecords = 0;
	let excludedRecords = invalidRecords;
	for (const current of canonicalRecords) {
		if (duplicateRecordIds.has(current.record.id)) {
			excludedRecords += 1;
			continue;
		}
		const coordinate = decisionCoordinate(
			requestIdentity.key,
			current.record.id,
			current.identity.key,
		);
		const matches = exact.get(coordinate) ?? [];
		const malformedClaimCount = invalidClaims.get(coordinate)?.length ?? 0;
		if (malformedClaimCount > 0) {
			excludedRecords += 1;
			addExclusion(diagnostics, "invalid-decision");
			addAudit(diagnostics, {
				action: "excluded",
				reason: "invalid-decision",
			});
			continue;
		}
		const anomalies = anomalyByRecordId.get(current.record.id);
		if (anomalies !== undefined && anomalies.size > 0) {
			excludedRecords += 1;
			const reason = anomalies.has("request-mismatch") ? "request-mismatch" : "stale-record";
			addExclusion(diagnostics, reason);
			addIssue(diagnostics, reason);
			addAudit(diagnostics, {
				action: "excluded",
				reason,
			});
			continue;
		}
		if (matches.length > 1) {
			excludedRecords += 1;
			const states = new Set(matches.map((match) => match.decision.state));
			const reason = states.size > 1 ? "ambiguous-decision" : "duplicate-decision";
			addExclusion(diagnostics, reason);
			addIssue(diagnostics, reason);
			addAudit(diagnostics, {
				action: "excluded",
				reason,
			});
			continue;
		}
		const match = matches[0];
		if (match === undefined) {
			excludedRecords += 1;
			const reason = "missing-decision";
			addExclusion(diagnostics, reason);
			addIssue(diagnostics, reason);
			addAudit(diagnostics, {
				action: "excluded",
				reason,
			});
			continue;
		}
		if (match.decision.state === "denied") {
			deniedRecords += 1;
			excludedRecords += 1;
			addExclusion(diagnostics, "denied");
			addAudit(diagnostics, {
				action: "denied",
				reason: "denied",
			});
			continue;
		}
		allowedRecords.push(current.record);
		addAudit(diagnostics, {
			action: "allowed",
		});
	}

	if (diagnostics.issues.length > 0 && allowedRecords.length > 0) {
		for (const _record of allowedRecords) {
			excludedRecords += 1;
			addExclusion(diagnostics, "evaluation-invalid");
			addAudit(diagnostics, {
				action: "excluded",
				reason: "evaluation-invalid",
			});
		}
		for (let index = diagnostics.audit.length - 1; index >= 0; index -= 1) {
			const entry = diagnostics.audit[index];
			if (entry?.action === "allowed") {
				diagnostics.audit.splice(index, 1);
			}
		}
		allowedRecords.length = 0;
	}
	allowedRecords.sort((left, right) => compareText(left.id, right.id));
	return finishSnapshot<TJson>({
		evaluation,
		inputRecords,
		validRecords: canonicalRecords.length,
		invalidRecords,
		inputDecisions,
		validDecisions: validDecisions.length,
		invalidDecisions,
		allowedRecords,
		deniedRecords,
		excludedRecords,
		diagnostics,
	});
}

/**
 * Create one real exact-use lifecycle for a bounded stream of complete inputs (D789).
 *
 * Every projection preserves scoped occurrence identity. Governed consumers must
 * correlate their query with this gate's allowedRecords occurrence, never raw records.
 * Permission errors are per-use invalid DATA. Malformed/conflicting occurrence
 * identity rejects the invocation synchronously; an upstream ERROR terminates
 * the lifecycle and all projections. Neither failure permits continued use of a
 * previously emitted authorization as a new occurrence's authority.
 *
 * @param graph - Graph owning the gate and its projections.
 * @param opts - Complete occurrences, retention bound and optional stable name.
 * @returns Snapshot and declared, identity-preserving authorization projections.
 * @category solutions
 * @example
 * ```ts
 * import { agenticMemoryRecordUseGateBundle } from "@graphrefly/ts/solutions/agentic-memory";
 * // completeUses: Node<AgenticMemoryRecordUseOccurrence>
 * const gate = agenticMemoryRecordUseGateBundle(graph, {
 *   occurrences: completeUses,
 *   maxOccurrences: 30,
 * });
 * // Match the query to the exact gate.allowedRecords occurrence before retrieval.
 * ```
 */
export function agenticMemoryRecordUseGateBundle<TJson extends StrictJsonValue = StrictJsonValue>(
	graph: Graph,
	opts: AgenticMemoryRecordUseGateBundleOptions<TJson>,
): AgenticMemoryRecordUseGateBundle<TJson> {
	const name = opts.name ?? "agenticMemoryRecordUseGate";
	const snapshot = solutionOccurrenceProjection(graph, opts.occurrences, {
		name: `${name}/snapshot`,
		factory: "agenticMemoryRecordUseGate",
		maxOccurrences: opts.maxOccurrences,
		project: (value) => {
			try {
				const fields = Object.getOwnPropertyDescriptors(value);
				for (const name of ["records", "request", "decisions"])
					if (fields[name] === undefined || !Object.hasOwn(fields[name]!, "value"))
						return globalFailure<TJson>("invalid-input", 1, 0, 0);
				return projectAgenticMemoryRecordUseGate<TJson>(
					fields.records!.value,
					fields.request!.value,
					fields.decisions!.value,
				);
			} catch {
				return globalFailure<TJson>("invalid-input", 1, 0, 0);
			}
		},
		// Invalid permission input has no canonical authority identity. Fingerprint
		// its bounded invalid result, never inspect rejected getters/Proxy contents.
		// A prior valid input cannot collide with this tagged invalid representation.
		identity: (value, snapshot) =>
			snapshot.status.state === "invalid"
				? { kind: "invalid-permission-input", snapshot }
				: { kind: "exact-permission-input", value },
	});
	const project = <T>(
		suffix: string,
		factory: string,
		select: (value: AgenticMemoryRecordUseSnapshot<TJson>) => T,
	) =>
		graph.node<SolutionOccurrence<T>>(
			[snapshot],
			(ctx) => {
				const outputs = (depBatch(ctx, 0) ?? []).map((raw) => {
					const occurrence = raw as SolutionOccurrence<AgenticMemoryRecordUseSnapshot<TJson>>;
					return [
						"DATA",
						Object.freeze({ ...occurrence, value: select(occurrence.value) }),
					] as const;
				});
				if (outputs.length > 0) ctx.down(outputs);
			},
			{ name: `${name}/${suffix}`, factory },
		);
	return {
		input: opts.occurrences,
		snapshot,
		allowedRecords: project(
			"allowedRecords",
			"agenticMemoryRecordUseAllowedRecords",
			(fact) => fact.allowedRecords,
		),
		exclusions: project(
			"exclusions",
			"agenticMemoryRecordUseExclusions",
			(fact) => fact.exclusions,
		),
		status: project("status", "agenticMemoryRecordUseStatus", (fact) => fact.status),
		issues: project("issues", "agenticMemoryRecordUseIssues", (fact) => fact.issues),
		audit: project("audit", "agenticMemoryRecordUseAudit", (fact) => fact.audit),
		cursor: project("cursor", "agenticMemoryRecordUseCursor", (fact) => fact.cursor),
	};
}

function canonicalCoordinate(value: unknown, label: string): AgenticMemoryRecordUseCoordinate {
	assertDataObject(value, label);
	assertExactFields(value, ["id", "kind"], label);
	if (!isNonEmptyString(value.kind) || !isNonEmptyString(value.id)) {
		throw new TypeError(`${label} kind and id must be non-empty strings`);
	}
	return Object.freeze({ kind: value.kind, id: value.id });
}

function canonicalRevisionCoordinates(
	value: unknown,
	label: string,
): readonly AgenticMemoryRecordUseRevisionCoordinate[] {
	if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
	const length = observedArrayLength(value);
	if (length === undefined) throw new TypeError(`${label} length is not canonical`);
	if (
		length > AGENTIC_MEMORY_RECORD_USE_V1_LIMITS.coordinatesPerRequestField ||
		dataArrayContainerErrors(value, label, length).length > 0
	) {
		throw new TypeError(`${label} is not a bounded dense data array`);
	}
	const coordinates: AgenticMemoryRecordUseRevisionCoordinate[] = [];
	const seen = new Set<string>();
	for (let index = 0; index < length; index += 1) {
		if (!Object.hasOwn(value, index)) throw new TypeError(`${label} must be dense`);
		const raw = value[index];
		assertDataObject(raw, `${label} entry`);
		assertExactFields(raw, ["id", "kind", "revision"], `${label} entry`);
		if (
			!isNonEmptyString(raw.kind) ||
			!isNonEmptyString(raw.id) ||
			!isNonEmptyString(raw.revision)
		) {
			throw new TypeError(`${label} entry fields must be non-empty strings`);
		}
		const coordinate = Object.freeze({
			kind: raw.kind,
			id: raw.id,
			revision: raw.revision,
		});
		const key = canonicalTupleKey([coordinate.kind, coordinate.id, coordinate.revision]);
		if (seen.has(key)) throw new TypeError(`${label} contains a duplicate coordinate`);
		seen.add(key);
		coordinates.push(coordinate);
	}
	coordinates.sort((left, right) =>
		compareText(
			canonicalTupleKey([left.kind, left.id, left.revision]),
			canonicalTupleKey([right.kind, right.id, right.revision]),
		),
	);
	return Object.freeze(coordinates);
}

function canonicalRecord<TJson extends StrictJsonValue>(
	value: AgenticMemoryRecord<TJson>,
	inputIndex: number,
): CanonicalRecord<TJson> {
	assertRecordUseRecordDataContainers(value);
	const codec = agenticMemoryRecordCodec<TJson>();
	const record = codec.decode(codec.encode(value));
	const frame = agenticMemoryRecordFrame(record);
	const identity = Object.freeze({
		version: AGENTIC_MEMORY_RECORD_USE_VERSION,
		algorithm: AGENTIC_MEMORY_RECORD_USE_RECORD_IDENTITY_ALGORITHM,
		key: strictJsonText({
			format: RECORD_IDENTITY_FRAME_FORMAT,
			version: AGENTIC_MEMORY_RECORD_USE_VERSION,
			record: frame,
		}),
	});
	return Object.freeze({ record, identity, inputIndex });
}

function assertRecordUseRecordDataContainers(value: unknown): void {
	assertDataObject(value, "record-use current record");
	const fragment = value.fragment;
	assertDataObject(fragment, "record-use current record fragment");
	if (value.scope !== undefined) {
		assertDataObject(value.scope, "record-use current record scope");
	}
	assertDataArray(fragment.tags, "record-use current record fragment tags");
	assertDataArray(fragment.sources, "record-use current record fragment sources");
	if (fragment.embedding !== undefined) {
		assertDataArray(fragment.embedding, "record-use current record fragment embedding");
	}
	strictCanonicalJsonBytes(fragment.payload);
}

function assertDataArray(value: unknown, label: string): asserts value is readonly unknown[] {
	if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
	const length = observedArrayLength(value);
	if (length === undefined || dataArrayContainerErrors(value, label, length).length > 0) {
		throw new TypeError(`${label} must be a dense data array`);
	}
}

function assertRequestIdentity(value: unknown): AgenticMemoryRecordUseRequestIdentity {
	assertDataObject(value, "record-use request identity");
	assertExactFields(value, ["algorithm", "key", "version"], "record-use request identity");
	if (value.version !== AGENTIC_MEMORY_RECORD_USE_VERSION) {
		throw new TypeError("record-use request identity has an invalid version");
	}
	if (value.algorithm !== AGENTIC_MEMORY_RECORD_USE_REQUEST_IDENTITY_ALGORITHM) {
		throw new TypeError("record-use request identity has an invalid algorithm");
	}
	if (!isNonEmptyString(value.key)) {
		throw new TypeError("record-use request identity key must be a non-empty string");
	}
	const decoded = strictJsonCodec.decode(textEncoder.encode(value.key));
	assertDataObject(decoded, "record-use request identity frame");
	assertExactFields(decoded, ["format", "request", "version"], "record-use request identity frame");
	if (
		decoded.format !== REQUEST_IDENTITY_FRAME_FORMAT ||
		decoded.version !== AGENTIC_MEMORY_RECORD_USE_VERSION
	) {
		throw new TypeError("record-use request identity frame is invalid");
	}
	const canonical = agenticMemoryRecordUseRequestIdentity(decoded.request);
	if (canonical.key !== value.key) {
		throw new TypeError("record-use request identity is not canonical");
	}
	return canonical;
}

function assertRecordIdentity(value: unknown): {
	readonly identity: AgenticMemoryRecordUseRecordIdentity;
	readonly recordId: string;
} {
	assertDataObject(value, "record-use record identity");
	assertExactFields(value, ["algorithm", "key", "version"], "record-use record identity");
	if (value.version !== AGENTIC_MEMORY_RECORD_USE_VERSION) {
		throw new TypeError("record-use record identity has an invalid version");
	}
	if (value.algorithm !== AGENTIC_MEMORY_RECORD_USE_RECORD_IDENTITY_ALGORITHM) {
		throw new TypeError("record-use record identity has an invalid algorithm");
	}
	if (!isNonEmptyString(value.key)) {
		throw new TypeError("record-use record identity key must be a non-empty string");
	}
	const decoded = strictJsonCodec.decode(textEncoder.encode(value.key));
	assertDataObject(decoded, "record-use record identity frame");
	assertExactFields(decoded, ["format", "record", "version"], "record-use record identity frame");
	if (
		decoded.format !== RECORD_IDENTITY_FRAME_FORMAT ||
		decoded.version !== AGENTIC_MEMORY_RECORD_USE_VERSION
	) {
		throw new TypeError("record-use record identity frame is invalid");
	}
	const frame = assertAgenticMemoryRecordFrame<StrictJsonValue>(decoded.record);
	const canonicalKey = strictJsonText({
		format: RECORD_IDENTITY_FRAME_FORMAT,
		version: AGENTIC_MEMORY_RECORD_USE_VERSION,
		record: frame,
	});
	if (canonicalKey !== value.key) {
		throw new TypeError("record-use record identity is not canonical");
	}
	return Object.freeze({
		identity: Object.freeze({
			version: AGENTIC_MEMORY_RECORD_USE_VERSION,
			algorithm: AGENTIC_MEMORY_RECORD_USE_RECORD_IDENTITY_ALGORITHM,
			key: value.key,
		}),
		recordId: frame.record.id,
	});
}

function decisionClaim(value: unknown): DecisionClaim | undefined {
	if (!isPlainRecord(value) || dataRecordContainerErrors(value, "decision claim").length > 0) {
		return undefined;
	}
	const requestKey = identityClaimKey(
		Object.getOwnPropertyDescriptor(value, "requestIdentity")?.value,
		AGENTIC_MEMORY_RECORD_USE_REQUEST_IDENTITY_ALGORITHM,
	);
	const recordKey = identityClaimKey(
		Object.getOwnPropertyDescriptor(value, "recordIdentity")?.value,
		AGENTIC_MEMORY_RECORD_USE_RECORD_IDENTITY_ALGORITHM,
	);
	const recordId = safeDataString(value, "recordId");
	if (requestKey === undefined || recordKey === undefined || recordId === undefined) {
		return undefined;
	}
	return { requestKey, recordKey, recordId };
}

function identityClaimKey(value: unknown, algorithm: string): string | undefined {
	if (!isPlainRecord(value) || dataRecordContainerErrors(value, "identity claim").length > 0) {
		return undefined;
	}
	const algorithmValue = safeDataString(value, "algorithm");
	const key = safeDataString(value, "key");
	return algorithmValue === algorithm ? key : undefined;
}

function globalFailure<TJson extends StrictJsonValue>(
	reason: Extract<
		AgenticMemoryRecordUseReasonCode,
		"input-overflow" | "invalid-input" | "invalid-request" | "invalid-record" | "invalid-decision"
	>,
	evaluation: number,
	inputRecords: number,
	inputDecisions: number,
): AgenticMemoryRecordUseSnapshot<TJson> {
	const diagnostics = emptyDiagnostics();
	addIssue(diagnostics, reason);
	for (
		let index = 0;
		index < Math.min(inputRecords, AGENTIC_MEMORY_RECORD_USE_V1_LIMITS.exclusions);
		index += 1
	) {
		addExclusion(diagnostics, reason);
	}
	for (
		let index = 0;
		index < Math.min(inputRecords, AGENTIC_MEMORY_RECORD_USE_V1_LIMITS.audit);
		index += 1
	) {
		addAudit(diagnostics, { action: "invalid-input", reason });
	}
	const missingExclusionTotals = Math.max(0, inputRecords - diagnostics.exclusions.length);
	diagnostics.reasonCounts[reason] += missingExclusionTotals;
	if (inputRecords === 0) diagnostics.reasonCounts[reason] += 1;
	return finishSnapshot<TJson>({
		evaluation,
		inputRecords,
		validRecords: 0,
		invalidRecords: 0,
		unevaluatedRecords: inputRecords,
		inputDecisions,
		validDecisions: 0,
		invalidDecisions: 0,
		unevaluatedDecisions: inputDecisions,
		allowedRecords: [],
		deniedRecords: 0,
		excludedRecords: inputRecords,
		diagnostics,
		exclusionTotalOverride: inputRecords,
		auditTotalOverride: inputRecords,
	});
}

function finishSnapshot<TJson extends StrictJsonValue>(input: {
	readonly evaluation: number;
	readonly inputRecords: number;
	readonly validRecords: number;
	readonly invalidRecords: number;
	readonly unevaluatedRecords?: number;
	readonly inputDecisions: number;
	readonly validDecisions: number;
	readonly invalidDecisions: number;
	readonly unevaluatedDecisions?: number;
	readonly allowedRecords: readonly AgenticMemoryRecord<TJson>[];
	readonly deniedRecords: number;
	readonly excludedRecords: number;
	readonly diagnostics: EvaluationDiagnostics;
	readonly exclusionTotalOverride?: number;
	readonly auditTotalOverride?: number;
}): AgenticMemoryRecordUseSnapshot<TJson> {
	const exclusions = bounded(
		input.diagnostics.exclusions,
		AGENTIC_MEMORY_RECORD_USE_V1_LIMITS.exclusions,
		compareExclusions,
		input.exclusionTotalOverride,
	);
	const issues = bounded(
		input.diagnostics.issues,
		AGENTIC_MEMORY_RECORD_USE_V1_LIMITS.issues,
		compareIssues,
	);
	const audit = bounded(
		input.diagnostics.audit,
		AGENTIC_MEMORY_RECORD_USE_V1_LIMITS.audit,
		compareAudit,
		input.auditTotalOverride,
	);
	const cursor: AgenticMemoryRecordUseCursor = Object.freeze({
		kind: "agentic-memory-record-use-cursor",
		version: AGENTIC_MEMORY_RECORD_USE_VERSION,
		evaluation: input.evaluation,
		inputRecords: input.inputRecords,
		validRecords: input.validRecords,
		invalidRecords: input.invalidRecords,
		unevaluatedRecords: input.unevaluatedRecords ?? 0,
		inputDecisions: input.inputDecisions,
		validDecisions: input.validDecisions,
		invalidDecisions: input.invalidDecisions,
		unevaluatedDecisions: input.unevaluatedDecisions ?? 0,
		allowedRecords: input.allowedRecords.length,
		deniedRecords: input.deniedRecords,
		excludedRecords: input.excludedRecords,
		reasonCounts: Object.freeze({ ...input.diagnostics.reasonCounts }),
		exclusions: exclusions.cursor,
		issues: issues.cursor,
		audit: audit.cursor,
	});
	return Object.freeze({
		format: AGENTIC_MEMORY_RECORD_USE_SNAPSHOT_FORMAT,
		version: AGENTIC_MEMORY_RECORD_USE_VERSION,
		allowedRecords: Object.freeze([...input.allowedRecords]),
		exclusions: exclusions.values,
		status: Object.freeze({
			kind: "agentic-memory-record-use-status",
			version: AGENTIC_MEMORY_RECORD_USE_VERSION,
			state: input.diagnostics.issues.length === 0 ? "ready" : "invalid",
			evaluated: true,
		}),
		issues: issues.values,
		audit: audit.values,
		cursor,
	});
}

function emptyDiagnostics(): EvaluationDiagnostics {
	return {
		exclusions: [],
		issues: [],
		audit: [],
		reasonCounts: Object.fromEntries(REASON_ORDER.map((reason) => [reason, 0])) as Record<
			AgenticMemoryRecordUseReasonCode,
			number
		>,
	};
}

function addRecordFault(
	diagnostics: EvaluationDiagnostics,
	reason: Extract<AgenticMemoryRecordUseReasonCode, "invalid-record" | "duplicate-record">,
): void {
	addExclusion(diagnostics, reason);
	addIssue(diagnostics, reason);
	addAudit(diagnostics, { action: "invalid-input", reason });
}

function addDecisionFault(diagnostics: EvaluationDiagnostics, reason: "invalid-decision"): void {
	addExclusion(diagnostics, reason);
	addIssue(diagnostics, reason);
	addAudit(diagnostics, { action: "invalid-input", reason });
}

function addExclusion(
	diagnostics: EvaluationDiagnostics,
	reason: AgenticMemoryRecordUseReasonCode,
): void {
	diagnostics.exclusions.push(
		Object.freeze({
			kind: "agentic-memory-record-use-exclusion",
			version: AGENTIC_MEMORY_RECORD_USE_VERSION,
			reason,
		}),
	);
	diagnostics.reasonCounts[reason] += 1;
}

function addIssue(
	diagnostics: EvaluationDiagnostics,
	reason: AgenticMemoryRecordUseReasonCode,
): void {
	diagnostics.issues.push(
		Object.freeze({
			kind: "issue",
			version: AGENTIC_MEMORY_RECORD_USE_VERSION,
			code: reason,
			message: REASON_MESSAGE[reason],
			severity: "error",
			source: "agentic-memory-record-use-gate",
		}),
	);
}

function addAudit(
	diagnostics: EvaluationDiagnostics,
	entry: Omit<AgenticMemoryRecordUseAuditEntry, "kind" | "version">,
): void {
	diagnostics.audit.push(
		Object.freeze({
			kind: "agentic-memory-record-use-audit",
			version: AGENTIC_MEMORY_RECORD_USE_VERSION,
			...entry,
		}),
	);
}

function addRecordAnomaly(
	anomalies: Map<string, Set<AgenticMemoryRecordUseReasonCode>>,
	recordId: string,
	reason: "request-mismatch" | "stale-record",
): void {
	const current = anomalies.get(recordId);
	if (current === undefined) anomalies.set(recordId, new Set([reason]));
	else current.add(reason);
}

function bounded<T>(
	values: readonly T[],
	limit: number,
	compare: (left: T, right: T) => number,
	totalOverride?: number,
): {
	readonly values: readonly T[];
	readonly cursor: AgenticMemoryRecordUseBoundedCollectionCursor;
} {
	const sorted = [...values].sort(compare);
	const total = totalOverride ?? sorted.length;
	const emitted = Math.min(sorted.length, limit);
	return Object.freeze({
		values: Object.freeze(sorted.slice(0, emitted)),
		cursor: Object.freeze({
			kind: "agentic-memory-record-use-bounded-collection-cursor",
			version: AGENTIC_MEMORY_RECORD_USE_VERSION,
			total,
			emitted,
			truncated: total > emitted,
		}),
	});
}

function decisionCoordinate(requestKey: string, recordId: string, recordKey: string): string {
	return canonicalTupleKey([requestKey, recordId, recordKey]);
}

function strictJsonText(value: unknown): string {
	return textDecoder.decode(strictCanonicalJsonBytes(value));
}

function assertDataObject(value: unknown, label: string): asserts value is Record<string, unknown> {
	if (!isPlainRecord(value) || dataRecordContainerErrors(value, label).length > 0) {
		throw new TypeError(`${label} must be a plain data object`);
	}
}

function assertExactFields(
	value: Record<string, unknown>,
	fields: readonly string[],
	label: string,
): void {
	const expected = [...fields].sort();
	const actual = Object.keys(value).sort();
	if (
		expected.length !== actual.length ||
		expected.some((field, index) => field !== actual[index])
	) {
		throw new TypeError(`${label} has unexpected or missing fields`);
	}
}

function safeDataString(value: unknown, key: string): string | undefined {
	if (!isPlainRecord(value)) return undefined;
	const descriptor = Object.getOwnPropertyDescriptor(value, key);
	return descriptor !== undefined &&
		"value" in descriptor &&
		typeof descriptor.value === "string" &&
		descriptor.value.length > 0
		? descriptor.value
		: undefined;
}

function observedArrayLength(value: readonly unknown[]): number | undefined {
	const length = safeArrayLength(value);
	return typeof length === "number" &&
		Number.isSafeInteger(length) &&
		length >= 0 &&
		!Object.is(length, -0)
		? length
		: undefined;
}

function arrayLength(value: unknown): number | undefined {
	if (!Array.isArray(value)) return 0;
	return observedArrayLength(value);
}

function safeInputLength(value: unknown): number {
	try {
		return arrayLength(value) ?? 0;
	} catch {
		return 0;
	}
}

function compareCanonicalRecords<TJson extends StrictJsonValue>(
	left: CanonicalRecord<TJson>,
	right: CanonicalRecord<TJson>,
): number {
	return (
		compareText(left.record.id, right.record.id) ||
		compareText(left.identity.key, right.identity.key) ||
		left.inputIndex - right.inputIndex
	);
}

function compareValidDecisions(left: ValidDecision, right: ValidDecision): number {
	return (
		compareText(left.decision.recordId, right.decision.recordId) ||
		compareText(left.decision.requestIdentity.key, right.decision.requestIdentity.key) ||
		compareText(left.decision.recordIdentity.key, right.decision.recordIdentity.key) ||
		compareText(left.decision.state, right.decision.state) ||
		compareText(left.decision.decisionId, right.decision.decisionId) ||
		left.inputIndex - right.inputIndex
	);
}

function compareExclusions(
	left: AgenticMemoryRecordUseExclusion,
	right: AgenticMemoryRecordUseExclusion,
): number {
	return reasonIndex(left.reason) - reasonIndex(right.reason);
}

function compareIssues(
	left: AgenticMemoryRecordUseIssue,
	right: AgenticMemoryRecordUseIssue,
): number {
	return reasonIndex(left.code) - reasonIndex(right.code);
}

function compareAudit(
	left: AgenticMemoryRecordUseAuditEntry,
	right: AgenticMemoryRecordUseAuditEntry,
): number {
	return (
		compareText(left.action, right.action) || reasonIndex(left.reason) - reasonIndex(right.reason)
	);
}

function reasonIndex(reason: AgenticMemoryRecordUseReasonCode | undefined): number {
	return reason === undefined ? -1 : REASON_ORDER.indexOf(reason);
}

function compareText(left: string, right: string): number {
	return left < right ? -1 : left > right ? 1 : 0;
}

import { depLatest } from "../../ctx/types.js";
import type { Graph } from "../../graph/graph.js";
import type { FactId } from "../../patterns/semantic-memory.js";
import { solutionProjection } from "./projection.js";
import {
	agenticStatusState,
	errorMessage,
	freezeError,
	isAgenticMemoryPersistenceLevel,
	isDenseArrayOf,
	isNonEmptyString,
	isPlainRecord,
	safeArrayLength,
	validateAndProjectRecords,
} from "./shared.js";
import type {
	AgenticMemoryConsolidationRequest,
	AgenticMemoryError,
	AgenticMemoryPersistenceLevel,
	AgenticMemoryRecord,
	AgenticMemoryRetentionBundle,
	AgenticMemoryRetentionBundleOptions,
	AgenticMemoryRetentionCommand,
	AgenticMemoryRetentionCursor,
	AgenticMemoryRetentionError,
	AgenticMemoryRetentionSnapshot,
	AgenticMemoryRetentionStatus,
} from "./types.js";

/**
 * Creates an agentic memory retention bundle.
 *
 * @param graph - Graph that owns the created nodes or projector.
 * @param opts - Options that configure the helper.
 * @returns A bundle of graph-visible nodes for the recipe.
 * @category solutions
 * @example
 * ```ts
 * import { agenticMemoryRetentionBundle } from "@graphrefly/ts/solutions/agentic-memory";
 * ```
 */
export function agenticMemoryRetentionBundle<T = unknown>(
	graph: Graph,
	opts: AgenticMemoryRetentionBundleOptions<T>,
): AgenticMemoryRetentionBundle<T> {
	const name = opts.name ?? "agenticMemoryRetention";
	const projection = graph.node<AgenticMemoryRetentionSnapshot<T>>(
		[opts.records, opts.commands],
		(ctx) => {
			const state =
				ctx.state.get<{ evaluation: number }>() ??
				({ evaluation: 0 } satisfies { evaluation: number });
			state.evaluation += 1;
			const recordProjection = validateAndProjectRecords<T>(depLatest(ctx, 0));
			const retention = projectRetention<T>(depLatest(ctx, 1), recordProjection.records);
			const cursor: AgenticMemoryRetentionCursor = Object.freeze({
				evaluation: state.evaluation,
				validRecords: recordProjection.records.length,
				validCommands: retention.validCommands,
				invalidCommands: retention.invalidCommands,
				activeRecords: retention.activeRecords.length,
				archivedRecords: retention.archivedRecords.length,
				consolidationRequests: retention.consolidationRequests.length,
			});
			const errors = Object.freeze(
				[...recordProjection.errors.map(retentionErrorFromRecordError), ...retention.errors].map(
					(error) => freezeError({ ...error, cursor }),
				),
			);
			const status: AgenticMemoryRetentionStatus = Object.freeze({
				state: agenticStatusState(errors.length, recordProjection.records.length),
				cursor,
			});
			ctx.state.set(state);
			ctx.down([
				[
					"DATA",
					Object.freeze({
						activeRecords: Object.freeze(retention.activeRecords),
						archivedRecords: Object.freeze(retention.archivedRecords),
						consolidationRequests: Object.freeze(retention.consolidationRequests),
						status,
						errors,
						cursor,
					}),
				],
			]);
		},
		{
			name: `${name}/projection`,
			factory: "agenticMemoryRetention",
			completeWhenDepsComplete: false,
			errorWhenDepsError: false,
		},
	);
	return {
		input: { records: opts.records, commands: opts.commands },
		projection,
		activeRecords: solutionProjection(
			graph,
			projection,
			`${name}/activeRecords`,
			"agenticMemoryRetentionActiveRecords",
			(fact) => fact.activeRecords,
		),
		archivedRecords: solutionProjection(
			graph,
			projection,
			`${name}/archivedRecords`,
			"agenticMemoryRetentionArchivedRecords",
			(fact) => fact.archivedRecords,
		),
		consolidationRequests: solutionProjection(
			graph,
			projection,
			`${name}/consolidationRequests`,
			"agenticMemoryRetentionConsolidationRequests",
			(fact) => fact.consolidationRequests,
		),
		status: solutionProjection(
			graph,
			projection,
			`${name}/status`,
			"agenticMemoryRetentionStatus",
			(fact) => fact.status,
		),
		errors: solutionProjection(
			graph,
			projection,
			`${name}/errors`,
			"agenticMemoryRetentionErrors",
			(fact) => fact.errors,
		),
		cursor: solutionProjection(
			graph,
			projection,
			`${name}/cursor`,
			"agenticMemoryRetentionCursor",
			(fact) => fact.cursor,
		),
	};
}

/**
 * D171 consolidation outcome projection.
 *
 * The bundle does not execute consolidation. External adapters may publish
 * outcome facts, and this projection turns them into visible result/proposal
 * facts for downstream record-creation policy.
 */

function projectRetention<T>(
	value: unknown,
	records: readonly AgenticMemoryRecord<T>[],
): {
	readonly activeRecords: AgenticMemoryRecord<T>[];
	readonly archivedRecords: AgenticMemoryRecord<T>[];
	readonly consolidationRequests: AgenticMemoryConsolidationRequest[];
	readonly errors: Omit<AgenticMemoryRetentionError, "cursor">[];
	readonly validCommands: number;
	readonly invalidCommands: number;
} {
	const byId = new Map(records.map((record) => [record.id, record]));
	const view = new Map(records.map((record) => [record.id, record]));
	const requests: AgenticMemoryConsolidationRequest[] = [];
	const errors: Omit<AgenticMemoryRetentionError, "cursor">[] = [];
	let validCommands = 0;
	let invalidCommands = 0;
	if (!Array.isArray(value)) {
		return {
			activeRecords: records.filter((record) => record.persistenceLevel !== "archived"),
			archivedRecords: records.filter((record) => record.persistenceLevel === "archived"),
			consolidationRequests: requests,
			validCommands,
			invalidCommands: 1,
			errors: [
				{
					code: "invalid-commands-input",
					message: "agenticMemoryRetentionBundle: commands input must be an array",
					command: value,
				},
			],
		};
	}
	const length = safeArrayLength(value);
	if (length === undefined) {
		return {
			activeRecords: records.filter((record) => record.persistenceLevel !== "archived"),
			archivedRecords: records.filter((record) => record.persistenceLevel === "archived"),
			consolidationRequests: requests,
			validCommands,
			invalidCommands: 1,
			errors: [
				{
					code: "invalid-commands-input",
					message: "agenticMemoryRetentionBundle: commands input length could not be read",
					command: value,
				},
			],
		};
	}
	const seenCommands = new Set<FactId>();
	for (let i = 0; i < length; i += 1) {
		let raw: unknown;
		try {
			raw = value[i];
			const result = validateRetentionCommand(raw, i);
			if (result.errors.length > 0 || result.command === undefined) {
				invalidCommands += 1;
				errors.push(...result.errors);
				continue;
			}
			const command = result.command;
			if (seenCommands.has(command.id)) {
				invalidCommands += 1;
				errors.push({
					code: "duplicate-command-id",
					message: "agenticMemoryRetentionBundle: duplicate command id",
					index: i,
					commandId: command.id,
					command: raw,
					validationErrors: [`duplicate command id '${command.id}'`],
				});
				continue;
			}
			const missing = retentionMissingRecords(command, byId);
			if (missing.length > 0) {
				invalidCommands += 1;
				errors.push({
					code: "missing-record-ref",
					message: "agenticMemoryRetentionBundle: command references missing records",
					index: i,
					commandId: command.id,
					recordId: "recordId" in command ? command.recordId : undefined,
					recordIds: Object.freeze(missing),
					command: raw,
					validationErrors: Object.freeze(missing.map((id) => `record '${id}' is not projected`)),
				});
				continue;
			}
			seenCommands.add(command.id);
			validCommands += 1;
			applyRetentionCommand(command, byId, view, requests);
		} catch (error) {
			invalidCommands += 1;
			errors.push({
				code: "invalid-command",
				message: `agenticMemoryRetentionBundle: command access failed: ${errorMessage(error)}`,
				index: i,
				command: raw,
				validationErrors: ["command access failed"],
			});
		}
	}
	const projected = records.map((record) => view.get(record.id) ?? record);
	return {
		activeRecords: projected.filter((record) => record.persistenceLevel !== "archived"),
		archivedRecords: projected.filter((record) => record.persistenceLevel === "archived"),
		consolidationRequests: requests,
		errors,
		validCommands,
		invalidCommands,
	};
}

function validateRetentionCommand(
	value: unknown,
	index: number,
): {
	readonly command?: AgenticMemoryRetentionCommand;
	readonly errors: Omit<AgenticMemoryRetentionError, "cursor">[];
} {
	if (!isPlainRecord(value)) {
		return {
			errors: [
				{
					code: "invalid-command",
					message: "agenticMemoryRetentionBundle: command must be an object",
					index,
					command: value,
				},
			],
		};
	}
	const id = typeof value.id === "string" && value.id.length > 0 ? value.id : undefined;
	const kind = value.kind;
	const errors: string[] = [];
	if (id === undefined) errors.push("command.id must be a non-empty string");
	if (
		kind !== "archive" &&
		kind !== "restore" &&
		kind !== "setPersistenceLevel" &&
		kind !== "requestConsolidation"
	) {
		errors.push("command.kind is invalid");
	}
	if (value.reason !== undefined && typeof value.reason !== "string") {
		errors.push("command.reason must be a string when present");
	}
	if (kind === "archive") {
		if (!isNonEmptyString(value.recordId)) errors.push("command.recordId must be non-empty");
	} else if (kind === "restore") {
		if (!isNonEmptyString(value.recordId)) errors.push("command.recordId must be non-empty");
		if (
			value.persistenceLevel !== undefined &&
			(!isAgenticMemoryPersistenceLevel(value.persistenceLevel) ||
				value.persistenceLevel === "archived")
		) {
			errors.push("restore.persistenceLevel must be a non-archived persistence level when present");
		}
	} else if (kind === "setPersistenceLevel") {
		if (!isNonEmptyString(value.recordId)) errors.push("command.recordId must be non-empty");
		if (!isAgenticMemoryPersistenceLevel(value.persistenceLevel)) {
			errors.push("setPersistenceLevel.persistenceLevel is invalid");
		}
	} else if (kind === "requestConsolidation") {
		if (!isDenseArrayOf(value.recordIds, isNonEmptyString) || value.recordIds.length === 0) {
			errors.push("requestConsolidation.recordIds must be a non-empty string array");
		}
		if (
			value.requestId !== undefined &&
			(typeof value.requestId !== "string" || value.requestId.length === 0)
		) {
			errors.push("requestConsolidation.requestId must be non-empty when present");
		}
	}
	if (errors.length > 0 || id === undefined) {
		return {
			errors: [
				{
					code: "invalid-command",
					message: "agenticMemoryRetentionBundle: command is invalid",
					index,
					commandId: id,
					command: value,
					validationErrors: Object.freeze(errors),
				},
			],
		};
	}
	const base = { id, reason: value.reason as string | undefined };
	if (kind === "archive") {
		return {
			command: Object.freeze({
				...base,
				kind,
				recordId: value.recordId as string,
				...(base.reason === undefined ? {} : { reason: base.reason }),
			}),
			errors: [],
		};
	}
	if (kind === "restore") {
		return {
			command: Object.freeze({
				...base,
				kind,
				recordId: value.recordId as string,
				...(value.persistenceLevel === undefined
					? {}
					: {
							persistenceLevel: value.persistenceLevel as Exclude<
								AgenticMemoryPersistenceLevel,
								"archived"
							>,
						}),
				...(base.reason === undefined ? {} : { reason: base.reason }),
			}),
			errors: [],
		};
	}
	if (kind === "setPersistenceLevel") {
		return {
			command: Object.freeze({
				...base,
				kind,
				recordId: value.recordId as string,
				persistenceLevel: value.persistenceLevel as AgenticMemoryPersistenceLevel,
				...(base.reason === undefined ? {} : { reason: base.reason }),
			}),
			errors: [],
		};
	}
	return {
		command: Object.freeze({
			...base,
			kind: "requestConsolidation",
			recordIds: Object.freeze([...(value.recordIds as readonly string[])]),
			...(value.requestId === undefined ? {} : { requestId: value.requestId as string }),
			...(base.reason === undefined ? {} : { reason: base.reason }),
		}),
		errors: [],
	};
}

function retentionMissingRecords(
	command: AgenticMemoryRetentionCommand,
	records: ReadonlyMap<FactId, AgenticMemoryRecord>,
): readonly FactId[] {
	if ("recordId" in command) return records.has(command.recordId) ? [] : [command.recordId];
	return command.recordIds.filter((recordId) => !records.has(recordId));
}

function applyRetentionCommand<T>(
	command: AgenticMemoryRetentionCommand,
	source: ReadonlyMap<FactId, AgenticMemoryRecord<T>>,
	view: Map<FactId, AgenticMemoryRecord<T>>,
	requests: AgenticMemoryConsolidationRequest[],
): void {
	if (command.kind === "requestConsolidation") {
		requests.push(
			Object.freeze({
				id: command.requestId ?? command.id,
				commandId: command.id,
				recordIds: Object.freeze([...command.recordIds]),
				...(command.reason === undefined ? {} : { reason: command.reason }),
			}),
		);
		return;
	}
	const record = view.get(command.recordId) ?? source.get(command.recordId);
	if (record === undefined) return;
	const persistenceLevel =
		command.kind === "archive"
			? "archived"
			: command.kind === "restore"
				? (command.persistenceLevel ?? nonArchivedLevel(source.get(command.recordId) ?? record))
				: command.persistenceLevel;
	view.set(command.recordId, withPersistenceLevel(record, persistenceLevel));
}

function nonArchivedLevel(
	record: AgenticMemoryRecord,
): Exclude<AgenticMemoryPersistenceLevel, "archived"> {
	return record.persistenceLevel === "archived" ? "session" : record.persistenceLevel;
}

function withPersistenceLevel<T>(
	record: AgenticMemoryRecord<T>,
	persistenceLevel: AgenticMemoryPersistenceLevel,
): AgenticMemoryRecord<T> {
	return Object.freeze({
		...record,
		persistenceLevel,
	});
}

function retentionErrorFromRecordError(
	error: Omit<AgenticMemoryError, "cursor">,
): Omit<AgenticMemoryRetentionError, "cursor"> {
	return {
		...error,
		code: error.code,
	};
}

import {
	cloneStrictJsonObject as cloneJsonStrictJsonObject,
	cloneStrictJsonValue,
	strictJsonDataErrors,
} from "../../json/codec.js";
import type { FactId, MemoryFragment } from "../../patterns/semantic-memory.js";
import { validateMemoryFragment } from "../../patterns/semantic-memory.js";
import type { MemoryRetrievalStatus } from "../../patterns/semantic-memory-graph.js";
import type {
	AgenticMemoryArtifactKind,
	AgenticMemoryContextAttribution,
	AgenticMemoryContextState,
	AgenticMemoryContextTruncation,
	AgenticMemoryError,
	AgenticMemoryFactRef,
	AgenticMemoryKind,
	AgenticMemoryPersistenceLevel,
	AgenticMemoryRecord,
	AgenticMemoryRecordMetadata,
	AgenticMemoryScope,
	AgenticMemoryStatusState,
	StrictJsonValue,
} from "./types.js";

export { strictJsonDataErrors } from "../../json/codec.js";

export function validateAndProjectRecords<T>(value: unknown): {
	readonly records: AgenticMemoryRecord<T>[];
	readonly fragments: MemoryFragment<T>[];
	readonly metadataByFragmentId: Record<FactId, AgenticMemoryRecordMetadata>;
	readonly errors: Omit<AgenticMemoryError, "cursor">[];
	readonly invalidRecordIndexes: Set<number>;
} {
	const records: AgenticMemoryRecord<T>[] = [];
	const fragments: MemoryFragment<T>[] = [];
	const metadataByFragmentId = Object.create(null) as Record<FactId, AgenticMemoryRecordMetadata>;
	const errors: Omit<AgenticMemoryError, "cursor">[] = [];
	const invalidRecordIndexes = new Set<number>();
	const seenRecordIds = new Set<FactId>();
	const seenFragmentIds = new Set<FactId>();
	if (!Array.isArray(value)) {
		errors.push({
			code: "invalid-records-input",
			message: "agenticMemoryBundle: records input must be an array",
			record: value,
		});
		return { records, fragments, metadataByFragmentId, errors, invalidRecordIndexes };
	}
	const length = safeArrayLength(value);
	if (length === undefined) {
		errors.push({
			code: "invalid-records-input",
			message: "agenticMemoryBundle: records input length could not be read",
			record: value,
		});
		return { records, fragments, metadataByFragmentId, errors, invalidRecordIndexes };
	}
	for (let i = 0; i < length; i += 1) {
		let raw: unknown;
		try {
			raw = value[i];
		} catch (error) {
			invalidRecordIndexes.add(i);
			errors.push({
				code: "invalid-record",
				message: `agenticMemoryBundle: record access failed: ${errorMessage(error)}`,
				index: i,
				validationErrors: Object.freeze(["record access failed"]),
			});
			continue;
		}
		const result = validateAndSnapshotRecord<T>(raw, i);
		if (result.errors.length > 0) {
			invalidRecordIndexes.add(i);
			errors.push(...result.errors);
			continue;
		}
		if (result.record === undefined) continue;
		if (seenRecordIds.has(result.record.id)) {
			invalidRecordIndexes.add(i);
			errors.push({
				code: "duplicate-record-id",
				message: "agenticMemoryBundle: duplicate record id",
				index: i,
				recordId: result.record.id,
				record: raw,
				validationErrors: [`duplicate record id '${result.record.id}'`],
			});
			continue;
		}
		if (seenFragmentIds.has(result.record.fragment.id)) {
			invalidRecordIndexes.add(i);
			errors.push({
				code: "duplicate-fragment-id",
				message: "agenticMemoryBundle: duplicate fragment id",
				index: i,
				recordId: result.record.id,
				fragmentId: result.record.fragment.id,
				record: raw,
				validationErrors: [`duplicate fragment id '${result.record.fragment.id}'`],
			});
			continue;
		}
		seenRecordIds.add(result.record.id);
		seenFragmentIds.add(result.record.fragment.id);
		records.push(result.record);
		fragments.push(result.record.fragment);
		metadataByFragmentId[result.record.fragment.id] = recordMetadata(result.record);
	}
	return { records, fragments, metadataByFragmentId, errors, invalidRecordIndexes };
}

export function validateAndSnapshotRecord<T>(
	value: unknown,
	index: number,
): {
	readonly record?: AgenticMemoryRecord<T>;
	readonly errors: Omit<AgenticMemoryError, "cursor">[];
} {
	try {
		return validateAndSnapshotRecordInner<T>(value, index);
	} catch (error) {
		return {
			errors: [
				{
					code: "invalid-record",
					message: `agenticMemoryBundle: record access failed: ${errorMessage(error)}`,
					index,
					record: value,
					validationErrors: Object.freeze(["record access failed"]),
				},
			],
		};
	}
}

export function validateAndSnapshotRecordInner<T>(
	value: unknown,
	index: number,
): {
	readonly record?: AgenticMemoryRecord<T>;
	readonly errors: Omit<AgenticMemoryError, "cursor">[];
} {
	const errors: Omit<AgenticMemoryError, "cursor">[] = [];
	if (typeof value !== "object" || value === null || Array.isArray(value)) {
		return {
			errors: [
				{
					code: "invalid-record",
					message: "agenticMemoryBundle: record must be an object",
					index,
					record: value,
				},
			],
		};
	}
	const record = value as Partial<AgenticMemoryRecord<T>> & Record<string, unknown>;
	const recordId = typeof record.id === "string" ? record.id : undefined;
	if (recordId === undefined || recordId.length === 0) {
		errors.push({
			code: "invalid-record",
			message: "agenticMemoryBundle: record.id must be a non-empty string",
			index,
			record: value,
			validationErrors: ["record.id must be a non-empty string"],
		});
	}
	if (!isAgenticMemoryKind(record.kind)) {
		errors.push({
			code: "invalid-record-kind",
			message: "agenticMemoryBundle: record.kind is invalid",
			index,
			recordId,
			record: value,
			validationErrors: ["kind must be one of working, episodic, semantic, procedural, profile"],
		});
	}
	if (!isAgenticMemoryPersistenceLevel(record.persistenceLevel)) {
		errors.push({
			code: "invalid-persistence-level",
			message: "agenticMemoryBundle: record.persistenceLevel is invalid",
			index,
			recordId,
			record: value,
			validationErrors: [
				"persistenceLevel must be one of turn, session, project, longTerm, permanent, archived",
			],
		});
	}
	if (!isAgenticMemoryArtifactKind(record.artifactKind)) {
		errors.push({
			code: "invalid-artifact-kind",
			message: "agenticMemoryBundle: record.artifactKind is invalid",
			index,
			recordId,
			record: value,
			validationErrors: ["artifactKind must be one of raw, insight, profile, procedure"],
		});
	}
	const scopeValidation = validateScope(record.scope);
	if (!scopeValidation.ok) {
		errors.push({
			code: "invalid-scope",
			message: "agenticMemoryBundle: record.scope is invalid",
			index,
			recordId,
			record: value,
			validationErrors: Object.freeze(scopeValidation.errors),
		});
	}
	const fragmentValidation = validateMemoryFragment(record.fragment);
	if (!fragmentValidation.ok) {
		errors.push({
			code: "invalid-fragment",
			message: "agenticMemoryBundle: record.fragment is invalid",
			index,
			recordId,
			fragmentId:
				typeof record.fragment === "object" &&
				record.fragment !== null &&
				typeof (record.fragment as Partial<MemoryFragment>).id === "string"
					? (record.fragment as Partial<MemoryFragment>).id
					: undefined,
			record: value,
			validationErrors: Object.freeze([...fragmentValidation.errors]),
		});
	}
	const forbiddenFields = [
		"storageTier",
		"storageKey",
		"adapter",
		"collection",
		"collections",
		"ttl",
		"ttlMs",
		"ttlNs",
		"expiresAt",
		"timer",
		"scheduler",
		"schedule",
		"retentionTimer",
		"consolidationSchedule",
		"reflectionSchedule",
		"llm",
		"llmHandle",
		"tool",
		"toolHandle",
		"runner",
		"runnerHandle",
		"restore",
		"hydrate",
		"hydration",
		"graphMutation",
		"protocol",
	] as const;
	const presentForbidden = forbiddenFields.filter((field) => Object.hasOwn(record, field));
	if (presentForbidden.length > 0) {
		errors.push({
			code: "invalid-record",
			message: "agenticMemoryBundle: record contains forbidden runtime/persistence fields",
			index,
			recordId,
			record: value,
			validationErrors: Object.freeze(
				presentForbidden.map((field) => `${field} is not part of AgenticMemoryRecord`),
			),
		});
	}
	if (errors.length > 0) return { errors };
	const scope = scopeValidation.scope;
	const fragment = snapshotFragment(record.fragment as MemoryFragment<T>);
	return {
		record: Object.freeze({
			id: recordId as FactId,
			kind: record.kind as AgenticMemoryKind,
			persistenceLevel: record.persistenceLevel as AgenticMemoryPersistenceLevel,
			artifactKind: record.artifactKind as AgenticMemoryArtifactKind,
			...(scope === undefined ? {} : { scope }),
			fragment,
		}),
		errors,
	};
}

export function snapshotFragment<T>(fragment: MemoryFragment<T>): MemoryFragment<T> {
	return Object.freeze({
		id: fragment.id,
		payload: fragment.payload,
		tNs: fragment.tNs,
		...(fragment.validFrom === undefined ? {} : { validFrom: fragment.validFrom }),
		...(fragment.validTo === undefined ? {} : { validTo: fragment.validTo }),
		confidence: fragment.confidence,
		tags: Object.freeze([...fragment.tags]),
		sources: Object.freeze([...fragment.sources]),
		...(fragment.embedding === undefined
			? {}
			: { embedding: Object.freeze([...fragment.embedding]) }),
		...(fragment.parentFragmentId === undefined
			? {}
			: { parentFragmentId: fragment.parentFragmentId }),
		...(fragment.provenance === undefined ? {} : { provenance: fragment.provenance }),
	});
}

export function recordMetadata(record: AgenticMemoryRecord): AgenticMemoryRecordMetadata {
	return Object.freeze({
		recordId: record.id,
		kind: record.kind,
		persistenceLevel: record.persistenceLevel,
		artifactKind: record.artifactKind,
		...(record.scope === undefined ? {} : { scope: record.scope }),
	});
}

export function validateRecordMetadata(value: unknown): {
	readonly ok: boolean;
	readonly metadata?: AgenticMemoryRecordMetadata;
	readonly errors: readonly string[];
} {
	if (value === undefined) return { ok: true, errors: [] };
	if (!isPlainRecord(value)) {
		return { ok: false, errors: ["record metadata must be an object when present"] };
	}
	const errors: string[] = [];
	for (const key of Object.keys(value)) {
		if (
			key !== "recordId" &&
			key !== "kind" &&
			key !== "persistenceLevel" &&
			key !== "artifactKind" &&
			key !== "scope"
		) {
			errors.push(`record.${key} is not part of AgenticMemoryRecordMetadata`);
		}
	}
	if (!isNonEmptyString(value.recordId)) {
		errors.push("record.recordId must be a non-empty string");
	}
	if (!isAgenticMemoryKind(value.kind)) {
		errors.push("record.kind is invalid");
	}
	if (!isAgenticMemoryPersistenceLevel(value.persistenceLevel)) {
		errors.push("record.persistenceLevel is invalid");
	}
	if (!isAgenticMemoryArtifactKind(value.artifactKind)) {
		errors.push("record.artifactKind is invalid");
	}
	const scopeValidation = validateScope(value.scope);
	if (!scopeValidation.ok) {
		errors.push(...scopeValidation.errors.map((error) => `record.${error}`));
	}
	if (errors.length > 0) return { ok: false, errors };
	return {
		ok: true,
		errors,
		metadata: Object.freeze({
			recordId: value.recordId as FactId,
			kind: value.kind as AgenticMemoryKind,
			persistenceLevel: value.persistenceLevel as AgenticMemoryPersistenceLevel,
			artifactKind: value.artifactKind as AgenticMemoryArtifactKind,
			...(scopeValidation.scope === undefined ? {} : { scope: scopeValidation.scope }),
		}),
	};
}

export function contextState(
	projection: AgenticMemoryStatusState,
	retrieval: MemoryRetrievalStatus["state"],
): AgenticMemoryContextState {
	if (projection === "error" || retrieval === "error") return "error";
	if (projection === "partial" || retrieval === "partial") return "partial";
	return retrieval;
}

export function agenticStatusState(
	errorCount: number,
	validRecords: number,
): AgenticMemoryStatusState {
	if (errorCount > 0 && validRecords === 0) return "error";
	if (errorCount > 0) return "partial";
	return validRecords > 0 ? "ready" : "empty";
}

export function isAgenticMemoryKind(value: unknown): value is AgenticMemoryKind {
	return (
		value === "working" ||
		value === "episodic" ||
		value === "semantic" ||
		value === "procedural" ||
		value === "profile"
	);
}

export function isAgenticMemoryPersistenceLevel(
	value: unknown,
): value is AgenticMemoryPersistenceLevel {
	return (
		value === "turn" ||
		value === "session" ||
		value === "project" ||
		value === "longTerm" ||
		value === "permanent" ||
		value === "archived"
	);
}

export function isAgenticMemoryArtifactKind(value: unknown): value is AgenticMemoryArtifactKind {
	return value === "raw" || value === "insight" || value === "profile" || value === "procedure";
}

export function validateScope(value: unknown): {
	readonly ok: boolean;
	readonly scope?: AgenticMemoryScope;
	readonly errors: readonly string[];
} {
	if (value === undefined) return { ok: true, errors: [] };
	if (typeof value !== "object" || value === null || Array.isArray(value)) {
		return { ok: false, errors: ["scope must be an object when present"] };
	}
	const scope = value as Record<string, unknown>;
	const errors: string[] = [];
	const allowed = new Set(["sessionId", "projectId", "userId", "tenantId"]);
	for (const key of Object.keys(scope)) {
		if (!allowed.has(key)) errors.push(`scope.${key} is not part of AgenticMemoryScope`);
	}
	for (const key of allowed) {
		if (scope[key] !== undefined && (typeof scope[key] !== "string" || scope[key].length === 0)) {
			errors.push(`scope.${key} must be a non-empty string when present`);
		}
	}
	if (errors.length > 0) return { ok: false, errors };
	return {
		ok: true,
		errors,
		scope: Object.freeze({
			...(scope.sessionId === undefined ? {} : { sessionId: scope.sessionId as string }),
			...(scope.projectId === undefined ? {} : { projectId: scope.projectId as string }),
			...(scope.userId === undefined ? {} : { userId: scope.userId as string }),
			...(scope.tenantId === undefined ? {} : { tenantId: scope.tenantId as string }),
		}),
	};
}

export function isPlainRecord(value: unknown): value is Record<string, unknown> {
	return value !== null && typeof value === "object" && !Array.isArray(value);
}

export function validateAgenticMemoryContextAttribution(
	value: unknown,
	opts: {
		readonly fragmentId?: FactId;
		readonly recordId?: FactId;
	} = {},
): {
	readonly ok: boolean;
	readonly attribution?: AgenticMemoryContextAttribution;
	readonly errors: readonly string[];
} {
	if (value === undefined) return { ok: true, errors: [] };
	const containerErrors = dataRecordContainerErrors(value, "attribution");
	if (containerErrors.length > 0) return { ok: false, errors: containerErrors };
	const recordValue = value as Record<string, unknown>;
	const errors: string[] = [];
	errors.push(...forbiddenAgenticMemoryDataFields(recordValue, "attribution"));
	const extra = unexpectedFields(recordValue, [
		"kind",
		"fragmentId",
		"recordId",
		"queryId",
		"rank",
		"score",
		"truncated",
		"truncation",
		"sourceRefs",
		"policyRefs",
		"metadata",
	]);
	errors.push(...extra.map((field) => `attribution.${field} is not part of attribution`));
	if (recordValue.kind !== undefined && recordValue.kind !== "agentic-memory-context-attribution") {
		errors.push("attribution.kind must be agentic-memory-context-attribution when present");
	}
	if (recordValue.fragmentId !== undefined && !isNonEmptyString(recordValue.fragmentId)) {
		errors.push("attribution.fragmentId must be a non-empty string when present");
	}
	if (recordValue.recordId !== undefined && !isNonEmptyString(recordValue.recordId)) {
		errors.push("attribution.recordId must be a non-empty string when present");
	}
	if (recordValue.queryId !== undefined && !isNonEmptyString(recordValue.queryId)) {
		errors.push("attribution.queryId must be a non-empty string when present");
	}
	if (
		recordValue.rank !== undefined &&
		(typeof recordValue.rank !== "number" ||
			!Number.isSafeInteger(recordValue.rank) ||
			recordValue.rank < 1)
	) {
		errors.push("attribution.rank must be a 1-based safe integer when present");
	}
	if (
		recordValue.score !== undefined &&
		(typeof recordValue.score !== "number" || !Number.isFinite(recordValue.score))
	) {
		errors.push("attribution.score must be a finite number when present");
	}
	if (recordValue.truncated !== undefined && typeof recordValue.truncated !== "boolean") {
		errors.push("attribution.truncated must be a boolean when present");
	}
	const truncation = validateContextTruncation(recordValue.truncation);
	if (!truncation.ok) {
		errors.push(...truncation.errors.map((error) => `attribution.${error}`));
	}
	if (recordValue.truncation !== undefined && recordValue.truncated === false) {
		errors.push("attribution.truncation requires attribution.truncated to be true or omitted");
	}
	for (const [field, refs] of [
		["sourceRefs", recordValue.sourceRefs],
		["policyRefs", recordValue.policyRefs],
	] as const) {
		if (refs !== undefined) {
			errors.push(
				...validateAgenticMemoryFactRefs(refs).map((error) => `attribution.${field}: ${error}`),
			);
		}
	}
	if (recordValue.metadata !== undefined && !isStrictJsonObject(recordValue.metadata)) {
		errors.push("attribution.metadata must be a strict JSON object");
	}
	if (
		opts.fragmentId !== undefined &&
		recordValue.fragmentId !== undefined &&
		recordValue.fragmentId !== opts.fragmentId
	) {
		errors.push("attribution.fragmentId must match the containing fragmentId");
	}
	if (
		opts.recordId !== undefined &&
		recordValue.recordId !== undefined &&
		recordValue.recordId !== opts.recordId
	) {
		errors.push("attribution.recordId must match the containing record.recordId");
	}
	if (errors.length > 0) return { ok: false, errors };
	return {
		ok: true,
		errors,
		attribution: Object.freeze({
			...(recordValue.kind === undefined
				? {}
				: { kind: "agentic-memory-context-attribution" as const }),
			...(recordValue.fragmentId === undefined
				? {}
				: { fragmentId: recordValue.fragmentId as FactId }),
			...(recordValue.recordId === undefined ? {} : { recordId: recordValue.recordId as FactId }),
			...(recordValue.queryId === undefined ? {} : { queryId: recordValue.queryId as string }),
			...(recordValue.rank === undefined ? {} : { rank: recordValue.rank as number }),
			...(recordValue.score === undefined ? {} : { score: recordValue.score as number }),
			...(recordValue.truncated === undefined
				? {}
				: { truncated: recordValue.truncated as boolean }),
			...(truncation.truncation === undefined ? {} : { truncation: truncation.truncation }),
			...(recordValue.sourceRefs === undefined
				? {}
				: { sourceRefs: snapshotAgenticMemoryFactRefs(recordValue.sourceRefs) }),
			...(recordValue.policyRefs === undefined
				? {}
				: { policyRefs: snapshotAgenticMemoryFactRefs(recordValue.policyRefs) }),
			...(recordValue.metadata === undefined
				? {}
				: { metadata: cloneStrictJsonObject(recordValue.metadata) }),
		}),
	};
}

export function validateAgenticMemoryFactRefs(value: unknown): readonly string[] {
	if (!Array.isArray(value)) return ["must be an array"];
	const length = safeArrayLength(value);
	if (length === undefined) return ["length could not be read"];
	const arrayContainerErrors = dataArrayContainerErrors(value, "refs", length);
	if (arrayContainerErrors.length > 0) return arrayContainerErrors;
	const errors: string[] = [];
	for (let i = 0; i < length; i += 1) {
		if (!Object.hasOwn(value, i)) {
			errors.push(`[${i}] must be present`);
			continue;
		}
		const ref = value[i];
		if (!isPlainRecord(ref)) {
			errors.push(`[${i}] must be an object`);
			continue;
		}
		const containerErrors = dataRecordContainerErrors(ref, `[${i}]`);
		if (containerErrors.length > 0) {
			errors.push(...containerErrors);
			continue;
		}
		const extraFields = unexpectedFields(ref, ["id", "kind", "metadata"]);
		if (extraFields.length > 0) {
			errors.push(`[${i}] has unexpected fields ${extraFields.join(",")}`);
		}
		if (!isNonEmptyString(ref.kind)) errors.push(`[${i}].kind must be non-empty`);
		if (!isNonEmptyString(ref.id)) errors.push(`[${i}].id must be non-empty`);
		errors.push(...forbiddenAgenticMemoryDataFields(ref, `[${i}]`));
		if (ref.metadata !== undefined && !isStrictJsonObject(ref.metadata)) {
			errors.push(`[${i}].metadata must be a strict JSON object`);
		}
	}
	return errors;
}

export function snapshotAgenticMemoryFactRefs(value: unknown): readonly AgenticMemoryFactRef[] {
	if (!Array.isArray(value)) return Object.freeze([]);
	const refs: AgenticMemoryFactRef[] = [];
	for (let i = 0; i < value.length; i += 1) {
		const ref = value[i] as Record<string, unknown>;
		refs.push(
			Object.freeze({
				kind: ref.kind as string,
				id: ref.id as FactId,
				...(ref.metadata === undefined
					? {}
					: {
							metadata: cloneStrictJsonObject(ref.metadata),
						}),
			}),
		);
	}
	return Object.freeze(refs);
}

export function forbiddenAgenticMemoryDataFields(
	value: Record<string, unknown>,
	label: string,
): readonly string[] {
	const forbidden = [
		"storage",
		"storageHandle",
		"storageTier",
		"storageKey",
		"provider",
		"providerHandle",
		"permission",
		"permissionHandle",
		"permissions",
		"graph",
		"graphHandle",
		"node",
		"nodeHandle",
		"handle",
		"adapter",
		"hydrate",
		"hydration",
		"restore",
		"runtime",
		"runtimeHandle",
		"protocol",
		"patch",
		"merge",
		"WorkItem",
		"workItem",
		"timer",
		"scheduler",
		"llm",
		"tool",
		"runner",
	] as const;
	const errors: string[] = [];
	for (const field of forbidden) {
		if (Object.hasOwn(value, field)) {
			errors.push(`${label}.${field} is not graph-visible DATA`);
		}
	}
	return errors;
}

export function ownKeys(value: Record<string, unknown>): readonly string[] {
	return Object.keys(value).sort();
}

export function assertExactKeys(
	value: Record<string, unknown>,
	expected: readonly string[],
	label: string,
): void {
	const actual = ownKeys(value);
	const want = [...expected].sort();
	if (actual.length !== want.length || actual.some((key, i) => key !== want[i])) {
		throw new TypeError(`${label}: unexpected fields ${actual.join(",")}`);
	}
}

export function assertAgenticMemoryRecordCodecShape(value: unknown): void {
	if (!isPlainRecord(value)) {
		throw new TypeError("agenticMemoryRecordFrame: record must be an object");
	}
	assertNoSymbolKeys(value, "agenticMemoryRecordFrame.record");
	assertExactKeys(
		value,
		value.scope === undefined
			? ["artifactKind", "fragment", "id", "kind", "persistenceLevel"]
			: ["artifactKind", "fragment", "id", "kind", "persistenceLevel", "scope"],
		"agenticMemoryRecordFrame.record",
	);
	const fragment = value.fragment;
	if (!isPlainRecord(fragment)) {
		throw new TypeError("agenticMemoryRecordFrame: fragment must be an object");
	}
	assertNoSymbolKeys(fragment, "agenticMemoryRecordFrame.record.fragment");
	assertExactKeys(
		fragment,
		[
			"id",
			"payload",
			"tNs",
			...(fragment.validFrom === undefined ? [] : ["validFrom"]),
			...(fragment.validTo === undefined ? [] : ["validTo"]),
			"confidence",
			"tags",
			"sources",
			...(fragment.embedding === undefined ? [] : ["embedding"]),
			...(fragment.parentFragmentId === undefined ? [] : ["parentFragmentId"]),
			...(fragment.provenance === undefined ? [] : ["provenance"]),
		],
		"agenticMemoryRecordFrame.record.fragment",
	);
	assertStrictJsonValue(fragment.tags, "record.fragment.tags");
	assertStrictJsonValue(fragment.sources, "record.fragment.sources");
	if (fragment.embedding !== undefined) {
		assertStrictJsonValue(fragment.embedding, "record.fragment.embedding");
	}
	if (value.scope !== undefined) assertScopeFrame(value.scope);
}

export function assertNoSymbolKeys(value: object, label: string): void {
	if (Object.getOwnPropertySymbols(value).length > 0) {
		throw new TypeError(`${label}: unexpected symbol fields`);
	}
}

export function decimalBigIntString(value: bigint, label: string): string {
	const out = value.toString(10);
	if (!/^-?(0|[1-9]\d*)$/.test(out)) {
		throw new TypeError(`${label} must encode as a canonical decimal bigint string`);
	}
	return out;
}

export function parseDecimalBigInt(value: unknown, label: string): bigint {
	if (typeof value !== "string" || !/^(0|-?[1-9]\d*)$/.test(value)) {
		throw new TypeError(`${label} must be a canonical decimal bigint string`);
	}
	return BigInt(value);
}

export function assertStrictJsonValue(value: unknown, label: string): StrictJsonValue {
	try {
		return cloneStrictJsonValue(value, label);
	} catch (error) {
		throw new TypeError(`${label} must be strict JSON: ${errorMessage(error)}`);
	}
}

export function assertScopeFrame(value: unknown): AgenticMemoryScope {
	if (!isPlainRecord(value)) {
		throw new TypeError("agenticMemoryRecordFrame: scope must be an object when present");
	}
	assertStrictJsonValue(value, "record.scope");
	const validation = validateScope(value);
	if (!validation.ok || validation.scope === undefined) {
		throw new TypeError(`agenticMemoryRecordFrame: invalid scope: ${validation.errors.join("; ")}`);
	}
	assertExactKeys(
		value as Record<string, unknown>,
		[
			...((value as Record<string, unknown>).sessionId === undefined ? [] : ["sessionId"]),
			...((value as Record<string, unknown>).projectId === undefined ? [] : ["projectId"]),
			...((value as Record<string, unknown>).userId === undefined ? [] : ["userId"]),
			...((value as Record<string, unknown>).tenantId === undefined ? [] : ["tenantId"]),
		],
		"agenticMemoryRecordFrame.record.scope",
	);
	return validation.scope;
}

export function assertKindValue(value: unknown): AgenticMemoryKind {
	if (!isAgenticMemoryKind(value)) {
		throw new TypeError("agenticMemoryRecordFrame: invalid memory kind");
	}
	return value;
}

export function assertPersistenceLevelValue(value: unknown): AgenticMemoryPersistenceLevel {
	if (!isAgenticMemoryPersistenceLevel(value)) {
		throw new TypeError("agenticMemoryRecordFrame: invalid persistence level");
	}
	return value;
}

export function assertArtifactKindValue(value: unknown): AgenticMemoryArtifactKind {
	if (!isAgenticMemoryArtifactKind(value)) {
		throw new TypeError("agenticMemoryRecordFrame: invalid artifact kind");
	}
	return value;
}

export function assertNonEmptyString(value: unknown, label: string): string {
	if (!isNonEmptyString(value)) throw new TypeError(`${label} must be a non-empty string`);
	return value;
}

export function assertString(value: unknown, label: string): string {
	if (typeof value !== "string") throw new TypeError(`${label} must be a string`);
	return value;
}

export function assertConfidence(value: unknown, label: string): number {
	if (!Number.isFinite(value) || (value as number) < 0 || (value as number) > 1) {
		throw new TypeError(`${label} must be a finite number in [0, 1]`);
	}
	return value as number;
}

export function assertStringArray(value: unknown, label: string): readonly string[] {
	if (!isDenseArrayOf(value, (item): item is string => typeof item === "string")) {
		throw new TypeError(`${label} must be a readonly string array`);
	}
	return Object.freeze([...value]);
}

export function assertFiniteNumberArray(value: unknown, label: string): readonly number[] {
	if (!isDenseArrayOf(value, (item): item is number => Number.isFinite(item))) {
		throw new TypeError(`${label} must be a finite number array`);
	}
	return Object.freeze([...value]);
}

export function isNonEmptyString(value: unknown): value is string {
	return typeof value === "string" && value.length > 0;
}

export function isDenseArrayOf<T>(
	value: unknown,
	predicate: (item: unknown) => item is T,
): value is T[] {
	if (!Array.isArray(value)) return false;
	for (let i = 0; i < value.length; i += 1) {
		if (!Object.hasOwn(value, i) || !predicate(value[i])) return false;
	}
	return true;
}

export function freezeError<T extends { readonly validationErrors?: readonly string[] }>(
	error: T,
): T {
	return Object.freeze({
		...error,
		...(error.validationErrors === undefined
			? {}
			: { validationErrors: Object.freeze([...error.validationErrors]) }),
	}) as T;
}

export function safeArrayLength(value: readonly unknown[]): number | undefined {
	try {
		return value.length;
	} catch {
		return undefined;
	}
}

export function errorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

function validateContextTruncation(value: unknown): {
	readonly ok: boolean;
	readonly truncation?: AgenticMemoryContextTruncation;
	readonly errors: readonly string[];
} {
	if (value === undefined) return { ok: true, errors: [] };
	const containerErrors = dataRecordContainerErrors(value, "truncation");
	if (containerErrors.length > 0) return { ok: false, errors: containerErrors };
	const recordValue = value as Record<string, unknown>;
	const errors: string[] = [];
	errors.push(...forbiddenAgenticMemoryDataFields(recordValue, "truncation"));
	const extra = unexpectedFields(recordValue, [
		"originalChars",
		"packedChars",
		"omittedChars",
		"originalCost",
		"packedCost",
		"omittedCost",
		"reason",
		"metadata",
	]);
	errors.push(...extra.map((field) => `truncation.${field} is not part of truncation`));
	for (const field of ["originalChars", "packedChars", "omittedChars"] as const) {
		const current = recordValue[field];
		if (
			current !== undefined &&
			(typeof current !== "number" || !Number.isSafeInteger(current) || current < 0)
		) {
			errors.push(`truncation.${field} must be a safe integer >= 0 when present`);
		}
	}
	for (const field of ["originalCost", "packedCost", "omittedCost"] as const) {
		const current = recordValue[field];
		if (
			current !== undefined &&
			(typeof current !== "number" || !Number.isFinite(current) || current < 0)
		) {
			errors.push(`truncation.${field} must be a finite number >= 0 when present`);
		}
	}
	if (recordValue.reason !== undefined && typeof recordValue.reason !== "string") {
		errors.push("truncation.reason must be a string when present");
	}
	if (recordValue.metadata !== undefined && !isStrictJsonObject(recordValue.metadata)) {
		errors.push("truncation.metadata must be a strict JSON object");
	}
	if (errors.length > 0) return { ok: false, errors };
	return {
		ok: true,
		errors,
		truncation: Object.freeze({
			...(recordValue.originalChars === undefined
				? {}
				: { originalChars: recordValue.originalChars as number }),
			...(recordValue.packedChars === undefined
				? {}
				: { packedChars: recordValue.packedChars as number }),
			...(recordValue.omittedChars === undefined
				? {}
				: { omittedChars: recordValue.omittedChars as number }),
			...(recordValue.originalCost === undefined
				? {}
				: { originalCost: recordValue.originalCost as number }),
			...(recordValue.packedCost === undefined
				? {}
				: { packedCost: recordValue.packedCost as number }),
			...(recordValue.omittedCost === undefined
				? {}
				: { omittedCost: recordValue.omittedCost as number }),
			...(recordValue.reason === undefined ? {} : { reason: recordValue.reason as string }),
			...(recordValue.metadata === undefined
				? {}
				: { metadata: cloneStrictJsonObject(recordValue.metadata) }),
		}),
	};
}

export function cloneStrictJsonObject(value: unknown): Readonly<Record<string, StrictJsonValue>> {
	return cloneJsonStrictJsonObject(value);
}

export function isStrictJsonObject(value: unknown): boolean {
	if (!isPlainRecord(value)) return false;
	return strictJsonDataErrors(value).length === 0;
}

function unexpectedFields(
	value: Record<string, unknown>,
	expected: readonly string[],
): readonly string[] {
	const allowed = new Set(expected);
	return Object.keys(value)
		.filter((key) => !allowed.has(key))
		.sort();
}

export function dataRecordContainerErrors(value: unknown, label: string): readonly string[] {
	if (!isPlainRecord(value)) return [`${label} must be an object when present`];
	const errors: string[] = [];
	const proto = Object.getPrototypeOf(value);
	if (proto !== Object.prototype && proto !== null) {
		errors.push(`${label} must be a plain data object`);
	}
	if (Object.getOwnPropertySymbols(value).length > 0) {
		errors.push(`${label} must not carry symbol keys`);
	}
	for (const key of Object.getOwnPropertyNames(value)) {
		const descriptor = Object.getOwnPropertyDescriptor(value, key);
		if (descriptor === undefined) continue;
		if ("get" in descriptor || "set" in descriptor) {
			errors.push(`${label}.${key} must be a data property`);
		}
		if (!descriptor.enumerable) {
			errors.push(`${label}.${key} must be enumerable`);
		}
	}
	return errors;
}

export function dataArrayContainerErrors(
	value: readonly unknown[],
	label: string,
	length: number,
): readonly string[] {
	const errors: string[] = [];
	if (Object.getOwnPropertySymbols(value).length > 0) {
		errors.push(`${label} must not carry symbol keys`);
	}
	for (const key of Object.getOwnPropertyNames(value)) {
		const descriptor = Object.getOwnPropertyDescriptor(value, key);
		if (descriptor === undefined) continue;
		const isIndex =
			/^(0|[1-9]\d*)$/.test(key) && Number.isSafeInteger(Number(key)) && Number(key) < length;
		if ("get" in descriptor || "set" in descriptor) {
			errors.push(`${label}.${key} must be a data property`);
		}
		if (key !== "length" && !isIndex) {
			errors.push(`${label}.${key} must be an indexed data property`);
		}
		if (key !== "length" && isIndex && !descriptor.enumerable) {
			errors.push(`${label}.${key} must be enumerable`);
		}
	}
	return errors;
}

