export interface RuntimeState<T>
	extends IdentityState<T>,
		LifecycleState,
		EvidenceState,
		CoordinationState {
	committedEffects?: CommittedEffectsView;
}
export type TransitionOptions = Pick<
	CausalOccurrenceBundleOptions<unknown>,
	| "requiredBranches"
	| "requiredEvidenceKinds"
	| "maxOccurrences"
	| "maxPending"
	| "maxEffects"
	| "maxEvidence"
>;
export interface IdentityDomain<T> {
	readonly watermark: number;
	readonly occurrences: CausalOccurrence<T>[];
	readonly sequenceComplete: boolean;
	readonly latestAdmitted: Map<string, CausalOccurrence<T>>;
}

/** Private synchronous transition context. No Graph, dispatcher, subscription or I/O capability. */
export interface TransitionContext<T> {
	readonly state: RuntimeState<T>;
	readonly opts: TransitionOptions;
	readonly outputs: AuthorityFact<T>[];
	/** D163: transient marker for actual accepted-record/retention changes. */
	committedViewChanged: boolean;
}

import { canonicalTupleKey } from "../../identity.js";
import type {
	Arrival,
	CausalEvidence,
	CausalOccurrenceRef,
	IdentityDomain,
	TransitionContext,
} from "./contracts.js";
import {
	canonicalEntry,
	canonicalSnapshot,
	dataKey,
	digestPattern,
	exactOccurrence,
	issue,
	pushIssue,
	refKey,
	rejectDefinitiveMissingRef,
	retainDomain,
	retainPending,
	terminalCoverage,
	validRef,
	validToken,
} from "./identity.js";

/** D160: fixed evidence transition helper; no graph control or retained closure. */
export function emitCoverage<T>(context: TransitionContext<T>, occurrence: CausalOccurrenceRef) {
	const { state, opts, outputs } = context;

	// One synchronous scan compares every entry with the same query reference.
	// Laziness preserves the empty-scan path; no key survives this invocation.
	let occurrenceKey: string | undefined;
	const entries = [...state.evidence.values(), ...state.coverageGaps.values()].filter((value) => {
		const entryKey = refKey(value.occurrence);
		occurrenceKey ??= refKey(occurrence);
		return entryKey === occurrenceKey;
	});
	const byKind = new Map(entries.map((value) => [value.evidenceKind, value]));
	const missingKinds = opts.requiredEvidenceKinds.filter((kind) => !byKind.has(kind));
	const terminalGapKinds = opts.requiredEvidenceKinds.filter((kind) => {
		const value = byKind.get(kind);
		return (
			value !== undefined && value.coverage !== "included" && value.coverage !== "external-only"
		);
	});
	outputs.push({
		kind: "coverage",
		value: {
			kind: "causal-evidence-coverage",
			occurrence,
			complete:
				missingKinds.length === 0 &&
				entries.every(
					(value) => value.coverage !== "retention-gap" && value.coverage !== "skipped-revision",
				),
			entries: Object.freeze(entries),
			missingKinds: Object.freeze(missingKinds),
			terminalGapKinds: Object.freeze(terminalGapKinds),
		},
	});
}

/** D160: fixed evidence transition helper; no graph control or retained closure. */
export function retainEvidence<T>(
	context: TransitionContext<T>,
	key: string,
	evidence: CausalEvidence,
) {
	const { state, opts, outputs } = context;

	const prior = state.evidence.get(key);
	if (prior !== undefined) {
		if (dataKey(prior) !== dataKey(evidence))
			pushIssue(
				outputs,
				issue("causal-occurrence/evidence-conflict", "Evidence replay conflicts.", [key]),
			);
		return;
	}
	if (state.evidence.size >= opts.maxEvidence) {
		pushIssue(
			outputs,
			issue("causal-occurrence/evidence-bound", "Evidence retention bound was reached.", [key]),
		);
		// One persistent gap per occurrence/required kind, plus one optional-kind
		// representative: bounded by maxOccurrences * (required kinds + 1).
		// Overflow details cannot consume maxPending or erase a known coverage gap.
		const gapKey = JSON.stringify([
			refKey(evidence.occurrence),
			opts.requiredEvidenceKinds.includes(evidence.evidenceKind) ? evidence.evidenceKind : null,
		]);
		if (!state.coverageGaps.has(gapKey))
			state.coverageGaps.set(
				gapKey,
				canonicalSnapshot({ ...evidence, coverage: "retention-gap" as const }),
			);
	} else {
		state.evidence.set(key, evidence);
	}
	emitCoverage(context, evidence.occurrence);
}

/** D160: fixed evidence transition helper; no graph control or retained closure. */
export function flushEvidence<T>(context: TransitionContext<T>) {
	const { state } = context;

	for (const [key, evidence] of state.pendingEvidence) {
		if (exactOccurrence(context, evidence.occurrence) === undefined) {
			if (rejectDefinitiveMissingRef(context, evidence.occurrence, "evidence"))
				state.pendingEvidence.delete(key);
			continue;
		}
		retainEvidence(context, key, evidence);
		state.pendingEvidence.delete(key);
	}
}

/** D160: fixed evidence transition helper; no graph control or retained closure. */
export function receiveEvidence<T>(
	context: TransitionContext<T>,
	arrival: Extract<Arrival<T>, { lane: "evidence" }>,
) {
	const { state, opts, outputs } = context;

	for (const evidence of arrival.values) {
		if (
			evidence === null ||
			typeof evidence !== "object" ||
			!validRef(evidence.occurrence) ||
			!validToken(evidence.evidenceKind) ||
			!validToken(evidence.evidenceId) ||
			typeof evidence.evidenceDigest !== "string" ||
			!digestPattern.test(evidence.evidenceDigest) ||
			!terminalCoverage.has(evidence.coverage) ||
			(evidence.coverage === "external-only" &&
				(!Array.isArray(evidence.refs) ||
					evidence.refs.length === 0 ||
					!evidence.refs.every(validToken)))
		) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/evidence-mismatch",
					"Evidence does not match retained occurrence authority.",
				),
			);
			continue;
		}
		const canonical = canonicalEntry(evidence);
		if (canonical === undefined) {
			pushIssue(
				outputs,
				issue("causal-occurrence/non-data-evidence", "Evidence must be canonical DATA."),
			);
			continue;
		}
		if (!retainDomain(context, evidence.occurrence.revisionDomain)) continue;
		const key = canonicalTupleKey([
			refKey(evidence.occurrence),
			evidence.evidenceKind,
			evidence.evidenceId,
		]);
		if (exactOccurrence(context, evidence.occurrence) === undefined) {
			if (rejectDefinitiveMissingRef(context, evidence.occurrence, "evidence")) continue;
			retainPending(opts, outputs, state.pendingEvidence, key, canonical.snapshot, "evidence");
			continue;
		}
		retainEvidence(context, key, canonical.snapshot);
	}
}

/** D160: fixed evidence transition helper; no graph control or retained closure. */
export function isEvidenceTerminal<T>(
	context: TransitionContext<T>,
	revisionDomain: string,
	domain: IdentityDomain<T>,
) {
	const { state, opts } = context;

	const { watermark, occurrences } = domain;
	for (const evidence of state.pendingEvidence.values()) {
		if (
			evidence.occurrence.revisionDomain === revisionDomain &&
			evidence.occurrence.revision <= watermark
		)
			return false;
	}
	if (occurrences.length === 0 || opts.requiredEvidenceKinds.length === 0) return true;

	// All entries here are retained canonical snapshots. refKey includes every
	// sameRef coordinate, including the full sourceRefs value. Compute it once
	// per entry in this query rather than once per occurrence/kind comparison.
	// This scratch map never survives the transition or becomes retained authority.
	const covered = new Map<string, Set<string>>();
	for (const records of [state.evidence, state.coverageGaps]) {
		for (const entry of records.values()) {
			if (
				entry.occurrence.revisionDomain !== revisionDomain ||
				!terminalCoverage.has(entry.coverage)
			)
				continue;
			const key = refKey(entry.occurrence);
			let kinds = covered.get(key);
			if (kinds === undefined) {
				kinds = new Set();
				covered.set(key, kinds);
			}
			kinds.add(entry.evidenceKind);
		}
	}
	return occurrences.every((occurrence) => {
		const kinds = covered.get(refKey(occurrence));
		return opts.requiredEvidenceKinds.every((kind) => kinds?.has(kind) === true);
	});
}

import type { DataIssue, DataResult } from "../../data/index.js";
import { canonicalTupleKey } from "../../identity.js";
import { stableJsonString } from "../../json/codec.js";
import type {
	Arrival,
	AuthorityFact,
	CausalBranchTerminal,
	CausalCurrentness,
	CausalEffectOutcomeState,
	CausalEvidenceCoverageState,
	CausalOccurrence,
	CausalOccurrenceAdmission,
	CausalOccurrenceRef,
	CausalSourceRef,
	IdentityDomain,
	TransitionOptions,
} from "./contracts.js";

export const digestPattern = /^sha256:[0-9a-f]{64}$/u;
export const CAUSAL_OCCURRENCE_SCHEMA_REVISION =
	"graphrefly/causal-occurrence-contract/v1@contract-v2";
export const terminalCoverage = new Set<CausalEvidenceCoverageState>([
	"included",
	"excluded",
	"redacted",
	"sampled",
	"external-only",
	"stale",
	"unavailable",
	"retention-gap",
	"skipped-revision",
]);

export function issue(code: string, message: string, refs: readonly string[] = []): DataIssue {
	return Object.freeze({ kind: "issue", code, message, severity: "error", refs });
}

export function dataKey(value: unknown): string {
	return stableJsonString(value);
}

export const sha256Constants = Object.freeze([
	0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
	0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
	0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
	0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
	0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
	0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
	0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
	0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

export function rotateRight(value: number, count: number): number {
	return (value >>> count) | (value << (32 - count));
}

export function sha256(value: string): string {
	const input = new TextEncoder().encode(value);
	const bitLength = input.length * 8;
	const paddedLength = Math.ceil((input.length + 9) / 64) * 64;
	const bytes = new Uint8Array(paddedLength);
	bytes.set(input);
	bytes[input.length] = 0x80;
	const view = new DataView(bytes.buffer);
	view.setUint32(paddedLength - 8, Math.floor(bitLength / 0x1_0000_0000), false);
	view.setUint32(paddedLength - 4, bitLength >>> 0, false);
	const hash = new Uint32Array([
		0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
	]);
	const words = new Uint32Array(64);
	for (let offset = 0; offset < bytes.length; offset += 64) {
		for (let index = 0; index < 16; index += 1)
			words[index] = view.getUint32(offset + index * 4, false);
		for (let index = 16; index < 64; index += 1) {
			const s0 =
				rotateRight(words[index - 15]!, 7) ^
				rotateRight(words[index - 15]!, 18) ^
				(words[index - 15]! >>> 3);
			const s1 =
				rotateRight(words[index - 2]!, 17) ^
				rotateRight(words[index - 2]!, 19) ^
				(words[index - 2]! >>> 10);
			words[index] = (words[index - 16]! + s0 + words[index - 7]! + s1) >>> 0;
		}
		let [a, b, c, d, e, f, g, h] = hash;
		for (let index = 0; index < 64; index += 1) {
			const sum1 = rotateRight(e!, 6) ^ rotateRight(e!, 11) ^ rotateRight(e!, 25);
			const choice = (e! & f!) ^ (~e! & g!);
			const temporary1 = (h! + sum1 + choice + sha256Constants[index]! + words[index]!) >>> 0;
			const sum0 = rotateRight(a!, 2) ^ rotateRight(a!, 13) ^ rotateRight(a!, 22);
			const majority = (a! & b!) ^ (a! & c!) ^ (b! & c!);
			const temporary2 = (sum0 + majority) >>> 0;
			h = g;
			g = f;
			f = e;
			e = (d! + temporary1) >>> 0;
			d = c;
			c = b;
			b = a;
			a = (temporary1 + temporary2) >>> 0;
		}
		hash[0] = (hash[0]! + a!) >>> 0;
		hash[1] = (hash[1]! + b!) >>> 0;
		hash[2] = (hash[2]! + c!) >>> 0;
		hash[3] = (hash[3]! + d!) >>> 0;
		hash[4] = (hash[4]! + e!) >>> 0;
		hash[5] = (hash[5]! + f!) >>> 0;
		hash[6] = (hash[6]! + g!) >>> 0;
		hash[7] = (hash[7]! + h!) >>> 0;
	}
	return `sha256:${[...hash].map((word) => word.toString(16).padStart(8, "0")).join("")}`;
}

export function causalOccurrenceDigest<T>(value: Omit<CausalOccurrence<T>, "digest">): string {
	return sha256(
		dataKey({
			schemaRevision: CAUSAL_OCCURRENCE_SCHEMA_REVISION,
			revisionDomain: value.revisionDomain,
			occurrenceId: value.occurrenceId,
			revision: value.revision,
			value: value.value,
			sourceRefs: value.sourceRefs,
		}),
	);
}

export function canonicalSnapshot<T>(value: T): T {
	const freeze = (item: unknown): unknown => {
		if (item === null || typeof item !== "object") return item;
		if (Array.isArray(item)) return Object.freeze(item.map(freeze));
		return Object.freeze(
			Object.fromEntries(Object.entries(item).map(([key, child]) => [key, freeze(child)])),
		);
	};
	return freeze(JSON.parse(dataKey(value))) as T;
}

export function canonicalEntry<T>(value: T): Readonly<{ key: string; snapshot: T }> | undefined {
	try {
		return Object.freeze({ key: dataKey(value), snapshot: canonicalSnapshot(value) });
	} catch {
		return undefined;
	}
}

export function refKey(value: CausalOccurrenceRef): string {
	return canonicalTupleKey([
		value.revisionDomain,
		String(value.revision),
		value.occurrenceId,
		value.digest,
		dataKey(value.sourceRefs),
	]);
}

export function occurrenceIdKey(value: CausalOccurrenceRef): string {
	return canonicalTupleKey([value.revisionDomain, value.occurrenceId]);
}

export function revisionKey(domain: string, revision: number): string {
	return canonicalTupleKey([domain, String(revision)]);
}

export function effectKey(value: { occurrence: CausalOccurrenceRef; effectId: string }): string {
	return canonicalTupleKey([refKey(value.occurrence), value.effectId]);
}

export function validToken(value: unknown): value is string {
	return typeof value === "string" && value.length > 0;
}

export function validSourceRef(value: unknown): value is CausalSourceRef {
	return (
		value !== null &&
		typeof value === "object" &&
		"kind" in value &&
		validToken(value.kind) &&
		"id" in value &&
		validToken(value.id)
	);
}

export function validRef(value: unknown): value is CausalOccurrenceRef {
	return (
		value !== null &&
		typeof value === "object" &&
		"revisionDomain" in value &&
		validToken(value.revisionDomain) &&
		"occurrenceId" in value &&
		validToken(value.occurrenceId) &&
		"revision" in value &&
		Number.isSafeInteger(value.revision) &&
		(value.revision as number) > 0 &&
		"digest" in value &&
		typeof value.digest === "string" &&
		digestPattern.test(value.digest) &&
		"sourceRefs" in value &&
		Array.isArray(value.sourceRefs) &&
		value.sourceRefs.length > 0 &&
		value.sourceRefs.every(validSourceRef) &&
		new Set(value.sourceRefs.map((ref) => canonicalTupleKey([ref.kind, ref.id]))).size ===
			value.sourceRefs.length
	);
}

export function validAdmissionState(value: unknown): value is CausalOccurrenceAdmission["state"] {
	return value === "admitted" || value === "rejected";
}

export function validOutcomeState(value: unknown): value is CausalEffectOutcomeState {
	return (
		value === "succeeded" ||
		value === "failed" ||
		value === "cancelled" ||
		value === "reconcile-required" ||
		value === "unknown"
	);
}

export function validTerminal(value: CausalBranchTerminal): boolean {
	return (
		(value.state === "completed" || value.state === "failed" || value.state === "skipped") &&
		validResult(value.result) &&
		(value.state === "completed") === (value.result.kind === "ok")
	);
}

export function sameRef(left: CausalOccurrenceRef, right: CausalOccurrenceRef): boolean {
	// refKey already includes digest and the full canonical sourceRefs value.
	// Retained/accepted DATA needs no second serialization of the same coordinates.
	return refKey(left) === refKey(right);
}

export function validResult(value: DataResult<unknown>): boolean {
	if (value === null || typeof value !== "object") return false;
	if (value.kind === "ok") return Object.hasOwn(value, "value");
	return (
		value.kind === "error" &&
		value.error?.kind === "issue" &&
		validToken(value.error.code) &&
		validToken(value.error.message)
	);
}

export function pushIssue<T>(outputs: AuthorityFact<T>[], value: DataIssue): void {
	outputs.push({ kind: "issue", value });
}
export const retainPending = <T, V>(
	opts: TransitionOptions,
	outputs: AuthorityFact<T>[],
	map: Map<string, V>,
	key: string,
	value: V,
	label: string,
) => {
	const prior = map.get(key);
	if (prior !== undefined) {
		if (dataKey(prior) !== dataKey(value))
			pushIssue(
				outputs,
				issue(
					`causal-occurrence/${label}-conflict`,
					`Pending ${label} replay conflicts with retained DATA.`,
					[key],
				),
			);
		return;
	}
	if (map.size >= opts.maxPending) {
		pushIssue(
			outputs,
			issue(
				`causal-occurrence/${label}-pending-bound`,
				`Pending ${label} exceeded bounded retention.`,
				[key],
			),
		);
		return;
	}
	map.set(key, value);
};

import type { TransitionContext } from "./contracts.js";

/** D160: fixed identity transition helper; no graph control or retained closure. */
export function retainDomain<T>(context: TransitionContext<T>, domain: string): boolean {
	const { state, opts, outputs } = context;

	if (state.domains.has(domain)) return true;
	if (state.domains.size >= opts.maxOccurrences) {
		pushIssue(
			outputs,
			issue("causal-occurrence/domain-bound", "Revision-domain retention bound was reached.", [
				domain,
			]),
		);
		return false;
	}
	state.domains.add(domain);
	return true;
}

/** D160: fixed identity transition helper; no graph control or retained closure. */
export function findOccurrence<T>(context: TransitionContext<T>, ref: CausalOccurrenceRef) {
	const { state } = context;
	return state.byRevision.get(revisionKey(ref.revisionDomain, ref.revision))?.value;
}

/** D160: fixed identity transition helper; no graph control or retained closure. */
export function exactOccurrence<T>(context: TransitionContext<T>, ref: CausalOccurrenceRef) {
	const retained = findOccurrence(context, ref);
	return retained !== undefined && sameRef(retained, ref) ? retained : undefined;
}

/** D160: fixed identity transition helper; no graph control or retained closure. */
export function rejectDefinitiveMissingRef<T>(
	context: TransitionContext<T>,
	ref: CausalOccurrenceRef,
	label: string,
) {
	const { state, outputs } = context;

	const retained = findOccurrence(context, ref);
	const floor = state.retentionFloorByDomain.get(ref.revisionDomain) ?? 0;
	const highWater = state.highWaterByDomain.get(ref.revisionDomain) ?? 0;
	if (retained !== undefined && !sameRef(retained, ref)) {
		pushIssue(
			outputs,
			issue(
				`causal-occurrence/${label}-occurrence-conflict`,
				`${label} references a conflicting occurrence revision.`,
				[refKey(ref)],
			),
		);
		return true;
	}
	if (ref.revision <= floor || (ref.revision <= highWater && retained === undefined)) {
		pushIssue(
			outputs,
			issue(
				ref.revision <= floor
					? `causal-occurrence/${label}-retention-gap`
					: `causal-occurrence/${label}-stale`,
				`${label} references a revision that cannot regain authority.`,
				[refKey(ref)],
			),
		);
		return true;
	}
	return false;
}

/** D160: fixed identity transition helper; no graph control or retained closure. */
export function maybeRelease<T>(context: TransitionContext<T>, occurrence: CausalOccurrence<T>) {
	const { state, outputs } = context;

	const key = refKey(occurrence);
	const admission = state.admissions.get(key);
	const currentness = state.currentness.get(key);
	if (
		admission?.state !== "admitted" ||
		!sameRef(admission.occurrence, occurrence) ||
		currentness?.state !== "current" ||
		state.released.has(key) ||
		currentness.evaluatedThroughRevision < occurrence.revision
	)
		return;
	state.released.add(key);
	outputs.push({ kind: "release", value: occurrence });
}

/** D160: fixed identity transition helper; no graph control or retained closure. */
export function exactAdmission<T>(context: TransitionContext<T>, occurrence: CausalOccurrence<T>) {
	const { state } = context;

	const admission = state.admissions.get(refKey(occurrence));
	return admission !== undefined && sameRef(admission.occurrence, occurrence)
		? admission
		: undefined;
}

// This call site receives a canonicalSnapshot-owned occurrence, not arbitrary DATA.
// cloneState preserves retained entry identities; a future state importer must re-establish
// this provenance. A shallow Object.freeze check alone is not a canonical-data proof.
function currentnessMetadata(value: CausalCurrentness, occurrence: CausalOccurrenceRef) {
	if (
		value === null ||
		typeof value !== "object" ||
		Object.getPrototypeOf(value) !== Object.prototype
	)
		return;
	const keys = Reflect.ownKeys(value);
	if (
		keys.length !== 4 ||
		!keys.every(
			(key) =>
				key === "kind" ||
				key === "occurrence" ||
				key === "evaluatedThroughRevision" ||
				key === "state",
		)
	)
		return;
	const fields = Object.getOwnPropertyDescriptors(value);
	for (const key of keys) {
		const field = fields[key as keyof typeof fields];
		if (field === undefined || !("value" in field) || !field.enumerable) return;
	}
	if (
		fields.kind.value !== "causal-currentness" ||
		fields.occurrence.value !== occurrence ||
		typeof fields.evaluatedThroughRevision.value !== "number" ||
		!Number.isSafeInteger(fields.evaluatedThroughRevision.value) ||
		fields.evaluatedThroughRevision.value < 0 ||
		(fields.state.value !== "current" && fields.state.value !== "stale")
	)
		return;
	return {
		kind: fields.kind.value,
		occurrence: null,
		evaluatedThroughRevision: fields.evaluatedThroughRevision.value,
		state: fields.state.value,
	};
}

function currentnessChanged(
	prior: CausalCurrentness,
	value: CausalCurrentness,
	occurrence: CausalOccurrenceRef,
): boolean {
	if (Object.isFrozen(occurrence)) {
		const before = currentnessMetadata(prior, occurrence);
		const after = currentnessMetadata(value, occurrence);
		if (before !== undefined && after !== undefined) return dataKey(before) !== dataKey(after);
	}
	return dataKey(prior) !== dataKey(value);
}

/** D160: fixed identity transition helper; no graph control or retained closure. */
export function recomputeCurrentness<T>(
	context: TransitionContext<T>,
	revisionDomain: string,
): IdentityDomain<T> | undefined {
	const { state, outputs } = context;

	const watermark = state.watermarks.get(revisionDomain);
	if (watermark === undefined) return;
	const floor = state.retentionFloorByDomain.get(revisionDomain) ?? 0;
	const occurrences = [...state.byRevision.values()]
		.map((entry) => entry.value)
		.filter((value) => value.revisionDomain === revisionDomain && value.revision <= watermark)
		.sort((left, right) => left.revision - right.revision);
	// Admissions do not change during this synchronous query. Keep the exact
	// identity check, but reuse its result across the three passes below.
	const evaluated = occurrences.map((occurrence) => ({
		occurrence,
		admission: exactAdmission(context, occurrence),
	}));
	const sequenceComplete =
		(state.highWaterByDomain.get(revisionDomain) ?? 0) >= watermark &&
		(state.retentionGapThroughByDomain.get(revisionDomain) ?? 0) === 0 &&
		![...state.pending.values()].some(
			(entry) => entry.value.revisionDomain === revisionDomain && entry.value.revision <= watermark,
		) &&
		evaluated
			.filter(({ occurrence }) => occurrence.revision > floor)
			.every(({ admission }) => admission !== undefined);
	const latestAdmitted = new Map<string, CausalOccurrence<T>>();
	for (const { occurrence, admission } of evaluated) {
		if (admission?.state === "admitted")
			latestAdmitted.set(occurrenceIdKey(occurrence), occurrence);
	}
	for (const { occurrence, admission } of evaluated) {
		const newer = latestAdmitted.get(occurrenceIdKey(occurrence));
		const value: CausalCurrentness =
			admission === undefined || !sequenceComplete
				? {
						kind: "causal-currentness",
						occurrence,
						evaluatedThroughRevision: watermark,
						state: "unverifiable",
						...((state.retentionGapThroughByDomain.get(revisionDomain) ?? 0) > 0
							? {
									gapRef: {
										revisionDomain,
										afterRevision: state.retentionGapThroughByDomain.get(revisionDomain)!,
										reason: "retention-gap" as const,
										evidenceRef: {
											kind: "causal-evidence",
											id: state.occurrenceRetentionGaps.get(revisionDomain)!.evidenceId,
										},
									},
								}
							: {}),
					}
				: admission.state === "rejected"
					? {
							kind: "causal-currentness",
							occurrence,
							evaluatedThroughRevision: watermark,
							state: "stale",
						}
					: newer !== undefined && newer !== occurrence
						? {
								kind: "causal-currentness",
								occurrence,
								evaluatedThroughRevision: watermark,
								state: "superseded",
								supersededBy: newer,
							}
						: {
								kind: "causal-currentness",
								occurrence,
								evaluatedThroughRevision: watermark,
								state: "current",
							};
		const key = refKey(occurrence);
		const prior = state.currentness.get(key);
		state.currentness.set(key, value);
		if (prior === undefined || currentnessChanged(prior, value, occurrence))
			outputs.push({ kind: "currentness", value });
		maybeRelease(context, occurrence);
	}
	return { watermark, occurrences, sequenceComplete, latestAdmitted };
}

/** D160: fixed identity transition helper; no graph control or retained closure. */
export function flushAdmissions<T>(context: TransitionContext<T>) {
	const { state, outputs } = context;

	for (const [key, admission] of state.admissions) {
		const retained = findOccurrence(context, admission.occurrence);
		if (retained !== undefined && !sameRef(retained, admission.occurrence)) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/admission-mismatch",
					"Deferred admission conflicts with the retained occurrence revision.",
					[key],
				),
			);
			state.admissions.delete(key);
		}
		if (
			retained === undefined &&
			rejectDefinitiveMissingRef(context, admission.occurrence, "admission")
		)
			state.admissions.delete(key);
	}
}

/** D160: fixed identity transition helper; no graph control or retained closure. */
export function receiveAdmissions<T>(
	context: TransitionContext<T>,
	arrival: Extract<Arrival<T>, { lane: "admissions" }>,
) {
	const { state, opts, outputs } = context;

	for (const admission of arrival.values) {
		if (
			admission === null ||
			typeof admission !== "object" ||
			!validRef(admission.occurrence) ||
			!validToken(admission.decisionId) ||
			typeof admission.decisionDigest !== "string" ||
			!digestPattern.test(admission.decisionDigest) ||
			!validAdmissionState(admission.state)
		) {
			pushIssue(
				outputs,
				issue("causal-occurrence/invalid-admission", "Occurrence admission identity is invalid."),
			);
			continue;
		}
		const canonical = canonicalEntry(admission);
		if (canonical === undefined) {
			pushIssue(
				outputs,
				issue("causal-occurrence/non-data-admission", "Admission must be canonical DATA."),
			);
			continue;
		}
		if (!retainDomain(context, admission.occurrence.revisionDomain)) continue;
		const key = refKey(admission.occurrence);
		const prior = state.admissions.get(key);
		if (prior !== undefined) {
			if (dataKey(prior) !== canonical.key)
				pushIssue(
					outputs,
					issue(
						"causal-occurrence/admission-conflict",
						"Admission replay conflicts with retained decision.",
						[key],
					),
				);
			continue;
		}
		const retained = findOccurrence(context, admission.occurrence);
		if (retained !== undefined && !sameRef(retained, admission.occurrence)) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/admission-mismatch",
					"Admission does not match the retained occurrence.",
					[key],
				),
			);
			continue;
		}
		if (retained === undefined && state.admissions.size >= opts.maxPending) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/admission-bound",
					"Unmatched admission exceeded bounded pending retention.",
					[key],
				),
			);
			continue;
		}
		state.admissions.set(key, canonical.snapshot);
	}
}

/** D160: fixed identity transition helper; no graph control or retained closure. */
export function receiveWatermarks<T>(
	context: TransitionContext<T>,
	arrival: Extract<Arrival<T>, { lane: "watermarks" }>,
) {
	const { state, outputs } = context;

	for (const watermark of arrival.values) {
		if (
			watermark === null ||
			typeof watermark !== "object" ||
			!validToken(watermark.revisionDomain) ||
			!Number.isSafeInteger(watermark.revision) ||
			watermark.revision < 0
		) {
			pushIssue(outputs, issue("causal-occurrence/invalid-watermark", "Watermark is invalid."));
			continue;
		}
		if (!retainDomain(context, watermark.revisionDomain)) continue;
		const prior = state.watermarks.get(watermark.revisionDomain) ?? 0;
		if (watermark.revision < prior) {
			pushIssue(
				outputs,
				issue("causal-occurrence/stale-watermark", "Watermark cannot move backwards."),
			);
			continue;
		}
		state.watermarks.set(watermark.revisionDomain, watermark.revision);
	}
}

import { canonicalTupleKey } from "../../identity.js";
import type {
	Arrival,
	CausalBranchTerminal,
	CausalEffectOutcomeState,
	CausalEffectProposal,
	CausalOccurrence,
	CausalOccurrenceRef,
	IdentityDomain,
	TransitionContext,
} from "./contracts.js";
import {
	canonicalEntry,
	dataKey,
	digestPattern,
	effectKey,
	exactAdmission,
	exactOccurrence,
	issue,
	occurrenceIdKey,
	pushIssue,
	refKey,
	rejectDefinitiveMissingRef,
	retainDomain,
	retainPending,
	sameRef,
	validAdmissionState,
	validOutcomeState,
	validRef,
	validResult,
	validSourceRef,
	validTerminal,
	validToken,
} from "./identity.js";

/** D160: fixed lifecycle transition helper; no graph control or retained closure. */
export function settledForEviction<T>(
	context: TransitionContext<T>,
	occurrence: CausalOccurrence<T>,
) {
	const { state } = context;

	const key = refKey(occurrence);
	const admission = state.admissions.get(key);
	if (admission?.state === "rejected") return true;
	if (
		admission?.state !== "admitted" ||
		!state.released.has(key) ||
		!state.emittedTerminals.has(key)
	)
		return false;
	if (
		[
			...state.pendingEffectProposals.values(),
			...state.pendingEffectAdmissions.values(),
			...state.pendingEffectOutcomes.values(),
		].some((fact) => sameRef(fact.occurrence, occurrence))
	)
		return false;
	return [...state.effects.values()]
		.filter((record) => sameRef(record.proposal.occurrence, occurrence))
		.every(
			(record) =>
				record.admission?.state === "rejected" ||
				(record.admission?.state === "admitted" && record.outcome !== undefined),
		);
}

/** D160: fixed lifecycle transition helper; no graph control or retained closure. */
export function emitConservation<T>(
	context: TransitionContext<T>,
	occurrence: CausalOccurrenceRef,
) {
	const { state, outputs } = context;

	const records = [...state.effects.values()].filter((record) =>
		sameRef(record.proposal.occurrence, occurrence),
	);
	const admitted = records.filter((record) => record.admission?.state === "admitted");
	const count = (value: CausalEffectOutcomeState) =>
		admitted.filter((record) => record.outcome?.state === value).length;
	outputs.push({
		kind: "conservation",
		value: {
			kind: "causal-effect-conservation",
			occurrence,
			proposed: records.length,
			pendingAdmission: records.filter((record) => record.admission === undefined).length,
			rejected: records.filter((record) => record.admission?.state === "rejected").length,
			admitted: admitted.length,
			active: admitted.filter((record) => record.outcome === undefined).length,
			succeeded: count("succeeded"),
			failed: count("failed"),
			cancelled: count("cancelled"),
			reconcileRequired: count("reconcile-required"),
			unknown: count("unknown"),
		},
	});
}

/** D160: fixed lifecycle transition helper; no graph control or retained closure. */
export function retainEffectProposal<T>(
	context: TransitionContext<T>,
	key: string,
	proposal: CausalEffectProposal,
) {
	const { state, opts, outputs } = context;

	const pending = state.pendingEffectProposals.get(key);
	if (pending !== undefined && dataKey(pending) !== dataKey(proposal)) {
		pushIssue(
			outputs,
			issue(
				"causal-occurrence/effect-proposal-conflict",
				"Effect proposal conflicts with its retained pending snapshot.",
				[key],
			),
		);
		return true;
	}
	const prior = state.effects.get(key);
	if (prior !== undefined) {
		if (prior.key !== dataKey(proposal))
			pushIssue(
				outputs,
				issue("causal-occurrence/effect-proposal-conflict", "Effect proposal replay conflicts.", [
					key,
				]),
			);
		return true;
	}
	if (state.effects.size >= opts.maxEffects) {
		pushIssue(
			outputs,
			issue("causal-occurrence/effect-bound", "Effect retention bound was reached.", [key]),
		);
		return false;
	}
	state.effects.set(key, { proposal, key: dataKey(proposal) });
	context.committedViewChanged = true;
	emitConservation(context, proposal.occurrence);
	return true;
}

/** D160: fixed lifecycle transition helper; no graph control or retained closure. */
export function flushEffectsAndTerminals<T>(context: TransitionContext<T>) {
	const { state, opts, outputs } = context;

	for (const [key, proposal] of state.pendingEffectProposals) {
		if (
			exactOccurrence(context, proposal.occurrence) === undefined &&
			rejectDefinitiveMissingRef(context, proposal.occurrence, "effect-proposal")
		) {
			state.pendingEffectProposals.delete(key);
			continue;
		}
		if (
			exactOccurrence(context, proposal.occurrence) === undefined ||
			!state.released.has(refKey(proposal.occurrence))
		)
			continue;
		if (retainEffectProposal(context, key, proposal)) state.pendingEffectProposals.delete(key);
	}
	for (const [key, admission] of state.pendingEffectAdmissions) {
		const record = state.effects.get(key);
		if (record === undefined) {
			if (rejectDefinitiveMissingRef(context, admission.occurrence, "effect-admission"))
				state.pendingEffectAdmissions.delete(key);
			continue;
		}
		if (
			record.proposal.proposalDigest !== admission.proposalDigest ||
			dataKey(record.proposal.requestRef) !== dataKey(admission.requestRef) ||
			!sameRef(record.proposal.occurrence, admission.occurrence)
		) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/effect-admission-mismatch",
					"Deferred effect admission does not match its proposal.",
					[key],
				),
			);
			state.pendingEffectAdmissions.delete(key);
			continue;
		}
		if (record.admission === undefined) {
			state.effects.set(key, { ...record, admission });
			context.committedViewChanged = true;
		} else if (dataKey(record.admission) !== dataKey(admission))
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/effect-admission-conflict",
					"Deferred effect admission conflicts with retained admission.",
					[key],
				),
			);
		state.pendingEffectAdmissions.delete(key);
		emitConservation(context, admission.occurrence);
	}
	for (const [key, outcome] of state.pendingEffectOutcomes) {
		const record = state.effects.get(key);
		if (record?.admission === undefined) {
			if (rejectDefinitiveMissingRef(context, outcome.occurrence, "effect-outcome"))
				state.pendingEffectOutcomes.delete(key);
			continue;
		}
		const matches =
			record.admission.state === "admitted" &&
			record.proposal.proposalDigest === outcome.proposalDigest &&
			dataKey(record.proposal.requestRef) === dataKey(outcome.requestRef) &&
			dataKey(record.admission.admissionRef) === dataKey(outcome.admissionRef) &&
			sameRef(record.proposal.occurrence, outcome.occurrence) &&
			(outcome.state === "succeeded") === (outcome.result.kind === "ok");
		if (!matches) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/effect-outcome-mismatch",
					"Deferred effect outcome lacks exact admitted authority.",
					[key],
				),
			);
			state.pendingEffectOutcomes.delete(key);
			continue;
		}
		if (record.outcome === undefined) {
			state.effects.set(key, { ...record, outcome });
			context.committedViewChanged = true;
		} else if (dataKey(record.outcome) !== dataKey(outcome))
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/effect-outcome-conflict",
					"Deferred effect outcome conflicts with retained outcome.",
					[key],
				),
			);
		state.pendingEffectOutcomes.delete(key);
		emitConservation(context, outcome.occurrence);
	}
	for (const [pendingKey, terminal] of state.pendingTerminals) {
		const key = refKey(terminal.occurrence);
		if (
			exactOccurrence(context, terminal.occurrence) === undefined &&
			rejectDefinitiveMissingRef(context, terminal.occurrence, "terminal")
		) {
			state.pendingTerminals.delete(pendingKey);
			continue;
		}
		if (exactOccurrence(context, terminal.occurrence) === undefined || !state.released.has(key))
			continue;
		const branches = state.terminals.get(key) ?? new Map<string, CausalBranchTerminal>();
		const prior = branches.get(terminal.branch);
		if (prior === undefined) branches.set(terminal.branch, terminal);
		else if (dataKey(prior) !== dataKey(terminal))
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/terminal-conflict",
					"Deferred branch terminal conflicts with retained terminal.",
					[key, terminal.branch],
				),
			);
		state.terminals.set(key, branches);
		state.pendingTerminals.delete(pendingKey);
		if (
			!state.emittedTerminals.has(key) &&
			opts.requiredBranches.every((branch) => branches.has(branch))
		) {
			state.emittedTerminals.add(key);
			outputs.push({
				kind: "terminal",
				value: {
					kind: "causal-terminal-fan-in",
					occurrence: terminal.occurrence,
					terminals: Object.freeze(opts.requiredBranches.map((branch) => branches.get(branch)!)),
				},
			});
		}
	}
}

/** D160: fixed lifecycle transition helper; no graph control or retained closure. */
export function receiveTerminals<T>(
	context: TransitionContext<T>,
	arrival: Extract<Arrival<T>, { lane: "branch-terminals" }>,
) {
	const { state, opts, outputs } = context;

	for (const terminal of arrival.values) {
		if (
			terminal === null ||
			typeof terminal !== "object" ||
			!validRef(terminal.occurrence) ||
			!validToken(terminal.branch) ||
			!opts.requiredBranches.includes(terminal.branch) ||
			!validTerminal(terminal)
		) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/terminal-mismatch",
					"Terminal does not match an admitted branch occurrence.",
				),
			);
			continue;
		}
		const canonical = canonicalEntry(terminal);
		if (canonical === undefined) {
			pushIssue(
				outputs,
				issue("causal-occurrence/non-data-terminal", "Terminal must be canonical DATA."),
			);
			continue;
		}
		if (!retainDomain(context, terminal.occurrence.revisionDomain)) continue;
		const key = refKey(terminal.occurrence);
		const pendingKey = canonicalTupleKey([key, terminal.branch]);
		if (
			exactOccurrence(context, terminal.occurrence) === undefined &&
			rejectDefinitiveMissingRef(context, terminal.occurrence, "terminal")
		)
			continue;
		if (exactOccurrence(context, terminal.occurrence) === undefined || !state.released.has(key)) {
			retainPending(
				opts,
				outputs,
				state.pendingTerminals,
				pendingKey,
				canonical.snapshot,
				"terminal",
			);
			continue;
		}
		const branches = state.terminals.get(key) ?? new Map<string, CausalBranchTerminal>();
		const prior = branches.get(terminal.branch);
		if (prior !== undefined && dataKey(prior) !== canonical.key)
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/terminal-conflict",
					"Branch terminal replay conflicts with retained terminal.",
					[key, terminal.branch],
				),
			);
		else if (prior === undefined) branches.set(terminal.branch, canonical.snapshot);
		state.terminals.set(key, branches);
		if (
			!state.emittedTerminals.has(key) &&
			opts.requiredBranches.every((branch) => branches.has(branch))
		) {
			state.emittedTerminals.add(key);
			outputs.push({
				kind: "terminal",
				value: {
					kind: "causal-terminal-fan-in",
					occurrence: terminal.occurrence,
					terminals: Object.freeze(opts.requiredBranches.map((branch) => branches.get(branch)!)),
				},
			});
		}
	}
}

/** D160: fixed lifecycle transition helper; no graph control or retained closure. */
export function receiveProposals<T>(
	context: TransitionContext<T>,
	arrival: Extract<Arrival<T>, { lane: "effect-proposals" }>,
) {
	const { state, opts, outputs } = context;

	for (const proposal of arrival.values) {
		if (
			proposal === null ||
			typeof proposal !== "object" ||
			!validRef(proposal.occurrence) ||
			!validToken(proposal.effectId) ||
			!validSourceRef(proposal.requestRef) ||
			typeof proposal.proposalDigest !== "string" ||
			!digestPattern.test(proposal.proposalDigest)
		) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/effect-proposal-mismatch",
					"Effect proposal lacks exact occurrence authority.",
				),
			);
			continue;
		}
		const canonical = canonicalEntry(proposal);
		if (canonical === undefined) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/non-data-effect-proposal",
					"Effect proposal must be canonical DATA.",
				),
			);
			continue;
		}
		if (!retainDomain(context, proposal.occurrence.revisionDomain)) continue;
		const key = effectKey(proposal);
		if (
			exactOccurrence(context, proposal.occurrence) === undefined &&
			rejectDefinitiveMissingRef(context, proposal.occurrence, "effect-proposal")
		)
			continue;
		if (
			exactOccurrence(context, proposal.occurrence) === undefined ||
			!state.released.has(refKey(proposal.occurrence))
		) {
			retainPending(
				opts,
				outputs,
				state.pendingEffectProposals,
				key,
				canonical.snapshot,
				"effect-proposal",
			);
			continue;
		}
		if (!retainEffectProposal(context, key, canonical.snapshot))
			retainPending(
				opts,
				outputs,
				state.pendingEffectProposals,
				key,
				canonical.snapshot,
				"effect-proposal",
			);
	}
}

/** D160: fixed lifecycle transition helper; no graph control or retained closure. */
export function receiveEffectAdmissions<T>(
	context: TransitionContext<T>,
	arrival: Extract<Arrival<T>, { lane: "effect-admissions" }>,
) {
	const { state, opts, outputs } = context;

	for (const admission of arrival.values) {
		if (
			admission === null ||
			typeof admission !== "object" ||
			!validRef(admission.occurrence) ||
			!validToken(admission.effectId) ||
			!validSourceRef(admission.requestRef) ||
			!validSourceRef(admission.admissionRef) ||
			typeof admission.proposalDigest !== "string" ||
			!digestPattern.test(admission.proposalDigest) ||
			!validAdmissionState(admission.state)
		) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/invalid-effect-admission",
					"Effect admission identity or state is invalid.",
				),
			);
			continue;
		}
		const canonical = canonicalEntry(admission);
		if (canonical === undefined) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/non-data-effect-admission",
					"Effect admission must be canonical DATA.",
				),
			);
			continue;
		}
		if (!retainDomain(context, admission.occurrence.revisionDomain)) continue;
		const key = effectKey(admission);
		const record = state.effects.get(key);
		if (record === undefined) {
			if (rejectDefinitiveMissingRef(context, admission.occurrence, "effect-admission")) continue;
			retainPending(
				opts,
				outputs,
				state.pendingEffectAdmissions,
				key,
				canonical.snapshot,
				"effect-admission",
			);
			continue;
		}
		if (
			record.proposal.proposalDigest !== admission.proposalDigest ||
			dataKey(record.proposal.requestRef) !== dataKey(canonical.snapshot.requestRef) ||
			!sameRef(record.proposal.occurrence, admission.occurrence)
		) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/effect-admission-mismatch",
					"Effect admission has no exact proposal.",
					[key],
				),
			);
			continue;
		}
		if (record.admission !== undefined) {
			if (dataKey(record.admission) !== canonical.key)
				pushIssue(
					outputs,
					issue(
						"causal-occurrence/effect-admission-conflict",
						"Effect admission replay conflicts.",
						[key],
					),
				);
			continue;
		}
		state.effects.set(key, { ...record, admission: canonical.snapshot });
		context.committedViewChanged = true;
		emitConservation(context, admission.occurrence);
	}
}

/** D160: fixed lifecycle transition helper; no graph control or retained closure. */
export function receiveOutcomes<T>(
	context: TransitionContext<T>,
	arrival: Extract<Arrival<T>, { lane: "effect-outcomes" }>,
) {
	const { state, opts, outputs } = context;

	for (const outcome of arrival.values) {
		if (
			outcome === null ||
			typeof outcome !== "object" ||
			!validRef(outcome.occurrence) ||
			!validToken(outcome.effectId) ||
			!validSourceRef(outcome.requestRef) ||
			!validSourceRef(outcome.admissionRef) ||
			typeof outcome.proposalDigest !== "string" ||
			!digestPattern.test(outcome.proposalDigest) ||
			!validOutcomeState(outcome.state) ||
			!validResult(outcome.result)
		) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/invalid-effect-outcome",
					"Effect outcome identity, state, or D184 result is invalid.",
				),
			);
			continue;
		}
		const canonical = canonicalEntry(outcome);
		if (canonical === undefined) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/non-data-effect-outcome",
					"Effect outcome must be canonical DATA.",
				),
			);
			continue;
		}
		const resultMatchesState =
			validResult(outcome.result) &&
			(outcome.state === "succeeded") === (outcome.result.kind === "ok");
		if (!resultMatchesState) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/effect-outcome-mismatch",
					"Effect outcome D184 result must match its terminal state.",
				),
			);
			continue;
		}
		if (!retainDomain(context, outcome.occurrence.revisionDomain)) continue;
		const key = effectKey(outcome);
		const record = state.effects.get(key);
		if (record === undefined || record.admission === undefined) {
			if (rejectDefinitiveMissingRef(context, outcome.occurrence, "effect-outcome")) continue;
			retainPending(
				opts,
				outputs,
				state.pendingEffectOutcomes,
				key,
				canonical.snapshot,
				"effect-outcome",
			);
			continue;
		}
		if (
			record.admission.state !== "admitted" ||
			record.proposal.proposalDigest !== outcome.proposalDigest ||
			dataKey(record.proposal.requestRef) !== dataKey(canonical.snapshot.requestRef) ||
			dataKey(record.admission.admissionRef) !== dataKey(canonical.snapshot.admissionRef) ||
			!sameRef(record.proposal.occurrence, outcome.occurrence)
		) {
			pushIssue(
				outputs,
				issue(
					"causal-occurrence/effect-outcome-mismatch",
					"Effect outcome requires exact admitted authority and a D184 result matching its state.",
					[key],
				),
			);
			continue;
		}
		if (record.outcome !== undefined) {
			if (dataKey(record.outcome) !== canonical.key)
				pushIssue(
					outputs,
					issue("causal-occurrence/effect-outcome-conflict", "Effect outcome replay conflicts.", [
						key,
					]),
				);
			continue;
		}
		state.effects.set(key, { ...record, outcome: canonical.snapshot });
		context.committedViewChanged = true;
		emitConservation(context, outcome.occurrence);
	}
}

/** D160: fixed lifecycle transition helper; no graph control or retained closure. */
export function pendingObligations<T>(
	context: TransitionContext<T>,
	revisionDomain: string,
	domain: IdentityDomain<T>,
) {
	const { state } = context;

	const { watermark, occurrences, latestAdmitted } = domain;
	const pending = new Map<string, CausalOccurrenceRef>();
	for (const occurrence of occurrences) {
		const key = refKey(occurrence);
		const admission = exactAdmission(context, occurrence);
		const isLatest = latestAdmitted.get(occurrenceIdKey(occurrence)) === occurrence;
		if (
			admission === undefined ||
			(admission.state === "admitted" && isLatest && !state.released.has(key)) ||
			(state.released.has(key) && !state.emittedTerminals.has(key))
		)
			pending.set(key, occurrence);
	}
	for (const admission of state.admissions.values()) {
		if (
			admission.occurrence.revisionDomain === revisionDomain &&
			admission.occurrence.revision <= watermark &&
			exactOccurrence(context, admission.occurrence) === undefined
		)
			pending.set(refKey(admission.occurrence), admission.occurrence);
	}
	for (const terminal of state.pendingTerminals.values()) {
		if (
			terminal.occurrence.revisionDomain === revisionDomain &&
			terminal.occurrence.revision <= watermark
		)
			pending.set(refKey(terminal.occurrence), terminal.occurrence);
	}
	const pendingEffects = [...state.effects.values()].filter(
		(record) =>
			record.proposal.occurrence.revisionDomain === revisionDomain &&
			record.proposal.occurrence.revision <= watermark &&
			(record.admission === undefined ||
				(record.admission.state === "admitted" && record.outcome === undefined)),
	);
	const pendingEffectIds = new Set(pendingEffects.map((record) => record.proposal.effectId));
	for (const effect of [
		...state.pendingEffectProposals.values(),
		...state.pendingEffectAdmissions.values(),
		...state.pendingEffectOutcomes.values(),
	]) {
		if (
			effect.occurrence.revisionDomain === revisionDomain &&
			effect.occurrence.revision <= watermark
		)
			pendingEffectIds.add(effect.effectId);
	}
	return { pendingOccurrenceRefs: Object.freeze([...pending.values()]), pendingEffectIds };
}

import type { DataIssue } from "../../data/index.js";
import type {
	Arrival,
	AuthorityFact,
	CausalEvidence,
	CausalQuiescence,
	RetainedOccurrence,
	RuntimeState,
	TransitionOptions,
} from "./contracts.js";
import * as evidence from "./evidence.js";
import * as identity from "./identity.js";
import {
	canonicalSnapshot,
	causalOccurrenceDigest,
	dataKey,
	issue,
	pushIssue,
	refKey,
	revisionKey,
	sameRef,
	validRef,
} from "./identity.js";
import * as execution from "./lifecycle.js";

function emptyState<T>(): RuntimeState<T> {
	return {
		domains: new Set(),
		highWaterByDomain: new Map(),
		retentionFloorByDomain: new Map(),
		byRevision: new Map(),
		pending: new Map(),
		admissions: new Map(),
		released: new Set(),
		terminals: new Map(),
		emittedTerminals: new Set(),
		effects: new Map(),
		evidence: new Map(),
		pendingTerminals: new Map(),
		pendingEffectProposals: new Map(),
		pendingEffectAdmissions: new Map(),
		pendingEffectOutcomes: new Map(),
		pendingEvidence: new Map(),
		coverageGaps: new Map(),
		watermarks: new Map(),
		currentness: new Map(),
		quiescence: new Map(),
		retentionGapThroughByDomain: new Map(),
		occurrenceRetentionGaps: new Map(),
	};
}

function cloneState<T>(prior: RuntimeState<T> | undefined): RuntimeState<T> {
	if (prior === undefined) return emptyState();
	return {
		...prior,
		domains: new Set(prior.domains),
		highWaterByDomain: new Map(prior.highWaterByDomain),
		retentionFloorByDomain: new Map(prior.retentionFloorByDomain),
		byRevision: new Map(prior.byRevision),
		pending: new Map(prior.pending),
		admissions: new Map(prior.admissions),
		released: new Set(prior.released),
		terminals: new Map([...prior.terminals].map(([key, value]) => [key, new Map(value)])),
		emittedTerminals: new Set(prior.emittedTerminals),
		effects: new Map(prior.effects),
		evidence: new Map(prior.evidence),
		pendingTerminals: new Map(prior.pendingTerminals),
		pendingEffectProposals: new Map(prior.pendingEffectProposals),
		pendingEffectAdmissions: new Map(prior.pendingEffectAdmissions),
		pendingEffectOutcomes: new Map(prior.pendingEffectOutcomes),
		pendingEvidence: new Map(prior.pendingEvidence),
		coverageGaps: new Map(prior.coverageGaps),
		watermarks: new Map(prior.watermarks),
		currentness: new Map(prior.currentness),
		quiescence: new Map(prior.quiescence),
		retentionGapThroughByDomain: new Map(prior.retentionGapThroughByDomain),
		occurrenceRetentionGaps: new Map(prior.occurrenceRetentionGaps),
	};
}

export function transitionCausalAuthority<T>(
	prior: RuntimeState<T> | undefined,
	arrivals: readonly Arrival<T>[],
	opts: TransitionOptions,
): { state: RuntimeState<T>; outputs: AuthorityFact<T>[]; committedViewChanged: boolean } {
	const state = cloneState(prior);
	const outputs: AuthorityFact<T>[] = [];
	const emitIssue = (value: DataIssue) => pushIssue(outputs, value);
	const context = { state, opts, outputs, committedViewChanged: false };
	const acceptOccurrence = (entry: RetainedOccurrence<T>): boolean => {
		const occurrence = entry.value;
		if (state.byRevision.size >= opts.maxOccurrences) {
			const oldest = [...state.byRevision.entries()]
				.sort(([, left], [, right]) => left.value.revision - right.value.revision)
				.find(([, retained]) => execution.settledForEviction(context, retained.value));
			if (oldest === undefined) {
				emitIssue(
					issue(
						"causal-occurrence/retention-capacity",
						"Occurrence retention is full of unsettled causal obligations.",
						[refKey(occurrence)],
					),
				);
				return false;
			}
			state.byRevision.delete(oldest[0]);
			const evicted = oldest[1].value;
			const evictedRefKey = refKey(evicted);
			state.admissions.delete(evictedRefKey);
			state.released.delete(evictedRefKey);
			state.terminals.delete(evictedRefKey);
			state.emittedTerminals.delete(evictedRefKey);
			state.currentness.delete(evictedRefKey);
			for (const [key, record] of state.effects) {
				if (sameRef(record.proposal.occurrence, evicted)) {
					state.effects.delete(key);
					context.committedViewChanged = true;
				}
			}
			for (const [key, evidence] of state.evidence) {
				if (sameRef(evidence.occurrence, evicted)) state.evidence.delete(key);
			}
			for (const map of [
				state.pendingTerminals,
				state.pendingEffectProposals,
				state.pendingEffectAdmissions,
				state.pendingEffectOutcomes,
				state.pendingEvidence,
				state.coverageGaps,
			]) {
				for (const [key, value] of map) {
					if (sameRef(value.occurrence, evicted)) map.delete(key);
				}
			}
			const priorFloor = state.retentionFloorByDomain.get(evicted.revisionDomain) ?? 0;
			const priorGap = state.retentionGapThroughByDomain.get(evicted.revisionDomain) ?? 0;
			if (evicted.revision > priorFloor || evicted.revision > priorGap)
				context.committedViewChanged = true;
			state.retentionFloorByDomain.set(
				evicted.revisionDomain,
				Math.max(state.retentionFloorByDomain.get(evicted.revisionDomain) ?? 0, evicted.revision),
			);
			state.retentionGapThroughByDomain.set(
				evicted.revisionDomain,
				Math.max(
					state.retentionGapThroughByDomain.get(evicted.revisionDomain) ?? 0,
					evicted.revision,
				),
			);
			const retentionGap = canonicalSnapshot<CausalEvidence>({
				occurrence: evicted,
				evidenceKind: "occurrence-retention",
				evidenceId: `retention-gap/${evicted.revisionDomain}/${evicted.revision}`,
				evidenceDigest: evicted.digest,
				coverage: "retention-gap",
				refs: Object.freeze([`causal-occurrence:${refKey(evicted)}`]),
			});
			state.occurrenceRetentionGaps.set(evicted.revisionDomain, retentionGap);
			outputs.push({
				kind: "coverage",
				value: {
					kind: "causal-evidence-coverage",
					occurrence: evicted,
					complete: false,
					entries: Object.freeze([retentionGap]),
					missingKinds: Object.freeze([...opts.requiredEvidenceKinds]),
					terminalGapKinds: Object.freeze([...opts.requiredEvidenceKinds]),
				},
			});
		}
		state.byRevision.set(revisionKey(occurrence.revisionDomain, occurrence.revision), entry);
		state.highWaterByDomain.set(occurrence.revisionDomain, occurrence.revision);
		return true;
	};
	const receiveOccurrences = (arrival: Extract<Arrival<T>, { lane: "occurrences" }>) => {
		for (const occurrence of arrival.values) {
			if (!validRef(occurrence)) {
				emitIssue(issue("causal-occurrence/invalid-identity", "Occurrence identity is invalid."));
				continue;
			}
			let key: string;
			try {
				key = dataKey(occurrence);
			} catch {
				emitIssue(issue("causal-occurrence/non-data", "Occurrence must be canonical DATA."));
				continue;
			}
			const { digest, ...digestMaterial } = occurrence;
			if (causalOccurrenceDigest(digestMaterial) !== digest) {
				emitIssue(
					issue(
						"causal-occurrence/digest-mismatch",
						"Occurrence digest does not bind contract-v2 identity and value material.",
						[refKey(occurrence)],
					),
				);
				continue;
			}
			if (!identity.retainDomain(context, occurrence.revisionDomain)) continue;
			const domainKey = revisionKey(occurrence.revisionDomain, occurrence.revision);
			const existing = state.byRevision.get(domainKey) ?? state.pending.get(domainKey);
			if (existing !== undefined) {
				if (existing.key !== key)
					emitIssue(
						issue(
							"causal-occurrence/replay-conflict",
							"Revision replay conflicts with retained identity.",
							[refKey(occurrence)],
						),
					);
				continue;
			}
			const highWater = state.highWaterByDomain.get(occurrence.revisionDomain) ?? 0;
			const floor = state.retentionFloorByDomain.get(occurrence.revisionDomain) ?? 0;
			if (occurrence.revision <= highWater) {
				emitIssue(
					issue(
						occurrence.revision <= floor
							? "causal-occurrence/retention-gap"
							: "causal-occurrence/stale-revision",
						"Revision cannot regain causal authority.",
						[refKey(occurrence)],
					),
				);
				outputs.push({
					kind: "currentness",
					value: {
						kind: "causal-currentness",
						occurrence,
						evaluatedThroughRevision: highWater,
						state: occurrence.revision <= floor ? "unverifiable" : "stale",
					},
				});
				continue;
			}
			const entry = { value: canonicalSnapshot(occurrence), key };
			if (occurrence.revision > highWater + 1) {
				if (state.pending.size >= opts.maxPending) {
					emitIssue(
						issue(
							"causal-occurrence/pending-bound",
							"Skipped revision exceeded bounded pending retention.",
							[refKey(occurrence)],
						),
					);
					continue;
				}
				state.pending.set(domainKey, entry);
				emitIssue(
					issue("causal-occurrence/skipped-revision", `Revision ${highWater + 1} is missing.`, [
						refKey(occurrence),
					]),
				);
				outputs.push({
					kind: "currentness",
					value: {
						kind: "causal-currentness",
						occurrence,
						evaluatedThroughRevision: highWater,
						state: "unverifiable",
						missingRevision: highWater + 1,
						gapRef: {
							revisionDomain: occurrence.revisionDomain,
							afterRevision: highWater,
							beforeRevision: occurrence.revision,
							reason: "skipped-revision",
						},
					},
				});
				outputs.push({
					kind: "coverage",
					value: {
						kind: "causal-evidence-coverage",
						occurrence,
						complete: false,
						entries: Object.freeze([
							{
								occurrence,
								evidenceKind: "revision-sequence",
								evidenceId: `${occurrence.revisionDomain}/${occurrence.revision}`,
								evidenceDigest: occurrence.digest,
								coverage: "skipped-revision",
							},
						]),
						missingKinds: Object.freeze([...opts.requiredEvidenceKinds]),
						terminalGapKinds: Object.freeze(["revision-sequence"]),
					},
				});
				continue;
			}
			if (!acceptOccurrence(entry)) {
				if (state.pending.size < opts.maxPending) state.pending.set(domainKey, entry);
				continue;
			}
			for (;;) {
				const nextRevision = (state.highWaterByDomain.get(occurrence.revisionDomain) ?? 0) + 1;
				const pending = state.pending.get(revisionKey(occurrence.revisionDomain, nextRevision));
				if (pending === undefined) break;
				if (!acceptOccurrence(pending)) break;
				state.pending.delete(revisionKey(occurrence.revisionDomain, nextRevision));
			}
		}
	};
	const recomputeDomain = (revisionDomain: string) => {
		const domain = identity.recomputeCurrentness(context, revisionDomain);
		if (domain === undefined) return;
		const { watermark, sequenceComplete } = domain;
		const { pendingOccurrenceRefs, pendingEffectIds } = execution.pendingObligations(
			context,
			revisionDomain,
			domain,
		);
		const lifecycle =
			sequenceComplete && pendingOccurrenceRefs.length === 0 && pendingEffectIds.size === 0;
		// This read-only completeness query cannot affect retainedEvidence until
		// lifecycle is settled. Evidence ingestion and coverage outputs remain eager.
		const evidenceTerminal =
			lifecycle && evidence.isEvidenceTerminal(context, revisionDomain, domain);
		const value: CausalQuiescence = {
			kind: "causal-quiescence",
			revisionDomain,
			evaluatedThroughRevision: watermark,
			lifecycle,
			retainedEvidence:
				lifecycle &&
				evidenceTerminal &&
				(state.retentionGapThroughByDomain.get(revisionDomain) ?? 0) === 0,
			pendingOccurrenceRefs,
			pendingEffectIds: Object.freeze([...pendingEffectIds]),
		};
		const prior = state.quiescence.get(revisionDomain);
		state.quiescence.set(revisionDomain, value);
		if (prior === undefined || dataKey(prior) !== dataKey(value))
			outputs.push({ kind: "quiescence", value });
	};
	// Flush only removes entries from these collections. Promotion separately
	// accounts for occurrence admission and cross-domain retention eviction.
	const pendingWorkCount = () =>
		state.admissions.size +
		state.pending.size +
		state.pendingTerminals.size +
		state.pendingEffectProposals.size +
		state.pendingEffectAdmissions.size +
		state.pendingEffectOutcomes.size +
		state.pendingEvidence.size;
	const refreshProjections = () => {
		// Preserve the storage/output object separation of the skipped pass.
		// Only entries that recomputeCurrentness would replace are copied.
		for (const { value: occurrence } of state.byRevision.values()) {
			const watermark = state.watermarks.get(occurrence.revisionDomain);
			if (watermark === undefined || occurrence.revision > watermark) continue;
			const key = refKey(occurrence);
			const current = state.currentness.get(key)!;
			state.currentness.set(
				key,
				current.state === "unverifiable" && current.gapRef !== undefined
					? {
							...current,
							gapRef: { ...current.gapRef, evidenceRef: { ...current.gapRef.evidenceRef! } },
						}
					: { ...current },
			);
		}
		for (const domain of state.watermarks.keys()) {
			const current = state.quiescence.get(domain)!;
			state.quiescence.set(domain, {
				...current,
				pendingOccurrenceRefs: Object.freeze([...current.pendingOccurrenceRefs]),
				pendingEffectIds: Object.freeze([...current.pendingEffectIds]),
			});
		}
	};
	const flushPending = () => {
		const before = pendingWorkCount();
		let promoted = false;
		identity.flushAdmissions(context);
		execution.flushEffectsAndTerminals(context);
		evidence.flushEvidence(context);
		for (const revisionDomain of state.domains) {
			for (;;) {
				const revision = (state.highWaterByDomain.get(revisionDomain) ?? 0) + 1;
				const key = revisionKey(revisionDomain, revision);
				const pending = state.pending.get(key);
				if (pending === undefined || !acceptOccurrence(pending)) break;
				state.pending.delete(key);
				promoted = true;
			}
		}
		return { promoted, changed: promoted || pendingWorkCount() !== before };
	};
	for (const arrival of arrivals) {
		if (arrival.lane === "occurrences") receiveOccurrences(arrival);
		if (arrival.lane === "admissions") identity.receiveAdmissions(context, arrival);
		if (arrival.lane === "branch-terminals") execution.receiveTerminals(context, arrival);
		if (arrival.lane === "effect-proposals") execution.receiveProposals(context, arrival);
		if (arrival.lane === "effect-admissions") execution.receiveEffectAdmissions(context, arrival);
		if (arrival.lane === "effect-outcomes") execution.receiveOutcomes(context, arrival);
		if (arrival.lane === "evidence") evidence.receiveEvidence(context, arrival);
		if (arrival.lane === "watermarks") identity.receiveWatermarks(context, arrival);
	}
	for (const revisionDomain of state.watermarks.keys()) recomputeDomain(revisionDomain);
	// Repeat only on finite progress. Commit remains in the authority node, after this drain.
	for (;;) {
		const { promoted, changed } = flushPending();
		if (!changed) {
			refreshProjections();
			break;
		}
		const releasedBefore = state.released.size;
		for (const revisionDomain of state.watermarks.keys()) recomputeDomain(revisionDomain);
		if (!promoted && state.released.size === releasedBefore) break;
	}
	return { state, outputs, committedViewChanged: context.committedViewChanged };
}

import { prepareConstruction, startConstruction } from "../graph/construction-scope.js";
import type { Graph } from "../graph/graph.js";
import {
	type CausalBinding,
	causalBinding,
	type FullCausalCapability,
} from "./causal-occurrence/capabilities.js";
import {
	buildCausalNodes,
	causalColdNodeNames,
	prepareCausalOptions,
} from "./causal-occurrence/construction.js";
import type {
	CausalOccurrenceBundle,
	CausalOccurrenceBundleOptions,
} from "./causal-occurrence/contracts.js";

export {
	assertCausalOccurrenceTopology,
	causalOccurrenceRequiredEdges,
} from "./causal-occurrence/construction.js";

export type {
	CausalBranchTerminal,
	CausalCurrentness,
	CausalEffectAdmission,
	CausalEffectConservation,
	CausalEffectOutcome,
	CausalEffectOutcomeState,
	CausalEffectProposal,
	CausalEvidence,
	CausalEvidenceCoverage,
	CausalEvidenceCoverageState,
	CausalOccurrence,
	CausalOccurrenceAdmission,
	CausalOccurrenceBundle,
	CausalOccurrenceBundleOptions,
	CausalOccurrenceRef,
	CausalQuiescence,
	CausalSourceRef,
	CausalTerminalFanIn,
	CausalWatermark,
} from "./causal-occurrence/contracts.js";
export {
	CAUSAL_OCCURRENCE_SCHEMA_REVISION,
	causalOccurrenceDigest,
} from "./causal-occurrence/identity.js";

export function causalOccurrenceBundle<T>(
	graph: Graph,
	opts: CausalOccurrenceBundleOptions<T>,
): CausalOccurrenceBundle<T> {
	return buildCausalComposition(
		graph,
		opts,
		causalBinding({
			contract: "contract-v2",
			implementationRevision: "construction-v1",
			scope: "full",
			epoch: 1,
		}),
	).ports;
}

/** Package-private one-shot graph-bound setup; construction material has no topology or subscriptions. */
export function causalComposition(graph: Graph) {
	return Object.freeze({
		composeFull<T>(
			facts: CausalOccurrenceBundleOptions<T>,
			binding: CausalBinding,
		): FullCausalCapability<T> {
			return buildCausalComposition(graph, facts, causalBinding(binding)).full;
		},
	});
}

function buildCausalComposition<T>(
	ownerGraph: Graph,
	opts: CausalOccurrenceBundleOptions<T>,
	binding: CausalBinding,
): { ports: CausalOccurrenceBundle<T>; full: FullCausalCapability<T> } {
	const preparedOptions = prepareCausalOptions(opts);
	opts = preparedOptions.options;
	const graph = prepareConstruction(ownerGraph, {
		name: opts.name,
		epoch: binding.epoch,
		names: [...causalColdNodeNames(opts.name), `${opts.name}/startup`],
		inputs: [
			opts.occurrences,
			opts.admissions,
			opts.branchTerminals,
			opts.effectProposals,
			opts.effectAdmissions,
			opts.effectOutcomes,
			opts.evidence,
			opts.watermarks,
		],
	});
	let prepared: import("../graph/construction-scope.js").OwnedConstruction;
	let built: ReturnType<typeof buildCausalNodes<T>>;
	try {
		const startup = graph.startupSource();
		built = buildCausalNodes(ownerGraph, graph, startup, preparedOptions, binding);
		prepared = graph.seal(startup, built.roots);
		graph.transferToGraph(prepared);
	} catch (error) {
		graph.abort(error);
	}
	startConstruction(ownerGraph, prepared);
	return built;
}

