			const facts: MeasurementFact<Size>[] = [];
			for (let i = 0; i < images.length; i += 1) {
				const image = (images as readonly (ImageSizeMeasurementTarget | undefined)[])[i];
				const subjectId = image?.id ?? image?.src ?? `image:${i}`;
