export type WorkItemValidationIssueCode =
	| "malformed-draft"
	| "missing-required-field"
	| "invalid-patch"
	| "duplicate-id"
	| "dangling-ref"
	| "cyclic-dependency"
	| "unsupported-mode"
	| "unsupported-effect-kind"
	| "oversized-inline-data"
	| "policy-mismatch"
	| "missing-policy"
	| "stale-revision"
	| "stale-execution-input"
	| "blocked-prerequisite"
	| "verification-unplanned"
	| "manual-review-required"
	| "duplicate-suppressed"
	| "ambiguous-coverage"
	| "partial-coverage"
	| "unverifiable-output"
	| "unauthorized-author"
	| "unauthorized-target"
	| "invalid-schedule";

