		| undefined
	>(
		deps,
		(ctx) => {
			const state = familyProjectionState(ctx);
			ingestDiagnosticInputFacts(ctx, state, depKinds);
			for (const result of projectWorkspaceProposalRepairReviewDecisionRecordings({
				requests: [...state.repairRequests.values()],
